  A('ja', { ex: { kofukuji: '興福寺旧境内出土の将棋駒', shosoin: '木画紫檀棊局' }, paint: { chaupar: 'チャウパルを打つシヴァとパールヴァティー' },
    shogi: { title: '将棋の「持ち駒」はいつ生まれたのか', lead: '取った駒を自分の駒として打てるのは、チェスの仲間の中で将棋だけ。このルールはいつ、なぜ生まれたのでしょう。',
      s: ['インドで生まれたチェスの祖先は、西へ東へ広がり、日本では将棋になりました。日本でいちばん古い将棋の駒は、奈良の興福寺の旧境内から1990年代はじめの発掘で出た16枚です。いっしょに「天喜六年（1058）」と書かれた札が見つかり、駒も同じころのものと考えられています。',
        'そのころの文書にも将棋は登場します。11世紀なかばに書かれた『新猿楽記』には将棋の名があり、平安時代の終わりごろの記録をまとめた『二中歴』には、玉将・金将・銀将・桂馬・香車・歩兵を使う「平安将棋」が書かれています。',
        '鎌倉・室町時代には、駒の数を増やした大きな将棋がいくつも生まれました。今の将棋のもとになった「小将棋」には、飛車・角行のほか、今はない「酔象」という駒も入っていました。',
        '持ち駒のルールが生まれたのは、16世紀ごろと考えられています。後奈良天皇が小将棋から酔象を取り除かせたという言い伝えがあり、持ち駒もそのころに始まったと見られています。',
        'なぜ持ち駒が生まれたのかは、はっきりしていません。敵味方の駒が同じ色で、向きだけで区別するので、取った駒をそのまま使いやすかったという見方があります。持ち駒によって、将棋は終盤まで駒が減らず、引き分けの少ないゲームになりました。'],
      quiz: [['興福寺の駒といっしょに見つかった札に書かれていた年は？', '天喜六年（1058）', '大宝元年（701）', '天正十年（1582）', '明治元年（1868）'],
        ['持ち駒のルールが生まれたと考えられているのは？', '16世紀ごろ', '8世紀ごろ', '19世紀ごろ', '20世紀になってから'],
        ['取った駒を使いやすかった理由として挙げられるのは？', '敵味方の駒が同じ色で、向きで区別する', '駒が金でできていた', '盤のマスが少なかった', 'さいころで駒を選んだ']] },
    pachisi: { title: 'パチーシはどうやってルドーになったのか', lead: 'インドの宮廷で遊ばれた十字形の盤のゲームは、名前を変えて世界中の子ども部屋に届きました。',
      s: ['インドには、十字の形をした盤のまわりを4人で駒を進める、チャウパルやパチーシというゲームがあります。チャウパルは細長いさいころ（パーサ）を振り、パチーシは子安貝を投げて進む数を決めます。パチーシという名前は「25」という意味で、子安貝を投げていちばん大きく出る数から来ています。',
        '神話の世界でも遊ばれました。17世紀末に描かれた絵には、シヴァ神と妻パールヴァティーがトラの毛皮の上でチャウパルを囲む姿があります。',
        'ムガル帝国のアクバル帝（16世紀）の宮殿があったファテープル・シークリーには、床に大きな十字形の盤が描かれた中庭が残っています。アクバルは色とりどりの服を着た人を駒にして遊んだと伝えられています。',
        '19世紀、このゲームは海を渡りました。アメリカでは「パーチージ」の名で売られ、1874年に商標になりました。イギリスでは1890年代に「ルドー」（ラテン語で「わたしは遊ぶ」）の名で売り出され、家族のゲームとして定着します。',
        'ルドーは、さいころ1つで、6が出たら駒を出せるなど、ルールが簡単になっています。スペインの「パルチス」、ドイツの「メンシュ・エルゲレ・ディッヒ・ニヒト（怒らないで）」など、名前を変えた仲間が世界中にあります。'],
      quiz: [['「パチーシ」という名前の意味は？', '25', '王の道', '十字', '子安貝'],
        ['大きな十字形の盤の中庭が残っているアクバル帝の都は？', 'ファテープル・シークリー', 'デリーのクトゥブ・ミナール', 'タージ・マハル', 'エローラ'],
        ['「ルドー」はラテン語でどういう意味？', 'わたしは遊ぶ', 'わたしは勝つ', 'わたしは走る', 'わたしは投げる']] },
    go: { title: '1300年前の碁盤が語ること', lead: '正倉院に伝わる碁盤には、今と同じ19路の線と、今とはちがう17の花の印があります。',
      s: ['碁は古代中国で生まれたゲームです。伝説では、聖王の堯が息子に教えるために作ったといわれます。紀元前の書物『孟子』には、碁の名人「弈秋」の名前が出てきます。',
        '碁盤の大きさは、時代によって変わってきたと考えられています。古い時代には17路の盤も使われ、やがて今と同じ19路の盤が広まりました。',
        '日本に碁が伝わった時期ははっきりしませんが、奈良時代にはすでに遊ばれていました。僧や尼の決まりを定めた僧尼令は、音楽や博打を禁じながら、碁と琴だけは許しています。双六とはずいぶんちがう扱いでした。',
        '正倉院の「木画紫檀棊局」は、聖武天皇ゆかりの品として伝えられてきた碁盤です。盤面は今と同じ19路ですが、星の代わりの花の印が17か所あります（今の碁盤の星は9つ）。両側の引き出しは、一方を引くともう一方も出てくる仕掛けです。正倉院には、赤や紺に染めた象牙に鳥の模様を彫った碁石も伝わっています。',
        '平安時代には、『源氏物語』に碁を打つ場面が描かれます。江戸時代には本因坊家などの家元が幕府に仕え、碁は専門の棋士が腕を競う芸になりました。'],
      quiz: [['正倉院の碁盤の盤面は何路？', '19路', '17路', '13路', '9路'],
        ['僧尼令が僧や尼に許していた遊びは？', '碁と琴', '双六', '博打', '蹴鞠'],
        ['正倉院の碁盤にある、星の代わりの花の印はいくつ？', '17', '9', '4', '25']] } });
  A('en', { ex: { kofukuji: 'Shogi pieces from Kōfuku-ji', shosoin: 'Shōsōin go board' }, paint: { chaupar: 'Shiva and Parvati playing chaupar' },
    shogi: { title: 'When did shogi’s dropped pieces begin?', lead: 'Of all the chess family, only shogi lets you put captured pieces back on the board as your own. When — and why — did that rule appear?',
      s: ['Chess’s Indian ancestor spread east and west; in Japan it became shogi. Japan’s oldest shogi pieces are 16 found in excavations in the early 1990s on the old grounds of Kōfuku-ji in Nara. A label dated 1058 (Tenki 6) was found with them, so the pieces are thought to be from about the same time.',
        'Writings of the period mention shogi too. The Shin Sarugaku-ki of the mid-11th century names it, and the Nichūreki, which gathers records from the end of the Heian period, describes “Heian shogi” with kings, golds, silvers, knights, lances and pawns.',
        'In the Kamakura and Muromachi periods many larger forms with more pieces appeared. The “small shogi” behind today’s game added the rook and bishop — and a piece called the drunk elephant, which no longer exists.',
        'The drop rule is thought to have appeared around the 16th century. Tradition says Emperor Go-Nara had the drunk elephant removed from small shogi, and the drops are thought to have begun at about that time.',
        'Why drops arose is not clear. One view: both sides’ pieces are the same colour, told apart only by the way they point, so a captured piece is easy to reuse. Thanks to drops, shogi keeps its pieces to the very end and rarely ends in a draw.'],
      quiz: [['What date was written on the label found with the Kōfuku-ji pieces?', '1058 (Tenki 6)', '701 (Taihō 1)', '1582 (Tenshō 10)', '1868 (Meiji 1)'],
        ['When is the drop rule thought to have appeared?', 'Around the 16th century', 'Around the 8th century', 'Around the 19th century', 'In the 20th century'],
        ['What is given as a reason captured pieces were easy to reuse?', 'Both sides’ pieces are the same colour, told apart by direction', 'The pieces were made of gold', 'The board had few squares', 'Pieces were chosen by dice']] },
    pachisi: { title: 'How pachisi became Ludo', lead: 'A cross-shaped board game played at Indian courts changed its name and reached playrooms all over the world.',
      s: ['India has games called chaupar and pachisi, in which four players move pieces round a cross-shaped board. Chaupar uses long dice (pasa); pachisi uses thrown cowrie shells. The name pachisi means “twenty-five,” the highest score the cowries could give.',
        'Even the gods played. A painting from the end of the 17th century shows the god Shiva and his wife Parvati around a chaupar board on a tiger skin.',
        'At Fatehpur Sikri, the city of the Mughal emperor Akbar (16th century), a courtyard still has a huge cross-shaped board laid out in its floor. Akbar is said to have played with people in coloured clothes as the pieces.',
        'In the 19th century the game crossed the seas. In America it was sold as Parcheesi, trademarked in 1874. In Britain it was sold in the 1890s as Ludo — Latin for “I play” — and became a family favourite.',
        'Ludo is simpler: one die, and a 6 to bring a piece out. Relatives under other names are played all over the world, such as Parchís in Spain and Mensch ärgere Dich nicht (“Don’t get annoyed”) in Germany.'],
      quiz: [['What does the name “pachisi” mean?', 'Twenty-five', 'The king’s road', 'Cross', 'Cowrie shell'],
        ['Which of Akbar’s cities still has a courtyard laid out as a huge board?', 'Fatehpur Sikri', 'The Qutb Minar in Delhi', 'The Taj Mahal', 'Ellora'],
        ['What does “Ludo” mean in Latin?', 'I play', 'I win', 'I run', 'I throw']] },
    go: { title: 'What a 1,300-year-old go board tells us', lead: 'The go board kept in the Shōsōin has 19 lines like today’s — and 17 flower marks, unlike today’s.',
      s: ['Go began in ancient China. Legend says the sage king Yao made it to teach his son. The book of Mencius, from before the common era, names a master player, Yi Qiu.',
        'The size of the board is thought to have changed over time: boards of 17 lines were also used in early times, and the 19-line board of today spread later.',
        'When go reached Japan is not clear, but it was played by the Nara period. The rules for monks and nuns banned music and gambling, yet allowed go and the koto — very different from the treatment of sugoroku.',
        'The Shōsōin’s marquetry go board has come down as a treasure linked to Emperor Shōmu. It has 19 lines like today’s board, but 17 flower marks where today’s board has 9 star points. Its two drawers are linked so that pulling one brings out the other. The Shōsōin also keeps go stones of ivory dyed red and dark blue, carved with birds.',
        'In the Heian period The Tale of Genji shows people playing go. In the Edo period houses such as the Hon’inbō served the shogunate, and go became an art in which professional players tested their skill.'],
      quiz: [['How many lines does the Shōsōin go board have?', '19', '17', '13', '9'],
        ['What did the rules for monks and nuns allow them to play?', 'Go and the koto', 'Sugoroku', 'Gambling games', 'Kemari']
        , ['How many flower marks does the Shōsōin board have instead of star points?', '17', '9', '4', '25']] } });
  A('zh', { ex: { kofukuji: '兴福寺旧址出土的将棋棋子', shosoin: '木画紫檀棋局' }, paint: { chaupar: '下乔帕尔的湿婆与帕尔瓦蒂' },
    shogi: { title: '将棋的“持驹”是何时出现的', lead: '在国际象棋家族中，只有将棋能把吃掉的棋子当作自己的再打回棋盘。这条规则是何时、为何出现的？',
      s: ['起源于印度的象棋祖先向东西方传播，在日本成了将棋。日本最古老的将棋棋子，是20世纪90年代初在奈良兴福寺旧址发掘出土的16枚。同时出土了写有“天喜六年（1058）”的木签，因此棋子也被认为是同一时期的东西。',
        '当时的文献也提到了将棋。11世纪中叶写成的《新猿乐记》中出现了将棋之名；汇集平安时代末期记录的《二中历》，记载了使用玉将、金将、银将、桂马、香车、步兵的“平安将棋”。',
        '镰仓、室町时代出现了许多增加棋子数量的大型将棋。成为今日将棋前身的“小将棋”中，除了飞车、角行，还有如今已不存在的“醉象”。',
        '一般认为，持驹规则大约出现在16世纪。相传后奈良天皇下令从小将棋中去掉醉象，持驹也被认为是在那时开始的。',
        '持驹为何出现尚无定论。有一种看法是：双方棋子颜色相同，只靠朝向区分敌我，所以吃掉的棋子容易直接使用。有了持驹，将棋直到终盘棋子都不会减少，也很少出现和棋。'],
      quiz: [['与兴福寺棋子一起出土的木签上写的年份是？', '天喜六年（1058）', '大宝元年（701）', '天正十年（1582）', '明治元年（1868）'],
        ['一般认为持驹规则出现在何时？', '16世纪前后', '8世纪前后', '19世纪前后', '20世纪以后'],
        ['被认为让吃掉的棋子容易再用的原因是？', '双方棋子同色，只靠朝向区分', '棋子是金做的', '棋盘格子很少', '用骰子选棋子']] },
    pachisi: { title: '帕奇西是怎样变成鲁多的', lead: '在印度宫廷里玩的十字形棋盘游戏，换了名字，走进了世界各地的儿童房。',
      s: ['印度有乔帕尔和帕奇西等游戏，四个人在十字形棋盘四周移动棋子。乔帕尔掷细长的骰子（帕萨），帕奇西则掷宝贝壳来决定步数。“帕奇西”意为“25”，来自掷宝贝壳能得到的最大点数。',
        '神话世界里也有人玩。17世纪末的一幅画中，湿婆神与妻子帕尔瓦蒂坐在虎皮上，围着乔帕尔的棋盘。',
        '莫卧儿帝国阿克巴大帝（16世纪）的都城法塔赫布尔西格里，至今留有地面上画着巨大十字形棋盘的庭院。相传阿克巴让穿着彩衣的人充当棋子来下棋。',
        '19世纪，这种游戏漂洋过海。在美国以“帕奇西”（Parcheesi）之名出售，1874年注册为商标。在英国，19世纪90年代以“鲁多”（拉丁语意为“我玩”）之名出售，成为家庭游戏。',
        '鲁多规则更简单：只用一颗骰子，掷出6才能出棋。世界各地还有许多换了名字的同类游戏，如西班牙的“帕尔奇斯”、德国的“别生气”。'],
      quiz: [['“帕奇西”这个名字的意思是？', '25', '王之路', '十字', '宝贝壳'],
        ['留有巨大十字形棋盘庭院的阿克巴都城是？', '法塔赫布尔西格里', '德里的顾特卜塔', '泰姬陵', '埃洛拉'],
        ['“鲁多”在拉丁语中是什么意思？', '我玩', '我赢', '我跑', '我掷']] },
    go: { title: '1300年前的棋盘告诉我们什么', lead: '正仓院所藏的棋盘，有与今天相同的19路线，也有与今天不同的17个花形标记。',
      s: ['围棋诞生于古代中国。传说是圣王尧为教导儿子而创。公元前的《孟子》中，就出现了围棋高手“弈秋”的名字。',
        '一般认为棋盘的大小随时代而变化：早期也使用过17路的棋盘，后来今天的19路棋盘才普及开来。',
        '围棋何时传入日本尚不清楚，但奈良时代已经有人下棋。规范僧尼的《僧尼令》禁止音乐与博戏，却唯独允许下棋和弹琴——与双六的待遇大不相同。',
        '正仓院的“木画紫檀棋局”，是作为圣武天皇遗物流传下来的棋盘。盘面与今天一样是19路，但在星位处有17个花形标记（今天的棋盘只有9个星位）。两侧的抽屉连动，拉出一边，另一边也会出来。正仓院还藏有用染成红色和绀色的象牙雕刻鸟纹的棋子。',
        '平安时代的《源氏物语》中有下围棋的场面。到了江户时代，本因坊家等家元为幕府效力，围棋成了职业棋手比拼技艺的技艺。'],
      quiz: [['正仓院棋盘的盘面是几路？', '19路', '17路', '13路', '9路'],
        ['《僧尼令》允许僧尼玩的是？', '围棋和琴', '双六', '博戏', '蹴鞠'],
        ['正仓院棋盘上代替星位的花形标记有几个？', '17', '9', '4', '25']] } });
  A('zh-TW', { ex: { kofukuji: '興福寺舊址出土的將棋棋子', shosoin: '木畫紫檀棋局' }, paint: { chaupar: '下喬帕爾的濕婆與帕爾瓦蒂' },
    shogi: { title: '將棋的「持駒」是何時出現的', lead: '在西洋棋家族中，只有將棋能把吃掉的棋子當作自己的再打回棋盤。這條規則是何時、為何出現的？',
      s: ['起源於印度的象棋祖先向東西方傳播，在日本成了將棋。日本最古老的將棋棋子，是1990年代初在奈良興福寺舊址發掘出土的16枚。同時出土了寫有「天喜六年（1058）」的木簽，因此棋子也被認為是同一時期的東西。',
        '當時的文獻也提到了將棋。11世紀中葉寫成的《新猿樂記》中出現了將棋之名；彙集平安時代末期紀錄的《二中歷》，記載了使用玉將、金將、銀將、桂馬、香車、步兵的「平安將棋」。',
        '鎌倉、室町時代出現了許多增加棋子數量的大型將棋。成為今日將棋前身的「小將棋」中，除了飛車、角行，還有如今已不存在的「醉象」。',
        '一般認為，持駒規則大約出現在16世紀。相傳後奈良天皇下令從小將棋中去掉醉象，持駒也被認為是在那時開始的。',
        '持駒為何出現尚無定論。有一種看法是：雙方棋子顏色相同，只靠朝向區分敵我，所以吃掉的棋子容易直接使用。有了持駒，將棋直到終盤棋子都不會減少，也很少出現和棋。'],
      quiz: [['與興福寺棋子一起出土的木簽上寫的年份是？', '天喜六年（1058）', '大寶元年（701）', '天正十年（1582）', '明治元年（1868）'],
        ['一般認為持駒規則出現在何時？', '16世紀前後', '8世紀前後', '19世紀前後', '20世紀以後'],
        ['被認為讓吃掉的棋子容易再用的原因是？', '雙方棋子同色，只靠朝向區分', '棋子是金做的', '棋盤格子很少', '用骰子選棋子']] },
    pachisi: { title: '帕奇西是怎樣變成魯多的', lead: '在印度宮廷裡玩的十字形棋盤遊戲，換了名字，走進了世界各地的兒童房。',
      s: ['印度有喬帕爾和帕奇西等遊戲，四個人在十字形棋盤四周移動棋子。喬帕爾擲細長的骰子（帕薩），帕奇西則擲寶貝殼來決定步數。「帕奇西」意為「25」，來自擲寶貝殼能得到的最大點數。',
        '神話世界裡也有人玩。17世紀末的一幅畫中，濕婆神與妻子帕爾瓦蒂坐在虎皮上，圍著喬帕爾的棋盤。',
        '蒙兀兒帝國阿克巴大帝（16世紀）的都城法塔赫布爾西格里，至今留有地面上畫著巨大十字形棋盤的庭院。相傳阿克巴讓穿著彩衣的人充當棋子來下棋。',
        '19世紀，這種遊戲漂洋過海。在美國以「帕奇西」（Parcheesi）之名出售，1874年註冊為商標。在英國，1890年代以「魯多」（拉丁語意為「我玩」）之名出售，成為家庭遊戲。',
        '魯多規則更簡單：只用一顆骰子，擲出6才能出棋。世界各地還有許多換了名字的同類遊戲，如西班牙的「帕爾奇斯」、德國的「別生氣」。'],
      quiz: [['「帕奇西」這個名字的意思是？', '25', '王之路', '十字', '寶貝殼'],
        ['留有巨大十字形棋盤庭院的阿克巴都城是？', '法塔赫布爾西格里', '德里的顧特卜塔', '泰姬瑪哈陵', '埃洛拉'],
        ['「魯多」在拉丁語中是什麼意思？', '我玩', '我贏', '我跑', '我擲']] },
    go: { title: '1300年前的棋盤告訴我們什麼', lead: '正倉院所藏的棋盤，有與今天相同的19路線，也有與今天不同的17個花形標記。',
      s: ['圍棋誕生於古代中國。傳說是聖王堯為教導兒子而創。西元前的《孟子》中，就出現了圍棋高手「弈秋」的名字。',
        '一般認為棋盤的大小隨時代而變化：早期也使用過17路的棋盤，後來今天的19路棋盤才普及開來。',
        '圍棋何時傳入日本尚不清楚，但奈良時代已經有人下棋。規範僧尼的《僧尼令》禁止音樂與博戲，卻唯獨允許下棋和彈琴——與雙六的待遇大不相同。',
        '正倉院的「木畫紫檀棋局」，是作為聖武天皇遺物流傳下來的棋盤。盤面與今天一樣是19路，但在星位處有17個花形標記（今天的棋盤只有9個星位）。兩側的抽屜連動，拉出一邊，另一邊也會出來。正倉院還藏有用染成紅色和紺色的象牙雕刻鳥紋的棋子。',
        '平安時代的《源氏物語》中有下圍棋的場面。到了江戶時代，本因坊家等家元為幕府效力，圍棋成了職業棋士比拼技藝的技藝。'],
      quiz: [['正倉院棋盤的盤面是幾路？', '19路', '17路', '13路', '9路'],
        ['《僧尼令》允許僧尼玩的是？', '圍棋和琴', '雙六', '博戲', '蹴鞠'],
        ['正倉院棋盤上代替星位的花形標記有幾個？', '17', '9', '4', '25']] } });
  A('ko', { ex: { kofukuji: '고후쿠지 옛 경내 출토 쇼기 말', shosoin: '목화자단 바둑판' }, paint: { chaupar: '차우파르를 두는 시바와 파르바티' },
    shogi: { title: '쇼기의 \'모치고마\'는 언제 생겼을까', lead: '잡은 말을 내 말로 다시 놓을 수 있는 것은 체스 가족 중 쇼기뿐입니다. 이 규칙은 언제, 왜 생겼을까요?',
      s: ['인도에서 생긴 체스의 조상은 동서로 퍼져, 일본에서는 쇼기가 되었습니다. 일본에서 가장 오래된 쇼기 말은 1990년대 초 나라 고후쿠지 옛 경내 발굴에서 나온 16개입니다. 함께 \'덴키 6년(1058)\'이라고 적힌 나무 패가 나와, 말도 같은 무렵의 것으로 여겨집니다.',
        '그 무렵의 문헌에도 쇼기가 나옵니다. 11세기 중엽의 《신사루가쿠키》에 쇼기의 이름이 있고, 헤이안 시대 말의 기록을 모은 《니추레키》에는 옥장·금장·은장·계마·향차·보병을 쓰는 \'헤이안 쇼기\'가 적혀 있습니다.',
        '가마쿠라·무로마치 시대에는 말의 수를 늘린 큰 쇼기가 여럿 생겼습니다. 오늘날 쇼기의 바탕이 된 \'소쇼기\'에는 비차·각행 외에 지금은 없는 \'취상\'이라는 말도 있었습니다.',
        '모치고마 규칙은 16세기 무렵 생겼다고 여겨집니다. 고나라 천황이 소쇼기에서 취상을 없애게 했다는 이야기가 전해지며, 모치고마도 그 무렵 시작된 것으로 봅니다.',
        '왜 모치고마가 생겼는지는 분명하지 않습니다. 양쪽 말의 색이 같고 방향으로만 구별하기 때문에, 잡은 말을 그대로 쓰기 쉬웠다는 견해가 있습니다. 모치고마 덕분에 쇼기는 끝까지 말이 줄지 않고, 무승부가 드문 게임이 되었습니다.'],
      quiz: [['고후쿠지 말과 함께 나온 패에 적힌 해는?', '덴키 6년(1058)', '다이호 원년(701)', '덴쇼 10년(1582)', '메이지 원년(1868)'],
        ['모치고마 규칙이 생긴 것으로 여겨지는 때는?', '16세기 무렵', '8세기 무렵', '19세기 무렵', '20세기 이후'],
        ['잡은 말을 다시 쓰기 쉬웠던 이유로 꼽히는 것은?', '양쪽 말의 색이 같고 방향으로 구별한다', '말이 금으로 만들어졌다', '판의 칸이 적었다', '주사위로 말을 골랐다']] },
    pachisi: { title: '파치시는 어떻게 루도가 되었을까', lead: '인도 궁정에서 즐기던 십자 모양 판의 게임은 이름을 바꾸어 세계 곳곳의 아이 방에 닿았습니다.',
      s: ['인도에는 십자 모양 판 둘레로 네 사람이 말을 움직이는 차우파르와 파치시라는 게임이 있습니다. 차우파르는 길쭉한 주사위(파사)를 던지고, 파치시는 개오지 조개를 던져 나아갈 수를 정합니다. \'파치시\'는 \'25\'라는 뜻으로, 조개를 던져 나오는 가장 큰 수에서 왔습니다.',
        '신화 속에서도 즐겼습니다. 17세기 말의 그림에는 시바 신과 아내 파르바티가 호랑이 가죽 위에서 차우파르 판을 둘러싼 모습이 있습니다.',
        '무굴 제국 아크바르 황제(16세기)의 도성 파테푸르 시크리에는 바닥에 큰 십자 모양 판이 그려진 안뜰이 남아 있습니다. 아크바르는 색색의 옷을 입은 사람을 말로 삼아 놀았다고 전해집니다.',
        '19세기에 이 게임은 바다를 건넜습니다. 미국에서는 \'파치지\'라는 이름으로 팔려 1874년에 상표가 되었습니다. 영국에서는 1890년대에 \'루도\'(라틴어로 \'나는 논다\')라는 이름으로 팔려 가족 게임으로 자리 잡았습니다.',
        '루도는 주사위 하나에 6이 나와야 말을 낼 수 있는 등 규칙이 간단합니다. 스페인의 \'파르치스\', 독일의 \'화내지 마\' 등 이름을 바꾼 친척이 세계 곳곳에 있습니다.'],
      quiz: [['\'파치시\'라는 이름의 뜻은?', '25', '왕의 길', '십자', '개오지 조개'],
        ['큰 십자 모양 판의 안뜰이 남아 있는 아크바르의 도성은?', '파테푸르 시크리', '델리의 쿠트브 미나르', '타지마할', '엘로라'],
        ['\'루도\'는 라틴어로 무슨 뜻?', '나는 논다', '나는 이긴다', '나는 달린다', '나는 던진다']] },
    go: { title: '1300년 전 바둑판이 말해 주는 것', lead: '쇼소인에 전하는 바둑판에는 지금과 같은 19줄과, 지금과 다른 17개의 꽃 표시가 있습니다.',
      s: ['바둑은 고대 중국에서 생겼습니다. 전설에서는 성왕 요가 아들을 가르치려고 만들었다고 합니다. 기원전의 책 《맹자》에는 바둑 명인 \'혁추\'의 이름이 나옵니다.',
        '바둑판의 크기는 시대에 따라 바뀌어 왔다고 여겨집니다. 이른 시기에는 17줄 판도 쓰였고, 뒤에 지금과 같은 19줄 판이 퍼졌습니다.',
        '바둑이 일본에 전해진 때는 분명하지 않지만, 나라 시대에는 이미 즐기고 있었습니다. 승려와 비구니의 규칙을 정한 승니령은 음악과 노름을 금하면서도 바둑과 거문고만은 허락했습니다. 쌍륙과는 아주 다른 대접이었습니다.',
        '쇼소인의 \'목화자단 바둑판\'은 쇼무 천황과 인연 있는 물건으로 전해 온 바둑판입니다. 판은 지금과 같은 19줄이지만, 화점 대신 꽃 모양 표시가 17곳에 있습니다(지금 바둑판의 화점은 9개). 양쪽 서랍은 한쪽을 당기면 다른 쪽도 나오는 장치입니다. 쇼소인에는 빨강과 감색으로 물들인 상아에 새 무늬를 새긴 바둑돌도 전합니다.',
        '헤이안 시대의 《겐지 이야기》에는 바둑을 두는 장면이 그려집니다. 에도 시대에는 혼인보가 등의 가문이 막부를 섬기며, 바둑은 전문 기사가 솜씨를 겨루는 예능이 되었습니다.'],
      quiz: [['쇼소인 바둑판은 몇 줄?', '19줄', '17줄', '13줄', '9줄'],
        ['승니령이 승려와 비구니에게 허락한 놀이는?', '바둑과 거문고', '쌍륙', '노름', '게마리'],
        ['쇼소인 바둑판에서 화점 대신 있는 꽃 표시는 몇 개?', '17', '9', '4', '25']] } });
  A('es', { ex: { kofukuji: 'Piezas de shogi de Kōfuku-ji', shosoin: 'Tablero de go del Shōsōin' }, paint: { chaupar: 'Shiva y Parvati jugando al chaupar' },
    shogi: { title: '¿Cuándo nacieron las piezas «en mano» del shogi?', lead: 'De toda la familia del ajedrez, solo el shogi deja volver a poner en juego las piezas capturadas como propias. ¿Cuándo y por qué apareció esa regla?',
      s: ['El antepasado indio del ajedrez se extendió al este y al oeste; en Japón se convirtió en el shogi. Las piezas de shogi más antiguas de Japón son 16 halladas a principios de los años noventa en el antiguo recinto de Kōfuku-ji, en Nara. Junto a ellas apareció una etiqueta fechada en 1058 (Tenki 6), así que se cree que las piezas son de la misma época.',
        'Los escritos de entonces también lo mencionan. El Shin Sarugaku-ki, de mediados del siglo XI, lo nombra, y el Nichūreki, que reúne registros de finales del periodo Heian, describe un «shogi Heian» con reyes, generales de oro y de plata, caballos, lanceros y peones.',
        'En los periodos Kamakura y Muromachi surgieron muchas formas mayores, con más piezas. El «shogi pequeño», base del juego actual, añadió la torre y el alfil… y una pieza que ya no existe: el elefante borracho.',
        'Se cree que la regla de reintroducir piezas apareció hacia el siglo XVI. La tradición dice que el emperador Go-Nara mandó quitar el elefante borracho del shogi pequeño, y se cree que las piezas en mano empezaron por entonces.',
        'No está claro por qué surgió. Una explicación: las piezas de ambos bandos son del mismo color y solo se distinguen por hacia dónde apuntan, así que una pieza capturada es fácil de reutilizar. Gracias a ello, en el shogi no se vacía el tablero y las tablas son raras.'],
      quiz: [['¿Qué fecha tenía la etiqueta hallada con las piezas de Kōfuku-ji?', '1058 (Tenki 6)', '701 (Taihō 1)', '1582 (Tenshō 10)', '1868 (Meiji 1)'],
        ['¿Cuándo se cree que apareció la regla de las piezas en mano?', 'Hacia el siglo XVI', 'Hacia el siglo VIII', 'Hacia el siglo XIX', 'En el siglo XX'],
        ['¿Qué se da como motivo de que fuera fácil reutilizar piezas?', 'Ambos bandos tienen piezas del mismo color, distinguidas por la dirección', 'Las piezas eran de oro', 'El tablero tenía pocas casillas', 'Las piezas se elegían con dados']] },
    pachisi: { title: 'Cómo el pachisi se convirtió en el parchís', lead: 'Un juego de tablero en cruz de las cortes indias cambió de nombre y llegó a los cuartos de juego de todo el mundo.',
      s: ['En la India existen el chaupar y el pachisi: cuatro jugadores mueven fichas alrededor de un tablero en forma de cruz. El chaupar usa dados alargados (pasa); el pachisi, conchas de cauri. El nombre pachisi significa «veinticinco», la tirada más alta de las conchas.',
        'Hasta los dioses jugaban. Una pintura de finales del siglo XVII muestra al dios Shiva y a su esposa Parvati ante un tablero de chaupar sobre una piel de tigre.',
        'En Fatehpur Sikri, la ciudad del emperador mogol Akbar (siglo XVI), un patio conserva en el suelo un enorme tablero en cruz. Se cuenta que Akbar jugaba usando como fichas a personas vestidas de colores.',
        'En el siglo XIX el juego cruzó los mares. En Estados Unidos se vendió como Parcheesi, marca registrada en 1874. En Gran Bretaña se vendió en la década de 1890 como Ludo —latín, «juego»— y se convirtió en un clásico familiar.',
        'El ludo es más sencillo: un solo dado y un 6 para sacar ficha. Hay parientes con otros nombres en todo el mundo, como el parchís en España o el Mensch ärgere Dich nicht («No te enfades») en Alemania.'],
      quiz: [['¿Qué significa el nombre «pachisi»?', 'Veinticinco', 'El camino del rey', 'Cruz', 'Concha de cauri'],
        ['¿Qué ciudad de Akbar conserva un patio con un tablero enorme?', 'Fatehpur Sikri', 'El Qutb Minar de Delhi', 'El Taj Mahal', 'Ellora'],
        ['¿Qué significa «ludo» en latín?', 'Juego (yo juego)', 'Gano', 'Corro', 'Lanzo']] },
    go: { title: 'Lo que cuenta un tablero de go de 1.300 años', lead: 'El tablero de go del Shōsōin tiene 19 líneas como los de hoy, y 17 marcas de flor, a diferencia de los de hoy.',
      s: ['El go nació en la antigua China. La leyenda dice que el rey sabio Yao lo creó para enseñar a su hijo. El libro de Mencio, anterior a nuestra era, nombra a un maestro del juego, Yi Qiu.',
        'Se cree que el tamaño del tablero cambió con el tiempo: en épocas tempranas también se usaron tableros de 17 líneas, y más tarde se extendió el de 19 líneas actual.',
        'No se sabe cuándo llegó el go a Japón, pero en el periodo Nara ya se jugaba. Las normas para monjes y monjas prohibían la música y los juegos de azar, pero permitían el go y el koto: un trato muy distinto del sugoroku.',
        'El tablero de marquetería del Shōsōin se ha transmitido como un tesoro ligado al emperador Shōmu. Tiene 19 líneas como hoy, pero 17 marcas de flor donde el tablero actual tiene 9 puntos estrella. Sus dos cajones están unidos: al tirar de uno sale también el otro. El Shōsōin guarda además piedras de go de marfil teñido de rojo y azul oscuro, grabadas con aves.',
        'En el periodo Heian, La historia de Genji muestra partidas de go. En el periodo Edo, casas como la Hon’inbō sirvieron al shogunato y el go se convirtió en un arte en que jugadores profesionales medían su habilidad.'],
      quiz: [['¿Cuántas líneas tiene el tablero de go del Shōsōin?', '19', '17', '13', '9'],
        ['¿Qué permitían jugar las normas a monjes y monjas?', 'El go y el koto', 'El sugoroku', 'Juegos de azar', 'El kemari'],
        ['¿Cuántas marcas de flor tiene el tablero del Shōsōin en lugar de puntos estrella?', '17', '9', '4', '25']] } });
  A('fr', { ex: { kofukuji: 'Pièces de shogi du Kōfuku-ji', shosoin: 'Goban du Shōsōin' }, paint: { chaupar: 'Shiva et Parvati jouant au chaupar' },
    shogi: { title: 'Quand sont nés les parachutages du shogi ?', lead: 'Dans toute la famille des échecs, seul le shogi permet de remettre en jeu, pour son camp, les pièces capturées. Quand — et pourquoi — cette règle est-elle apparue ?',
      s: ['L’ancêtre indien des échecs s’est répandu vers l’est et l’ouest ; au Japon, il est devenu le shogi. Les plus anciennes pièces de shogi du Japon sont 16 pièces trouvées au début des années 1990 dans l’ancienne enceinte du Kōfuku-ji, à Nara. Une étiquette datée de 1058 (Tenki 6) était avec elles : on pense donc que les pièces datent de la même époque.',
        'Les écrits de l’époque le mentionnent aussi. Le Shin Sarugaku-ki, du milieu du XIe siècle, le nomme, et le Nichūreki, qui rassemble des documents de la fin de l’époque de Heian, décrit un « shogi de Heian » avec rois, généraux d’or et d’argent, cavaliers, lanciers et pions.',
        'Aux époques de Kamakura et de Muromachi apparurent de nombreuses formes plus grandes, avec plus de pièces. Le « petit shogi », à l’origine du jeu actuel, ajouta la tour et le fou… et une pièce aujourd’hui disparue : l’éléphant ivre.',
        'La règle du parachutage serait apparue vers le XVIe siècle. Selon la tradition, l’empereur Go-Nara fit retirer l’éléphant ivre du petit shogi, et les parachutages auraient commencé vers la même époque.',
        'On ignore pourquoi. Une explication : les pièces des deux camps sont de la même couleur, distinguées seulement par leur orientation, si bien qu’une pièce capturée se réutilise facilement. Grâce à cela, l’échiquier ne se vide pas et les parties nulles sont rares.'],
      quiz: [['Quelle date portait l’étiquette trouvée avec les pièces du Kōfuku-ji ?', '1058 (Tenki 6)', '701 (Taihō 1)', '1582 (Tenshō 10)', '1868 (Meiji 1)'],
        ['Quand la règle du parachutage serait-elle apparue ?', 'Vers le XVIe siècle', 'Vers le VIIIe siècle', 'Vers le XIXe siècle', 'Au XXe siècle'],
        ['Quelle raison avance-t-on pour la facilité de réutiliser les pièces ?', 'Les pièces des deux camps ont la même couleur, distinguées par l’orientation', 'Les pièces étaient en or', 'Le plateau avait peu de cases', 'On choisissait les pièces aux dés']] },
    pachisi: { title: 'Comment le pachisi est devenu le ludo', lead: 'Un jeu de plateau en croix des cours indiennes a changé de nom et gagné les salles de jeux du monde entier.',
      s: ['L’Inde connaît le chaupar et le pachisi : quatre joueurs font avancer des pions autour d’un plateau en forme de croix. Le chaupar se joue avec de longs dés (pasa), le pachisi avec des cauris lancés. Le nom pachisi signifie « vingt-cinq », le plus haut score que donnaient les cauris.',
        'Même les dieux y jouaient. Une peinture de la fin du XVIIe siècle montre le dieu Shiva et son épouse Parvati autour d’un plateau de chaupar, sur une peau de tigre.',
        'À Fatehpur Sikri, la cité de l’empereur moghol Akbar (XVIe siècle), une cour conserve dans son dallage un immense plateau en croix. Akbar y aurait joué avec des personnes vêtues de couleurs en guise de pions.',
        'Au XIXe siècle, le jeu traversa les mers. Aux États-Unis, il fut vendu sous le nom de Parcheesi, marque déposée en 1874. En Grande-Bretagne, il fut vendu dans les années 1890 sous le nom de Ludo — « je joue » en latin — et devint un classique familial.',
        'Le ludo est plus simple : un seul dé, et un 6 pour sortir un pion. Il a des cousins sous d’autres noms partout dans le monde, comme les Petits Chevaux en France ou le Mensch ärgere Dich nicht (« Ne t’énerve pas ») en Allemagne.'],
      quiz: [['Que signifie le nom « pachisi » ?', 'Vingt-cinq', 'La route du roi', 'Croix', 'Cauri'],
        ['Quelle cité d’Akbar conserve une cour au plateau géant ?', 'Fatehpur Sikri', 'Le Qutb Minar de Delhi', 'Le Taj Mahal', 'Ellora'],
        ['Que signifie « ludo » en latin ?', 'Je joue', 'Je gagne', 'Je cours', 'Je lance']] },
    go: { title: 'Ce que raconte un goban vieux de 1 300 ans', lead: 'Le goban du Shōsōin a 19 lignes comme aujourd’hui — et 17 marques en forme de fleur, à la différence d’aujourd’hui.',
      s: ['Le go est né dans la Chine ancienne. La légende veut que le sage roi Yao l’ait créé pour instruire son fils. Le livre de Mencius, antérieur à notre ère, cite un maître du jeu, Yi Qiu.',
        'On pense que la taille du plateau a changé au fil du temps : des plateaux de 17 lignes furent aussi utilisés anciennement, et le plateau actuel de 19 lignes s’est imposé plus tard.',
        'On ignore quand le go arriva au Japon, mais on y jouait à l’époque de Nara. Les règles pour les moines et les nonnes interdisaient la musique et les jeux d’argent, mais permettaient le go et le koto — un traitement bien différent de celui du sugoroku.',
        'Le goban en marqueterie du Shōsōin s’est transmis comme un trésor lié à l’empereur Shōmu. Il a 19 lignes comme aujourd’hui, mais 17 marques en fleur là où le goban actuel a 9 points étoile. Ses deux tiroirs sont liés : en tirer un fait sortir l’autre. Le Shōsōin garde aussi des pierres de go en ivoire teint en rouge et bleu sombre, gravées d’oiseaux.',
        'À l’époque de Heian, le Dit du Genji montre des parties de go. À l’époque d’Edo, des maisons comme les Hon’inbō servirent le shogunat, et le go devint un art où des joueurs professionnels mesuraient leur talent.'],
      quiz: [['Combien de lignes compte le goban du Shōsōin ?', '19', '17', '13', '9'],
        ['Que permettaient les règles aux moines et aux nonnes ?', 'Le go et le koto', 'Le sugoroku', 'Les jeux d’argent', 'Le kemari'],
        ['Combien de marques en fleur le goban du Shōsōin a-t-il au lieu des points étoile ?', '17', '9', '4', '25']] } });
  A('pt', { ex: { kofukuji: 'Peças de shogi de Kōfuku-ji', shosoin: 'Tabuleiro de go do Shōsōin' }, paint: { chaupar: 'Shiva e Parvati jogando chaupar' },
    shogi: { title: 'Quando nasceram as peças “na mão” do shogi?', lead: 'De toda a família do xadrez, só o shogi deixa recolocar no jogo, como suas, as peças capturadas. Quando — e por quê — essa regra surgiu?',
      s: ['O ancestral indiano do xadrez se espalhou para leste e oeste; no Japão, virou shogi. As peças de shogi mais antigas do Japão são 16 achadas no início dos anos 1990 no antigo recinto do Kōfuku-ji, em Nara. Junto delas apareceu uma etiqueta datada de 1058 (Tenki 6), por isso se acredita que as peças sejam da mesma época.',
        'Textos da época também o mencionam. O Shin Sarugaku-ki, de meados do século XI, cita o jogo, e o Nichūreki, que reúne registros do fim do período Heian, descreve um “shogi Heian” com reis, generais de ouro e de prata, cavalos, lanceiros e peões.',
        'Nos períodos Kamakura e Muromachi surgiram muitas formas maiores, com mais peças. O “shogi pequeno”, base do jogo atual, acrescentou a torre e o bispo… e uma peça que não existe mais: o elefante bêbado.',
        'Acredita-se que a regra de recolocar peças surgiu por volta do século XVI. A tradição diz que o imperador Go-Nara mandou retirar o elefante bêbado do shogi pequeno, e as peças na mão teriam começado nessa época.',
        'Não se sabe ao certo por quê. Uma explicação: as peças dos dois lados têm a mesma cor e se distinguem só pela direção, então uma peça capturada é fácil de reutilizar. Por isso o tabuleiro não se esvazia e os empates são raros.'],
      quiz: [['Que data tinha a etiqueta achada com as peças do Kōfuku-ji?', '1058 (Tenki 6)', '701 (Taihō 1)', '1582 (Tenshō 10)', '1868 (Meiji 1)'],
        ['Quando se acredita que surgiu a regra das peças na mão?', 'Por volta do século XVI', 'Por volta do século VIII', 'Por volta do século XIX', 'No século XX'],
        ['Que motivo se dá para ser fácil reutilizar as peças?', 'As peças dos dois lados têm a mesma cor, distinguidas pela direção', 'As peças eram de ouro', 'O tabuleiro tinha poucas casas', 'As peças eram escolhidas nos dados']] },
    pachisi: { title: 'Como o pachisi virou ludo', lead: 'Um jogo de tabuleiro em cruz das cortes indianas mudou de nome e chegou às salas de brinquedo do mundo inteiro.',
      s: ['A Índia tem o chaupar e o pachisi: quatro jogadores movem peças em volta de um tabuleiro em forma de cruz. O chaupar usa dados compridos (pasa); o pachisi, búzios lançados. O nome pachisi quer dizer “vinte e cinco”, o maior resultado dos búzios.',
        'Até os deuses jogavam. Uma pintura do fim do século XVII mostra o deus Shiva e sua esposa Parvati diante de um tabuleiro de chaupar, sobre uma pele de tigre.',
        'Em Fatehpur Sikri, a cidade do imperador mogol Akbar (século XVI), um pátio ainda tem no chão um enorme tabuleiro em cruz. Conta-se que Akbar jogava usando como peças pessoas vestidas de cores.',
        'No século XIX o jogo atravessou os mares. Nos Estados Unidos foi vendido como Parcheesi, marca registrada em 1874. Na Grã-Bretanha foi vendido nos anos 1890 como Ludo — em latim, “eu jogo” — e virou um clássico de família.',
        'O ludo é mais simples: um só dado, e um 6 para tirar a peça. Há parentes com outros nomes no mundo todo, como o parchís na Espanha e o Mensch ärgere Dich nicht (“Não se irrite”) na Alemanha.'],
      quiz: [['O que significa o nome “pachisi”?', 'Vinte e cinco', 'O caminho do rei', 'Cruz', 'Búzio'],
        ['Que cidade de Akbar guarda um pátio com um tabuleiro enorme?', 'Fatehpur Sikri', 'O Qutb Minar de Délhi', 'O Taj Mahal', 'Ellora'],
        ['O que significa “ludo” em latim?', 'Eu jogo', 'Eu venço', 'Eu corro', 'Eu lanço']] },
    go: { title: 'O que conta um tabuleiro de go de 1.300 anos', lead: 'O tabuleiro de go do Shōsōin tem 19 linhas como os de hoje — e 17 marcas de flor, ao contrário dos de hoje.',
      s: ['O go nasceu na China antiga. A lenda diz que o rei sábio Yao o criou para ensinar o filho. O livro de Mêncio, de antes da nossa era, cita um mestre do jogo, Yi Qiu.',
        'Acredita-se que o tamanho do tabuleiro mudou com o tempo: em épocas antigas também se usaram tabuleiros de 17 linhas, e depois se espalhou o de 19 linhas de hoje.',
        'Não se sabe quando o go chegou ao Japão, mas no período Nara já se jogava. As regras para monges e monjas proibiam a música e os jogos de azar, mas permitiam o go e o koto — um tratamento bem diferente do sugoroku.',
        'O tabuleiro de marchetaria do Shōsōin foi transmitido como um tesouro ligado ao imperador Shōmu. Tem 19 linhas como hoje, mas 17 marcas de flor onde o tabuleiro atual tem 9 pontos-estrela. Suas duas gavetas são ligadas: puxar uma faz a outra sair. O Shōsōin guarda também pedras de go de marfim tingido de vermelho e azul-escuro, gravadas com pássaros.',
        'No período Heian, a Narrativa de Genji mostra partidas de go. No período Edo, casas como a Hon’inbō serviram o xogunato, e o go virou uma arte em que jogadores profissionais mediam sua habilidade.'],
      quiz: [['Quantas linhas tem o tabuleiro de go do Shōsōin?', '19', '17', '13', '9'],
        ['O que as regras permitiam a monges e monjas?', 'O go e o koto', 'O sugoroku', 'Jogos de azar', 'O kemari'],
        ['Quantas marcas de flor o tabuleiro do Shōsōin tem no lugar dos pontos-estrela?', '17', '9', '4', '25']] } });
  A('de', { ex: { kofukuji: 'Shogi-Figuren aus dem Kōfuku-ji', shosoin: 'Go-Brett des Shōsōin' }, paint: { chaupar: 'Shiva und Parvati beim Chaupar' },
    shogi: { title: 'Wann entstanden die „Handfiguren“ des Shogi?', lead: 'In der ganzen Schachfamilie darf man nur im Shogi geschlagene Figuren als eigene wieder einsetzen. Wann – und warum – kam diese Regel auf?',
      s: ['Der indische Vorfahr des Schachs verbreitete sich nach Osten und Westen; in Japan wurde daraus Shogi. Die ältesten Shogi-Figuren Japans sind 16 Stück, die Anfang der 1990er-Jahre auf dem alten Gelände des Kōfuku-ji in Nara ausgegraben wurden. Mit ihnen fand man ein Etikett mit dem Datum 1058 (Tenki 6); die Figuren gelten daher als etwa gleich alt.',
        'Auch Schriften jener Zeit erwähnen Shogi. Das Shin Sarugaku-ki aus der Mitte des 11. Jahrhunderts nennt es, und das Nichūreki, das Aufzeichnungen vom Ende der Heian-Zeit sammelt, beschreibt ein „Heian-Shogi“ mit Königen, Gold- und Silbergenerälen, Springern, Lanzen und Bauern.',
        'In der Kamakura- und Muromachi-Zeit entstanden viele größere Formen mit mehr Figuren. Das „kleine Shogi“, Vorläufer des heutigen Spiels, fügte Turm und Läufer hinzu – und eine Figur, die es nicht mehr gibt: den betrunkenen Elefanten.',
        'Die Regel zum Wiedereinsetzen kam vermutlich im 16. Jahrhundert auf. Der Überlieferung nach ließ Kaiser Go-Nara den betrunkenen Elefanten aus dem kleinen Shogi entfernen; etwa zur selben Zeit sollen die Handfiguren begonnen haben.',
        'Warum, ist unklar. Eine Erklärung: Die Figuren beider Seiten haben dieselbe Farbe und unterscheiden sich nur durch ihre Richtung, sodass eine geschlagene Figur leicht wiederzuverwenden ist. Dadurch leert sich das Brett nicht, und Remis sind selten.'],
      quiz: [['Welches Datum stand auf dem Etikett bei den Kōfuku-ji-Figuren?', '1058 (Tenki 6)', '701 (Taihō 1)', '1582 (Tenshō 10)', '1868 (Meiji 1)'],
        ['Wann kam die Regel der Handfiguren vermutlich auf?', 'Etwa im 16. Jahrhundert', 'Etwa im 8. Jahrhundert', 'Etwa im 19. Jahrhundert', 'Im 20. Jahrhundert'],
        ['Welcher Grund wird dafür genannt, dass sich Figuren leicht wiederverwenden ließen?', 'Beide Seiten haben gleichfarbige Figuren, unterschieden durch die Richtung', 'Die Figuren waren aus Gold', 'Das Brett hatte wenige Felder', 'Figuren wurden ausgewürfelt']] },
    pachisi: { title: 'Wie Pachisi zu Ludo wurde', lead: 'Ein kreuzförmiges Brettspiel indischer Höfe wechselte den Namen und erreichte Kinderzimmer in aller Welt.',
      s: ['In Indien gibt es Chaupar und Pachisi: Vier Spieler ziehen Figuren um ein kreuzförmiges Brett. Beim Chaupar wirft man lange Würfel (Pasa), beim Pachisi Kaurimuscheln. Der Name Pachisi bedeutet „fünfundzwanzig“ – der höchste Wurf der Muscheln.',
        'Sogar die Götter spielten. Ein Gemälde vom Ende des 17. Jahrhunderts zeigt den Gott Shiva und seine Frau Parvati an einem Chaupar-Brett auf einem Tigerfell.',
        'In Fatehpur Sikri, der Stadt des Mogulkaisers Akbar (16. Jahrhundert), zeigt ein Hof noch heute ein riesiges kreuzförmiges Brett im Boden. Akbar soll mit farbig gekleideten Menschen als Figuren gespielt haben.',
        'Im 19. Jahrhundert reiste das Spiel über die Meere. In Amerika wurde es als Parcheesi verkauft und 1874 als Marke eingetragen. In Großbritannien kam es in den 1890er-Jahren als Ludo – lateinisch „ich spiele“ – auf den Markt und wurde zum Familienklassiker.',
        'Ludo ist einfacher: ein Würfel, und mit einer 6 kommt eine Figur heraus. Verwandte unter anderen Namen gibt es weltweit, etwa Parchís in Spanien oder Mensch ärgere Dich nicht in Deutschland.'],
      quiz: [['Was bedeutet der Name „Pachisi“?', 'Fünfundzwanzig', 'Weg des Königs', 'Kreuz', 'Kaurimuschel'],
        ['Welche Stadt Akbars hat noch einen Hof mit riesigem Spielbrett?', 'Fatehpur Sikri', 'Der Qutb Minar in Delhi', 'Das Taj Mahal', 'Ellora'],
        ['Was bedeutet „ludo“ auf Lateinisch?', 'Ich spiele', 'Ich gewinne', 'Ich laufe', 'Ich werfe']] },
    go: { title: 'Was ein 1300 Jahre altes Go-Brett erzählt', lead: 'Das Go-Brett im Shōsōin hat 19 Linien wie heute – und 17 Blumenzeichen, anders als heute.',
      s: ['Go entstand im alten China. Der Legende nach erfand der weise König Yao es, um seinen Sohn zu unterrichten. Das Buch Mengzi aus vorchristlicher Zeit nennt einen Meisterspieler, Yi Qiu.',
        'Die Größe des Bretts hat sich vermutlich gewandelt: In früher Zeit wurden auch Bretter mit 17 Linien benutzt, später setzte sich das heutige 19er-Brett durch.',
        'Wann Go nach Japan kam, ist unklar, doch in der Nara-Zeit wurde es schon gespielt. Die Regeln für Mönche und Nonnen verboten Musik und Glücksspiel, erlaubten aber Go und Koto – ganz anders als beim Sugoroku.',
        'Das Go-Brett mit Intarsien im Shōsōin wurde als Schatz Kaiser Shōmus überliefert. Es hat 19 Linien wie heute, aber 17 Blumenzeichen, wo das heutige Brett 9 Sternpunkte hat. Seine zwei Schubladen sind gekoppelt: Zieht man eine heraus, kommt auch die andere. Im Shōsōin liegen außerdem Go-Steine aus rot und dunkelblau gefärbtem Elfenbein mit eingravierten Vögeln.',
        'In der Heian-Zeit zeigt die Geschichte vom Prinzen Genji Go-Partien. In der Edo-Zeit dienten Häuser wie die Hon’inbō dem Shogunat, und Go wurde zu einer Kunst, in der Berufsspieler ihr Können maßen.'],
      quiz: [['Wie viele Linien hat das Go-Brett im Shōsōin?', '19', '17', '13', '9'],
        ['Was erlaubten die Regeln Mönchen und Nonnen?', 'Go und Koto', 'Sugoroku', 'Glücksspiele', 'Kemari'],
        ['Wie viele Blumenzeichen hat das Shōsōin-Brett statt Sternpunkten?', '17', '9', '4', '25']] } });
  A('ru', { ex: { kofukuji: 'Фигуры сёги из Кофукудзи', shosoin: 'Доска для го из Сёсоина' }, paint: { chaupar: 'Шива и Парвати играют в чаупар' },
    shogi: { title: 'Когда в сёги появились сбросы?', lead: 'Во всей шахматной семье только в сёги можно вернуть взятую фигуру на доску как свою. Когда и почему появилось это правило?',
      s: ['Индийский предок шахмат распространился на запад и восток; в Японии он стал сёги. Древнейшие фигуры сёги в Японии — 16 штук, найденных при раскопках в начале 1990-х на старой территории храма Кофукудзи в Наре. Вместе с ними нашли бирку с датой 1058 год (Тэнги 6), поэтому фигуры считают того же времени.',
        'Упоминают сёги и тексты той эпохи. «Новые записки о саругаку» середины XI века называют игру, а «Нитюрэки», собравший записи конца эпохи Хэйан, описывает «хэйанские сёги» с королями, золотыми и серебряными генералами, конями, копьями и пешками.',
        'В эпохи Камакура и Муромати появилось много больших вариантов с бóльшим числом фигур. «Малые сёги», предок нынешней игры, добавили ладью и слона — и фигуру, которой больше нет: пьяного слона.',
        'Считается, что правило сбросов появилось около XVI века. По преданию, император Го-Нара велел убрать из малых сёги пьяного слона, и сбросы, как полагают, возникли примерно тогда же.',
        'Почему — неясно. Одно объяснение: фигуры обеих сторон одного цвета и различаются лишь направлением, так что взятую фигуру легко использовать снова. Благодаря сбросам доска не пустеет, а ничьи редки.'],
      quiz: [['Какая дата стояла на бирке, найденной с фигурами Кофукудзи?', '1058 (Тэнги 6)', '701 (Тайхо 1)', '1582 (Тэнсё 10)', '1868 (Мэйдзи 1)'],
        ['Когда, как считают, появилось правило сбросов?', 'Около XVI века', 'Около VIII века', 'Около XIX века', 'В XX веке'],
        ['Какую причину называют тому, что взятые фигуры легко использовать?', 'Фигуры обеих сторон одного цвета и различаются направлением', 'Фигуры были из золота', 'На доске было мало клеток', 'Фигуры выбирали костями']] },
    pachisi: { title: 'Как пачиси стала лудо', lead: 'Игра на крестообразной доске индийских дворов сменила имя и попала в детские комнаты всего мира.',
      s: ['В Индии есть чаупар и пачиси: четверо игроков ведут фишки вокруг доски в форме креста. В чаупаре бросают длинные кости (паса), в пачиси — раковины каури. Название пачиси означает «двадцать пять» — наибольший результат броска раковин.',
        'Играли даже боги. На картине конца XVII века бог Шива и его супруга Парвати сидят у доски для чаупара на тигровой шкуре.',
        'В Фатехпур-Сикри, городе могольского императора Акбара (XVI век), во дворе до сих пор выложена огромная крестообразная доска. Говорят, Акбар играл, используя вместо фишек людей в цветных одеждах.',
        'В XIX веке игра пересекла моря. В Америке её продавали как «Парчизи», товарный знак зарегистрирован в 1874 году. В Британии в 1890-х её выпустили под названием «Лудо» (по-латыни «я играю»), и она стала семейной классикой.',
        'Лудо проще: одна кость, и фишка выходит при шестёрке. Родственники с другими именами есть по всему миру — «Парчис» в Испании, «Не сердись» (Mensch ärgere Dich nicht) в Германии.'],
      quiz: [['Что означает название «пачиси»?', 'Двадцать пять', 'Царский путь', 'Крест', 'Раковина каури'],
        ['В каком городе Акбара сохранился двор с огромной доской?', 'Фатехпур-Сикри', 'Кутб-Минар в Дели', 'Тадж-Махал', 'Эллора'],
        ['Что означает «ludo» по-латыни?', 'Я играю', 'Я побеждаю', 'Я бегу', 'Я бросаю']] },
    go: { title: 'Что рассказывает доска для го возрастом 1300 лет', lead: 'У доски для го из Сёсоина 19 линий, как сейчас, — и 17 знаков-цветков, в отличие от нынешних досок.',
      s: ['Го возникла в Древнем Китае. По легенде, мудрый царь Яо придумал её, чтобы учить сына. В книге «Мэн-цзы», написанной до нашей эры, упоминается мастер игры И Цю.',
        'Считается, что размер доски менялся: в ранние времена использовали и доски в 17 линий, а позже распространилась нынешняя доска в 19 линий.',
        'Когда го попала в Японию, неясно, но в эпоху Нара в неё уже играли. Правила для монахов и монахинь запрещали музыку и азартные игры, но разрешали го и кото — совсем не так, как с сугороку.',
        'Доска с инкрустацией из Сёсоина дошла до нас как сокровище, связанное с императором Сёму. На ней 19 линий, как сейчас, но 17 знаков-цветков там, где у нынешней доски 9 звёздных точек. Два её ящика связаны: потянешь один — выдвигается и другой. В Сёсоине хранятся и камни для го из слоновой кости, окрашенной в красный и тёмно-синий, с вырезанными птицами.',
        'В эпоху Хэйан в «Повести о Гэндзи» изображены партии в го. В эпоху Эдо дома вроде Хонъимбо служили сёгунату, и го стало искусством, в котором профессиональные игроки состязались в мастерстве.'],
      quiz: [['Сколько линий на доске для го из Сёсоина?', '19', '17', '13', '9'],
        ['Что правила разрешали монахам и монахиням?', 'Го и кото', 'Сугороку', 'Азартные игры', 'Кэмари'],
        ['Сколько знаков-цветков на доске из Сёсоина вместо звёздных точек?', '17', '9', '4', '25']] } });
  A('tr', { ex: { kofukuji: 'Kōfuku-ji’den çıkan shogi taşları', shosoin: 'Shōsōin go tahtası' }, paint: { chaupar: 'Çaupar oynayan Şiva ve Parvati' },
    shogi: { title: 'Shogi’de alınan taşları geri koyma kuralı ne zaman doğdu?', lead: 'Bütün satranç ailesinde yalnızca shogi, alınan taşları kendi taşın olarak tahtaya geri koymana izin verir. Bu kural ne zaman ve neden ortaya çıktı?',
      s: ['Satrancın Hint atası doğuya ve batıya yayıldı; Japonya’da shogi oldu. Japonya’nın en eski shogi taşları, 1990’ların başında Nara’daki Kōfuku-ji’nin eski alanında yapılan kazıda çıkan 16 taştır. Yanlarında 1058 (Tenki 6) tarihli bir etiket bulunduğu için taşların da aynı döneme ait olduğu düşünülür.',
        'Dönemin yazıları da shogi’den söz eder. 11. yüzyıl ortasından Shin Sarugaku-ki oyunun adını anar; Heian döneminin sonundaki kayıtları toplayan Nichūreki ise krallar, altın ve gümüş generaller, atlar, mızraklar ve piyonlarla oynanan “Heian shogi”sini anlatır.',
        'Kamakura ve Muromachi dönemlerinde daha çok taşlı büyük biçimler doğdu. Bugünkü oyunun atası olan “küçük shogi” kale ve fili ekledi — bir de artık olmayan bir taşı: sarhoş fili.',
        'Taşları geri koyma kuralının 16. yüzyıl dolaylarında doğduğu düşünülür. Rivayete göre İmparator Go-Nara sarhoş fili küçük shogi’den çıkarttı; kuralın da o sıralarda başladığı sanılır.',
        'Nedeni belli değil. Bir açıklama: iki tarafın taşları aynı renktedir ve yalnızca yönleriyle ayrılır; bu yüzden alınan bir taş kolayca yeniden kullanılır. Bu kural sayesinde tahta boşalmaz ve beraberlik nadirdir.'],
      quiz: [['Kōfuku-ji taşlarıyla bulunan etikette hangi tarih yazıyordu?', '1058 (Tenki 6)', '701 (Taihō 1)', '1582 (Tenshō 10)', '1868 (Meiji 1)'],
        ['Geri koyma kuralının ne zaman doğduğu düşünülür?', '16. yüzyıl dolaylarında', '8. yüzyıl dolaylarında', '19. yüzyıl dolaylarında', '20. yüzyılda'],
        ['Alınan taşların kolay kullanılmasının nedeni olarak ne gösterilir?', 'İki tarafın taşları aynı renkte, yönle ayrılır', 'Taşlar altındandı', 'Tahtada az kare vardı', 'Taşlar zarla seçilirdi']] },
    pachisi: { title: 'Paçisi nasıl ludo oldu', lead: 'Hint saraylarında oynanan haç biçimli bir tahta oyunu adını değiştirdi ve dünyanın dört bir yanındaki çocuk odalarına ulaştı.',
      s: ['Hindistan’da çaupar ve paçisi oyunları vardır: dört oyuncu taşlarını haç biçimli bir tahtanın çevresinde ilerletir. Çauparda uzun zarlar (pasa), paçiside atılan kauri kabukları kullanılır. Paçisi adı “yirmi beş” demektir; kabuklarla atılabilen en yüksek sayıdır.',
        'Tanrılar bile oynardı. 17. yüzyıl sonundan bir resimde tanrı Şiva ve eşi Parvati, bir kaplan postu üzerinde çaupar tahtasının başında oturur.',
        'Babür imparatoru Ekber’in (16. yüzyıl) şehri Fatehpur Sikri’de bir avlunun zemininde hâlâ dev bir haç biçimli tahta durur. Ekber’in renkli giysili insanları taş olarak kullanıp oynadığı anlatılır.',
        '19. yüzyılda oyun denizleri aştı. ABD’de “Parcheesi” adıyla satıldı ve 1874’te marka olarak tescil edildi. Britanya’da 1890’larda “Ludo” (Latince “oynuyorum”) adıyla satışa çıktı ve bir aile klasiği oldu.',
        'Ludo daha basittir: tek zar vardır ve taş 6 gelince çıkar. Dünyanın her yerinde başka adlarla akrabaları vardır; İspanya’da parchís, Almanya’da Mensch ärgere Dich nicht (“Kızma birader”) gibi.'],
      quiz: [['“Paçisi” adı ne demektir?', 'Yirmi beş', 'Kralın yolu', 'Haç', 'Kauri kabuğu'],
        ['Ekber’in hangi şehrinde dev tahtalı avlu hâlâ durur?', 'Fatehpur Sikri', 'Delhi’deki Kutub Minar', 'Tac Mahal', 'Ellora'],
        ['“Ludo” Latincede ne demektir?', 'Oynuyorum', 'Kazanıyorum', 'Koşuyorum', 'Atıyorum']] },
    go: { title: '1300 yıllık bir go tahtasının anlattıkları', lead: 'Shōsōin’deki go tahtasında bugünkü gibi 19 çizgi var — ve bugünkünden farklı olarak 17 çiçek işareti.',
      s: ['Go eski Çin’de doğdu. Efsaneye göre bilge kral Yao onu oğlunu eğitmek için yarattı. Milattan önce yazılmış Mencius kitabı, oyunun ustası Yi Qiu’nun adını anar.',
        'Tahtanın büyüklüğünün zamanla değiştiği düşünülür: eski dönemlerde 17 çizgili tahtalar da kullanıldı, sonra bugünkü 19 çizgili tahta yaygınlaştı.',
        'Go’nun Japonya’ya ne zaman geldiği belli değil ama Nara döneminde oynanıyordu. Keşişler ve rahibeler için kurallar müziği ve kumarı yasaklarken go ve koto’ya izin veriyordu — sugoroku’dan çok farklı bir tutum.',
        'Shōsōin’deki kakmalı go tahtası, İmparator Shōmu’yla bağlantılı bir hazine olarak günümüze ulaştı. Bugünkü gibi 19 çizgisi var ama bugünkü tahtanın 9 yıldız noktası olan yerlerde 17 çiçek işareti var. İki çekmecesi birbirine bağlıdır: birini çekince öteki de çıkar. Shōsōin’de ayrıca kırmızı ve lacivert boyanmış, kuş desenleri oyulmuş fildişi go taşları da saklanır.',
        'Heian döneminde Genji’nin Hikâyesi go oynayanları anlatır. Edo döneminde Hon’inbō gibi evler şogunluğa hizmet etti ve go, profesyonel oyuncuların ustalık yarıştırdığı bir sanata dönüştü.'],
      quiz: [['Shōsōin go tahtasında kaç çizgi var?', '19', '17', '13', '9'],
        ['Kurallar keşişlere ve rahibelere neye izin veriyordu?', 'Go ve koto', 'Sugoroku', 'Kumar', 'Kemari'],
        ['Shōsōin tahtasında yıldız noktaları yerine kaç çiçek işareti var?', '17', '9', '4', '25']] } });
  A('id', { ex: { kofukuji: 'Bidak shogi dari Kōfuku-ji', shosoin: 'Papan go Shōsōin' }, paint: { chaupar: 'Siwa dan Parwati bermain chaupar' },
    shogi: { title: 'Kapan aturan menurunkan bidak tawanan di shogi lahir?', lead: 'Dari seluruh keluarga catur, hanya shogi yang membolehkan bidak tawanan dipasang lagi sebagai milik sendiri. Kapan — dan mengapa — aturan ini muncul?',
      s: ['Leluhur catur dari India menyebar ke timur dan barat; di Jepang ia menjadi shogi. Bidak shogi tertua di Jepang adalah 16 bidak yang digali pada awal 1990-an di bekas lahan Kōfuku-ji, Nara. Bersama bidak itu ditemukan label bertanggal 1058 (Tenki 6), sehingga bidaknya diduga berasal dari masa yang sama.',
        'Tulisan zaman itu juga menyebut shogi. Shin Sarugaku-ki dari pertengahan abad ke-11 menyebut namanya, dan Nichūreki, yang menghimpun catatan akhir zaman Heian, menggambarkan “shogi Heian” dengan raja, jenderal emas dan perak, kuda, tombak, dan pion.',
        'Pada zaman Kamakura dan Muromachi muncul banyak bentuk besar dengan bidak lebih banyak. “Shogi kecil”, cikal bakal permainan sekarang, menambahkan benteng dan gajah menteri — juga bidak yang kini tak ada lagi: gajah mabuk.',
        'Aturan memasang kembali bidak tawanan diduga muncul sekitar abad ke-16. Menurut tradisi, Kaisar Go-Nara menyuruh gajah mabuk dibuang dari shogi kecil, dan aturan ini diduga mulai pada masa yang sama.',
        'Alasannya belum jelas. Satu penjelasan: bidak kedua pihak berwarna sama dan hanya dibedakan arah hadapnya, sehingga bidak tawanan mudah dipakai lagi. Berkat aturan ini, papan tak pernah kosong dan remis jarang terjadi.'],
      quiz: [['Tanggal berapa tertulis pada label yang ditemukan bersama bidak Kōfuku-ji?', '1058 (Tenki 6)', '701 (Taihō 1)', '1582 (Tenshō 10)', '1868 (Meiji 1)'],
        ['Kapan aturan bidak tawanan diduga muncul?', 'Sekitar abad ke-16', 'Sekitar abad ke-8', 'Sekitar abad ke-19', 'Pada abad ke-20'],
        ['Apa alasan yang disebut mengapa bidak tawanan mudah dipakai lagi?', 'Bidak kedua pihak sewarna, dibedakan arah hadapnya', 'Bidaknya dari emas', 'Petak papannya sedikit', 'Bidak dipilih dengan dadu']] },
    pachisi: { title: 'Bagaimana pachisi menjadi ludo', lead: 'Permainan papan berbentuk salib dari istana India berganti nama dan sampai ke kamar bermain di seluruh dunia.',
      s: ['India punya chaupar dan pachisi: empat pemain menjalankan bidak mengelilingi papan berbentuk salib. Chaupar memakai dadu panjang (pasa), pachisi memakai cangkang kauri yang dilempar. Nama pachisi berarti “dua puluh lima”, angka tertinggi dari lemparan kauri.',
        'Para dewa pun bermain. Lukisan dari akhir abad ke-17 menampilkan Dewa Siwa dan istrinya Parwati di depan papan chaupar di atas kulit harimau.',
        'Di Fatehpur Sikri, kota Kaisar Mughal Akbar (abad ke-16), sebuah halaman masih memiliki papan raksasa berbentuk salib di lantainya. Konon Akbar bermain dengan orang-orang berbaju warna-warni sebagai bidaknya.',
        'Pada abad ke-19 permainan ini menyeberangi lautan. Di Amerika ia dijual dengan nama Parcheesi, menjadi merek dagang pada 1874. Di Inggris ia dijual pada 1890-an dengan nama Ludo — bahasa Latin untuk “aku bermain” — dan menjadi permainan keluarga.',
        'Ludo lebih sederhana: satu dadu, dan angka 6 untuk mengeluarkan bidak. Kerabatnya dengan nama lain ada di seluruh dunia, seperti parchís di Spanyol dan Mensch ärgere Dich nicht (“Jangan marah”) di Jerman.'],
      quiz: [['Apa arti nama “pachisi”?', 'Dua puluh lima', 'Jalan raja', 'Salib', 'Cangkang kauri'],
        ['Kota Akbar mana yang masih punya halaman berpapan raksasa?', 'Fatehpur Sikri', 'Qutb Minar di Delhi', 'Taj Mahal', 'Ellora'],
        ['Apa arti “ludo” dalam bahasa Latin?', 'Aku bermain', 'Aku menang', 'Aku berlari', 'Aku melempar']] },
    go: { title: 'Kisah papan go berusia 1.300 tahun', lead: 'Papan go di Shōsōin punya 19 garis seperti sekarang — dan 17 tanda bunga, tidak seperti sekarang.',
      s: ['Go lahir di Tiongkok kuno. Menurut legenda, raja bijak Yao menciptakannya untuk mendidik putranya. Kitab Mencius, dari sebelum Masehi, menyebut seorang ahli permainan ini, Yi Qiu.',
        'Ukuran papan diduga berubah seiring waktu: pada masa awal papan 17 garis juga dipakai, lalu papan 19 garis seperti sekarang menyebar.',
        'Kapan go sampai ke Jepang belum jelas, tetapi pada zaman Nara sudah dimainkan. Aturan bagi biksu dan biksuni melarang musik dan judi, tetapi membolehkan go dan koto — sangat berbeda dari perlakuan terhadap sugoroku.',
        'Papan go bertatah di Shōsōin diwariskan sebagai pusaka yang terkait dengan Kaisar Shōmu. Garisnya 19 seperti sekarang, tetapi ada 17 tanda bunga di tempat papan sekarang memiliki 9 titik bintang. Dua lacinya saling terhubung: menarik satu membuat yang lain ikut keluar. Shōsōin juga menyimpan batu go dari gading yang diwarnai merah dan biru tua, diukir dengan burung.',
        'Pada zaman Heian, Hikayat Genji menggambarkan orang bermain go. Pada zaman Edo, keluarga seperti Hon’inbō mengabdi pada keshogunan, dan go menjadi seni tempat pemain profesional beradu kemahiran.'],
      quiz: [['Berapa garis papan go Shōsōin?', '19', '17', '13', '9'],
        ['Apa yang dibolehkan aturan bagi biksu dan biksuni?', 'Go dan koto', 'Sugoroku', 'Judi', 'Kemari'],
        ['Berapa tanda bunga di papan Shōsōin sebagai ganti titik bintang?', '17', '9', '4', '25']] } });
  A('hi', { ex: { kofukuji: 'कोफ़ुकु‑जी से निकले शोगी मोहरे', shosoin: 'शोसोइन का गो बोर्ड' }, paint: { chaupar: 'चौपड़ खेलते शिव और पार्वती' },
    shogi: { title: 'शोगी में पकड़े मोहरे वापस रखने का नियम कब बना?', lead: 'शतरंज के पूरे परिवार में सिर्फ़ शोगी में पकड़े गए मोहरे को अपना बनाकर फिर बोर्ड पर रखा जा सकता है। यह नियम कब और क्यों बना?',
      s: ['शतरंज का भारतीय पूर्वज पूरब और पश्चिम में फैला; जापान में वह शोगी बना। जापान के सबसे पुराने शोगी मोहरे 16 हैं, जो 1990 के दशक की शुरुआत में नारा के कोफ़ुकु‑जी के पुराने परिसर में खुदाई से मिले। उनके साथ 1058 (तेनकी 6) की तारीख़ वाली एक पट्टी मिली, इसलिए मोहरे भी उसी समय के माने जाते हैं।',
        'उस दौर के लेखों में भी शोगी आता है। 11वीं सदी के मध्य की "शिन सारुगाकु‑की" में इसका नाम है, और हेइआन काल के अंत के अभिलेख जुटाने वाली "निचूरेकी" में राजा, सोने‑चाँदी के सेनापति, घोड़े, भाले और प्यादों वाले "हेइआन शोगी" का वर्णन है।',
        'कामाकुरा और मुरोमाची काल में ज़्यादा मोहरों वाले कई बड़े रूप बने। आज के खेल के पूर्वज "छोटे शोगी" में रुख़ और ऊँट जोड़े गए — और एक ऐसा मोहरा भी, जो अब नहीं है: नशे में धुत हाथी।',
        'माना जाता है कि पकड़े मोहरे वापस रखने का नियम लगभग 16वीं सदी में बना। परंपरा कहती है कि सम्राट गो‑नारा ने छोटे शोगी से नशे वाला हाथी हटवाया, और माना जाता है कि यह नियम भी लगभग तभी शुरू हुआ।',
        'ऐसा क्यों हुआ, साफ़ नहीं। एक व्याख्या यह है: दोनों पक्षों के मोहरे एक ही रंग के होते हैं और सिर्फ़ दिशा से पहचाने जाते हैं, इसलिए पकड़ा मोहरा आसानी से दोबारा इस्तेमाल हो जाता है। इसी नियम से बोर्ड ख़ाली नहीं होता और ड्रॉ बहुत कम होते हैं।'],
      quiz: [['कोफ़ुकु‑जी के मोहरों के साथ मिली पट्टी पर कौन‑सी तारीख़ थी?', '1058 (तेनकी 6)', '701 (ताइहो 1)', '1582 (तेनशो 10)', '1868 (मेइजी 1)'],
        ['माना जाता है कि मोहरे वापस रखने का नियम कब बना?', 'लगभग 16वीं सदी में', 'लगभग 8वीं सदी में', 'लगभग 19वीं सदी में', '20वीं सदी में'],
        ['पकड़े मोहरे आसानी से दोबारा इस्तेमाल होने का कारण क्या बताया जाता है?', 'दोनों पक्षों के मोहरे एक रंग के, दिशा से पहचान', 'मोहरे सोने के थे', 'बोर्ड में कम खाने थे', 'मोहरे पासे से चुने जाते थे']] },
    pachisi: { title: 'पचीसी लूडो कैसे बनी', lead: 'भारतीय दरबारों में खेला जाने वाला क्रॉस‑आकार का बोर्ड‑खेल नाम बदलकर दुनिया भर के बच्चों के कमरों तक पहुँचा।',
      s: ['भारत में चौपड़ और पचीसी नाम के खेल हैं: चार खिलाड़ी क्रॉस‑आकार के बोर्ड के चारों ओर गोटियाँ चलाते हैं। चौपड़ में लंबे पासे (पासा) और पचीसी में कौड़ियाँ फेंकी जाती हैं। पचीसी का अर्थ है "पच्चीस" — कौड़ियों से आने वाला सबसे बड़ा अंक।',
        'देवता भी खेलते थे। 17वीं सदी के अंत की एक चित्रकृति में भगवान शिव और पार्वती बाघ की खाल पर चौपड़ के बोर्ड के पास बैठे हैं।',
        'मुग़ल बादशाह अकबर (16वीं सदी) के नगर फ़तेहपुर सीकरी के एक आँगन के फ़र्श पर आज भी एक विशाल क्रॉस‑आकार का बोर्ड बना है। कहा जाता है कि अकबर रंगीन कपड़े पहने लोगों को गोटी बनाकर खेलता था।',
        '19वीं सदी में यह खेल समंदर पार गया। अमेरिका में यह "पारचीज़ी" नाम से बिका और 1874 में ट्रेडमार्क बना। ब्रिटेन में 1890 के दशक में यह "लूडो" (लैटिन में "मैं खेलता हूँ") नाम से बाज़ार में आया और परिवारों का पसंदीदा बन गया।',
        'लूडो सरल है: एक पासा, और 6 आने पर गोटी बाहर आती है। दूसरे नामों वाले इसके रिश्तेदार पूरी दुनिया में हैं, जैसे स्पेन का पारचीस और जर्मनी का "मेन्श एर्गेरे डिश निष्ट" ("ग़ुस्सा मत हो")।'],
      quiz: [['"पचीसी" नाम का अर्थ क्या है?', 'पच्चीस', 'राजा का रास्ता', 'क्रॉस', 'कौड़ी'],
        ['अकबर के किस नगर में विशाल बोर्ड वाला आँगन आज भी है?', 'फ़तेहपुर सीकरी', 'दिल्ली की क़ुतुब मीनार', 'ताज महल', 'एलोरा'],
        ['लैटिन में "लूडो" का अर्थ क्या है?', 'मैं खेलता हूँ', 'मैं जीतता हूँ', 'मैं दौड़ता हूँ', 'मैं फेंकता हूँ']] },
    go: { title: '1300 साल पुराना गो बोर्ड क्या बताता है', lead: 'शोसोइन के गो बोर्ड पर आज जैसी 19 रेखाएँ हैं — और आज से अलग, 17 फूल‑चिह्न।',
      s: ['गो प्राचीन चीन में जन्मा। किंवदंती है कि ज्ञानी राजा याओ ने इसे अपने बेटे को सिखाने के लिए बनाया। ईसा पूर्व की पुस्तक "मेंगज़ी" में इस खेल के उस्ताद यी चिउ का नाम आता है।',
        'माना जाता है कि बोर्ड का आकार समय के साथ बदला: शुरुआती दौर में 17 रेखाओं वाले बोर्ड भी चलते थे, बाद में आज का 19 रेखाओं वाला बोर्ड फैला।',
        'गो जापान कब पहुँचा, साफ़ नहीं, पर नारा काल में यह खेला जाता था। भिक्षुओं और भिक्षुणियों के नियम संगीत और जुए पर रोक लगाते थे, पर गो और कोतो की छूट देते थे — सुगोरोकु से बिल्कुल अलग बरताव।',
        'शोसोइन का जड़ाऊ गो बोर्ड सम्राट शोमु से जुड़े ख़ज़ाने के रूप में चला आया है। इसमें आज जैसी 19 रेखाएँ हैं, पर जहाँ आज के बोर्ड पर 9 तारा‑बिंदु होते हैं, वहाँ इसमें 17 फूल‑चिह्न हैं। इसकी दोनों दराज़ें जुड़ी हैं: एक खींचो तो दूसरी भी निकल आती है। शोसोइन में लाल और गहरे नीले रंग में रँगे हाथीदाँत के, पक्षियों की नक़्क़ाशी वाले गो पत्थर भी हैं।',
        'हेइआन काल की "गेंजी की कथा" में गो खेलने के दृश्य हैं। एदो काल में होन’इम्बो जैसे घरानों ने शोगुनशाही की सेवा की, और गो पेशेवर खिलाड़ियों के हुनर की होड़ वाली कला बन गया।'],
      quiz: [['शोसोइन के गो बोर्ड में कितनी रेखाएँ हैं?', '19', '17', '13', '9'],
        ['भिक्षुओं और भिक्षुणियों को किस खेल की छूट थी?', 'गो और कोतो', 'सुगोरोकु', 'जुआ', 'केमारी'],
        ['शोसोइन बोर्ड पर तारा‑बिंदुओं की जगह कितने फूल‑चिह्न हैं?', '17', '9', '4', '25']] } });
  A('ar', { ex: { kofukuji: 'قطع شوغي من كوفوكو-جي', shosoin: 'لوحة غو في شوسوئين' }, paint: { chaupar: 'شيفا وبارفاتي يلعبان التشوبار' },
    shogi: { title: 'متى وُلدت قاعدة إعادة القطع المأسورة في الشوغي؟', lead: 'في عائلة الشطرنج كلها، وحده الشوغي يتيح لك أن تعيد القطعة المأسورة إلى اللوحة لتصبح من قطعك. متى ولماذا ظهرت هذه القاعدة؟',
      s: ['انتشر الجدّ الهندي للشطرنج شرقًا وغربًا، وصار في اليابان شوغي. أقدم قطع شوغي في اليابان 16 قطعة عُثر عليها في أوائل التسعينيات في الحرم القديم لمعبد كوفوكو-جي في نارا. ووُجدت معها بطاقة مؤرخة بعام 1058 (تنكي 6)، لذا يُعتقد أن القطع من الزمن نفسه.',
        'وتذكر كتابات ذلك العصر الشوغي أيضًا. فكتاب «شين ساروغاكو-كي» من منتصف القرن الحادي عشر يذكر اسمه، وكتاب «نيتشوريكي» الذي يجمع سجلات أواخر عصر هييان يصف «شوغي هييان» بالملوك والقادة الذهبيين والفضيين والخيول والرماح والجنود.',
        'وفي عصري كاماكورا وموروماتشي ظهرت أشكال كبيرة كثيرة بقطع أكثر. وأضاف «الشوغي الصغير»، سلف اللعبة الحالية، الرخ والفيل — وقطعة لم تعد موجودة: «الفيل السكران».',
        'يُعتقد أن قاعدة إعادة القطع ظهرت نحو القرن السادس عشر. وتروي التقاليد أن الإمبراطور غو-نارا أمر بإزالة الفيل السكران من الشوغي الصغير، ويُرجَّح أن القاعدة بدأت في ذلك الوقت تقريبًا.',
        'لا يُعرف السبب يقينًا. ومن التفسيرات أن قطع الطرفين بلون واحد ولا تتميز إلا باتجاهها، فيسهل استخدام القطعة المأسورة من جديد. وبفضل هذه القاعدة لا تفرغ اللوحة، والتعادل نادر.'],
      quiz: [['ما التاريخ المكتوب على البطاقة التي وُجدت مع قطع كوفوكو-جي؟', '1058 (تنكي 6)', '701 (تايهو 1)', '1582 (تينشو 10)', '1868 (ميجي 1)'],
        ['متى يُعتقد أن قاعدة إعادة القطع ظهرت؟', 'نحو القرن السادس عشر', 'نحو القرن الثامن', 'نحو القرن التاسع عشر', 'في القرن العشرين'],
        ['ما السبب المذكور لسهولة إعادة استخدام القطع المأسورة؟', 'قطع الطرفين بلون واحد وتتميز بالاتجاه', 'كانت القطع من الذهب', 'كانت مربعات اللوحة قليلة', 'كانت القطع تُختار بالنرد']] },
    pachisi: { title: 'كيف صارت البتشيسي لودو', lead: 'لعبة لوحة على شكل صليب كانت تُلعب في البلاطات الهندية غيّرت اسمها ووصلت إلى غرف لعب الأطفال في العالم كله.',
      s: ['في الهند لعبتا التشوبار والبتشيسي: يحرّك أربعة لاعبين قطعهم حول لوحة على شكل صليب. يُستخدم في التشوبار نرد طويل (باسا)، وفي البتشيسي أصداف الودع. ومعنى اسم البتشيسي «خمسة وعشرون»، وهو أعلى ما تعطيه رمية الأصداف.',
        'حتى الآلهة كانت تلعب. ففي لوحة من أواخر القرن السابع عشر يجلس الإله شيفا وزوجته بارفاتي أمام لوحة تشوبار على جلد نمر.',
        'وفي فاتحبور سيكري، مدينة الإمبراطور المغولي أكبر (القرن السادس عشر)، ما زالت ساحة تحمل في أرضيتها لوحة ضخمة على شكل صليب. ويُروى أن أكبر كان يلعب مستخدمًا أشخاصًا بملابس ملونة قطعًا.',
        'وفي القرن التاسع عشر عبرت اللعبة البحار. ففي أمريكا بيعت باسم «بارتشيزي» وسُجّلت علامةً تجارية سنة 1874. وفي بريطانيا طُرحت في تسعينيات القرن التاسع عشر باسم «لودو» (باللاتينية «أنا ألعب») وصارت من ألعاب العائلة المفضلة.',
        'اللودو أبسط: نرد واحد، وتخرج القطعة عند الرقم 6. ولها أقارب بأسماء أخرى في أنحاء العالم، مثل «بارتشيس» في إسبانيا و«لا تغضب» (Mensch ärgere Dich nicht) في ألمانيا.'],
      quiz: [['ما معنى اسم «البتشيسي»؟', 'خمسة وعشرون', 'طريق الملك', 'صليب', 'صدفة الودع'],
        ['أي مدينة لأكبر ما زالت فيها ساحة بلوحة ضخمة؟', 'فاتحبور سيكري', 'قطب منار في دلهي', 'تاج محل', 'إلورا'],
        ['ما معنى «لودو» باللاتينية؟', 'أنا ألعب', 'أنا أفوز', 'أنا أركض', 'أنا أرمي']] },
    go: { title: 'ما الذي تحكيه لوحة غو عمرها 1300 عام', lead: 'لوحة الغو في شوسوئين فيها 19 خطًا كما اليوم — و17 علامة زهرة، على خلاف لوحات اليوم.',
      s: ['وُلدت لعبة الغو في الصين القديمة. وتقول الأسطورة إن الملك الحكيم ياو صنعها ليعلّم ابنه. ويذكر كتاب «منشيوس» الذي يسبق الميلاد اسم أحد أساتذة اللعبة، يي تشيو.',
        'يُعتقد أن حجم اللوحة تغيّر مع الزمن: ففي العصور المبكرة استُخدمت أيضًا لوحات من 17 خطًا، ثم انتشرت لوحة الـ19 خطًا الحالية.',
        'لا يُعرف متى وصل الغو إلى اليابان، لكنه كان يُلعب في عصر نارا. وكانت قواعد الرهبان والراهبات تحظر الموسيقى والقمار، لكنها تسمح بالغو والكوتو — معاملة مختلفة تمامًا عن السوغوروكو.',
        'وصلتنا لوحة الغو المطعّمة في شوسوئين كنزًا مرتبطًا بالإمبراطور شومو. فيها 19 خطًا كما اليوم، لكن فيها 17 علامة زهرة حيث تحمل لوحة اليوم 9 نقاط نجمية. ودُرجاها متصلان: إذا سحبت أحدهما خرج الآخر. ويحفظ شوسوئين أيضًا أحجار غو من العاج المصبوغ بالأحمر والأزرق الداكن، محفورًا عليها طيور.',
        'وفي عصر هييان تصوّر «حكاية غينجي» مشاهد للعب الغو. وفي عصر إيدو خدمت بيوت مثل هون-إنبو الشوغونية، وصار الغو فنًا يتبارى فيه لاعبون محترفون.'],
      quiz: [['كم خطًا في لوحة الغو بشوسوئين؟', '19', '17', '13', '9'],
        ['بماذا سمحت القواعد للرهبان والراهبات؟', 'الغو والكوتو', 'السوغوروكو', 'القمار', 'الكيماري'],
        ['كم علامة زهرة في لوحة شوسوئين بدل النقاط النجمية؟', '17', '9', '4', '25']] } });
