(T => { const C = {"ja": [["大英博物館の「ウルのゲーム」。所蔵品の部屋で3Dで回して見られます"], ["20のマスと5つのロゼット（花の模様）。緑の数字は、片方の駒が進む順番（復元ルール）", "4面体のさいころ4つを投げたときの出方（16通りのうち）"]], "en": [["The Royal Game of Ur in the British Museum — turn it round in 3D in the Collection room"], ["The twenty squares and five rosettes. The green numbers are one player’s road, square by square (reconstructed rules)", "How four tetrahedral dice fall (out of 16 equally likely ways)"]], "zh": [["大英博物馆藏的“乌尔王家游戏”，可在馆藏展厅里以3D旋转观看"], ["20个格子与5个玫瑰花饰。绿色数字是一方棋子前进的顺序（复原规则）", "掷4枚四面体骰子时各点数出现的次数（16种情况中）"]], "zh-TW": [["大英博物館藏的「烏爾王家遊戲」，可在館藏展廳裡以3D旋轉觀看"], ["20個格子與5個玫瑰花飾。綠色數字是一方棋子前進的順序（復原規則）", "擲4枚四面體骰子時各點數出現的次數（16種情況中）"]], "ko": [["대영박물관의 ‘우르의 왕실 게임’. 소장품 전시실에서 3D로 돌려 볼 수 있습니다"], ["20칸과 5개의 로제트(꽃무늬). 초록 숫자는 한쪽 말이 나아가는 순서(복원 규칙)", "사면체 주사위 4개를 던졌을 때 나오는 비율(16가지 중)"]], "es": [["El Juego Real de Ur del Museo Británico; gíralo en 3D en la sala Colección"], ["Las veinte casillas y las cinco rosetas. Los números verdes son el camino de un jugador, casilla a casilla (reglas reconstruidas)", "Cómo caen cuatro dados tetraédricos (de 16 formas igual de probables)"]], "fr": [["Le jeu royal d’Ur du British Museum — à faire tourner en 3D dans la salle Collection"], ["Les vingt cases et les cinq rosettes. Les numéros verts suivent le chemin d’un joueur, case par case (règles reconstituées)", "Comment tombent quatre dés tétraédriques (sur 16 cas également probables)"]], "pt": [["O Jogo Real de Ur do Museu Britânico — gire-o em 3D na sala Acervo"], ["As vinte casas e as cinco rosetas. Os números verdes são o caminho de um jogador, casa a casa (regras reconstruídas)", "Como caem quatro dados tetraédricos (em 16 casos igualmente prováveis)"]], "de": [["Das Königliche Spiel von Ur im British Museum – im Raum „Sammlung“ in 3D drehbar"], ["Die zwanzig Felder und die fünf Rosetten. Die grünen Zahlen zeigen den Weg eines Spielers Feld für Feld (rekonstruierte Regeln)", "Wie vier Tetraeder-Würfel fallen (von 16 gleich wahrscheinlichen Fällen)"]], "ru": [["Царская игра Ура в Британском музее — её можно повернуть в 3D в зале «Собрание»"], ["Двадцать клеток и пять розеток. Зелёные числа — путь одного игрока по клеткам (восстановленные правила)", "Как выпадают четыре тетраэдра (из 16 равновероятных случаев)"]], "tr": [["British Museum’daki Ur’un Kraliyet Oyunu — Koleksiyon odasında 3D olarak çevirebilirsin"], ["Yirmi hane ve beş gül motifi. Yeşil sayılar bir oyuncunun haneden haneye yolu (yeniden kurulan kurallar)", "Dört dörtyüzlü zarın düşüşleri (eşit olasılıklı 16 durumdan)"]], "id": [["Permainan Kerajaan Ur di British Museum — putar dalam 3D di ruang Koleksi"], ["Dua puluh petak dan lima roset. Angka hijau adalah jalur satu pemain, petak demi petak (aturan rekonstruksi)", "Cara jatuhnya empat dadu tetrahedron (dari 16 kemungkinan yang sama besar)"]], "hi": [["ब्रिटिश संग्रहालय का \"उर का शाही खेल\" — संग्रह कक्ष में इसे 3D में घुमाकर देखें"], ["बीस ख़ाने और पाँच रोज़ेट। हरे अंक एक खिलाड़ी का रास्ता ख़ाना‑दर‑ख़ाना दिखाते हैं (पुनर्निर्मित नियम)", "चार चतुष्फलक पासे कैसे गिरते हैं (16 बराबर संभावनाओं में से)"]], "ar": [["لعبة أور الملكية في المتحف البريطاني — أدِرها ثلاثية الأبعاد في قاعة المقتنيات"], ["الخانات العشرون والوردات الخمس. الأرقام الخضراء طريق لاعب واحد خانةً خانة (القواعد المعاد بناؤها)", "كيف تسقط أربعة أحجار نرد رباعية الأوجه (من 16 حالة متساوية الاحتمال)"]]};
  Object.keys(C).forEach(l => { const m = T[l] && T[l].ur && T[l].ur.more; if (!m) return; m[0].cap = C[l][0]; m[1].cap = C[l][1]; }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (8): story 2 (liubo) made fuller — key points, sections with figure captions, timeline */
(T => { const D = {"ja": {"liubo": {"kf": ["戦国時代から漢（紀元前5世紀〜紀元3世紀）にかけて、中国で大流行した", "盤にはT・L・Vを組み合わせた独特の線、投げるのは細い棒", "漢が滅びると急にすたれ、遊び方は今も完全にはわかっていない"], "more": [{"h": "T・L・Vの盤", "p": ["六博の盤は正方形で、まん中に四角、各辺の中ほどにT、そのまわりにL、四すみにVの形の線が刻まれています。この線の上や間を駒が進んだと考えられています。", "同じ線は、鏡の裏の文様（TLV鏡）や日時計にも見られます。盤の形が天と地、四方を表す宇宙の図だと考えた研究者もいて、六博がただの遊びではなかったことを感じさせます。"], "cap": ["六博の盤の線（TLV文様）。四角の中心、各辺のT、角のLとVの組み合わせ"]}, {"h": "どうやって遊んだか", "p": ["2人がそれぞれ6つの駒を持ち、細い竹の棒（箸）を投げて進む数を決めた、というのが多くの研究者の考えです。「六博」の「六」は、この6本の棒か6つの駒から来たとされます。", "駒は進むと強い「梟（きょう）」になったらしく、紀元前3世紀ごろの詩『楚辞』の「招魂」には「梟と成りて牟（むさぼ）り、五白と呼ぶ」という一節があります。盤のまん中の「水」で「魚」を取り合う遊び方もあったと書かれています。"], "cap": ["漢の墓に納められた、六博を打つ2人の像（メトロポリタン美術館）"]}, {"h": "墓から出た道具", "p": ["湖南省長沙の馬王堆漢墓3号墓（紀元前168年ごろ）からは、漆塗りの箱に入った盤・駒・棒がそろって見つかりました。死者があの世でも遊べるように納めたものです。", "墓の壁や石に刻まれた画像石には、神仙たちが山の上で六博を打つ場面がたびたび描かれています。六博は不老長寿の世界と結びついた、特別な遊びでもあったのです。"], "cap": ["所蔵品の六博盤。博物館の所蔵品の部屋で3Dで見られます"]}], "tl": [["前5〜前3世紀（戦国時代）", "六博の盤が墓に納められはじめる"], ["前3世紀ごろ", "『楚辞』の「招魂」に六博を打つ様子が詠まれる"], ["前168年ごろ", "馬王堆漢墓3号墓に、盤・駒・棒の一式が納められる"], ["前206〜後220年（漢）", "皇帝から庶民まで大流行。画像石や鏡の文様にも"], ["唐（7〜10世紀）", "遊び方がわからなくなっていたと考えられる"], ["1993年", "尹湾漢墓から、盤の図を使う占いの文書が出る"], ["2010年代", "海昏侯・劉賀の墓から六博の竹簡が見つかる"]]}}, "en": {"liubo": {"kf": ["Hugely popular in China from the Warring States through the Han (5th century BC – 3rd century AD)", "A board cut with lines shaped like T, L and V; thin sticks thrown for the move", "It faded fast after the Han fell, and its rules are still not fully known"], "more": [{"h": "The TLV board", "p": ["A liubo board is square, with a square in the middle, a T at the middle of each side, L shapes around them and V shapes in the corners. The pieces are thought to have moved along and between these lines.", "The same lines appear on the backs of mirrors (“TLV mirrors”) and on sundials. Some scholars read the board as a map of the cosmos — heaven, earth and the four directions — a hint that liubo was more than a pastime."], "cap": ["The lines of a liubo board (the TLV pattern): a central square, a T on each side, L and V shapes toward the corners"]}, {"h": "How it was played", "p": ["Most scholars think each player had six pieces and threw thin bamboo sticks to decide the move. The “six” (liu) in the name is said to come from those six sticks or six pieces.", "A piece that advanced seems to have become a powerful “owl” (xiao). A poem of about the 3rd century BC, “Summoning the Soul” in the Songs of Chu, has the line “making an owl, they press on and call out ‘five whites!’”. Texts also describe a way of play in which pieces caught “fish” in the “water” at the centre of the board."], "cap": ["Two figures playing liubo, made for a Han tomb (The Metropolitan Museum of Art)"]}, {"h": "Sets from the tombs", "p": ["Tomb 3 at Mawangdui in Changsha, Hunan (about 168 BC), held a complete set — board, pieces and sticks — in a lacquered box, placed so the dead could play in the afterlife.", "Relief stones from tomb walls often show immortals playing liubo on mountaintops. The game was tied to the world of the immortals and long life — a special kind of play."], "cap": ["The museum’s liubo board — see it in 3D in the Collection room"]}], "tl": [["5th–3rd c. BC (Warring States)", "Liubo boards begin to be placed in tombs"], ["c. 3rd c. BC", "“Summoning the Soul” in the Songs of Chu describes a game of liubo"], ["c. 168 BC", "A full set — board, pieces, sticks — is laid in Mawangdui tomb 3"], ["206 BC – AD 220 (Han)", "Played by emperors and commoners alike; on reliefs and mirrors"], ["Tang (7th–10th c.)", "The rules are thought to have been forgotten"], ["1993", "A divination text using the board appears from the Yinwan Han tombs"], ["2010s", "Bamboo slips on liubo are found in the tomb of the Marquis of Haihun, Liu He"]]}}, "zh": {"liubo": {"kf": ["从战国到汉代（前5世纪—3世纪），在中国极为流行", "棋盘刻着T、L、V组合的独特线条，掷细棍决定步数", "汉亡后迅速衰落，玩法至今仍未完全弄清"], "more": [{"h": "T、L、V的棋盘", "p": ["六博棋盘是正方形，中央有方框，各边中间有T，周围有L，四角有V形的线。人们认为棋子就在这些线上或线间行进。", "同样的线条也见于铜镜背面（规矩镜）和日晷。有学者认为棋盘是象征天地四方的宇宙图，可见六博不只是消遣。"], "cap": ["六博棋盘的线条（TLV纹）：中央方框、各边的T、角上的L与V"]}, {"h": "怎么玩", "p": ["多数学者认为双方各有6枚棋子，掷细竹棍（箸）决定步数。“六博”的“六”据说来自这6根棍或6枚棋子。", "棋子前进后似乎会变成强大的“枭”。约公元前3世纪的《楚辞·招魂》中有“成枭而牟，呼五白些”一句。文献还记载了在棋盘中央的“水”里取“鱼”的玩法。"], "cap": ["汉墓随葬的对弈六博的两人俑（大都会艺术博物馆）"]}, {"h": "墓中出土的器具", "p": ["湖南长沙马王堆汉墓3号墓（约前168年）出土了装在漆盒里的棋盘、棋子和棍，一应俱全，是为了让墓主在另一个世界也能玩。", "墓壁和石刻的画像石上，常描绘仙人在山上对弈六博的场面。六博也是与长生不老的仙界相连的特别游戏。"], "cap": ["馆藏的六博棋盘，可在馆藏展厅以3D观看"]}], "tl": [["前5—前3世纪（战国）", "六博棋盘开始被放入墓中"], ["约前3世纪", "《楚辞·招魂》吟咏六博对弈"], ["约前168年", "马王堆汉墓3号墓放入棋盘、棋子、棍一套"], ["前206—220年（汉）", "上至皇帝下至百姓都热衷，见于画像石与铜镜"], ["唐（7—10世纪）", "玩法被认为已经失传"], ["1993年", "尹湾汉墓出土用棋盘图占卜的文书"], ["2010年代", "海昏侯刘贺墓出土六博竹简"]]}}, "zh-TW": {"liubo": {"kf": ["從戰國到漢代（前5世紀—3世紀），在中國極為流行", "棋盤刻著T、L、V組合的獨特線條，擲細棍決定步數", "漢亡後迅速衰落，玩法至今仍未完全弄清"], "more": [{"h": "T、L、V的棋盤", "p": ["六博棋盤是正方形，中央有方框，各邊中間有T，周圍有L，四角有V形的線。人們認為棋子就在這些線上或線間行進。", "同樣的線條也見於銅鏡背面（規矩鏡）和日晷。有學者認為棋盤是象徵天地四方的宇宙圖，可見六博不只是消遣。"], "cap": ["六博棋盤的線條（TLV紋）：中央方框、各邊的T、角上的L與V"]}, {"h": "怎麼玩", "p": ["多數學者認為雙方各有6枚棋子，擲細竹棍（箸）決定步數。「六博」的「六」據說來自這6根棍或6枚棋子。", "棋子前進後似乎會變成強大的「梟」。約公元前3世紀的《楚辭·招魂》中有「成梟而牟，呼五白些」一句。文獻還記載了在棋盤中央的「水」裡取「魚」的玩法。"], "cap": ["漢墓隨葬的對弈六博的兩人俑（大都會藝術博物館）"]}, {"h": "墓中出土的器具", "p": ["湖南長沙馬王堆漢墓3號墓（約前168年）出土了裝在漆盒裡的棋盤、棋子和棍，一應俱全，是為了讓墓主在另一個世界也能玩。", "墓壁和石刻的畫像石上，常描繪仙人在山上對弈六博的場面。六博也是與長生不老的仙界相連的特別遊戲。"], "cap": ["館藏的六博棋盤，可在館藏展廳以3D觀看"]}], "tl": [["前5—前3世紀（戰國）", "六博棋盤開始被放入墓中"], ["約前3世紀", "《楚辭·招魂》吟詠六博對弈"], ["約前168年", "馬王堆漢墓3號墓放入棋盤、棋子、棍一套"], ["前206—220年（漢）", "上至皇帝下至百姓都熱衷，見於畫像石與銅鏡"], ["唐（7—10世紀）", "玩法被認為已經失傳"], ["1993年", "尹灣漢墓出土用棋盤圖占卜的文書"], ["2010年代", "海昏侯劉賀墓出土六博竹簡"]]}}, "ko": {"liubo": {"kf": ["전국시대부터 한나라까지(기원전 5세기~3세기) 중국에서 크게 유행했다", "판에는 T·L·V를 조합한 독특한 선, 던지는 것은 가는 막대", "한나라가 망하자 급격히 쇠퇴해, 놀이 방법은 지금도 완전히 밝혀지지 않았다"], "more": [{"h": "T·L·V의 판", "p": ["육박 판은 정사각형으로, 가운데에 네모, 각 변 가운데에 T, 그 둘레에 L, 네 모서리에 V 모양의 선이 새겨져 있습니다. 말은 이 선 위나 사이를 나아갔다고 봅니다.", "같은 선은 거울 뒷면 무늬(TLV 거울)와 해시계에도 보입니다. 판을 하늘과 땅, 사방을 나타낸 우주의 그림으로 본 학자도 있어, 육박이 단순한 놀이가 아니었음을 느끼게 합니다."], "cap": ["육박 판의 선(TLV 무늬): 가운데 네모, 각 변의 T, 모서리 쪽의 L과 V"]}, {"h": "어떻게 놀았나", "p": ["두 사람이 각각 말 6개를 가지고 가는 대나무 막대를 던져 나아갈 수를 정했다는 것이 많은 학자의 생각입니다. ‘육박’의 ‘육’은 이 막대 6개나 말 6개에서 왔다고 합니다.", "말은 나아가면 강한 ‘효(梟)’가 된 듯하며, 기원전 3세기쯤의 『초사』 「초혼」에는 “효가 되어 몰아치며 오백을 외친다”는 구절이 있습니다. 판 가운데 ‘물’에서 ‘물고기’를 잡는 놀이 방법도 기록되어 있습니다."], "cap": ["한나라 무덤에 넣은, 육박을 두는 두 사람의 상(메트로폴리탄 미술관)"]}, {"h": "무덤에서 나온 도구", "p": ["후난성 창사의 마왕퇴 한묘 3호묘(기원전 168년경)에서는 칠기 상자에 든 판·말·막대가 한 벌로 나왔습니다. 죽은 이가 저세상에서도 놀 수 있도록 넣은 것입니다.", "무덤 벽이나 돌에 새긴 화상석에는 신선들이 산 위에서 육박을 두는 장면이 자주 그려집니다. 육박은 불로장생의 세계와 이어진 특별한 놀이이기도 했습니다."], "cap": ["소장품 육박 판. 박물관 소장품 전시실에서 3D로 볼 수 있습니다"]}], "tl": [["기원전 5~3세기(전국시대)", "육박 판이 무덤에 들어가기 시작한다"], ["기원전 3세기경", "『초사』 「초혼」에 육박 두는 모습이 읊어진다"], ["기원전 168년경", "마왕퇴 한묘 3호묘에 판·말·막대 한 벌이 들어간다"], ["기원전 206~기원후 220년(한)", "황제부터 서민까지 크게 유행, 화상석과 거울 무늬에도"], ["당(7~10세기)", "놀이 방법이 잊혔다고 본다"], ["1993년", "인완 한묘에서 판 그림으로 점치는 문서가 나온다"], ["2010년대", "해혼후 유하의 무덤에서 육박 죽간이 발견된다"]]}}, "es": {"liubo": {"kf": ["Muy popular en China desde los Reinos Combatientes hasta los Han (s. V a. C. – s. III d. C.)", "Un tablero con líneas en forma de T, L y V; se lanzaban palitos para mover", "Decayó deprisa tras la caída de los Han y sus reglas aún no se conocen del todo"], "more": [{"h": "El tablero TLV", "p": ["El tablero de liubo es cuadrado, con un cuadrado en el centro, una T en medio de cada lado, formas de L a su alrededor y de V en las esquinas. Se cree que las piezas avanzaban por estas líneas y entre ellas.", "Las mismas líneas aparecen en el dorso de espejos («espejos TLV») y en relojes de sol. Algunos estudiosos ven el tablero como un mapa del cosmos —cielo, tierra y los cuatro rumbos—, señal de que el liubo era más que un pasatiempo."], "cap": ["Las líneas de un tablero de liubo (patrón TLV): un cuadrado central, una T en cada lado, formas de L y V hacia las esquinas"]}, {"h": "Cómo se jugaba", "p": ["La mayoría de los estudiosos cree que cada jugador tenía seis piezas y lanzaba finos palitos de bambú para decidir el movimiento. El «seis» (liu) del nombre vendría de esos seis palitos o seis piezas.", "Una pieza que avanzaba parece que se convertía en un poderoso «búho» (xiao). Un poema de hacia el siglo III a. C., «Invocación del alma» de los Cantos de Chu, dice: «hecho búho, se lanza y grita “¡cinco blancos!”». Los textos describen también un modo de juego en que las piezas pescaban «peces» en el «agua» del centro."], "cap": ["Dos figuras jugando al liubo, hechas para una tumba Han (Museo Metropolitano de Arte)"]}, {"h": "Juegos de las tumbas", "p": ["La tumba 3 de Mawangdui, en Changsha (Hunan), de hacia el 168 a. C., guardaba un juego completo —tablero, piezas y palitos— en una caja lacada, para que el difunto pudiera jugar en el más allá.", "Los relieves de las paredes de las tumbas muestran a menudo a inmortales jugando al liubo en cumbres. El juego estaba unido al mundo de los inmortales y la larga vida."], "cap": ["El tablero de liubo del museo; míralo en 3D en la sala Colección"]}], "tl": [["s. V–III a. C. (Reinos Combatientes)", "Los tableros de liubo empiezan a ponerse en tumbas"], ["h. s. III a. C.", "«Invocación del alma» describe una partida de liubo"], ["h. 168 a. C.", "Un juego completo entra en la tumba 3 de Mawangdui"], ["206 a. C. – 220 d. C. (Han)", "Lo juegan emperadores y gente común; aparece en relieves y espejos"], ["Tang (s. VII–X)", "Se cree que las reglas ya se habían olvidado"], ["1993", "Aparece en las tumbas Han de Yinwan un texto adivinatorio con el tablero"], ["Años 2010", "Tablillas de bambú sobre el liubo en la tumba del marqués de Haihun, Liu He"]]}}, "fr": {"liubo": {"kf": ["Très populaire en Chine des Royaumes combattants aux Han (Ve s. av. J.-C. – IIIe s.)", "Un plateau aux lignes en T, L et V ; on lançait de fines baguettes pour avancer", "Il déclina vite après la chute des Han et ses règles ne sont toujours pas entièrement connues"], "more": [{"h": "Le plateau TLV", "p": ["Le plateau de liubo est carré, avec un carré au centre, un T au milieu de chaque côté, des L autour et des V dans les coins. Les pièces devaient avancer sur ces lignes et entre elles.", "Les mêmes lignes se retrouvent au dos de miroirs (« miroirs TLV ») et sur des cadrans solaires. Certains chercheurs y lisent une carte du cosmos — ciel, terre et quatre directions —, signe que le liubo était plus qu’un passe-temps."], "cap": ["Les lignes d’un plateau de liubo (motif TLV) : un carré central, un T sur chaque côté, des L et des V vers les coins"]}, {"h": "Comment on y jouait", "p": ["La plupart des chercheurs pensent que chaque joueur avait six pièces et lançait de fines baguettes de bambou pour fixer le coup. Le « six » (liu) du nom viendrait de ces six baguettes ou six pièces.", "Une pièce qui avançait devenait semble-t-il une puissante « chouette » (xiao). Un poème du IIIe s. av. J.-C. environ, « Rappel de l’âme » des Chants de Chu, dit : « devenue chouette, elle presse et l’on crie “cinq blancs !” ». Des textes décrivent aussi une manière de jouer où l’on pêchait des « poissons » dans l’« eau » au centre du plateau."], "cap": ["Deux figurines jouant au liubo, faites pour une tombe Han (Metropolitan Museum of Art)"]}, {"h": "Des jeux sortis des tombes", "p": ["La tombe 3 de Mawangdui, à Changsha (Hunan), vers 168 av. J.-C., contenait un jeu complet — plateau, pièces et baguettes — dans une boîte laquée, pour que le défunt puisse jouer dans l’au-delà.", "Les reliefs des murs de tombes montrent souvent des immortels jouant au liubo sur des sommets. Le jeu était lié au monde des immortels et à la longue vie."], "cap": ["Le plateau de liubo du musée — à voir en 3D dans la salle Collection"]}], "tl": [["Ve–IIIe s. av. J.-C. (Royaumes combattants)", "Des plateaux de liubo commencent à être déposés dans les tombes"], ["v. IIIe s. av. J.-C.", "« Rappel de l’âme » décrit une partie de liubo"], ["v. 168 av. J.-C.", "Un jeu complet entre dans la tombe 3 de Mawangdui"], ["206 av. J.-C. – 220 (Han)", "Joué par empereurs et gens du commun ; sur reliefs et miroirs"], ["Tang (VIIe–Xe s.)", "On pense que les règles étaient déjà oubliées"], ["1993", "Un texte divinatoire utilisant le plateau sort des tombes Han de Yinwan"], ["Années 2010", "Des lattes de bambou sur le liubo apparaissent dans la tombe du marquis de Haihun, Liu He"]]}}, "pt": {"liubo": {"kf": ["Muito popular na China dos Reinos Combatentes aos Han (séc. V a.C. – séc. III d.C.)", "Um tabuleiro com linhas em T, L e V; lançavam-se varetas finas para mover", "Decaiu depressa após a queda dos Han, e suas regras ainda não são totalmente conhecidas"], "more": [{"h": "O tabuleiro TLV", "p": ["O tabuleiro de liubo é quadrado, com um quadrado no centro, um T no meio de cada lado, formas de L em volta e de V nos cantos. Acredita-se que as peças avançavam sobre essas linhas e entre elas.", "As mesmas linhas aparecem no verso de espelhos (“espelhos TLV”) e em relógios de sol. Alguns estudiosos leem o tabuleiro como um mapa do cosmos — céu, terra e as quatro direções —, sinal de que o liubo era mais que um passatempo."], "cap": ["As linhas de um tabuleiro de liubo (padrão TLV): um quadrado central, um T em cada lado, formas de L e V perto dos cantos"]}, {"h": "Como se jogava", "p": ["A maioria dos estudiosos acha que cada jogador tinha seis peças e lançava finas varetas de bambu para decidir o lance. O “seis” (liu) do nome viria dessas seis varetas ou seis peças.", "Uma peça que avançava parece que virava uma poderosa “coruja” (xiao). Um poema de cerca do século III a.C., “Chamando a alma”, dos Cantos de Chu, diz: “virando coruja, avança e grita ‘cinco brancos!’”. Textos descrevem também um modo de jogo em que as peças pescavam “peixes” na “água” do centro."], "cap": ["Duas figuras jogando liubo, feitas para um túmulo Han (Metropolitan Museum of Art)"]}, {"h": "Jogos vindos dos túmulos", "p": ["O túmulo 3 de Mawangdui, em Changsha (Hunan), de cerca de 168 a.C., guardava um jogo completo — tabuleiro, peças e varetas — numa caixa laqueada, para que o morto pudesse jogar no além.", "Relevos das paredes dos túmulos mostram muitas vezes imortais jogando liubo no alto das montanhas. O jogo estava ligado ao mundo dos imortais e à vida longa."], "cap": ["O tabuleiro de liubo do museu — veja-o em 3D na sala Acervo"]}], "tl": [["Séc. V–III a.C. (Reinos Combatentes)", "Tabuleiros de liubo começam a ir para os túmulos"], ["c. séc. III a.C.", "“Chamando a alma” descreve uma partida de liubo"], ["c. 168 a.C.", "Um jogo completo entra no túmulo 3 de Mawangdui"], ["206 a.C. – 220 d.C. (Han)", "Jogado de imperadores a gente comum; em relevos e espelhos"], ["Tang (séc. VII–X)", "Acredita-se que as regras já estavam esquecidas"], ["1993", "Surge nos túmulos Han de Yinwan um texto de adivinhação com o tabuleiro"], ["Anos 2010", "Tiras de bambu sobre o liubo aparecem no túmulo do marquês de Haihun, Liu He"]]}}, "de": {"liubo": {"kf": ["In China von den Streitenden Reichen bis zur Han-Zeit (5. Jh. v. Chr. – 3. Jh. n. Chr.) sehr beliebt", "Ein Brett mit T-, L- und V-förmigen Linien; geworfen wurden dünne Stäbchen", "Nach dem Ende der Han verschwand es rasch; die Regeln sind bis heute nicht ganz bekannt"], "more": [{"h": "Das TLV-Brett", "p": ["Ein Liubo-Brett ist quadratisch, mit einem Quadrat in der Mitte, einem T in der Mitte jeder Seite, L-Formen darum und V-Formen in den Ecken. Die Steine zogen vermutlich auf und zwischen diesen Linien.", "Dieselben Linien finden sich auf Spiegelrückseiten („TLV-Spiegel“) und auf Sonnenuhren. Manche Forscher lesen das Brett als Weltkarte – Himmel, Erde und die vier Richtungen –, ein Hinweis, dass Liubo mehr als Zeitvertreib war."], "cap": ["Die Linien eines Liubo-Bretts (TLV-Muster): ein Quadrat in der Mitte, ein T an jeder Seite, L- und V-Formen zu den Ecken"]}, {"h": "Wie man spielte", "p": ["Die meisten Forscher meinen, dass jeder Spieler sechs Steine hatte und dünne Bambusstäbchen warf, um den Zug zu bestimmen. Die „Sechs“ (liu) im Namen soll von diesen sechs Stäbchen oder Steinen kommen.", "Ein vorgerückter Stein wurde offenbar zur mächtigen „Eule“ (xiao). Ein Gedicht aus etwa dem 3. Jh. v. Chr., „Die Seele zurückrufen“ in den Liedern von Chu, sagt: „zur Eule geworden, drängt man vor und ruft ‚fünf Weiße!‘“. Texte beschreiben auch eine Spielweise, bei der man im „Wasser“ in der Brettmitte „Fische“ fing."], "cap": ["Zwei Liubo-Spieler, für ein Han-Grab gefertigt (Metropolitan Museum of Art)"]}, {"h": "Spiele aus den Gräbern", "p": ["Grab 3 von Mawangdui in Changsha (Hunan), um 168 v. Chr., enthielt einen vollständigen Satz – Brett, Steine und Stäbchen – in einem Lackkasten, damit der Tote im Jenseits spielen konnte.", "Reliefs an Grabwänden zeigen oft Unsterbliche, die auf Berggipfeln Liubo spielen. Das Spiel war mit der Welt der Unsterblichen und dem langen Leben verbunden."], "cap": ["Das Liubo-Brett des Museums – im Raum „Sammlung“ in 3D zu sehen"]}], "tl": [["5.–3. Jh. v. Chr. (Streitende Reiche)", "Liubo-Bretter werden in Gräber gelegt"], ["um das 3. Jh. v. Chr.", "„Die Seele zurückrufen“ beschreibt eine Liubo-Partie"], ["um 168 v. Chr.", "Ein vollständiger Satz kommt in Grab 3 von Mawangdui"], ["206 v. Chr. – 220 n. Chr. (Han)", "Von Kaisern bis zum einfachen Volk gespielt; auf Reliefs und Spiegeln"], ["Tang (7.–10. Jh.)", "Die Regeln waren vermutlich schon vergessen"], ["1993", "Aus den Han-Gräbern von Yinwan kommt ein Orakeltext mit dem Brett"], ["2010er", "Bambusleisten zum Liubo im Grab des Markgrafen von Haihun, Liu He"]]}}, "ru": {"liubo": {"kf": ["Была очень популярна в Китае от Сражающихся царств до Хань (V в. до н. э. – III в. н. э.)", "Доска с линиями в форме T, L и V; бросали тонкие палочки", "После падения Хань быстро забылась, и её правила до сих пор известны не полностью"], "more": [{"h": "Доска TLV", "p": ["Доска любо квадратная: в центре квадрат, посередине каждой стороны T, вокруг — фигуры L, в углах — V. Считается, что фишки ходили по этим линиям и между ними.", "Те же линии встречаются на оборотах зеркал («зеркала TLV») и на солнечных часах. Некоторые учёные видят в доске карту мироздания — небо, земля и четыре стороны света, — так что любо было больше чем забавой."], "cap": ["Линии доски любо (узор TLV): квадрат в центре, T на каждой стороне, L и V к углам"]}, {"h": "Как играли", "p": ["Большинство учёных считает, что у каждого игрока было шесть фишек, а ход определяли броском тонких бамбуковых палочек. «Шесть» (лю) в названии, говорят, — от этих шести палочек или фишек.", "Продвинувшаяся фишка, видимо, становилась сильной «совой» (сяо). В стихотворении примерно III в. до н. э. «Призывание души» из «Чуских строф» сказано: «став совой, теснят и кричат: „пять белых!“». В текстах описан и способ игры, где в «воде» в центре доски ловили «рыб»."], "cap": ["Две фигурки игроков в любо, сделанные для ханьской гробницы (Метрополитен-музей)"]}, {"h": "Наборы из гробниц", "p": ["Гробница № 3 Мавандуя в Чанше (Хунань), около 168 г. до н. э., хранила полный набор — доску, фишки и палочки — в лаковом ящике, чтобы умерший мог играть в загробном мире.", "На рельефах стен гробниц часто изображены бессмертные, играющие в любо на горных вершинах. Игра была связана с миром бессмертных и долголетием."], "cap": ["Доска любо из собрания музея — её можно рассмотреть в 3D в зале «Собрание»"]}], "tl": [["V–III вв. до н. э. (Сражающиеся царства)", "Доски любо начинают класть в гробницы"], ["ок. III в. до н. э.", "«Призывание души» описывает партию в любо"], ["ок. 168 г. до н. э.", "Полный набор кладут в гробницу № 3 Мавандуя"], ["206 до н. э. – 220 н. э. (Хань)", "Играют от императоров до простолюдинов; на рельефах и зеркалах"], ["Тан (VII–X вв.)", "Правила, по-видимому, уже забыты"], ["1993", "Из ханьских гробниц Иньвань — гадательный текст с доской"], ["2010-е", "В гробнице маркиза Хайхуня Лю Хэ находят бамбуковые планки о любо"]]}}, "tr": {"liubo": {"kf": ["Savaşan Devletler’den Han’a (MÖ 5. yy – MS 3. yy) Çin’de çok popülerdi", "T, L ve V biçimli çizgileri olan bir tahta; hamle için ince çubuklar atılırdı", "Han yıkılınca hızla unutuldu; kuralları bugün bile tam bilinmiyor"], "more": [{"h": "TLV tahtası", "p": ["Liubo tahtası karedir; ortada bir kare, her kenarın ortasında T, çevresinde L ve köşelerde V biçimli çizgiler vardır. Taşların bu çizgilerin üzerinde ve aralarında ilerlediği düşünülür.", "Aynı çizgiler ayna sırtlarında (“TLV aynaları”) ve güneş saatlerinde de görülür. Bazı araştırmacılar tahtayı gök, yer ve dört yönü gösteren bir evren haritası olarak okur; liubo yalnızca eğlence değildi."], "cap": ["Bir liubo tahtasının çizgileri (TLV deseni): ortada kare, her kenarda T, köşelere doğru L ve V"]}, {"h": "Nasıl oynanırdı", "p": ["Araştırmacıların çoğuna göre her oyuncunun altı taşı vardı ve hamle ince bambu çubuklar atılarak belirlenirdi. Adındaki “altı” (liu) bu altı çubuktan ya da altı taştan gelir.", "İlerleyen bir taş güçlü bir “baykuş”a (xiao) dönüşüyordu anlaşılan. MÖ 3. yüzyıl dolaylarından Chu Şarkıları’ndaki “Ruhu Çağırma” şiirinde “baykuş olup bastırır, ‘beş beyaz!’ diye bağırırlar” dizesi vardır. Metinler, tahtanın ortasındaki “su”da “balık” tutulan bir oynayışı da anlatır."], "cap": ["Bir Han mezarı için yapılmış, liubo oynayan iki figür (Metropolitan Sanat Müzesi)"]}, {"h": "Mezarlardan çıkan takımlar", "p": ["Hunan, Changsha’daki Mawangdui 3 numaralı mezarında (MÖ y. 168) lake bir kutu içinde tahta, taşlar ve çubuklardan oluşan eksiksiz bir takım bulundu; ölü öteki dünyada da oynayabilsin diye konmuştu.", "Mezar duvarlarındaki kabartmalarda, dağ tepelerinde liubo oynayan ölümsüzler sık sık görülür. Oyun, ölümsüzler ve uzun ömür dünyasıyla bağlantılıydı."], "cap": ["Müzenin liubo tahtası — Koleksiyon odasında 3D olarak görebilirsin"]}], "tl": [["MÖ 5.–3. yy (Savaşan Devletler)", "Liubo tahtaları mezarlara konmaya başlar"], ["MÖ y. 3. yy", "“Ruhu Çağırma” bir liubo oyununu anlatır"], ["MÖ y. 168", "Mawangdui 3 numaralı mezara eksiksiz bir takım konur"], ["MÖ 206 – MS 220 (Han)", "İmparatorlardan halka herkes oynar; kabartmalarda ve aynalarda"], ["Tang (7.–10. yy)", "Kuralların çoktan unutulduğu düşünülür"], ["1993", "Yinwan Han mezarlarından tahtayla fal bakılan bir metin çıkar"], ["2010’lar", "Haihun markisi Liu He’nin mezarında liubo bambu yazıtları bulunur"]]}}, "id": {"liubo": {"kf": ["Sangat populer di Tiongkok dari Zaman Negara Berperang hingga Han (abad ke-5 SM – abad ke-3 M)", "Papan bergaris berbentuk T, L, dan V; batang tipis dilempar untuk melangkah", "Cepat memudar setelah Han runtuh, dan aturannya masih belum sepenuhnya diketahui"], "more": [{"h": "Papan TLV", "p": ["Papan liubo berbentuk persegi, dengan persegi di tengah, T di tengah tiap sisi, bentuk L di sekitarnya, dan V di sudut-sudut. Bidak diduga bergerak di atas dan di antara garis-garis ini.", "Garis yang sama muncul di balik cermin (“cermin TLV”) dan pada jam matahari. Sebagian peneliti membaca papan ini sebagai peta kosmos — langit, bumi, dan empat arah — tanda bahwa liubo lebih dari sekadar hiburan."], "cap": ["Garis-garis papan liubo (pola TLV): persegi di tengah, T di tiap sisi, bentuk L dan V ke arah sudut"]}, {"h": "Cara memainkannya", "p": ["Kebanyakan peneliti menduga tiap pemain punya enam bidak dan melempar batang bambu tipis untuk menentukan langkah. “Enam” (liu) dalam namanya konon berasal dari enam batang atau enam bidak itu.", "Bidak yang maju tampaknya menjadi “burung hantu” (xiao) yang kuat. Puisi sekitar abad ke-3 SM, “Memanggil Jiwa” dalam Nyanyian Chu, berbunyi: “menjadi burung hantu, mendesak dan berseru ‘lima putih!’”. Teks juga menyebut cara bermain dengan menangkap “ikan” di “air” di tengah papan."], "cap": ["Dua figur pemain liubo yang dibuat untuk makam Han (Metropolitan Museum of Art)"]}, {"h": "Perangkat dari makam", "p": ["Makam 3 Mawangdui di Changsha, Hunan (sekitar 168 SM), berisi satu set lengkap — papan, bidak, dan batang — dalam kotak berpernis, agar yang meninggal bisa bermain di alam baka.", "Relief dinding makam sering menggambarkan para dewa abadi bermain liubo di puncak gunung. Permainan ini terkait dengan dunia keabadian dan umur panjang."], "cap": ["Papan liubo milik museum — lihat dalam 3D di ruang Koleksi"]}], "tl": [["Abad ke-5–3 SM (Negara Berperang)", "Papan liubo mulai diletakkan di makam"], ["sekitar abad ke-3 SM", "“Memanggil Jiwa” menggambarkan permainan liubo"], ["sekitar 168 SM", "Satu set lengkap masuk ke makam 3 Mawangdui"], ["206 SM – 220 M (Han)", "Dimainkan dari kaisar hingga rakyat; muncul di relief dan cermin"], ["Tang (abad ke-7–10)", "Aturannya diduga sudah terlupakan"], ["1993", "Teks ramalan dengan papan muncul dari makam Han Yinwan"], ["2010-an", "Bilah bambu tentang liubo ditemukan di makam Marquis Haihun, Liu He"]]}}, "hi": {"liubo": {"kf": ["वारिंग स्टेट्स से हान काल (5वीं सदी ई.पू. – तीसरी सदी ई.) तक चीन में बेहद लोकप्रिय", "T, L और V आकार की रेखाओं वाला बोर्ड; चाल के लिए पतली छड़ें फेंकी जाती थीं", "हान के पतन के बाद तेज़ी से भुला दिया गया; नियम आज भी पूरी तरह मालूम नहीं"], "more": [{"h": "TLV बोर्ड", "p": ["लिउबो का बोर्ड वर्गाकार होता है — बीच में एक वर्ग, हर भुजा के बीच में T, उसके आसपास L और कोनों में V के आकार की रेखाएँ। माना जाता है कि मोहरे इन रेखाओं पर और इनके बीच चलते थे।", "यही रेखाएँ दर्पणों की पीठ (\"TLV दर्पण\") और धूप‑घड़ियों पर भी मिलती हैं। कुछ विद्वान बोर्ड को आकाश, धरती और चारों दिशाओं वाले ब्रह्मांड का नक़्शा मानते हैं — यानी लिउबो सिर्फ़ मनोरंजन नहीं था।"], "cap": ["लिउबो बोर्ड की रेखाएँ (TLV नमूना): बीच में वर्ग, हर भुजा पर T, कोनों की ओर L और V"]}, {"h": "कैसे खेलते थे", "p": ["ज़्यादातर विद्वान मानते हैं कि हर खिलाड़ी के पास छह मोहरे थे और चाल तय करने के लिए बाँस की पतली छड़ें फेंकी जाती थीं। नाम का \"छह\" (लिउ) इन्हीं छह छड़ों या मोहरों से आया बताया जाता है।", "आगे बढ़ा मोहरा शायद ताक़तवर \"उल्लू\" (श्याओ) बन जाता था। लगभग तीसरी सदी ई.पू. की \"चू के गीत\" की कविता \"आत्मा का आवाहन\" में पंक्ति है: \"उल्लू बनकर धावा बोलते हैं और पुकारते हैं ‘पाँच सफ़ेद!’\"। ग्रंथों में बोर्ड के बीच के \"पानी\" में \"मछली\" पकड़ने वाले खेल का भी ज़िक्र है।"], "cap": ["हान मक़बरे के लिए बनी, लिउबो खेलती दो मूर्तियाँ (मेट्रोपॉलिटन म्यूज़ियम ऑफ़ आर्ट)"]}, {"h": "मक़बरों से मिले सेट", "p": ["हूनान के चांगशा में मावांगदुई के मक़बरा 3 (लगभग 168 ई.पू.) में लाख के डिब्बे में बोर्ड, मोहरे और छड़ों का पूरा सेट मिला — ताकि मृतक परलोक में भी खेल सके।", "मक़बरों की दीवारों की नक़्क़ाशियों में अमर प्राणी अक्सर पहाड़ की चोटियों पर लिउबो खेलते दिखते हैं। यह खेल अमरता और लंबी उम्र की दुनिया से जुड़ा था।"], "cap": ["संग्रहालय का लिउबो बोर्ड — संग्रह कक्ष में इसे 3D में देखें"]}], "tl": [["5वीं–3वीं सदी ई.पू. (वारिंग स्टेट्स)", "लिउबो बोर्ड मक़बरों में रखे जाने लगे"], ["लगभग 3वीं सदी ई.पू.", "\"आत्मा का आवाहन\" में लिउबो की बाज़ी का वर्णन"], ["लगभग 168 ई.पू.", "मावांगदुई मक़बरा 3 में पूरा सेट रखा गया"], ["206 ई.पू. – 220 ई. (हान)", "सम्राट से आम लोगों तक लोकप्रिय; नक़्क़ाशियों और दर्पणों पर"], ["तांग (7वीं–10वीं सदी)", "माना जाता है कि नियम भुला दिए गए थे"], ["1993", "यिनवान हान मक़बरों से बोर्ड वाला भविष्यवाणी का लेख मिला"], ["2010 का दशक", "हाइहुन के मार्क्विस लिउ हे के मक़बरे में लिउबो की बाँस‑पट्टियाँ मिलीं"]]}}, "ar": {"liubo": {"kf": ["كانت شائعة جدًا في الصين من عصر الممالك المتحاربة إلى أسرة هان (القرن الخامس ق.م – القرن الثالث م)", "لوحة بخطوط على هيئة T وL وV، وتُرمى عيدان رفيعة لتحديد الحركة", "اندثرت سريعًا بعد سقوط هان، وما زالت قواعدها غير معروفة كلها"], "more": [{"h": "لوحة TLV", "p": ["لوحة ليوبو مربعة، في وسطها مربع، وفي منتصف كل ضلع T، وحولها أشكال L، وفي الأركان V. ويُعتقد أن القطع كانت تسير على هذه الخطوط وبينها.", "وتظهر الخطوط نفسها على ظهور المرايا («مرايا TLV») وعلى المزاول الشمسية. ويرى بعض الباحثين في اللوحة خريطة للكون — السماء والأرض والجهات الأربع — مما يوحي بأن ليوبو كانت أكثر من تسلية."], "cap": ["خطوط لوحة ليوبو (نمط TLV): مربع في الوسط، وحرف T على كل ضلع، وأشكال L وV نحو الأركان"]}, {"h": "كيف كانت تُلعب", "p": ["يرى أكثر الباحثين أن لكل لاعب ست قطع، وأنهم كانوا يرمون عيدانًا رفيعة من الخيزران لتحديد الحركة. ويُقال إن «الست» (ليو) في الاسم من هذه العيدان الستة أو القطع الستة.", "ويبدو أن القطعة المتقدمة كانت تصير «بومة» (شياو) قوية. وفي قصيدة من نحو القرن الثالث ق.م، «استدعاء الروح» من «أغاني تشو»، بيت يقول: «إذا صارت بومة اندفعوا وصاحوا: خمسة بيض!». وتصف النصوص أيضًا طريقة لعب تُصاد فيها «الأسماك» من «الماء» في وسط اللوحة."], "cap": ["تمثالان للاعبَي ليوبو صُنعا لقبر من عهد هان (متحف المتروبوليتان للفنون)"]}, {"h": "أطقم من القبور", "p": ["ضمّ القبر رقم 3 في ماوانغدوي بتشانغشا في هونان (نحو 168 ق.م) طقمًا كاملًا — اللوحة والقطع والعيدان — في صندوق مطلي باللك، ليلعب الميت في العالم الآخر.", "وكثيرًا ما تُظهر النقوش البارزة على جدران القبور الخالدين يلعبون ليوبو على قمم الجبال. فقد ارتبطت اللعبة بعالم الخلود وطول العمر."], "cap": ["لوحة ليوبو في مقتنيات المتحف — شاهدها ثلاثية الأبعاد في قاعة المقتنيات"]}], "tl": [["القرن 5–3 ق.م (الممالك المتحاربة)", "تبدأ ألواح ليوبو بالوضع في القبور"], ["نحو القرن 3 ق.م", "«استدعاء الروح» يصف دورًا من ليوبو"], ["نحو 168 ق.م", "يوضع طقم كامل في القبر رقم 3 بماوانغدوي"], ["206 ق.م – 220 م (هان)", "يلعبها الأباطرة والعامة؛ وتظهر على النقوش والمرايا"], ["تانغ (القرن 7–10)", "يُعتقد أن القواعد كانت قد نُسيت"], ["1993", "يظهر من قبور يينوان الهانية نص عرافة يستعمل اللوحة"], ["العقد الثاني من القرن 21", "تُكتشف شرائح خيزران عن ليوبو في قبر مركيز هايهون ليو خه"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (9): story 3 (zeno) made fuller */
(T => { const D = {"ja": {"zeno": {"kf": ["タブラは24の点とさいころ3つで遊ぶ、バックギャモンの祖先", "西暦480年ごろの皇帝ゼノンの一局が、詩で盤面ごと残った", "ローマ人は、いかさまを防ぐ「ダイスタワー」まで作った"], "more": [{"h": "タブラの盤", "p": ["タブラの盤は、今のバックギャモンと同じく24の点を12ずつ2列に並べたものです。駒は1人15個で、最初はすべて盤の外にあり、さいころ3つの目に従って盤に入れ、ぐるりと回って外へ出します。", "バックギャモンと大きく違うのは、2人とも同じ向きに進むことです。ひとつだけで立つ駒は相手に止まられると取られ、もう一度入れ直さなければなりません。ゼノンの盤に8つもできてしまったのは、この取られやすい駒でした。"], "cap": ["タブラの盤。24の点を12ずつ2列に並べ、両方の駒が同じ向き（矢印）に進む"]}, {"h": "いかさまを防ぐ道具", "p": ["ローマの人々はさいころ遊びに夢中で、法律では賭けが禁じられ、許されたのは冬のサトゥルナリア祭のあいだだけだったといわれます。それでも賭けは止まず、手でさいころを操るずるも横行しました。", "そこで使われたのが、上から入れたさいころが中の板に当たって転がり出る「ダイスタワー」です。ドイツのヴィラ跡から見つかった4世紀のものには「ピクト人は破れ、敵は滅ぼされた。安心して遊べ」と透かし彫りされています。"], "cap": ["ヴェットヴァイス＝フロイツハイムのダイスタワー（4世紀）。所蔵品の部屋で3Dで見られます"]}, {"h": "皇帝たちとさいころ", "p": ["ゼノンだけではありません。1世紀の皇帝クラウディウスはさいころ遊びが大好きで、その技についての本まで書き、馬車の中でも盤がずれないように工夫して遊んだと、歴史家スエトニウスが伝えています。", "ローマの遺跡からは、36の文字を6文字ずつ並べた盤もたくさん見つかります。文字が1マスの役目をしていて、「立て、遊び方を知らないなら場所をゆずれ」のような、からかいの言葉が刻まれたものもあります。"], "cap": ["タブラやさいころの遊びは、皇帝から兵士までの楽しみでした（偶然の道具の部屋で立方体のさいころを振れます）"]}], "tl": [["1世紀", "皇帝クラウディウスがさいころ遊びの本を書く"], ["4世紀", "ドイツのヴィラでダイスタワーが使われる"], ["480年ごろ", "東ローマ皇帝ゼノンの不運な一局"], ["6世紀", "アガティアスがその一局を詩に詠む"], ["10世紀ごろ", "詩が『ギリシア詞華集』にまとめられ、伝わる"], ["1869年", "ベック・ド・フーキエールが盤面とルールを読み解く"], ["1934年", "オースティンがゼノンの一局を詳しく検証する"]]}}, "en": {"zeno": {"kf": ["Tabula used 24 points and three dice — an ancestor of backgammon", "Emperor Zeno’s game of about AD 480 survives, position and all, in a poem", "The Romans even built “dice towers” to stop cheating"], "more": [{"h": "The tabula board", "p": ["A tabula board, like today’s backgammon board, has 24 points in two rows of 12. Each player had fifteen pieces, all starting off the board; following three dice, they were brought on, travelled round and were borne off.", "The great difference from backgammon is that both players move in the same direction. A piece standing alone could be hit when the opponent landed on it, and had to come in again. Zeno’s eight were exactly such easily hit pieces."], "cap": ["A tabula board: 24 points in two rows of 12; both players’ pieces travel the same way (arrow)"]}, {"h": "A device against cheating", "p": ["Romans were mad about dice. Gambling was against the law, said to be allowed only during the winter festival of Saturnalia, but it never stopped, and so did sleight of hand with the dice.", "Hence the dice tower: dice dropped in at the top bounce off boards inside and roll out at the bottom. A fourth-century tower from a villa in Germany is pierced with the words “The Picts are beaten, the enemy destroyed — play in safety.”"], "cap": ["The dice tower of Vettweiß-Froitzheim (4th century) — see it in 3D in the Collection room"]}, {"h": "Emperors and dice", "p": ["Zeno was not alone. The historian Suetonius says the first-century emperor Claudius loved dice so much that he wrote a book on the art and had his carriage fitted so the board would not slip while he played.", "Roman sites also yield many boards of 36 letters set in six-letter words; each letter served as a square, and some carry teasing lines such as “Get up — you can’t play; make room for a player.”"], "cap": ["Tables and dice were a pleasure from emperors down to soldiers (throw cubic dice in the Chance room)"]}], "tl": [["1st century", "Emperor Claudius writes a book on dice-play"], ["4th century", "A dice tower is in use at a villa in Germany"], ["c. 480", "Emperor Zeno’s unlucky game"], ["6th century", "Agathias puts the game into verse"], ["c. 10th century", "The poem is gathered into the Greek Anthology"], ["1869", "Becq de Fouquières works out the position and the rules"], ["1934", "R. G. Austin re-examines Zeno’s game in detail"]]}}, "zh": {"zeno": {"kf": ["塔布拉用24个点和3颗骰子来玩，是双陆的祖先", "约公元480年皇帝芝诺的一局，连同棋盘局面一起留在诗里", "罗马人甚至造出防作弊的“骰塔”"], "more": [{"h": "塔布拉的棋盘", "p": ["塔布拉的棋盘和今天的双陆一样，把24个点分成两排，每排12个。每人15枚棋子，开始时全在盘外，按3颗骰子的点数入盘，绕一圈后再移出。", "与双陆最大的不同，是双方都朝同一方向走。单独立着的棋子若被对方停上就会被吃掉，必须重新入盘。芝诺盘上那8枚，正是这种容易被吃的棋子。"], "cap": ["塔布拉棋盘：24个点分成两排各12个，双方棋子都朝同一方向（箭头）前进"]}, {"h": "防作弊的器具", "p": ["罗马人热衷掷骰，据说法律禁止赌博，只有冬季的农神节期间才被允许。但赌博从未停止，用手法操控骰子的作弊也很常见。", "于是有了“骰塔”：从上面投入的骰子撞上塔内的板子后滚出。在德国一处别墅遗址发现的4世纪骰塔上，镂刻着“皮克特人已败，敌人已灭，安心玩吧”。"], "cap": ["韦特魏斯—弗罗伊茨海姆的骰塔（4世纪），可在馆藏展厅以3D观看"]}, {"h": "皇帝与骰子", "p": ["不只芝诺。史家苏维托尼乌斯记载，1世纪的皇帝克劳狄乌斯酷爱掷骰，还写过一本论掷骰技巧的书，并在马车里设法固定棋盘，好在途中也能玩。", "罗马遗址还出土了许多由36个字母、每6个一组排成的棋盘；每个字母就是一格，有的刻着“起来，不会玩就让位”之类的调侃话。"], "cap": ["塔布拉和掷骰是从皇帝到士兵的共同乐趣（可在“偶然的道具”展厅掷立方体骰子）"]}], "tl": [["1世纪", "克劳狄乌斯皇帝写下掷骰之书"], ["4世纪", "德国的别墅里使用骰塔"], ["约480年", "东罗马皇帝芝诺不走运的一局"], ["6世纪", "阿加提阿斯把这一局写成诗"], ["约10世纪", "诗被收入《希腊诗选》流传下来"], ["1869年", "贝克·德·富基耶尔解读出局面与规则"], ["1934年", "奥斯汀详细重新检验芝诺的一局"]]}}, "zh-TW": {"zeno": {"kf": ["塔布拉用24個點和3顆骰子來玩，是雙陸的祖先", "約公元480年皇帝芝諾的一局，連同棋盤局面一起留在詩裡", "羅馬人甚至造出防作弊的「骰塔」"], "more": [{"h": "塔布拉的棋盤", "p": ["塔布拉的棋盤和今天的雙陸一樣，把24個點分成兩排，每排12個。每人15枚棋子，開始時全在盤外，按3顆骰子的點數入盤，繞一圈後再移出。", "與雙陸最大的不同，是雙方都朝同一方向走。單獨立著的棋子若被對方停上就會被吃掉，必須重新入盤。芝諾盤上那8枚，正是這種容易被吃的棋子。"], "cap": ["塔布拉棋盤：24個點分成兩排各12個，雙方棋子都朝同一方向（箭頭）前進"]}, {"h": "防作弊的器具", "p": ["羅馬人熱衷擲骰，據說法律禁止賭博，只有冬季的農神節期間才被允許。但賭博從未停止，用手法操控骰子的作弊也很常見。", "於是有了「骰塔」：從上面投入的骰子撞上塔內的板子後滾出。在德國一處別墅遺址發現的4世紀骰塔上，鏤刻著「皮克特人已敗，敵人已滅，安心玩吧」。"], "cap": ["韋特魏斯—弗羅伊茨海姆的骰塔（4世紀），可在館藏展廳以3D觀看"]}, {"h": "皇帝與骰子", "p": ["不只芝諾。史家蘇維托尼烏斯記載，1世紀的皇帝克勞狄烏斯酷愛擲骰，還寫過一本論擲骰技巧的書，並在馬車裡設法固定棋盤，好在途中也能玩。", "羅馬遺址還出土了許多由36個字母、每6個一組排成的棋盤；每個字母就是一格，有的刻著「起來，不會玩就讓位」之類的調侃話。"], "cap": ["塔布拉和擲骰是從皇帝到士兵的共同樂趣（可在「偶然的道具」展廳擲立方體骰子）"]}], "tl": [["1世紀", "克勞狄烏斯皇帝寫下擲骰之書"], ["4世紀", "德國的別墅裡使用骰塔"], ["約480年", "東羅馬皇帝芝諾不走運的一局"], ["6世紀", "阿加提阿斯把這一局寫成詩"], ["約10世紀", "詩被收入《希臘詩選》流傳下來"], ["1869年", "貝克·德·富基耶爾解讀出局面與規則"], ["1934年", "奧斯汀詳細重新檢驗芝諾的一局"]]}}, "ko": {"zeno": {"kf": ["타불라는 24개의 점과 주사위 3개로 하는 백개먼의 조상", "480년경 황제 제논의 대국이 판의 모습째 시로 남았다", "로마인은 속임수를 막는 ‘다이스 타워’까지 만들었다"], "more": [{"h": "타불라의 판", "p": ["타불라 판은 지금의 백개먼처럼 24개의 점을 12개씩 두 줄로 놓은 것입니다. 말은 한 사람에 15개로, 처음에는 모두 판 밖에 있다가 주사위 3개의 눈에 따라 판에 들어가 한 바퀴 돌아 밖으로 나갑니다.", "백개먼과 크게 다른 점은 두 사람이 같은 방향으로 나아간다는 것입니다. 홀로 선 말은 상대가 그 칸에 멈추면 잡혀 다시 들어가야 합니다. 제논의 판에 8개나 생긴 것이 바로 이 잡히기 쉬운 말이었습니다."], "cap": ["타불라 판. 24개의 점을 12개씩 두 줄로 놓고, 양쪽 말이 같은 방향(화살표)으로 나아간다"]}, {"h": "속임수를 막는 도구", "p": ["로마 사람들은 주사위 놀이에 푹 빠져 있었고, 법으로 도박이 금지되어 겨울의 사투르날리아 축제 동안에만 허락되었다고 합니다. 그래도 도박은 그치지 않았고, 손으로 주사위를 조작하는 속임수도 흔했습니다.", "그래서 쓰인 것이, 위에서 넣은 주사위가 안의 판에 부딪혀 굴러 나오는 ‘다이스 타워’입니다. 독일의 빌라 터에서 나온 4세기 것에는 “픽트인은 졌고 적은 멸망했다. 안심하고 놀아라”라는 글이 투조되어 있습니다."], "cap": ["페트바이스-프로이츠하임의 다이스 타워(4세기). 소장품 전시실에서 3D로 볼 수 있습니다"]}, {"h": "황제들과 주사위", "p": ["제논만이 아닙니다. 역사가 수에토니우스에 따르면 1세기의 황제 클라우디우스는 주사위 놀이를 무척 좋아해 그 기술에 관한 책까지 쓰고, 마차 안에서도 판이 미끄러지지 않게 꾸며 놀았다고 합니다.", "로마 유적에서는 36개의 글자를 6자씩 늘어놓은 판도 많이 나옵니다. 글자 하나가 한 칸 구실을 했고, “일어나, 놀 줄 모르면 자리를 비켜라” 같은 놀리는 말이 새겨진 것도 있습니다."], "cap": ["타불라와 주사위 놀이는 황제부터 병사까지의 즐거움이었습니다(우연의 도구 전시실에서 정육면체 주사위를 던질 수 있습니다)"]}], "tl": [["1세기", "클라우디우스 황제가 주사위 놀이 책을 쓴다"], ["4세기", "독일의 빌라에서 다이스 타워가 쓰인다"], ["480년경", "동로마 황제 제논의 불운한 대국"], ["6세기", "아가티아스가 그 대국을 시로 읊는다"], ["10세기경", "시가 『그리스 사화집』에 묶여 전해진다"], ["1869년", "벡 드 푸키에르가 판의 모습과 규칙을 풀어낸다"], ["1934년", "오스틴이 제논의 대국을 자세히 다시 검증한다"]]}}, "es": {"zeno": {"kf": ["La tabula se jugaba con 24 puntos y tres dados: un antepasado del backgammon", "La partida del emperador Zenón, hacia el año 480, sobrevive con su posición en un poema", "Los romanos llegaron a construir «torres de dados» contra las trampas"], "more": [{"h": "El tablero de la tabula", "p": ["El tablero de la tabula, como el del backgammon actual, tiene 24 puntos en dos filas de 12. Cada jugador tenía quince piezas, todas fuera al empezar; según tres dados se metían, daban la vuelta y se sacaban.", "La gran diferencia con el backgammon es que los dos jugadores avanzan en el mismo sentido. Una pieza sola podía ser golpeada si el rival caía en su punto y tenía que volver a entrar. Las ocho de Zenón eran justamente piezas así."], "cap": ["Un tablero de tabula: 24 puntos en dos filas de 12; las piezas de ambos avanzan en el mismo sentido (flecha)"]}, {"h": "Un aparato contra las trampas", "p": ["A los romanos les apasionaban los dados. Las leyes prohibían apostar, y se dice que solo se permitía durante la fiesta invernal de las Saturnales, pero las apuestas nunca cesaron, ni las trampas con los dedos.", "De ahí la torre de dados: los dados que se echan por arriba chocan con tablillas interiores y salen rodando por abajo. Una del siglo IV hallada en una villa de Alemania lleva calado «Los pictos vencidos, el enemigo destruido: jugad tranquilos»."], "cap": ["La torre de dados de Vettweiß-Froitzheim (siglo IV); mírala en 3D en la sala Colección"]}, {"h": "Emperadores y dados", "p": ["Zenón no fue el único. Según el historiador Suetonio, el emperador Claudio, en el siglo I, adoraba los dados: escribió un libro sobre ese arte y hizo adaptar su carruaje para que el tablero no se moviera mientras jugaba.", "En los yacimientos romanos aparecen también muchos tableros de 36 letras en palabras de seis; cada letra hacía de casilla, y algunos llevan burlas como «Levántate, no sabes jugar; deja sitio a un jugador»."], "cap": ["Tablas y dados eran un placer de emperadores a soldados (lanza dados cúbicos en la sala Azar)"]}], "tl": [["Siglo I", "El emperador Claudio escribe un libro sobre los dados"], ["Siglo IV", "Se usa una torre de dados en una villa de Alemania"], ["h. 480", "La desafortunada partida del emperador Zenón"], ["Siglo VI", "Agatías pone la partida en verso"], ["h. siglo X", "El poema se recoge en la Antología griega"], ["1869", "Becq de Fouquières reconstruye la posición y las reglas"], ["1934", "R. G. Austin reexamina en detalle la partida de Zenón"]]}}, "fr": {"zeno": {"kf": ["La tabula se jouait sur 24 flèches avec trois dés : un ancêtre du backgammon", "La partie de l’empereur Zénon, vers 480, survit avec sa position dans un poème", "Les Romains ont même fabriqué des « tours à dés » contre la triche"], "more": [{"h": "Le plateau de la tabula", "p": ["Le plateau de la tabula, comme celui du backgammon, compte 24 flèches en deux rangées de 12. Chaque joueur avait quinze pions, tous hors du plateau au départ ; selon trois dés, on les entrait, on faisait le tour et on les sortait.", "Grande différence avec le backgammon : les deux joueurs vont dans le même sens. Un pion seul pouvait être frappé si l’adversaire tombait sur sa flèche, et devait rentrer de nouveau. Les huit de Zénon étaient justement de ces pions vulnérables."], "cap": ["Un plateau de tabula : 24 flèches en deux rangées de 12 ; les pions des deux joueurs vont dans le même sens (flèche)"]}, {"h": "Un appareil contre la triche", "p": ["Les Romains raffolaient des dés. La loi interdisait les jeux d’argent, permis, dit-on, seulement pendant la fête d’hiver des Saturnales — mais les paris ne cessaient pas, ni les tours de main avec les dés.", "D’où la tour à dés : les dés jetés en haut rebondissent sur des planchettes et ressortent en bas. Une tour du IVe siècle trouvée dans une villa d’Allemagne porte, ajourée : « Pictes vaincus, ennemi anéanti : jouez tranquilles »."], "cap": ["La tour à dés de Vettweiß-Froitzheim (IVe siècle) — à voir en 3D dans la salle Collection"]}, {"h": "Les empereurs et les dés", "p": ["Zénon n’était pas seul. Selon l’historien Suétone, l’empereur Claude, au Ier siècle, aimait tant les dés qu’il écrivit un livre sur cet art et fit aménager sa voiture pour que le plateau ne bouge pas pendant qu’il jouait.", "Les sites romains livrent aussi de nombreux plateaux de 36 lettres en mots de six ; chaque lettre tenait lieu de case, et certains portent des moqueries comme « Lève-toi, tu ne sais pas jouer ; laisse la place à un joueur »."], "cap": ["Tables et dés plaisaient des empereurs aux soldats (lancez des dés cubiques dans la salle Hasard)"]}], "tl": [["Ier siècle", "L’empereur Claude écrit un livre sur les dés"], ["IVe siècle", "Une tour à dés sert dans une villa d’Allemagne"], ["v. 480", "La partie malchanceuse de l’empereur Zénon"], ["VIe siècle", "Agathias met la partie en vers"], ["v. Xe siècle", "Le poème entre dans l’Anthologie grecque"], ["1869", "Becq de Fouquières reconstitue la position et les règles"], ["1934", "R. G. Austin réexamine en détail la partie de Zénon"]]}}, "pt": {"zeno": {"kf": ["A tabula usava 24 pontos e três dados — um ancestral do gamão", "A partida do imperador Zenão, por volta de 480, sobrevive com a posição num poema", "Os romanos chegaram a construir “torres de dados” contra a trapaça"], "more": [{"h": "O tabuleiro da tabula", "p": ["O tabuleiro da tabula, como o do gamão atual, tem 24 pontos em duas fileiras de 12. Cada jogador tinha quinze peças, todas fora no início; conforme três dados, entravam, davam a volta e saíam.", "A grande diferença do gamão é que os dois jogadores andam no mesmo sentido. Uma peça sozinha podia ser batida se o rival caísse no seu ponto e tinha de entrar de novo. As oito de Zenão eram justamente peças assim."], "cap": ["Um tabuleiro de tabula: 24 pontos em duas fileiras de 12; as peças dos dois andam no mesmo sentido (seta)"]}, {"h": "Um aparelho contra a trapaça", "p": ["Os romanos eram loucos por dados. A lei proibia o jogo a dinheiro, permitido, diz-se, só na festa de inverno das Saturnais — mas as apostas nunca pararam, nem os truques de mão com os dados.", "Daí a torre de dados: os dados lançados por cima batem em tabuinhas internas e saem rolando por baixo. Uma do século IV achada numa vila na Alemanha traz vazado: “Pictos vencidos, inimigo destruído: joguem tranquilos”."], "cap": ["A torre de dados de Vettweiß-Froitzheim (século IV) — veja-a em 3D na sala Acervo"]}, {"h": "Imperadores e dados", "p": ["Zenão não foi o único. Segundo o historiador Suetônio, o imperador Cláudio, no século I, adorava dados: escreveu um livro sobre essa arte e adaptou a carruagem para o tabuleiro não escorregar enquanto jogava.", "Os sítios romanos também revelam muitos tabuleiros de 36 letras em palavras de seis; cada letra fazia as vezes de casa, e alguns trazem provocações como “Levanta, não sabes jogar; dá lugar a um jogador”."], "cap": ["Tábulas e dados agradavam de imperadores a soldados (lance dados cúbicos na sala Acaso)"]}], "tl": [["Século I", "O imperador Cláudio escreve um livro sobre os dados"], ["Século IV", "Uma torre de dados é usada numa vila na Alemanha"], ["c. 480", "A partida azarada do imperador Zenão"], ["Século VI", "Agátias põe a partida em versos"], ["c. século X", "O poema entra na Antologia Grega"], ["1869", "Becq de Fouquières reconstrói a posição e as regras"], ["1934", "R. G. Austin reexamina em detalhe a partida de Zenão"]]}}, "de": {"zeno": {"kf": ["Tabula wurde mit 24 Zungen und drei Würfeln gespielt – ein Vorfahr des Backgammon", "Kaiser Zenons Partie um 480 ist samt Stellung in einem Gedicht erhalten", "Die Römer bauten sogar „Würfeltürme“ gegen Betrug"], "more": [{"h": "Das Tabula-Brett", "p": ["Das Tabula-Brett hat wie das heutige Backgammon 24 Zungen in zwei Reihen zu 12. Jeder Spieler hatte fünfzehn Steine, die anfangs alle außerhalb lagen; nach drei Würfeln wurden sie eingesetzt, liefen herum und wurden ausgewürfelt.", "Der große Unterschied zum Backgammon: Beide Spieler ziehen in dieselbe Richtung. Ein einzeln stehender Stein konnte geschlagen werden, wenn der Gegner auf seine Zunge kam, und musste neu einsetzen. Zenons acht waren genau solche verwundbaren Steine."], "cap": ["Ein Tabula-Brett: 24 Zungen in zwei Reihen zu 12; die Steine beider Spieler laufen in dieselbe Richtung (Pfeil)"]}, {"h": "Ein Gerät gegen Betrug", "p": ["Die Römer liebten das Würfeln. Glücksspiel war verboten und angeblich nur während der Saturnalien im Winter erlaubt – doch gewettet wurde immer, und auch mit flinken Fingern betrogen.", "Daher der Würfelturm: Oben eingeworfene Würfel prallen an inneren Brettchen ab und rollen unten heraus. Ein Turm des 4. Jahrhunderts aus einer Villa in Deutschland trägt durchbrochen die Worte „Die Pikten besiegt, der Feind vernichtet – spielt unbesorgt“."], "cap": ["Der Würfelturm von Vettweiß-Froitzheim (4. Jh.) – im Raum „Sammlung“ in 3D zu sehen"]}, {"h": "Kaiser und Würfel", "p": ["Zenon war nicht der Einzige. Nach dem Historiker Sueton liebte Kaiser Claudius im 1. Jahrhundert das Würfeln so sehr, dass er ein Buch über diese Kunst schrieb und seinen Wagen so einrichten ließ, dass das Brett beim Spielen nicht verrutschte.", "Römische Fundorte liefern auch viele Bretter mit 36 Buchstaben in Wörtern zu sechs; jeder Buchstabe diente als Feld, und manche tragen Spott wie „Steh auf, du kannst nicht spielen – mach Platz für einen Spieler“."], "cap": ["Tables und Würfel erfreuten Kaiser wie Soldaten (würfle mit Sechsflächnern im Raum „Zufall“)"]}], "tl": [["1. Jh.", "Kaiser Claudius schreibt ein Buch über das Würfelspiel"], ["4. Jh.", "In einer Villa in Deutschland wird ein Würfelturm benutzt"], ["um 480", "Kaiser Zenons unglückliche Partie"], ["6. Jh.", "Agathias fasst die Partie in Verse"], ["um das 10. Jh.", "Das Gedicht kommt in die Griechische Anthologie"], ["1869", "Becq de Fouquières erschließt Stellung und Regeln"], ["1934", "R. G. Austin prüft Zenons Partie eingehend neu"]]}}, "ru": {"zeno": {"kf": ["Табулу играли на 24 пунктах тремя костями — это предок нард", "Партия императора Зенона около 480 года сохранилась вместе с позицией в стихотворении", "Римляне даже строили «башни для костей» против жульничества"], "more": [{"h": "Доска табулы", "p": ["Доска табулы, как и нынешних нард, — это 24 пункта в два ряда по 12. У каждого было пятнадцать фишек, вначале все вне доски; по трём костям их вводили, проводили по кругу и выводили.", "Главное отличие от бэкгаммона: оба игрока идут в одну сторону. Одиночную фишку можно было побить, если соперник вставал на её пункт, и её приходилось вводить заново. Восемь фишек Зенона были как раз такими уязвимыми."], "cap": ["Доска табулы: 24 пункта в два ряда по 12; фишки обоих игроков идут в одну сторону (стрелка)"]}, {"h": "Прибор против жульничества", "p": ["Римляне обожали кости. Азартные игры запрещал закон — говорят, их разрешали лишь на зимний праздник Сатурналий, — но ставки не прекращались, как и ловкость рук с костями.", "Отсюда башня для костей: брошенные сверху кости ударяются о дощечки внутри и выкатываются снизу. На башне IV века из виллы в Германии прорезано: «Пикты побеждены, враг уничтожен — играйте спокойно»."], "cap": ["Башня для костей из Фетвайс-Фройцхайма (IV в.) — её можно рассмотреть в 3D в зале «Собрание»"]}, {"h": "Императоры и кости", "p": ["Зенон был не одинок. По словам историка Светония, император Клавдий в I веке так любил кости, что написал книгу об этом искусстве и велел обустроить повозку, чтобы доска не съезжала во время игры.", "На римских памятниках находят и много досок из 36 букв, сложенных в слова по шесть; каждая буква служила клеткой, а на некоторых — насмешки вроде «Встань, ты не умеешь играть; уступи место игроку»."], "cap": ["Табулой и костями наслаждались от императоров до солдат (бросайте кубические кости в зале «Случай»)"]}], "tl": [["I в.", "Император Клавдий пишет книгу об игре в кости"], ["IV в.", "На вилле в Германии пользуются башней для костей"], ["ок. 480", "Несчастливая партия императора Зенона"], ["VI в.", "Агафий излагает партию в стихах"], ["ок. X в.", "Стихотворение входит в «Греческую антологию»"], ["1869", "Бек де Фукьер восстанавливает позицию и правила"], ["1934", "Р. Г. Остин подробно пересматривает партию Зенона"]]}}, "tr": {"zeno": {"kf": ["Tabula 24 hane ve üç zarla oynanırdı — tavlanın atası", "İmparator Zenon’un 480 dolaylarındaki oyunu, konumuyla birlikte bir şiirde yaşıyor", "Romalılar hileye karşı “zar kuleleri” bile yaptı"], "more": [{"h": "Tabula tahtası", "p": ["Tabula tahtası, bugünkü tavla gibi 12’şerli iki sırada 24 haneden oluşur. Her oyuncunun on beş taşı vardı ve başta hepsi tahtanın dışındaydı; üç zara göre girilir, tahta dolaşılır ve dışarı çıkılırdı.", "Tavladan en büyük farkı, iki oyuncunun da aynı yöne gitmesidir. Tek başına duran taş, rakip onun hanesine gelirse vurulur ve yeniden girmek zorunda kalırdı. Zenon’un sekiz taşı tam da böyle açık taşlardı."], "cap": ["Bir tabula tahtası: 12’şerli iki sırada 24 hane; iki oyuncunun taşları da aynı yöne (ok) gider"]}, {"h": "Hileye karşı bir alet", "p": ["Romalılar zara bayılırdı. Kumar yasaktı ve söylendiğine göre yalnızca kışın Saturnalia bayramında serbestti — ama bahis hiç durmadı, zarla el çabukluğu da.", "Zar kulesi bu yüzden vardı: Üstten atılan zarlar içerideki tahtalara çarpıp alttan yuvarlanarak çıkar. Almanya’da bir villada bulunan 4. yüzyıla ait kulenin üzerinde “Piktler yenildi, düşman yok edildi — gönül rahatlığıyla oynayın” yazısı oyulmuştur."], "cap": ["Vettweiß-Froitzheim zar kulesi (4. yy) — Koleksiyon odasında 3D olarak görebilirsin"]}, {"h": "İmparatorlar ve zarlar", "p": ["Yalnız Zenon değil. Tarihçi Suetonius’a göre 1. yüzyıldaki İmparator Claudius zara o kadar düşkündü ki bu sanat üzerine bir kitap yazdı ve oynarken tahta kaymasın diye arabasını düzenletti.", "Roma kalıntılarında, altışar harfli kelimelerle dizilmiş 36 harfli pek çok tahta da çıkar; her harf bir hane işi görürdü, bazılarında “Kalk, oynamayı bilmiyorsun; bir oyuncuya yer aç” gibi takılmalar vardır."], "cap": ["Tavla ve zar, imparatorlardan askerlere herkesin eğlencesiydi (Şans odasında küp zar atabilirsin)"]}], "tl": [["1. yy", "İmparator Claudius zar oyunu üzerine bir kitap yazar"], ["4. yy", "Almanya’da bir villada zar kulesi kullanılır"], ["y. 480", "İmparator Zenon’un talihsiz oyunu"], ["6. yy", "Agathias oyunu şiire döker"], ["y. 10. yy", "Şiir Yunan Antolojisi’ne girer"], ["1869", "Becq de Fouquières konumu ve kuralları çözer"], ["1934", "R. G. Austin Zenon’un oyununu ayrıntılı yeniden inceler"]]}}, "id": {"zeno": {"kf": ["Tabula dimainkan dengan 24 titik dan tiga dadu — leluhur backgammon", "Permainan Kaisar Zeno sekitar tahun 480 bertahan, lengkap dengan posisinya, dalam sebuah puisi", "Orang Romawi bahkan membuat “menara dadu” untuk mencegah kecurangan"], "more": [{"h": "Papan tabula", "p": ["Papan tabula, seperti papan backgammon kini, punya 24 titik dalam dua baris berisi 12. Tiap pemain punya lima belas bidak yang semuanya di luar papan pada awalnya; menurut tiga dadu, bidak dimasukkan, berkeliling, lalu dikeluarkan.", "Perbedaan besar dengan backgammon: kedua pemain bergerak ke arah yang sama. Bidak yang berdiri sendiri bisa dipukul bila lawan mendarat di titiknya, dan harus masuk lagi. Delapan bidak Zeno adalah bidak rawan semacam itu."], "cap": ["Papan tabula: 24 titik dalam dua baris berisi 12; bidak kedua pemain bergerak ke arah yang sama (panah)"]}, {"h": "Alat anti-kecurangan", "p": ["Orang Romawi tergila-gila pada dadu. Judi dilarang hukum dan konon hanya dibolehkan selama festival musim dingin Saturnalia — tetapi taruhan tak pernah berhenti, begitu pula kecurangan dengan tangan.", "Maka dibuatlah menara dadu: dadu yang dimasukkan dari atas memantul pada papan-papan di dalam dan keluar menggelinding di bawah. Menara abad ke-4 dari sebuah vila di Jerman berukiran tembus: “Bangsa Pikt kalah, musuh hancur — bermainlah dengan tenang”."], "cap": ["Menara dadu Vettweiß-Froitzheim (abad ke-4) — lihat dalam 3D di ruang Koleksi"]}, {"h": "Kaisar dan dadu", "p": ["Bukan hanya Zeno. Menurut sejarawan Suetonius, Kaisar Claudius pada abad ke-1 begitu menyukai dadu sampai menulis buku tentang seninya dan mengatur keretanya agar papan tidak bergeser saat ia bermain.", "Situs-situs Romawi juga menghasilkan banyak papan berisi 36 huruf dalam kata-kata enam huruf; tiap huruf berfungsi sebagai petak, dan sebagian memuat ejekan seperti “Bangun, kau tak bisa main; beri tempat untuk pemain”."], "cap": ["Tables dan dadu disukai dari kaisar hingga prajurit (lempar dadu kubus di ruang Peluang)"]}], "tl": [["Abad ke-1", "Kaisar Claudius menulis buku tentang permainan dadu"], ["Abad ke-4", "Menara dadu dipakai di sebuah vila di Jerman"], ["sekitar 480", "Permainan sial Kaisar Zeno"], ["Abad ke-6", "Agathias menuangkan permainan itu ke dalam puisi"], ["sekitar abad ke-10", "Puisi itu masuk ke Antologi Yunani"], ["1869", "Becq de Fouquières menguraikan posisi dan aturannya"], ["1934", "R. G. Austin menelaah ulang permainan Zeno secara rinci"]]}}, "hi": {"zeno": {"kf": ["ताबुला 24 बिंदुओं और तीन पासों से खेला जाता था — बैकगैमन का पूर्वज", "लगभग 480 ई. की सम्राट ज़ेनो की बाज़ी, स्थिति सहित, एक कविता में बची है", "रोमनों ने बेईमानी रोकने के लिए \"पासा‑मीनार\" तक बनाई"], "more": [{"h": "ताबुला का बोर्ड", "p": ["ताबुला का बोर्ड आज के बैकगैमन की तरह 12‑12 की दो पंक्तियों में 24 बिंदुओं का होता है। हर खिलाड़ी की पंद्रह गोटियाँ शुरू में बोर्ड के बाहर होती थीं; तीन पासों के अनुसार उन्हें अंदर लाया जाता, चक्कर लगवाया जाता और बाहर निकाला जाता।", "बैकगैमन से बड़ा अंतर यह है कि दोनों खिलाड़ी एक ही दिशा में चलते हैं। अकेली खड़ी गोटी पर विरोधी आ जाए तो वह मारी जाती और उसे फिर से अंदर लाना पड़ता। ज़ेनो की आठ गोटियाँ ठीक ऐसी ही असुरक्षित थीं।"], "cap": ["ताबुला बोर्ड: 12‑12 की दो पंक्तियों में 24 बिंदु; दोनों खिलाड़ियों की गोटियाँ एक ही दिशा (तीर) में चलती हैं"]}, {"h": "बेईमानी रोकने का यंत्र", "p": ["रोमन पासों के दीवाने थे। क़ानून जुए पर रोक लगाता था — कहते हैं केवल सर्दियों के सैटर्नेलिया उत्सव में छूट थी — पर दाँव कभी नहीं रुके, न हाथ की सफ़ाई वाली बेईमानी।", "इसीलिए पासा‑मीनार बनी: ऊपर डाले गए पासे भीतर की पट्टियों से टकराकर नीचे लुढ़कते निकलते हैं। जर्मनी के एक विला से मिली चौथी सदी की मीनार पर जालीदार अक्षरों में लिखा है: \"पिक्ट हारे, दुश्मन नष्ट — निश्चिंत होकर खेलो\"।"], "cap": ["फ़ेटवाइस‑फ़्रॉइत्सहाइम की पासा‑मीनार (चौथी सदी) — संग्रह कक्ष में इसे 3D में देखें"]}, {"h": "सम्राट और पासे", "p": ["सिर्फ़ ज़ेनो ही नहीं। इतिहासकार सुएटोनियस बताते हैं कि पहली सदी के सम्राट क्लॉडियस को पासे इतने प्रिय थे कि उन्होंने इस कला पर एक किताब लिखी और अपनी गाड़ी ऐसी बनवाई कि खेलते समय बोर्ड न खिसके।", "रोमन स्थलों से 36 अक्षरों वाले, छह‑छह अक्षरों के शब्दों में बने बहुत से बोर्ड भी मिलते हैं; हर अक्षर एक ख़ाने का काम करता था, और कुछ पर ऐसे ताने खुदे हैं: \"उठो, तुम्हें खेलना नहीं आता; खिलाड़ी को जगह दो\"।"], "cap": ["ताबुला और पासे सम्राटों से सैनिकों तक सबके मनोरंजन थे (\"संयोग\" कक्ष में घनाकार पासे फेंकें)"]}], "tl": [["पहली सदी", "सम्राट क्लॉडियस पासों के खेल पर किताब लिखते हैं"], ["चौथी सदी", "जर्मनी के एक विला में पासा‑मीनार इस्तेमाल होती है"], ["लगभग 480", "सम्राट ज़ेनो की बदक़िस्मत बाज़ी"], ["छठी सदी", "अगाथियास बाज़ी को कविता में ढालते हैं"], ["लगभग 10वीं सदी", "कविता \"यूनानी संकलन\" में शामिल होती है"], ["1869", "बेक द फ़ूकिएर स्थिति और नियम सुलझाते हैं"], ["1934", "आर. जी. ऑस्टिन ज़ेनो की बाज़ी की विस्तार से फिर जाँच करते हैं"]]}}, "ar": {"zeno": {"kf": ["كانت التابولا تُلعب على 24 نقطة بثلاثة أحجار نرد — وهي سلف الطاولة", "بقي دور الإمبراطور زينون نحو سنة 480 بوضعه كاملًا في قصيدة", "بل صنع الرومان «أبراج نرد» لمنع الغش"], "more": [{"h": "لوحة التابولا", "p": ["لوحة التابولا، مثل لوحة الطاولة اليوم، 24 نقطة في صفّين من 12. ولكل لاعب خمس عشرة قطعة تكون كلها خارج اللوحة في البداية، فتدخل بحسب ثلاثة أحجار نرد وتدور ثم تخرج.", "والفرق الكبير عن الطاولة أن اللاعبين يسيران في الاتجاه نفسه. وكانت القطعة الوحيدة في نقطتها تُضرب إذا حلّ الخصم عليها، فتعود لتدخل من جديد. وقطع زينون الثماني كانت من هذا النوع المكشوف."], "cap": ["لوحة تابولا: 24 نقطة في صفّين من 12، وقطع اللاعبين كليهما تسير في الاتجاه نفسه (السهم)"]}, {"h": "أداة ضد الغش", "p": ["كان الرومان مولعين بالنرد. وقد حظر القانون القمار، ويُقال إنه لم يُبَح إلا في عيد ساتورناليا الشتوي — لكن الرهان لم يتوقف، ولا خفة اليد في رمي النرد.", "ومن هنا برج النرد: تُلقى الأحجار من أعلاه فتصطدم بألواح في داخله وتتدحرج خارجة من أسفله. وعلى برج من القرن الرابع وُجد في فيلا بألمانيا نقش مخرّم: «هُزم البيكت وأُبيد العدو — العبوا آمنين»."], "cap": ["برج النرد من فيتفايس-فرويتسهايم (القرن الرابع) — شاهده ثلاثي الأبعاد في قاعة المقتنيات"]}, {"h": "الأباطرة والنرد", "p": ["لم يكن زينون وحده. فبحسب المؤرخ سويتونيوس كان الإمبراطور كلوديوس في القرن الأول مغرمًا بالنرد حتى ألّف كتابًا في فنّه، وجهّز عربته كي لا تنزلق اللوحة وهو يلعب.", "وتكشف المواقع الرومانية أيضًا ألواحًا كثيرة من 36 حرفًا في كلمات من ستة أحرف؛ يقوم كل حرف مقام خانة، وعلى بعضها سخرية مثل: «قم، لا تعرف اللعب؛ أفسح المكان للاعب»."], "cap": ["كانت الطاولات والنرد متعة من الأباطرة إلى الجنود (ارمِ النرد المكعب في قاعة الحظ)"]}], "tl": [["القرن الأول", "الإمبراطور كلوديوس يكتب كتابًا عن لعب النرد"], ["القرن الرابع", "يُستعمل برج نرد في فيلا بألمانيا"], ["نحو 480", "دور الإمبراطور زينون السيئ الحظ"], ["القرن السادس", "أغاثياس ينظم الدور شعرًا"], ["نحو القرن العاشر", "تدخل القصيدة «المختارات اليونانية»"], ["1869", "بيك دو فوكيير يحلّ الوضع والقواعد"], ["1934", "ر. ج. أوستن يعيد فحص دور زينون بالتفصيل"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (10): story 4 (sugoroku) made fuller */
(T => { const D = {"ja": {"sugoroku": {"kf": ["盤双六はバックギャモンの仲間で、7世紀には日本で遊ばれていた", "689年の持統天皇をはじめ、賭けを理由に何度も禁じられた", "明治のころに遊ばれなくなり、「すごろく」は紙の絵双六を指すようになった"], "more": [{"h": "正倉院の双六盤", "p": ["正倉院に伝わる「木画紫檀双六局」は、紫檀の盤に象牙や色をつけた木を細かくはめこんだ豪華な盤です。左右に12ずつ、合わせて24の目があり、中央の仕切りに花の模様が置かれています。", "正倉院には、ガラスや石でできた双六の駒（双六子）もたくさん残っています。盤双六の駒は白と黒の各15個、さいころは2つ。今のバックギャモンとよく似た道具立てで、ペルシアのナルドが中国を経て伝わったと考えられています。"], "cap": ["正倉院の木画紫檀双六局。博物館の所蔵品の部屋で遊べます"]}, {"h": "盤双六の遊び方", "p": ["盤双六では、2人がそれぞれ15の駒を決まった並びに置き、2つのさいころの目だけ進めます。白と黒は逆向きに回り、自分の駒をすべて最後の6つの目（内地）に集めた方の勝ちです。", "ひとつだけで立つ駒は相手に打たれて振り出しに戻されます。2つ以上重なった目には相手が入れないので、駒を組み合わせて道をふさぐのがコツ。博物館の所蔵品の部屋では、この遊び方で正倉院の盤と対局できます。"], "cap": ["盤双六の盤（模式図）。24の目と、白と黒が逆向きに進む道"]}, {"h": "禁止と流行のくり返し", "p": ["持統天皇の禁令のあとも、双六は何度も禁じられました。賭けに夢中になって財産を失う人が後を絶たなかったからです。鎌倉幕府も、双六の賭けを禁じる法令を出しています。", "一方で、双六は貴族の教養でもありました。嫁入り道具に美しい双六盤が入れられ、江戸時代には蒔絵の豪華な盤も作られています。賭けの道具として嫌われ、宝物として愛される――盤双六はその両方の顔を持っていました。"], "cap": ["江戸時代の絵に描かれた盤双六（描かれたゲームの部屋）"]}], "tl": [["7世紀", "盤双六が中国から伝わる"], ["689年", "持統天皇が双六を禁じる（『日本書紀』）"], ["8世紀", "正倉院の木画紫檀双六局が納められる"], ["757年", "養老律令が施行され、僧尼の双六を戒める"], ["平安時代", "『枕草子』『源氏物語』に双六が登場"], ["12世紀", "白河法皇の「双六の賽」の嘆き（『平家物語』）"], ["江戸時代", "嫁入り道具の豪華な盤が作られる"], ["明治", "盤双六がほとんど遊ばれなくなる"]]}}, "en": {"sugoroku": {"kf": ["Ban-sugoroku is a relative of backgammon, played in Japan by the 7th century", "It was banned again and again for gambling, first by Empress Jitō in 689", "By the Meiji era it had faded, and “sugoroku” came to mean the paper picture game"], "more": [{"h": "The Shōsōin board", "p": ["The board kept in the Shōsōin is rosewood inlaid with ivory and stained woods in fine patterns. It has 24 points, twelve on each side, with flowers set on the middle divider.", "The Shōsōin also keeps many sugoroku pieces of glass and stone. Ban-sugoroku uses fifteen white and fifteen black pieces and two dice — much the same kit as backgammon. The game is thought to have come from Persian nard by way of China."], "cap": ["The Shōsōin sugoroku board, inlaid rosewood — play on it in the museum’s Collection room"]}, {"h": "How ban-sugoroku is played", "p": ["Each player sets fifteen pieces in a fixed pattern and moves by the two dice. White and black travel in opposite directions; whoever gathers all their pieces into the last six points first wins.", "A piece standing alone can be hit and sent back to the start. A point holding two or more cannot be entered by the opponent, so the art is to build blocks. In the museum’s Collection room you can play this game on the Shōsōin board."], "cap": ["A ban-sugoroku board (diagram): the 24 points, and white and black running opposite ways"]}, {"h": "Bans and fashions, round and round", "p": ["After Jitō’s ban sugoroku was forbidden again and again, because people kept losing everything to the gambling. Laws of the Kamakura shogunate also warn against betting on it.", "Yet it was also an accomplishment of the nobility. A beautiful board went with a bride’s trousseau, and in the Edo period lavish lacquered boards were made. Hated as a gambler’s tool, loved as a treasure — ban-sugoroku had both faces."], "cap": ["Ban-sugoroku in an Edo-period picture (the In-art room)"]}], "tl": [["7th century", "Ban-sugoroku arrives from China"], ["689", "Empress Jitō bans sugoroku (Nihon shoki)"], ["8th century", "The inlaid rosewood board enters the Shōsōin"], ["757", "The Yōrō Code takes effect, warning monks and nuns off sugoroku"], ["Heian period", "Sugoroku appears in The Pillow Book and The Tale of Genji"], ["12th century", "Emperor Shirakawa’s lament over “the dice of sugoroku” (Tale of the Heike)"], ["Edo period", "Lavish boards are made for brides’ trousseaux"], ["Meiji era", "Ban-sugoroku all but stops being played"]]}}, "zh": {"sugoroku": {"kf": ["盘双六是双陆的同类，7世纪时已在日本流行", "以持统天皇689年的禁令为首，因赌博屡遭禁止", "明治时期渐渐无人再玩，“双六”变成指纸上的绘双六"], "more": [{"h": "正仓院的双六盘", "p": ["正仓院所藏的“木画紫檀双六局”，是在紫檀盘上细细镶嵌象牙和染色木材的华美棋盘。左右各12个、共24个点位，中间的隔栏上饰有花纹。", "正仓院还留有许多玻璃和石头做的双六棋子（双六子）。盘双六用黑白各15枚棋子和2颗骰子，器具与今天的双陆十分相似，一般认为是波斯的纳尔德经中国传来的。"], "cap": ["正仓院的木画紫檀双六局，可在博物馆的馆藏展厅里对弈"]}, {"h": "盘双六怎么玩", "p": ["双方各把15枚棋子按规定摆好，按2颗骰子的点数前进。黑白两方朝相反方向绕行，先把全部棋子集中到最后6个点位（内场）的一方获胜。", "单独立着的棋子会被对方打回起点。叠了两枚以上的点位对方不能进入，所以诀窍是让棋子相连、封住道路。在博物馆的馆藏展厅里，可以用这种玩法在正仓院的棋盘上对局。"], "cap": ["盘双六棋盘（示意图）：24个点位，黑白两方相向而行"]}, {"h": "禁止与流行的反复", "p": ["持统天皇之后，双六又被禁止了许多次，因为沉迷赌博、倾家荡产的人始终不断。镰仓幕府也颁布过禁止以双六赌博的法令。", "另一方面，双六也是贵族的修养。精美的双六盘被列为嫁妆，江户时代还制作了华丽的莳绘棋盘。作为赌具被厌恶，作为珍宝被喜爱——盘双六兼有这两副面孔。"], "cap": ["江户时代画中的盘双六（描绘的游戏展厅）"]}], "tl": [["7世纪", "盘双六从中国传入"], ["689年", "持统天皇禁止双六（《日本书纪》）"], ["8世纪", "木画紫檀双六局被收入正仓院"], ["757年", "《养老律令》施行，告诫僧尼勿玩双六"], ["平安时代", "双六出现在《枕草子》《源氏物语》中"], ["12世纪", "白河法皇感叹“双六的骰子”（《平家物语》）"], ["江户时代", "制作作为嫁妆的华美棋盘"], ["明治", "盘双六几乎无人再玩"]]}}, "zh-TW": {"sugoroku": {"kf": ["盤雙六是雙陸的同類，7世紀時已在日本流行", "以持統天皇689年的禁令為首，因賭博屢遭禁止", "明治時期漸漸無人再玩，「雙六」變成指紙上的繪雙六"], "more": [{"h": "正倉院的雙六盤", "p": ["正倉院所藏的「木畫紫檀雙六局」，是在紫檀盤上細細鑲嵌象牙和染色木材的華美棋盤。左右各12個、共24個點位，中間的隔欄上飾有花紋。", "正倉院還留有許多玻璃和石頭做的雙六棋子（雙六子）。盤雙六用黑白各15枚棋子和2顆骰子，器具與今天的雙陸十分相似，一般認為是波斯的納爾德經中國傳來的。"], "cap": ["正倉院的木畫紫檀雙六局，可在博物館的館藏展廳裡對弈"]}, {"h": "盤雙六怎麼玩", "p": ["雙方各把15枚棋子按規定擺好，按2顆骰子的點數前進。黑白兩方朝相反方向繞行，先把全部棋子集中到最後6個點位（內場）的一方獲勝。", "單獨立著的棋子會被對方打回起點。疊了兩枚以上的點位對方不能進入，所以訣竅是讓棋子相連、封住道路。在博物館的館藏展廳裡，可以用這種玩法在正倉院的棋盤上對局。"], "cap": ["盤雙六棋盤（示意圖）：24個點位，黑白兩方相向而行"]}, {"h": "禁止與流行的反覆", "p": ["持統天皇之後，雙六又被禁止了許多次，因為沉迷賭博、傾家蕩產的人始終不斷。鎌倉幕府也頒布過禁止以雙六賭博的法令。", "另一方面，雙六也是貴族的修養。精美的雙六盤被列為嫁妝，江戶時代還製作了華麗的蒔繪棋盤。作為賭具被厭惡，作為珍寶被喜愛——盤雙六兼有這兩副面孔。"], "cap": ["江戶時代畫中的盤雙六（描繪的遊戲展廳）"]}], "tl": [["7世紀", "盤雙六從中國傳入"], ["689年", "持統天皇禁止雙六（《日本書紀》）"], ["8世紀", "木畫紫檀雙六局被收入正倉院"], ["757年", "《養老律令》施行，告誡僧尼勿玩雙六"], ["平安時代", "雙六出現在《枕草子》《源氏物語》中"], ["12世紀", "白河法皇感嘆「雙六的骰子」（《平家物語》）"], ["江戶時代", "製作作為嫁妝的華美棋盤"], ["明治", "盤雙六幾乎無人再玩"]]}}, "ko": {"sugoroku": {"kf": ["반스고로쿠는 백개먼의 친척으로, 7세기에는 일본에서 즐겼다", "689년 지토 천황을 시작으로, 도박을 이유로 여러 번 금지되었다", "메이지 무렵 잊혀, ‘스고로쿠’는 종이 그림 놀이를 가리키게 되었다"], "more": [{"h": "쇼소인의 스고로쿠 판", "p": ["쇼소인에 전해지는 ‘목화자단 쌍륙국’은 자단 판에 상아와 물들인 나무를 섬세하게 박은 호화로운 판입니다. 좌우에 12개씩, 모두 24개의 칸이 있고 가운데 칸막이에 꽃무늬가 놓여 있습니다.", "쇼소인에는 유리와 돌로 만든 스고로쿠 말도 많이 남아 있습니다. 반스고로쿠는 흑백 각 15개의 말과 주사위 2개를 써서, 지금의 백개먼과 아주 비슷합니다. 페르시아의 나르드가 중국을 거쳐 전해졌다고 봅니다."], "cap": ["쇼소인의 목화자단 스고로쿠 판. 박물관 소장품 전시실에서 둘 수 있습니다"]}, {"h": "반스고로쿠 놀이법", "p": ["두 사람이 각각 15개의 말을 정해진 자리에 놓고, 주사위 2개의 눈만큼 나아갑니다. 흑과 백은 반대 방향으로 돌고, 자기 말을 모두 마지막 6칸(내지)에 먼저 모은 쪽이 이깁니다.", "홀로 선 말은 상대에게 맞아 출발점으로 돌아갑니다. 2개 이상 겹친 칸에는 상대가 들어갈 수 없으므로, 말을 이어 길을 막는 것이 요령입니다. 박물관 소장품 전시실에서 이 방법으로 쇼소인의 판과 대국할 수 있습니다."], "cap": ["반스고로쿠 판(모식도). 24개의 칸과, 흑백이 서로 반대로 나아가는 길"]}, {"h": "금지와 유행의 되풀이", "p": ["지토 천황 이후에도 스고로쿠는 여러 번 금지되었습니다. 도박에 빠져 재산을 잃는 사람이 끊이지 않았기 때문입니다. 가마쿠라 막부도 스고로쿠 도박을 금하는 법령을 냈습니다.", "한편 스고로쿠는 귀족의 교양이기도 했습니다. 아름다운 판이 혼수에 들어갔고, 에도 시대에는 마키에로 꾸민 호화로운 판도 만들어졌습니다. 도박 도구로 미움받고 보물로 사랑받은 ― 반스고로쿠는 두 얼굴을 가졌습니다."], "cap": ["에도 시대 그림에 그려진 반스고로쿠(그려진 게임 전시실)"]}], "tl": [["7세기", "반스고로쿠가 중국에서 전해진다"], ["689년", "지토 천황이 스고로쿠를 금한다(『일본서기』)"], ["8세기", "목화자단 쌍륙국이 쇼소인에 들어간다"], ["757년", "요로 율령 시행, 승려의 스고로쿠를 경계한다"], ["헤이안 시대", "『마쿠라노소시』『겐지 이야기』에 스고로쿠가 나온다"], ["12세기", "시라카와 법황의 ‘스고로쿠 주사위’ 한탄(『헤이케 이야기』)"], ["에도 시대", "혼수용 호화로운 판이 만들어진다"], ["메이지", "반스고로쿠가 거의 사라진다"]]}}, "es": {"sugoroku": {"kf": ["El ban-sugoroku es pariente del backgammon y ya se jugaba en Japón en el siglo VII", "Se prohibió una y otra vez por las apuestas, primero la emperatriz Jitō en 689", "En la era Meiji ya casi no se jugaba, y «sugoroku» pasó a nombrar el juego de papel ilustrado"], "more": [{"h": "El tablero del Shōsōin", "p": ["El tablero del Shōsōin es de palisandro con finas incrustaciones de marfil y maderas teñidas. Tiene 24 puntos, doce por lado, con flores en el separador central.", "El Shōsōin guarda también muchas piezas de sugoroku de vidrio y piedra. El ban-sugoroku usa quince piezas blancas y quince negras y dos dados: casi lo mismo que el backgammon. Se cree que llegó del nard persa a través de China."], "cap": ["El tablero de sugoroku del Shōsōin, de palisandro con incrustaciones; juega en él en la sala Colección"]}, {"h": "Cómo se juega", "p": ["Cada jugador coloca quince piezas en un orden fijo y avanza según dos dados. Blancas y negras giran en sentidos opuestos; gana quien junta antes todas sus piezas en los últimos seis puntos.", "Una pieza sola puede ser golpeada y devuelta al inicio. Un punto con dos o más no admite al rival, así que el arte está en formar bloqueos. En la sala Colección puedes jugar así sobre el tablero del Shōsōin."], "cap": ["Un tablero de ban-sugoroku (esquema): los 24 puntos y el blanco y el negro en sentidos opuestos"]}, {"h": "Prohibiciones y modas", "p": ["Tras Jitō, el sugoroku se prohibió muchas veces más, porque no dejaba de haber quien lo perdía todo apostando. El shogunato de Kamakura también dictó leyes contra las apuestas al sugoroku.", "Pero también era un refinamiento de la nobleza. Un tablero bello formaba parte del ajuar de la novia, y en la época Edo se hicieron lujosos tableros lacados. Odiado como herramienta de apuesta y amado como tesoro: el ban-sugoroku tuvo ambas caras."], "cap": ["Ban-sugoroku en un cuadro de la época Edo (sala Juegos pintados)"]}], "tl": [["Siglo VII", "El ban-sugoroku llega desde China"], ["689", "La emperatriz Jitō prohíbe el sugoroku (Nihon shoki)"], ["Siglo VIII", "El tablero de palisandro entra en el Shōsōin"], ["757", "Entra en vigor el código Yōrō, que lo veta a monjes y monjas"], ["Periodo Heian", "Aparece en El libro de la almohada y La historia de Genji"], ["Siglo XII", "El lamento de Shirakawa por «los dados del sugoroku» (Heike monogatari)"], ["Periodo Edo", "Se hacen lujosos tableros para el ajuar de las novias"], ["Era Meiji", "El ban-sugoroku casi deja de jugarse"]]}}, "fr": {"sugoroku": {"kf": ["Le ban-sugoroku est un cousin du backgammon, joué au Japon dès le VIIe siècle", "Il fut interdit maintes fois à cause des paris, d’abord par l’impératrice Jitō en 689", "À l’ère Meiji, il était presque oublié et « sugoroku » désigna le jeu de l’oie illustré sur papier"], "more": [{"h": "Le plateau du Shōsōin", "p": ["Le plateau du Shōsōin est en palissandre finement marqueté d’ivoire et de bois teintés. Il compte 24 cases, douze de chaque côté, avec des fleurs sur la séparation centrale.", "Le Shōsōin conserve aussi de nombreux pions de sugoroku en verre et en pierre. Le ban-sugoroku se joue avec quinze pions blancs et quinze noirs et deux dés : presque le matériel du backgammon. Il serait venu du nard persan par la Chine."], "cap": ["Le plateau de sugoroku du Shōsōin, en palissandre marqueté — jouez dessus dans la salle Collection"]}, {"h": "Comment on y joue", "p": ["Chacun dispose quinze pions selon un ordre fixe et avance selon deux dés. Blancs et noirs tournent en sens contraire ; gagne celui qui rassemble le premier tous ses pions dans les six dernières cases.", "Un pion seul peut être frappé et renvoyé au départ. Une case qui en porte deux ou plus est interdite à l’adversaire : l’art consiste à bâtir des barrages. Dans la salle Collection, on peut jouer ainsi sur le plateau du Shōsōin."], "cap": ["Un plateau de ban-sugoroku (schéma) : les 24 cases, blancs et noirs tournant en sens contraire"]}, {"h": "Interdits et modes", "p": ["Après Jitō, le sugoroku fut encore interdit bien des fois : il y avait toujours des gens pour y perdre leur fortune. Le shogunat de Kamakura promulgua lui aussi des lois contre les paris au sugoroku.", "Mais c’était aussi un art d’agrément de la noblesse. Un beau plateau faisait partie du trousseau de la mariée, et l’époque Edo produisit de somptueux plateaux laqués. Haï comme instrument de jeu d’argent, aimé comme trésor : le ban-sugoroku avait les deux visages."], "cap": ["Le ban-sugoroku dans une image de l’époque Edo (salle des jeux peints)"]}], "tl": [["VIIe siècle", "Le ban-sugoroku arrive de Chine"], ["689", "L’impératrice Jitō interdit le sugoroku (Nihon shoki)"], ["VIIIe siècle", "Le plateau marqueté entre au Shōsōin"], ["757", "Le code Yōrō l’interdit aux moines et nonnes"], ["Époque Heian", "Il apparaît dans les Notes de chevet et le Dit du Genji"], ["XIIe siècle", "La plainte de Shirakawa sur « les dés du sugoroku » (Dit des Heike)"], ["Époque Edo", "De somptueux plateaux pour les trousseaux de mariée"], ["Ère Meiji", "Le ban-sugoroku n’est presque plus joué"]]}}, "pt": {"sugoroku": {"kf": ["O ban-sugoroku é parente do gamão e já era jogado no Japão no século VII", "Foi proibido várias vezes por causa das apostas, primeiro pela imperatriz Jitō em 689", "Na era Meiji quase não se jogava mais, e “sugoroku” passou a designar o jogo ilustrado de papel"], "more": [{"h": "O tabuleiro do Shōsōin", "p": ["O tabuleiro do Shōsōin é de pau-rosa com finas incrustações de marfim e madeiras tingidas. Tem 24 casas, doze de cada lado, com flores na divisória central.", "O Shōsōin guarda ainda muitas peças de sugoroku de vidro e pedra. O ban-sugoroku usa quinze peças brancas e quinze pretas e dois dados — quase o mesmo do gamão. Acredita-se que veio do nard persa pela China."], "cap": ["O tabuleiro de sugoroku do Shōsōin, em pau-rosa marchetado — jogue nele na sala Acervo"]}, {"h": "Como se joga", "p": ["Cada jogador põe quinze peças numa ordem fixa e anda conforme dois dados. Brancas e pretas giram em sentidos opostos; vence quem reúne primeiro todas as peças nas seis últimas casas.", "Uma peça sozinha pode ser batida e voltar ao início. Uma casa com duas ou mais fica vedada ao rival, então a arte é formar bloqueios. Na sala Acervo dá para jogar assim no tabuleiro do Shōsōin."], "cap": ["Um tabuleiro de ban-sugoroku (esquema): as 24 casas e brancas e pretas em sentidos opostos"]}, {"h": "Proibições e modas", "p": ["Depois de Jitō, o sugoroku foi proibido muitas outras vezes, porque sempre havia quem perdesse tudo nas apostas. O xogunato de Kamakura também baixou leis contra as apostas no sugoroku.", "Mas era também um refinamento da nobreza. Um belo tabuleiro fazia parte do enxoval da noiva, e no período Edo fizeram-se luxuosos tabuleiros laqueados. Odiado como instrumento de aposta, amado como tesouro: o ban-sugoroku teve as duas faces."], "cap": ["Ban-sugoroku numa pintura do período Edo (sala Jogos pintados)"]}], "tl": [["Século VII", "O ban-sugoroku chega da China"], ["689", "A imperatriz Jitō proíbe o sugoroku (Nihon shoki)"], ["Século VIII", "O tabuleiro marchetado entra no Shōsōin"], ["757", "O código Yōrō o veda a monges e monjas"], ["Período Heian", "Aparece em O Livro de Cabeceira e na História de Genji"], ["Século XII", "O lamento de Shirakawa sobre “os dados do sugoroku” (Heike monogatari)"], ["Período Edo", "Fazem-se luxuosos tabuleiros para enxovais"], ["Era Meiji", "O ban-sugoroku quase deixa de ser jogado"]]}}, "de": {"sugoroku": {"kf": ["Ban-Sugoroku ist ein Verwandter des Backgammon und wurde in Japan schon im 7. Jahrhundert gespielt", "Wegen des Glücksspiels wurde es immer wieder verboten, zuerst 689 von Kaiserin Jitō", "In der Meiji-Zeit war es fast vergessen; „Sugoroku“ meinte nun das Bilderspiel auf Papier"], "more": [{"h": "Das Brett im Shōsōin", "p": ["Das Brett im Shōsōin ist aus Palisander mit feinen Einlagen aus Elfenbein und gefärbten Hölzern. Es hat 24 Felder, zwölf auf jeder Seite, mit Blumen auf dem Mittelsteg.", "Im Shōsōin liegen auch viele Sugoroku-Steine aus Glas und Stein. Ban-Sugoroku wird mit fünfzehn weißen und fünfzehn schwarzen Steinen und zwei Würfeln gespielt – fast dieselbe Ausstattung wie Backgammon. Es kam vermutlich vom persischen Nard über China."], "cap": ["Das Sugoroku-Brett des Shōsōin aus eingelegtem Palisander – im Raum „Sammlung“ spielbar"]}, {"h": "Wie man spielt", "p": ["Jeder stellt fünfzehn Steine nach festem Muster auf und zieht nach zwei Würfeln. Weiß und Schwarz laufen in entgegengesetzte Richtungen; wer zuerst alle Steine in den letzten sechs Feldern sammelt, gewinnt.", "Ein einzelner Stein kann geschlagen und zum Start zurückgeschickt werden. Ein Feld mit zwei oder mehr Steinen ist für den Gegner gesperrt – die Kunst ist es, Blockaden zu bauen. Im Raum „Sammlung“ kannst du so auf dem Shōsōin-Brett spielen."], "cap": ["Ein Ban-Sugoroku-Brett (Schema): die 24 Felder, Weiß und Schwarz laufen gegeneinander"]}, {"h": "Verbote und Moden", "p": ["Nach Jitō wurde Sugoroku noch oft verboten, denn immer wieder verspielten Leute ihr ganzes Vermögen. Auch das Kamakura-Shogunat erließ Gesetze gegen Wetten beim Sugoroku.", "Zugleich war es eine Fertigkeit des Adels. Ein schönes Brett gehörte zur Aussteuer der Braut, und in der Edo-Zeit entstanden prächtige Lackbretter. Gehasst als Glücksspielgerät, geliebt als Schatz – Ban-Sugoroku hatte beide Gesichter."], "cap": ["Ban-Sugoroku auf einem Bild der Edo-Zeit (Raum „Gemalte Spiele“)"]}], "tl": [["7. Jh.", "Ban-Sugoroku kommt aus China"], ["689", "Kaiserin Jitō verbietet Sugoroku (Nihon shoki)"], ["8. Jh.", "Das eingelegte Brett kommt ins Shōsōin"], ["757", "Der Yōrō-Kodex verbietet es Mönchen und Nonnen"], ["Heian-Zeit", "Sugoroku im Kopfkissenbuch und im Genji monogatari"], ["12. Jh.", "Shirakawas Klage über „die Würfel des Sugoroku“ (Heike monogatari)"], ["Edo-Zeit", "Prächtige Bretter für die Aussteuer"], ["Meiji-Zeit", "Ban-Sugoroku wird kaum noch gespielt"]]}}, "ru": {"sugoroku": {"kf": ["Бан-сугороку — родня нард; в Японии в неё играли уже в VII веке", "Её снова и снова запрещали из-за азарта, впервые — императрица Дзито в 689 году", "К эпохе Мэйдзи её почти забыли, и «сугороку» стало значить бумажную игру с картинками"], "more": [{"h": "Доска из Сёсоина", "p": ["Доска из Сёсоина сделана из палисандра с тонкой инкрустацией слоновой костью и окрашенным деревом. На ней 24 пункта, по двенадцать с каждой стороны, и цветы на средней перегородке.", "В Сёсоине хранится и много фишек сугороку из стекла и камня. В бан-сугороку играют пятнадцатью белыми и пятнадцатью чёрными фишками и двумя костями — почти как в нардах. Считается, что игра пришла от персидского нарда через Китай."], "cap": ["Доска сугороку из Сёсоина, палисандр с инкрустацией — сыграть на ней можно в зале «Собрание»"]}, {"h": "Как играют", "p": ["Каждый расставляет пятнадцать фишек в установленном порядке и ходит по двум костям. Белые и чёрные идут в противоположные стороны; побеждает тот, кто первым соберёт все фишки на последних шести пунктах.", "Одиночную фишку могут побить и вернуть на старт. На пункт с двумя и более фишками соперник встать не может, поэтому искусство — строить заслоны. В зале «Собрание» можно сыграть так на доске Сёсоина."], "cap": ["Доска бан-сугороку (схема): 24 пункта, белые и чёрные идут навстречу друг другу"]}, {"h": "Запреты и мода", "p": ["После Дзито сугороку запрещали ещё много раз: всегда находились те, кто проигрывал всё состояние. Сёгунат Камакура тоже издавал законы против ставок в сугороку.", "Но это было и умение знати. Красивая доска входила в приданое невесты, а в эпоху Эдо делали роскошные лаковые доски. Ненавидимая как орудие азарта, любимая как сокровище — у бан-сугороку было два лица."], "cap": ["Бан-сугороку на картине эпохи Эдо (зал «Игры на картинах»)"]}], "tl": [["VII в.", "Бан-сугороку приходит из Китая"], ["689", "Императрица Дзито запрещает сугороку («Нихон сёки»)"], ["VIII в.", "Инкрустированная доска поступает в Сёсоин"], ["757", "Кодекс Ёро запрещает её монахам и монахиням"], ["Эпоха Хэйан", "Сугороку в «Записках у изголовья» и «Повести о Гэндзи»"], ["XII в.", "Жалоба Сиракавы на «кости сугороку» («Повесть о доме Тайра»)"], ["Эпоха Эдо", "Роскошные доски для приданого"], ["Эпоха Мэйдзи", "В бан-сугороку почти перестают играть"]]}}, "tr": {"sugoroku": {"kf": ["Ban-sugoroku tavlanın akrabasıdır; Japonya’da 7. yüzyılda oynanıyordu", "Kumar yüzünden defalarca yasaklandı; ilki 689’da İmparatoriçe Jitō", "Meiji döneminde neredeyse unutuldu; “sugoroku” kâğıt resimli oyunun adı oldu"], "more": [{"h": "Shōsōin tahtası", "p": ["Shōsōin’deki tahta, fildişi ve boyalı ahşapla ince kakmalar yapılmış gül ağacındandır. Her yanda on iki, toplam 24 hanesi ve ortadaki bölmede çiçekleri vardır.", "Shōsōin’de camdan ve taştan pek çok sugoroku taşı da saklanır. Ban-sugoroku on beş beyaz, on beş siyah taş ve iki zarla oynanır — tavlayla neredeyse aynı takım. Oyunun İran nardından Çin yoluyla geldiği düşünülür."], "cap": ["Shōsōin’in kakma gül ağacından sugoroku tahtası — Koleksiyon odasında üzerinde oynayabilirsin"]}, {"h": "Nasıl oynanır", "p": ["Her oyuncu on beş taşı belirli bir düzende dizer ve iki zara göre ilerler. Beyaz ve siyah zıt yönlerde döner; bütün taşlarını önce son altı haneye toplayan kazanır.", "Tek başına duran taş vurulup başlangıca gönderilebilir. İki veya daha fazla taşlı haneye rakip giremez; ustalık, kapı kurmaktır. Koleksiyon odasında Shōsōin tahtasında bu şekilde oynayabilirsin."], "cap": ["Bir ban-sugoroku tahtası (şema): 24 hane, beyaz ve siyah zıt yönlere gider"]}, {"h": "Yasaklar ve modalar", "p": ["Jitō’dan sonra sugoroku daha pek çok kez yasaklandı; çünkü kumar yüzünden her şeyini kaybedenler hiç eksik olmadı. Kamakura şogunluğu da sugoroku bahsine karşı yasalar çıkardı.", "Öte yandan soyluların bir hüneriydi de. Güzel bir tahta gelinin çeyizine girer, Edo döneminde gösterişli lake tahtalar yapılırdı. Kumar aleti diye sevilmeyen, hazine diye sevilen ban-sugoroku’nun iki yüzü vardı."], "cap": ["Edo dönemi bir resimde ban-sugoroku (Resimlerdeki Oyunlar odası)"]}], "tl": [["7. yy", "Ban-sugoroku Çin’den gelir"], ["689", "İmparatoriçe Jitō sugorokuyu yasaklar (Nihon shoki)"], ["8. yy", "Kakma tahta Shōsōin’e girer"], ["757", "Yōrō kanunu keşiş ve rahibelere yasaklar"], ["Heian dönemi", "Yastık Kitabı ve Genji’nin Hikâyesi’nde geçer"], ["12. yy", "Shirakawa’nın “sugoroku zarları” yakınması (Heike Hikâyesi)"], ["Edo dönemi", "Çeyiz için gösterişli tahtalar yapılır"], ["Meiji dönemi", "Ban-sugoroku neredeyse hiç oynanmaz olur"]]}}, "id": {"sugoroku": {"kf": ["Ban-sugoroku kerabat backgammon dan sudah dimainkan di Jepang pada abad ke-7", "Berulang kali dilarang karena judi, pertama oleh Maharani Jitō tahun 689", "Pada era Meiji hampir terlupakan, dan “sugoroku” beralih menjadi nama permainan gambar di kertas"], "more": [{"h": "Papan Shōsōin", "p": ["Papan di Shōsōin terbuat dari kayu sonokeling dengan tatahan halus gading dan kayu berwarna. Ada 24 petak, dua belas di tiap sisi, dengan hiasan bunga di sekat tengah.", "Shōsōin juga menyimpan banyak bidak sugoroku dari kaca dan batu. Ban-sugoroku memakai lima belas bidak putih dan lima belas hitam serta dua dadu — hampir sama dengan backgammon. Diduga berasal dari nard Persia lewat Tiongkok."], "cap": ["Papan sugoroku Shōsōin dari kayu sonokeling bertatah — mainkan di ruang Koleksi"]}, {"h": "Cara bermain", "p": ["Tiap pemain menata lima belas bidak menurut pola tetap dan maju sesuai dua dadu. Putih dan hitam berputar berlawanan arah; yang lebih dulu mengumpulkan semua bidak di enam petak terakhir menang.", "Bidak yang sendirian bisa dipukul dan dikembalikan ke awal. Petak berisi dua bidak atau lebih tak bisa dimasuki lawan, jadi seninya adalah membangun blokade. Di ruang Koleksi kamu bisa bermain begini di papan Shōsōin."], "cap": ["Papan ban-sugoroku (bagan): 24 petak, putih dan hitam bergerak berlawanan arah"]}, {"h": "Larangan dan tren", "p": ["Setelah Jitō, sugoroku dilarang lagi berkali-kali, karena selalu ada orang yang kehilangan harta akibat judi. Keshogunan Kamakura juga mengeluarkan aturan melarang taruhan sugoroku.", "Namun sugoroku juga keterampilan kaum bangsawan. Papan indah menjadi bagian barang bawaan pengantin, dan pada zaman Edo dibuat papan bernis mewah. Dibenci sebagai alat judi, dicintai sebagai harta — ban-sugoroku punya dua wajah."], "cap": ["Ban-sugoroku dalam lukisan zaman Edo (ruang Permainan dalam Lukisan)"]}], "tl": [["Abad ke-7", "Ban-sugoroku datang dari Tiongkok"], ["689", "Maharani Jitō melarang sugoroku (Nihon shoki)"], ["Abad ke-8", "Papan bertatah masuk ke Shōsōin"], ["757", "Kitab hukum Yōrō melarangnya bagi biksu dan biksuni"], ["Zaman Heian", "Muncul dalam Buku Bantal dan Hikayat Genji"], ["Abad ke-12", "Keluhan Shirakawa soal “dadu sugoroku” (Hikayat Heike)"], ["Zaman Edo", "Papan mewah dibuat untuk barang bawaan pengantin"], ["Era Meiji", "Ban-sugoroku hampir tak dimainkan lagi"]]}}, "hi": {"sugoroku": {"kf": ["बान‑सुगोरोकु बैकगैमन का रिश्तेदार है, जापान में 7वीं सदी में खेला जाता था", "जुए के कारण बार‑बार रोका गया, पहली बार 689 में महारानी जितो ने", "मेइजी काल तक लगभग भुला दिया गया, और \"सुगोरोकु\" काग़ज़ के चित्र‑खेल का नाम बन गया"], "more": [{"h": "शोसोइन का बोर्ड", "p": ["शोसोइन का बोर्ड शीशम (रोज़वुड) का है, जिस पर हाथीदाँत और रंगी लकड़ी की बारीक जड़ाई है। इसमें 24 ख़ाने हैं, दोनों ओर बारह‑बारह, और बीच की पट्टी पर फूल बने हैं।", "शोसोइन में काँच और पत्थर की बहुत‑सी सुगोरोकु गोटियाँ भी रखी हैं। बान‑सुगोरोकु पंद्रह सफ़ेद, पंद्रह काली गोटियों और दो पासों से खेला जाता है — लगभग बैकगैमन जैसा सामान। माना जाता है कि यह फ़ारसी नर्द से चीन होते हुए आया।"], "cap": ["शोसोइन का जड़ाऊ शीशम का सुगोरोकु बोर्ड — संग्रह कक्ष में इस पर खेलें"]}, {"h": "कैसे खेलते हैं", "p": ["हर खिलाड़ी पंद्रह गोटियाँ तय क्रम में रखता है और दो पासों के अनुसार चलता है। सफ़ेद और काली उलटी दिशाओं में घूमती हैं; जो पहले अपनी सारी गोटियाँ आख़िरी छह ख़ानों में जमा कर ले, वह जीतता है।", "अकेली गोटी पीटी जाकर शुरुआत पर लौटाई जा सकती है। दो या ज़्यादा गोटियों वाले ख़ाने में विरोधी नहीं आ सकता, इसलिए हुनर है नाकेबंदी बनाना। संग्रह कक्ष में शोसोइन के बोर्ड पर ऐसे ही खेल सकते हैं।"], "cap": ["बान‑सुगोरोकु बोर्ड (रेखाचित्र): 24 ख़ाने, सफ़ेद और काली उलटी दिशाओं में"]}, {"h": "रोक और चलन", "p": ["जितो के बाद भी सुगोरोकु पर कई बार रोक लगी, क्योंकि जुए में सब कुछ हार जाने वाले कभी कम नहीं हुए। कामाकुरा शोगुनत ने भी सुगोरोकु पर दाँव के ख़िलाफ़ क़ानून बनाए।", "दूसरी ओर, यह अभिजात वर्ग का एक हुनर भी था। सुंदर बोर्ड दुल्हन के दहेज़ में जाता था, और एदो काल में लाख‑चित्रित शानदार बोर्ड बने। जुए के औज़ार के रूप में नापसंद, ख़ज़ाने के रूप में प्रिय — बान‑सुगोरोकु के दोनों चेहरे थे।"], "cap": ["एदो काल के एक चित्र में बान‑सुगोरोकु (चित्रों में खेल कक्ष)"]}], "tl": [["7वीं सदी", "बान‑सुगोरोकु चीन से आया"], ["689", "महारानी जितो ने सुगोरोकु पर रोक लगाई (निहोन शोकी)"], ["8वीं सदी", "जड़ाऊ बोर्ड शोसोइन में पहुँचा"], ["757", "योरो संहिता ने भिक्षु‑भिक्षुणियों के लिए इसे वर्जित किया"], ["हेइआन काल", "\"तकिये की किताब\" और \"गेंजी की कथा\" में सुगोरोकु"], ["12वीं सदी", "शिराकावा की \"सुगोरोकु के पासों\" वाली शिकायत (हेइके की कथा)"], ["एदो काल", "दहेज़ के लिए शानदार बोर्ड बने"], ["मेइजी काल", "बान‑सुगोरोकु लगभग खेलना बंद हुआ"]]}}, "ar": {"sugoroku": {"kf": ["بان-سوغوروكو قريبة الطاولة، وكانت تُلعب في اليابان في القرن السابع", "حُظرت مرارًا بسبب القمار، أولها على يد الإمبراطورة جيتو سنة 689", "في عصر ميجي كادت تُنسى، وصار «سوغوروكو» اسمًا للعبة الصور الورقية"], "more": [{"h": "لوحة شوسوين", "p": ["لوحة شوسوين من خشب الورد، مطعّمة بدقة بالعاج والأخشاب المصبوغة، وفيها 24 خانة، اثنتا عشرة في كل جانب، وزهور على الفاصل الأوسط.", "ويحفظ شوسوين أيضًا كثيرًا من قطع السوغوروكو المصنوعة من الزجاج والحجر. وتُلعب بان-سوغوروكو بخمس عشرة قطعة بيضاء وخمس عشرة سوداء وحجري نرد، وهي عدة قريبة جدًا من الطاولة. ويُرجّح أنها جاءت من النرد الفارسي عبر الصين."], "cap": ["لوحة سوغوروكو في شوسوين من خشب الورد المطعّم — العب عليها في قاعة المقتنيات"]}, {"h": "طريقة اللعب", "p": ["يرتّب كل لاعب خمس عشرة قطعة بترتيب ثابت ويتقدّم بحسب حجري النرد. ويدور الأبيض والأسود في اتجاهين متعاكسين، ويفوز من يجمع أولًا كل قطعه في الخانات الست الأخيرة.", "والقطعة الوحيدة في خانتها قد تُضرب وتعود إلى البداية. ولا يدخل الخصم خانة فيها قطعتان أو أكثر، فالبراعة في بناء الحواجز. وفي قاعة المقتنيات يمكنك اللعب هكذا على لوحة شوسوين."], "cap": ["لوحة بان-سوغوروكو (مخطط): الخانات الـ24، والأبيض والأسود يسيران في اتجاهين متعاكسين"]}, {"h": "حظر وموضة", "p": ["بعد جيتو حُظرت سوغوروكو مرات كثيرة أخرى، إذ لم يكفّ الناس عن خسارة ثرواتهم في القمار. وأصدرت شوغونية كاماكورا أيضًا قوانين ضد الرهان عليها.", "لكنها كانت كذلك من مهارات النبلاء؛ فكانت اللوحة الجميلة جزءًا من جهاز العروس، وصُنعت في عصر إيدو ألواح فاخرة مطلية باللك. مكروهة أداةً للقمار ومحبوبة كنزًا — كان لبان-سوغوروكو الوجهان معًا."], "cap": ["بان-سوغوروكو في لوحة من عصر إيدو (قاعة الألعاب في الرسوم)"]}], "tl": [["القرن السابع", "تصل بان-سوغوروكو من الصين"], ["689", "الإمبراطورة جيتو تحظر السوغوروكو (نيهون شوكي)"], ["القرن الثامن", "تدخل اللوحة المطعّمة شوسوين"], ["757", "قانون يورو يمنعها على الرهبان والراهبات"], ["عصر هييان", "تظهر في «كتاب الوسادة» و«حكاية غينجي»"], ["القرن الثاني عشر", "شكوى شيراكاوا من «نرد السوغوروكو» (حكاية هيكي)"], ["عصر إيدو", "تُصنع ألواح فاخرة لجهاز العرائس"], ["عصر ميجي", "تكاد بان-سوغوروكو تختفي"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (11): story 5 (queen) made fuller */
(T => { const D = {"ja": {"queen": {"kf": ["女王の前身はペルシア・アラブの「フェルズ（大臣）」で、斜めに1マスしか動けなかった", "1475年ごろのスペインで、今の強い女王の動きが初めて記録された", "新しいルールは印刷された本で、数十年のうちにヨーロッパ中へ広まった"], "more": [{"h": "弱かった大臣", "p": ["フェルズが動けるのは、斜めのとなり1マスだけでした。いまの女王が盤の端から端まで一気に走れるのとは大違いです。そのころのチェスは駒の動きがのんびりしていて、1局が何時間もかかることも珍しくありませんでした。", "象（今のビショップ）も、斜めに2マス目へ跳ぶだけの駒でした。ポーンが最後の列に着くと「成る」決まりはありましたが、なれるのはこの弱いフェルズだけでした。"], "cap": ["フェルズ（左）と今の女王（右）の動ける範囲"]}, {"h": "「女王のチェス」と「狂ったチェス」", "p": ["新しい女王が現れると、スペインではこの遊び方が「女王のチェス（アヘドレス・デ・ラ・ダマ）」、イタリアではその激しさから「狂ったチェス（スカッキ・アッラ・ラッビオーザ）」と呼ばれました。ビショップも同じころ、斜めにどこまでも進めるようになります。", "駒が強くなると、ゲームは一気に速く、激しくなりました。数手で決着がつく罠や、序盤の決まった手順（定跡）を研究する本が次々に書かれ、チェスは「研究する遊び」になっていきます。"], "cap": ["リベラーレ・ダ・ヴェローナ《チェスをする人々》（1475年ごろ）。ちょうど新しい女王が生まれたころの絵です"]}, {"h": "なぜ女王だったのか", "p": ["なぜ大臣が女王に変わったのかは、はっきりしません。王のとなりに立つ駒を王妃と見たのは自然だったのかもしれません。ラテン語では「フェルズ」が「フェルシア」になり、さらに「レジーナ（女王）」と呼ばれるようになりました。", "強くなった理由も、勝負を速くしたかったという考えのほか、カスティーリャのイサベル1世のような力のある女王たちの時代だったからという説があります。歴史家マリリン・ヤーロムは、この変化を中世の女性の地位と結びつけて論じています。"], "cap": ["ルイス島のチェス駒の女王（12世紀）。動きはまだ弱いままでした"]}], "tl": [["6世紀ごろ", "インドでチェスの祖先チャトランガが生まれる"], ["7〜9世紀", "ペルシア・アラブで遊ばれ、王のとなりはフェルズ（大臣）"], ["10世紀ごろ", "チェスがヨーロッパに伝わる"], ["12世紀", "ルイス島のチェス駒に女王が現れる（動きは弱いまま）"], ["1475年ごろ", "バレンシアの詩『スカックス・ダモール』に新しい女王の動き"], ["1497年", "ルセナのチェス本がスペインで印刷される"], ["1512年", "ダミアーノの本がイタリアで出て、新しいルールが広まる"]]}}, "en": {"queen": {"kf": ["The queen began as the Persian and Arab “fers” (counsellor), which could move only one square diagonally", "The strong modern queen first appears in writing in Spain around 1475", "Printed books spread the new rules across Europe within a few decades"], "more": [{"h": "The weak counsellor", "p": ["The fers could step only one square diagonally — a far cry from today’s queen, who can sweep from one edge of the board to the other. Chess in those days moved slowly, and a single game could take hours.", "The elephant (today’s bishop) only leapt two squares diagonally. A pawn that reached the last rank did promote — but only into this weak fers."], "cap": ["How far the fers (left) and the modern queen (right) can move"]}, {"h": "“The queen’s chess” and “mad chess”", "p": ["Once the new queen arrived, the Spanish called the game “the queen’s chess” (ajedrez de la dama), and the Italians, for its fury, “mad chess” (scacchi alla rabbiosa). Around the same time the bishop gained the power to slide any distance diagonally.", "With stronger pieces the game became fast and fierce. Books appeared on traps that win in a few moves and on set opening sequences, and chess became a game to be studied."], "cap": ["Liberale da Verona, The Chess Players (about 1475) — painted just as the new queen was born"]}, {"h": "Why a queen?", "p": ["Why the counsellor became a queen is not certain. Seeing the piece beside the king as his consort may simply have felt natural. In Latin “fers” became “fercia”, and then the piece was called “regina”, the queen.", "Why she grew strong is debated too: perhaps to speed the game up, or perhaps because it was an age of powerful queens such as Isabella I of Castile. The historian Marilyn Yalom linked the change to the standing of women in the Middle Ages."], "cap": ["The queen from the Lewis chessmen (12th century) — still with the old, weak move"]}], "tl": [["c. 6th century", "Chaturanga, the ancestor of chess, appears in India"], ["7th–9th centuries", "Played in Persia and the Arab world, with the fers beside the king"], ["c. 10th century", "Chess reaches Europe"], ["12th century", "The Lewis chessmen include queens (still moving weakly)"], ["c. 1475", "The Valencian poem Scachs d’amor records the new queen’s move"], ["1497", "Lucena’s chess book is printed in Spain"], ["1512", "Damiano’s book appears in Italy, spreading the new rules"]]}}, "zh": {"queen": {"kf": ["皇后的前身是波斯、阿拉伯的“费尔兹（大臣）”，只能斜走一格", "约1475年的西班牙，最早记录了今天强大皇后的走法", "新规则借由印刷的书，在几十年内传遍欧洲"], "more": [{"h": "弱小的大臣", "p": ["费尔兹只能走斜向相邻的一格，和今天能从棋盘一端一口气冲到另一端的皇后大不相同。那时的国际象棋棋子走得很慢，一局下上好几个小时并不稀奇。", "象（今天的主教）也只能斜跳到第二格。兵走到最后一排可以“升变”，但只能变成这个弱小的费尔兹。"], "cap": ["费尔兹（左）与今天的皇后（右）能走的范围"]}, {"h": "“皇后棋”与“疯狂棋”", "p": ["新皇后出现后，西班牙人把这种下法叫作“皇后棋”，意大利人则因其激烈称之为“疯狂棋”。差不多同时，主教也变得可以斜走任意格。", "棋子变强后，对局一下子变得又快又激烈。研究几步就能取胜的陷阱、开局固定走法（定式）的书接连出现，国际象棋成了“需要钻研的游戏”。"], "cap": ["利贝拉莱·达·维罗纳《下棋的人们》（约1475年），正是新皇后诞生时期的画"]}, {"h": "为什么是皇后", "p": ["大臣为什么变成皇后，并不清楚。把站在王旁边的棋子看作王后，也许很自然。在拉丁语里，“费尔兹”变成“费尔西亚”，后来又被叫作“雷吉娜（皇后）”。", "皇后变强的原因，除了想让对局更快分出胜负之外，也有人认为是因为那是卡斯蒂利亚的伊莎贝拉一世等强势女王的时代。历史学家玛丽莲·亚隆把这一变化与中世纪女性的地位联系起来讨论。"], "cap": ["刘易斯岛棋子中的皇后（12世纪），走法仍然很弱"]}], "tl": [["约6世纪", "印度诞生国际象棋的祖先恰图兰卡"], ["7—9世纪", "在波斯、阿拉伯流行，王旁边是费尔兹"], ["约10世纪", "国际象棋传入欧洲"], ["12世纪", "刘易斯岛棋子中出现皇后（走法仍弱）"], ["约1475年", "瓦伦西亚的诗《爱的棋局》记下新皇后的走法"], ["1497年", "卢塞纳的棋书在西班牙印行"], ["1512年", "达米亚诺的书在意大利出版，新规则传开"]]}}, "zh-TW": {"queen": {"kf": ["皇后的前身是波斯、阿拉伯的「費爾茲（大臣）」，只能斜走一格", "約1475年的西班牙，最早記錄了今天強大皇后的走法", "新規則藉由印刷的書，在幾十年內傳遍歐洲"], "more": [{"h": "弱小的大臣", "p": ["費爾茲只能走斜向相鄰的一格，和今天能從棋盤一端一口氣衝到另一端的皇后大不相同。那時的西洋棋棋子走得很慢，一局下上好幾個小時並不稀奇。", "象（今天的主教）也只能斜跳到第二格。兵走到最後一排可以「升變」，但只能變成這個弱小的費爾茲。"], "cap": ["費爾茲（左）與今天的皇后（右）能走的範圍"]}, {"h": "「皇后棋」與「瘋狂棋」", "p": ["新皇后出現後，西班牙人把這種下法叫作「皇后棋」，義大利人則因其激烈稱之為「瘋狂棋」。差不多同時，主教也變得可以斜走任意格。", "棋子變強後，對局一下子變得又快又激烈。研究幾步就能取勝的陷阱、開局固定走法（定式）的書接連出現，西洋棋成了「需要鑽研的遊戲」。"], "cap": ["利貝拉萊·達·維羅納《下棋的人們》（約1475年），正是新皇后誕生時期的畫"]}, {"h": "為什麼是皇后", "p": ["大臣為什麼變成皇后，並不清楚。把站在王旁邊的棋子看作王后，也許很自然。在拉丁語裡，「費爾茲」變成「費爾西亞」，後來又被叫作「雷吉娜（皇后）」。", "皇后變強的原因，除了想讓對局更快分出勝負之外，也有人認為是因為那是卡斯提亞的伊莎貝拉一世等強勢女王的時代。歷史學家瑪麗蓮·亞隆把這一變化與中世紀女性的地位聯繫起來討論。"], "cap": ["劉易斯島棋子中的皇后（12世紀），走法仍然很弱"]}], "tl": [["約6世紀", "印度誕生西洋棋的祖先恰圖蘭卡"], ["7—9世紀", "在波斯、阿拉伯流行，王旁邊是費爾茲"], ["約10世紀", "西洋棋傳入歐洲"], ["12世紀", "劉易斯島棋子中出現皇后（走法仍弱）"], ["約1475年", "瓦倫西亞的詩《愛的棋局》記下新皇后的走法"], ["1497年", "盧塞納的棋書在西班牙印行"], ["1512年", "達米亞諾的書在義大利出版，新規則傳開"]]}}, "ko": {"queen": {"kf": ["여왕의 전신은 페르시아·아랍의 ‘페르즈(대신)’로, 대각선으로 한 칸밖에 못 움직였다", "1475년경 스페인에서 지금의 강한 여왕의 움직임이 처음 기록되었다", "새 규칙은 인쇄된 책을 통해 수십 년 만에 유럽 전역에 퍼졌다"], "more": [{"h": "약했던 대신", "p": ["페르즈는 대각선 옆 한 칸만 갈 수 있었습니다. 판의 끝에서 끝까지 한 번에 달리는 지금의 여왕과는 딴판이지요. 그 무렵 체스는 말의 움직임이 느긋해서 한 판에 몇 시간이 걸리는 일도 흔했습니다.", "코끼리(지금의 비숍)도 대각선 두 칸째로 뛰는 것뿐이었습니다. 폰이 마지막 줄에 닿으면 ‘승진’했지만, 될 수 있는 것은 이 약한 페르즈뿐이었습니다."], "cap": ["페르즈(왼쪽)와 지금의 여왕(오른쪽)이 움직일 수 있는 범위"]}, {"h": "‘여왕의 체스’와 ‘미친 체스’", "p": ["새 여왕이 나타나자 스페인에서는 이 놀이법을 ‘여왕의 체스’, 이탈리아에서는 그 격렬함 때문에 ‘미친 체스’라고 불렀습니다. 비숍도 같은 무렵 대각선으로 얼마든지 갈 수 있게 됩니다.", "말이 강해지자 게임은 단숨에 빠르고 격렬해졌습니다. 몇 수 만에 끝나는 함정이나 정해진 초반 수순(정석)을 연구하는 책이 잇따라 나왔고, 체스는 ‘연구하는 놀이’가 되어 갔습니다."], "cap": ["리베랄레 다 베로나 《체스 두는 사람들》(1475년경). 마침 새 여왕이 태어나던 무렵의 그림입니다"]}, {"h": "왜 여왕이었을까", "p": ["대신이 왜 여왕으로 바뀌었는지는 분명하지 않습니다. 왕 옆에 선 말을 왕비로 본 것은 자연스러웠는지도 모릅니다. 라틴어에서 ‘페르즈’는 ‘페르시아’가 되었다가 ‘레지나(여왕)’라 불리게 됩니다.", "강해진 이유도, 승부를 빨리 내고 싶었다는 생각 외에 카스티야의 이사벨 1세 같은 힘 있는 여왕들의 시대였기 때문이라는 설이 있습니다. 역사가 메릴린 얄롬은 이 변화를 중세 여성의 지위와 연결해 논했습니다."], "cap": ["루이스섬 체스 말의 여왕(12세기). 움직임은 아직 약했습니다"]}], "tl": [["6세기경", "인도에서 체스의 조상 차투랑가가 생겨난다"], ["7~9세기", "페르시아·아랍에서 즐기며, 왕 옆은 페르즈"], ["10세기경", "체스가 유럽에 전해진다"], ["12세기", "루이스섬 체스 말에 여왕이 나타난다(움직임은 약함)"], ["1475년경", "발렌시아의 시 『사랑의 체스』에 새 여왕의 움직임"], ["1497년", "루세나의 체스 책이 스페인에서 인쇄된다"], ["1512년", "다미아누의 책이 이탈리아에서 나와 새 규칙이 퍼진다"]]}}, "es": {"queen": {"kf": ["La dama empezó como el «alferza» o fers persa y árabe (consejero), que solo se movía una casilla en diagonal", "La dama fuerte moderna aparece por escrito en España hacia 1475", "Los libros impresos difundieron las nuevas reglas por Europa en pocas décadas"], "more": [{"h": "El consejero débil", "p": ["El fers solo podía avanzar una casilla en diagonal, muy lejos de la dama de hoy, que cruza el tablero de punta a punta. El ajedrez de entonces era lento, y una partida podía durar horas.", "El elefante (el alfil actual) solo saltaba dos casillas en diagonal. Un peón que llegaba a la última fila coronaba, pero solo en ese débil fers."], "cap": ["Hasta dónde llegan el fers (izquierda) y la dama moderna (derecha)"]}, {"h": "«Ajedrez de la dama» y «ajedrez rabioso»", "p": ["Con la nueva dama, en España se llamó a esta forma de jugar «ajedrez de la dama», y en Italia, por su furia, «scacchi alla rabbiosa» (ajedrez rabioso). Por la misma época el alfil pasó a deslizarse cualquier distancia en diagonal.", "Con piezas más fuertes el juego se volvió rápido y feroz. Aparecieron libros sobre trampas que ganan en pocas jugadas y sobre secuencias fijas de apertura, y el ajedrez se convirtió en un juego para estudiar."], "cap": ["Liberale da Verona, Los jugadores de ajedrez (h. 1475), pintado justo cuando nacía la nueva dama"]}, {"h": "¿Por qué una dama?", "p": ["No se sabe con certeza por qué el consejero se convirtió en dama. Ver a la pieza junto al rey como su consorte quizá resultaba natural. En latín «fers» pasó a «fercia» y luego se la llamó «regina», reina.", "También se discute por qué se hizo fuerte: quizá para acelerar las partidas, quizá porque era una época de reinas poderosas como Isabel I de Castilla. La historiadora Marilyn Yalom relacionó el cambio con la posición de la mujer en la Edad Media."], "cap": ["La dama de las piezas de Lewis (siglo XII), todavía con el movimiento débil"]}], "tl": [["h. siglo VI", "Nace en la India el chaturanga, antepasado del ajedrez"], ["Siglos VII–IX", "Se juega en Persia y el mundo árabe, con el fers junto al rey"], ["h. siglo X", "El ajedrez llega a Europa"], ["Siglo XII", "Las piezas de Lewis incluyen damas (aún débiles)"], ["h. 1475", "El poema valenciano Scachs d’amor recoge el nuevo movimiento"], ["1497", "Se imprime en España el libro de ajedrez de Lucena"], ["1512", "Sale en Italia el libro de Damiano y se difunden las reglas"]]}}, "fr": {"queen": {"kf": ["La dame est née du « fers » persan et arabe (le conseiller), qui ne bougeait que d’une case en diagonale", "La dame forte moderne apparaît par écrit en Espagne vers 1475", "Les livres imprimés ont répandu les nouvelles règles en Europe en quelques décennies"], "more": [{"h": "Le faible conseiller", "p": ["Le fers n’avançait que d’une case en diagonale — rien à voir avec la dame d’aujourd’hui, qui traverse l’échiquier d’un bout à l’autre. Les échecs d’alors étaient lents, et une partie pouvait durer des heures.", "L’éléphant (le fou actuel) sautait seulement à la deuxième case en diagonale. Un pion arrivé au dernier rang était promu — mais seulement en ce faible fers."], "cap": ["Jusqu’où vont le fers (à gauche) et la dame moderne (à droite)"]}, {"h": "« Échecs de la dame » et « échecs enragés »", "p": ["Avec la nouvelle dame, on appela en Espagne ce jeu « échecs de la dame », et en Italie, pour sa fougue, « scacchi alla rabbiosa » (échecs enragés). À la même époque, le fou put glisser à n’importe quelle distance en diagonale.", "Avec des pièces plus fortes, le jeu devint rapide et féroce. Des livres parurent sur les pièges qui gagnent en quelques coups et sur des suites d’ouverture fixes : les échecs devinrent un jeu qu’on étudie."], "cap": ["Liberale da Verona, Les Joueurs d’échecs (vers 1475), peint au moment même où naissait la nouvelle dame"]}, {"h": "Pourquoi une dame ?", "p": ["On ne sait pas au juste pourquoi le conseiller devint une dame. Voir la pièce placée près du roi comme son épouse semblait peut-être naturel. En latin, « fers » devint « fercia », puis la pièce fut appelée « regina », la reine.", "La raison de sa force est débattue aussi : accélérer les parties, ou l’époque des reines puissantes comme Isabelle Ire de Castille. L’historienne Marilyn Yalom a relié ce changement à la place des femmes au Moyen Âge."], "cap": ["La dame des pièces de Lewis (XIIe siècle), au déplacement encore faible"]}], "tl": [["v. VIe siècle", "Le chaturanga, ancêtre des échecs, naît en Inde"], ["VIIe–IXe siècles", "Joué en Perse et dans le monde arabe, avec le fers près du roi"], ["v. Xe siècle", "Les échecs arrivent en Europe"], ["XIIe siècle", "Les pièces de Lewis comptent des dames (encore faibles)"], ["v. 1475", "Le poème valencien Scachs d’amor décrit le nouveau déplacement"], ["1497", "Le livre d’échecs de Lucena est imprimé en Espagne"], ["1512", "Le livre de Damiano paraît en Italie et diffuse les règles"]]}}, "pt": {"queen": {"kf": ["A dama nasceu do “fers” persa e árabe (o conselheiro), que só andava uma casa na diagonal", "A dama forte moderna aparece por escrito na Espanha por volta de 1475", "Livros impressos espalharam as novas regras pela Europa em poucas décadas"], "more": [{"h": "O conselheiro fraco", "p": ["O fers só andava uma casa na diagonal — bem diferente da dama de hoje, que cruza o tabuleiro de ponta a ponta. O xadrez de então era lento, e uma partida podia levar horas.", "O elefante (o bispo atual) só saltava duas casas na diagonal. Um peão que chegava à última fileira era promovido — mas apenas a esse fraco fers."], "cap": ["Até onde vão o fers (à esquerda) e a dama moderna (à direita)"]}, {"h": "“Xadrez da dama” e “xadrez raivoso”", "p": ["Com a nova dama, na Espanha esse jogo passou a ser chamado de “xadrez da dama”, e na Itália, por sua fúria, “scacchi alla rabbiosa” (xadrez raivoso). Na mesma época, o bispo passou a deslizar qualquer distância na diagonal.", "Com peças mais fortes, o jogo ficou rápido e feroz. Surgiram livros sobre armadilhas que vencem em poucos lances e sobre sequências fixas de abertura, e o xadrez virou um jogo de estudo."], "cap": ["Liberale da Verona, Os jogadores de xadrez (c. 1475), pintado justo quando nascia a nova dama"]}, {"h": "Por que uma dama?", "p": ["Não se sabe ao certo por que o conselheiro virou dama. Ver a peça ao lado do rei como sua consorte talvez parecesse natural. Em latim, “fers” virou “fercia” e depois a peça foi chamada de “regina”, rainha.", "Também se discute por que ficou forte: talvez para acelerar as partidas, talvez por ser uma época de rainhas poderosas como Isabel I de Castela. A historiadora Marilyn Yalom ligou a mudança à posição da mulher na Idade Média."], "cap": ["A dama das peças de Lewis (século XII), ainda com o movimento fraco"]}], "tl": [["c. século VI", "Nasce na Índia o chaturanga, ancestral do xadrez"], ["Séculos VII–IX", "Jogado na Pérsia e no mundo árabe, com o fers ao lado do rei"], ["c. século X", "O xadrez chega à Europa"], ["Século XII", "As peças de Lewis têm damas (ainda fracas)"], ["c. 1475", "O poema valenciano Scachs d’amor registra o novo movimento"], ["1497", "O livro de xadrez de Lucena é impresso na Espanha"], ["1512", "Sai na Itália o livro de Damiano e as regras se espalham"]]}}, "de": {"queen": {"kf": ["Die Dame begann als persischer und arabischer „Fers“ (Ratgeber), der nur ein Feld diagonal ziehen konnte", "Die starke moderne Dame erscheint um 1475 in Spanien zum ersten Mal schriftlich", "Gedruckte Bücher verbreiteten die neuen Regeln in wenigen Jahrzehnten in ganz Europa"], "more": [{"h": "Der schwache Ratgeber", "p": ["Der Fers konnte nur ein Feld diagonal ziehen – ganz anders als die heutige Dame, die von einem Rand zum anderen jagt. Schach war damals langsam, eine Partie konnte Stunden dauern.", "Der Elefant (der heutige Läufer) sprang nur zwei Felder diagonal. Ein Bauer auf der letzten Reihe wurde umgewandelt – aber nur in diesen schwachen Fers."], "cap": ["Wie weit der Fers (links) und die heutige Dame (rechts) ziehen können"]}, {"h": "„Damenschach“ und „wütendes Schach“", "p": ["Mit der neuen Dame nannte man das Spiel in Spanien „Damenschach“ (ajedrez de la dama) und in Italien wegen seiner Wucht „scacchi alla rabbiosa“, wütendes Schach. Etwa zur gleichen Zeit durfte auch der Läufer beliebig weit diagonal ziehen.", "Mit stärkeren Figuren wurde das Spiel schnell und heftig. Es erschienen Bücher über Fallen, die in wenigen Zügen gewinnen, und über feste Eröffnungsfolgen – Schach wurde zum Spiel, das man studiert."], "cap": ["Liberale da Verona, Die Schachspieler (um 1475) – gemalt, gerade als die neue Dame entstand"]}, {"h": "Warum eine Dame?", "p": ["Warum der Ratgeber zur Dame wurde, ist nicht sicher. Die Figur neben dem König als seine Gemahlin zu sehen, lag vielleicht nahe. Im Lateinischen wurde „Fers“ zu „fercia“, später hieß die Figur „regina“, Königin.", "Auch warum sie stark wurde, ist umstritten: um das Spiel zu beschleunigen, oder weil es eine Zeit mächtiger Königinnen wie Isabella I. von Kastilien war. Die Historikerin Marilyn Yalom verband den Wandel mit der Stellung der Frau im Mittelalter."], "cap": ["Die Dame aus den Lewis-Schachfiguren (12. Jh.) – noch mit dem alten, schwachen Zug"]}], "tl": [["um das 6. Jh.", "In Indien entsteht Chaturanga, der Vorfahr des Schachs"], ["7.–9. Jh.", "Gespielt in Persien und der arabischen Welt, neben dem König der Fers"], ["um das 10. Jh.", "Schach erreicht Europa"], ["12. Jh.", "Unter den Lewis-Figuren gibt es Damen (noch schwach)"], ["um 1475", "Das valencianische Gedicht Scachs d’amor beschreibt den neuen Zug"], ["1497", "Lucenas Schachbuch wird in Spanien gedruckt"], ["1512", "Damianos Buch erscheint in Italien und verbreitet die Regeln"]]}}, "ru": {"queen": {"kf": ["Ферзь начинался как персидский и арабский «ферз» (советник), ходивший лишь на одно поле по диагонали", "Сильный современный ферзь впервые описан в Испании около 1475 года", "Печатные книги за несколько десятилетий разнесли новые правила по Европе"], "more": [{"h": "Слабый советник", "p": ["Старый ферз ходил лишь на одно поле по диагонали — совсем не то, что нынешний ферзь, проносящийся через всю доску. Шахматы тогда были медленными, и партия могла длиться часами.", "Слон тоже лишь прыгал через поле по диагонали. Пешка, дойдя до последней горизонтали, превращалась — но только в этого слабого ферза."], "cap": ["Как далеко ходят старый ферз (слева) и нынешний ферзь (справа)"]}, {"h": "«Шахматы дамы» и «бешеные шахматы»", "p": ["С появлением нового ферзя в Испании такую игру назвали «шахматами дамы», а в Италии за её неистовство — «бешеными шахматами» (scacchi alla rabbiosa). Примерно тогда же слон получил право скользить по диагонали на любое расстояние.", "С сильными фигурами игра стала быстрой и острой. Появились книги о ловушках, выигрывающих за несколько ходов, и о заученных дебютных последовательностях, — шахматы стали игрой, которую изучают."], "cap": ["Либерале да Верона, «Игроки в шахматы» (около 1475) — написано как раз тогда, когда родился новый ферзь"]}, {"h": "Почему королева?", "p": ["Почему советник стал королевой, точно неизвестно. Видеть в фигуре рядом с королём его супругу, наверное, было естественно. По-латыни «ферз» превратился в «fercia», а затем фигуру стали звать «regina» — королева.", "Спорят и о том, почему она усилилась: чтобы ускорить игру или потому, что это была эпоха сильных королев вроде Изабеллы I Кастильской. Историк Мэрилин Ялом связала эту перемену с положением женщин в Средние века."], "cap": ["Королева из шахмат с острова Льюис (XII в.) — всё ещё со старым, слабым ходом"]}], "tl": [["ок. VI в.", "В Индии появляется чатуранга — предок шахмат"], ["VII–IX вв.", "Играют в Персии и арабском мире, рядом с королём — ферз"], ["ок. X в.", "Шахматы приходят в Европу"], ["XII в.", "Среди шахмат с Льюиса есть королевы (ещё слабые)"], ["ок. 1475", "Валенсийская поэма «Scachs d’amor» описывает новый ход"], ["1497", "В Испании печатается шахматная книга Лусены"], ["1512", "В Италии выходит книга Дамиано, новые правила распространяются"]]}}, "tr": {"queen": {"kf": ["Vezirin atası, çaprazlama yalnızca bir kare gidebilen Fars ve Arap “fers”iydi (danışman)", "Bugünkü güçlü vezir ilk kez 1475 dolaylarında İspanya’da yazıya geçti", "Basılı kitaplar yeni kuralları birkaç on yılda Avrupa’ya yaydı"], "more": [{"h": "Zayıf danışman", "p": ["Fers yalnızca çaprazlama bir kare gidebiliyordu; tahtanın bir ucundan öbürüne koşan bugünkü vezirden çok farklıydı. O zamanki satranç yavaştı, bir oyun saatler sürebilirdi.", "Fil de yalnızca çaprazlama ikinci kareye sıçrardı. Son sıraya varan piyon terfi ederdi — ama yalnızca bu zayıf fers’e."], "cap": ["Fers (solda) ve bugünkü vezirin (sağda) gidebildiği yerler"]}, {"h": "“Vezir satrancı” ve “çılgın satranç”", "p": ["Yeni vezir ortaya çıkınca İspanya’da bu oyuna “vezir satrancı”, İtalya’da ise sertliğinden ötürü “çılgın satranç” (scacchi alla rabbiosa) dendi. Aynı sıralarda fil de çaprazlama istediği kadar kayabilir oldu.", "Taşlar güçlenince oyun hızlanıp sertleşti. Birkaç hamlede kazanan tuzaklar ve sabit açılış dizileri üzerine kitaplar çıktı; satranç incelenen bir oyuna dönüştü."], "cap": ["Liberale da Verona, Satranç Oynayanlar (1475 dolayları) — yeni vezirin doğduğu sıralarda yapıldı"]}, {"h": "Neden kraliçe?", "p": ["Danışmanın neden kraliçeye dönüştüğü kesin değil. Şahın yanında duran taşı onun eşi saymak belki doğal geldi. Latincede “fers” “fercia” oldu, sonra taşa “regina”, yani kraliçe dendi.", "Neden güçlendiği de tartışmalı: oyunu hızlandırmak için, ya da Kastilya Kraliçesi I. Isabel gibi güçlü kraliçelerin çağı olduğu için. Tarihçi Marilyn Yalom bu değişimi Orta Çağ’da kadınların konumuyla ilişkilendirdi."], "cap": ["Lewis satranç taşlarından kraliçe (12. yy) — hâlâ eski, zayıf hareketiyle"]}], "tl": [["y. 6. yy", "Hindistan’da satrancın atası çaturanga doğar"], ["7.–9. yy", "İran ve Arap dünyasında oynanır; şahın yanında fers vardır"], ["y. 10. yy", "Satranç Avrupa’ya ulaşır"], ["12. yy", "Lewis taşları arasında kraliçeler vardır (hâlâ zayıf)"], ["y. 1475", "Valensiya şiiri Scachs d’amor yeni hareketi anlatır"], ["1497", "Lucena’nın satranç kitabı İspanya’da basılır"], ["1512", "Damiano’nun kitabı İtalya’da çıkar, kurallar yayılır"]]}}, "id": {"queen": {"kf": ["Ratu bermula dari “fers” Persia dan Arab (penasihat), yang hanya bisa melangkah satu petak diagonal", "Ratu kuat modern pertama kali tercatat di Spanyol sekitar 1475", "Buku cetak menyebarkan aturan baru ke seluruh Eropa dalam beberapa dasawarsa"], "more": [{"h": "Penasihat yang lemah", "p": ["Fers hanya bisa melangkah satu petak diagonal — jauh berbeda dari ratu masa kini yang melesat dari ujung ke ujung papan. Catur saat itu lambat, dan satu permainan bisa berlangsung berjam-jam.", "Gajah (benteng miring masa kini) hanya melompat dua petak diagonal. Pion yang mencapai baris terakhir memang dipromosikan — tetapi hanya menjadi fers yang lemah ini."], "cap": ["Jangkauan fers (kiri) dan ratu modern (kanan)"]}, {"h": "“Catur ratu” dan “catur gila”", "p": ["Setelah ratu baru muncul, orang Spanyol menyebut permainan ini “catur ratu”, dan orang Italia, karena keganasannya, “catur gila” (scacchi alla rabbiosa). Sekitar waktu yang sama, gajah juga boleh meluncur diagonal sejauh apa pun.", "Dengan bidak yang lebih kuat, permainan menjadi cepat dan sengit. Muncul buku tentang jebakan yang menang dalam beberapa langkah dan urutan pembukaan yang baku; catur menjadi permainan yang dipelajari."], "cap": ["Liberale da Verona, Para Pemain Catur (sekitar 1475) — dilukis tepat saat ratu baru lahir"]}, {"h": "Mengapa ratu?", "p": ["Mengapa penasihat berubah menjadi ratu tidak pasti. Melihat bidak di samping raja sebagai permaisurinya mungkin terasa wajar. Dalam bahasa Latin, “fers” menjadi “fercia”, lalu bidak itu disebut “regina”, ratu.", "Alasan ia menjadi kuat juga diperdebatkan: untuk mempercepat permainan, atau karena saat itu zaman ratu-ratu berkuasa seperti Isabel I dari Kastilia. Sejarawan Marilyn Yalom mengaitkan perubahan ini dengan kedudukan perempuan di Abad Pertengahan."], "cap": ["Ratu dari bidak catur Lewis (abad ke-12) — masih dengan langkah lama yang lemah"]}], "tl": [["sekitar abad ke-6", "Chaturanga, leluhur catur, lahir di India"], ["abad ke-7–9", "Dimainkan di Persia dan dunia Arab, dengan fers di samping raja"], ["sekitar abad ke-10", "Catur sampai di Eropa"], ["abad ke-12", "Bidak catur Lewis memuat ratu (masih lemah)"], ["sekitar 1475", "Puisi Valencia Scachs d’amor mencatat langkah baru"], ["1497", "Buku catur Lucena dicetak di Spanyol"], ["1512", "Buku Damiano terbit di Italia dan aturan baru menyebar"]]}}, "hi": {"queen": {"kf": ["रानी (वज़ीर) का पूर्वज फ़ारसी‑अरबी \"फ़र्ज़\" (सलाहकार) था, जो तिरछा बस एक ख़ाना चलता था", "आज की ताक़तवर रानी पहली बार लगभग 1475 में स्पेन में लिखित मिलती है", "छपी किताबों ने कुछ ही दशकों में नए नियम पूरे यूरोप में फैला दिए"], "more": [{"h": "कमज़ोर सलाहकार", "p": ["फ़र्ज़ बस तिरछा एक ख़ाना चल सकता था — आज की रानी से बिल्कुल अलग, जो बिसात के एक छोर से दूसरे तक दौड़ जाती है। तब शतरंज धीमी थी, और एक बाज़ी घंटों चल सकती थी।", "हाथी (आज का ऊँट/बिशप) भी बस तिरछा दूसरे ख़ाने पर कूदता था। प्यादा आख़िरी पंक्ति तक पहुँचकर पदोन्नत होता था — पर सिर्फ़ इसी कमज़ोर फ़र्ज़ में।"], "cap": ["फ़र्ज़ (बाएँ) और आज की रानी (दाएँ) कहाँ तक चल सकते हैं"]}, {"h": "\"रानी की शतरंज\" और \"पागल शतरंज\"", "p": ["नई रानी के आने पर स्पेन में इस खेल को \"रानी की शतरंज\" कहा गया, और इटली में उसकी तेज़ी के कारण \"पागल शतरंज\" (scacchi alla rabbiosa)। लगभग उसी समय बिशप भी तिरछा कितनी भी दूर सरकने लगा।", "मोहरे ताक़तवर हुए तो खेल तेज़ और तीखा हो गया। कुछ ही चालों में जिताने वाले जालों और तय शुरुआती चालों पर किताबें आने लगीं — शतरंज अध्ययन का खेल बन गई।"], "cap": ["लिबेराले दा वेरोना, \"शतरंज खेलते लोग\" (लगभग 1475) — ठीक उसी समय का चित्र जब नई रानी जन्मी"]}, {"h": "रानी ही क्यों?", "p": ["सलाहकार रानी क्यों बना, यह पक्का नहीं। राजा के पास खड़े मोहरे को उसकी पत्नी मानना शायद स्वाभाविक लगा। लैटिन में \"फ़र्ज़\" \"फ़र्सिया\" बना और फिर मोहरे को \"रेजिना\" यानी रानी कहा जाने लगा।", "उसके ताक़तवर होने की वजह पर भी बहस है: खेल तेज़ करने के लिए, या इसलिए कि वह कास्तील की इसाबेला प्रथम जैसी शक्तिशाली रानियों का दौर था। इतिहासकार मर्लिन यालोम ने इस बदलाव को मध्ययुग में स्त्रियों की स्थिति से जोड़ा।"], "cap": ["लुईस द्वीप के शतरंज‑मोहरों की रानी (12वीं सदी) — अभी पुरानी, कमज़ोर चाल के साथ"]}], "tl": [["लगभग 6वीं सदी", "भारत में शतरंज का पूर्वज चतुरंग जन्मा"], ["7वीं–9वीं सदी", "फ़ारस और अरब जगत में खेला गया, राजा के पास फ़र्ज़"], ["लगभग 10वीं सदी", "शतरंज यूरोप पहुँची"], ["12वीं सदी", "लुईस द्वीप के मोहरों में रानियाँ (अभी कमज़ोर)"], ["लगभग 1475", "वालेंसिया की कविता \"स्काक्स दामोर\" में नई चाल"], ["1497", "लुसेना की शतरंज‑पुस्तक स्पेन में छपी"], ["1512", "दामियानो की पुस्तक इटली में छपी, नए नियम फैले"]]}}, "ar": {"queen": {"kf": ["بدأ الوزير/الملكة «فرزًا» فارسيًا عربيًا (مستشارًا) لا يتحرك إلا خانة واحدة قطريًا", "ظهرت الملكة القوية الحديثة مكتوبة لأول مرة في إسبانيا نحو 1475", "نشرت الكتب المطبوعة القواعد الجديدة في أوروبا خلال عقود قليلة"], "more": [{"h": "المستشار الضعيف", "p": ["لم يكن الفرز يتحرك إلا خانة واحدة قطريًا — بعيدًا جدًا عن ملكة اليوم التي تعبر الرقعة من طرف إلى طرف. وكان الشطرنج آنذاك بطيئًا، وقد يستغرق الدور ساعات.", "وكان الفيل لا يقفز إلا إلى الخانة الثانية قطريًا. والبيدق الذي يبلغ الصف الأخير يترقّى — لكن إلى هذا الفرز الضعيف وحده."], "cap": ["مدى حركة الفرز (يسارًا) والملكة الحديثة (يمينًا)"]}, {"h": "«شطرنج الملكة» و«الشطرنج المجنون»", "p": ["لما ظهرت الملكة الجديدة سُمّيت اللعبة في إسبانيا «شطرنج الملكة»، وفي إيطاليا لشدتها «الشطرنج المجنون» (scacchi alla rabbiosa). وفي الفترة نفسها صار الفيل ينزلق قطريًا أي مسافة.", "ومع القطع الأقوى صارت اللعبة سريعة شرسة. وظهرت كتب عن فخاخ تُكسب في نقلات قليلة وعن افتتاحيات ثابتة، فصار الشطرنج لعبة تُدرَس."], "cap": ["ليبيرالي دا فيرونا، «لاعبو الشطرنج» (نحو 1475)، رُسمت حين وُلدت الملكة الجديدة تمامًا"]}, {"h": "لماذا ملكة؟", "p": ["لا يُعرف يقينًا لماذا صار المستشار ملكة. ولعل رؤية القطعة التي بجوار الملك زوجةً له بدت طبيعية. ففي اللاتينية صار «فرز» «فيرسيا»، ثم سُمّيت القطعة «ريجينا» أي الملكة.", "ويُختلف أيضًا في سبب قوتها: لتسريع اللعب، أو لأنه كان عصر ملكات قويات مثل إيزابيلا الأولى ملكة قشتالة. وقد ربطت المؤرخة مارلين يالوم هذا التغير بمكانة المرأة في العصور الوسطى."], "cap": ["الملكة من قطع شطرنج جزيرة لويس (القرن الثاني عشر)، ما زالت بحركتها القديمة الضعيفة"]}], "tl": [["نحو القرن السادس", "تنشأ التشاتورانغا في الهند، سلف الشطرنج"], ["القرن 7–9", "تُلعب في فارس والعالم العربي، والفرز بجوار الملك"], ["نحو القرن العاشر", "يصل الشطرنج إلى أوروبا"], ["القرن الثاني عشر", "بين قطع لويس ملكات (ما زالت ضعيفة)"], ["نحو 1475", "القصيدة البلنسية «سكاكس دامور» تذكر الحركة الجديدة"], ["1497", "يُطبع كتاب لوثينا في الشطرنج بإسبانيا"], ["1512", "يصدر كتاب داميانو في إيطاليا فتنتشر القواعد"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
