/* 2026-11-24 (13): story 6 (senet) made fuller */
(T => { const D = {"ja": {"senet": {"kf": ["3列×10マス、30マスの盤で駒を進める、世界でも最古級のボードゲーム", "名前は「通り過ぎること」。新王国時代には魂があの世を抜ける旅と重ねられた", "遊び方の記録は残っておらず、今のルールは20世紀の研究者による復元"], "more": [{"h": "30マスの盤と特別なマス", "p": ["セネトの盤は3列に10マスずつ、合わせて30マス。駒は1列目を左から右へ、2列目を右から左へ、3列目をまた左から右へと、S字を描いて進んだと考えられています。", "最後の5マスには、とくに意味のある印が描かれることが多くありました。26番目は「美しい家」、27番目は「水」のマスで、水に落ちた駒は戻されるという復元が一般的です。28〜30番目には、数字やあの世の神々の姿が描かれました。"], "cap": ["セネトの盤。駒はS字に進み、最後の5マス（26〜30）には特別な印がある"]}, {"h": "投げ棒で進む", "p": ["さいころの代わりに使われたのは、片面が平らで片面が丸い4本の棒や、動物の距骨でした。平らな面が上を向いた本数で進む数を決め、0本のときは5進む――と考える研究者が多くいます。", "この数え方は、遠く離れた韓国のユンノリの棒とまったく同じです。博物館の「偶然の道具」の部屋で投げ棒を振ると、1〜5の出やすさの違いを確かめられます。"], "cap": ["エジプトの投げ棒（偶然の道具の部屋で振れます）"]}, {"h": "ツタンカーメンのゲーム箱", "p": ["1922年にハワード・カーターが開いたツタンカーメンの墓には、少なくとも5つのゲーム箱が納められていました。いちばん大きな箱は黒檀と象牙でできていて、引き出しに駒と投げ棒をしまえます。", "表と裏の両方が盤になった箱は、この時代によく作られました。片面がセネト、もう片面がウルのゲームと同じ20マスの盤です。王は、あの世でもどちらのゲームでも遊べるように、と願われたのでしょう。"], "cap": ["ツタンカーメンのセネト箱（所蔵品の部屋で3Dで見て、遊べます）"]}], "tl": [["前3100年ごろ", "第1王朝の墓から、セネトらしい盤の破片"], ["前2600年ごろ", "古王国の墓の壁画に、セネトを打つ人々が描かれる"], ["前1550年ごろ〜", "新王国時代。セネトがあの世への旅と結びつく"], ["前1323年ごろ", "ツタンカーメンの墓に5つのゲーム箱が納められる"], ["前1250年ごろ", "ネフェルタリの墓の壁に、セネトに向かう王妃が描かれる"], ["1922年", "カーターがツタンカーメンの墓を開く"], ["1978年", "ケンドールが遊び方の復元を発表"]]}}, "en": {"senet": {"kf": ["One of the world’s oldest board games: pieces race over a board of 3 × 10 squares", "Its name means “passing”; in the New Kingdom it became the soul’s journey through the afterlife", "No rules survive; today’s ways of play are 20th-century reconstructions"], "more": [{"h": "Thirty squares and the special ones", "p": ["A senet board has three rows of ten — thirty squares. The pieces are thought to have run left to right along the first row, right to left along the second and left to right again along the third, tracing an S.", "The last five squares were often marked with special signs. Square 26 is the “beautiful house”, 27 the “water”, and in most reconstructions a piece that falls into the water is sent back. Squares 28 to 30 bore numbers or gods of the afterlife."], "cap": ["A senet board. The pieces run in an S; the last five squares (26–30) carry special signs"]}, {"h": "Moving by throwing sticks", "p": ["Instead of dice the players threw four sticks, flat on one side and round on the other, or animal knucklebones. Many scholars think the number of flat sides up gave the move, with none up counting five.", "That count is exactly the one used with the yut sticks of faraway Korea. Throw the sticks in the museum’s Chance room and see how much more often some scores come than others."], "cap": ["Egyptian throwing sticks (throw them in the Chance room)"]}, {"h": "Tutankhamun’s game boxes", "p": ["The tomb of Tutankhamun, opened by Howard Carter in 1922, held at least five game boxes. The largest is of ebony and ivory, with a drawer for the pieces and sticks.", "Boxes with a board on both sides were common in this period: senet on one face, and on the other the same twenty-square game as the Royal Game of Ur. The king was meant to be able to play either game in the next world."], "cap": ["Tutankhamun’s senet box — see it in 3D and play on it in the Collection room"]}], "tl": [["c. 3100 BC", "Fragments of a senet-like board in a First Dynasty tomb"], ["c. 2600 BC", "Old Kingdom tomb paintings show people playing senet"], ["From c. 1550 BC", "New Kingdom: senet is tied to the journey into the afterlife"], ["c. 1323 BC", "Five game boxes are laid in Tutankhamun’s tomb"], ["c. 1250 BC", "Queen Nefertari is painted at a senet board in her tomb"], ["1922", "Carter opens Tutankhamun’s tomb"], ["1978", "Kendall publishes a reconstruction of the rules"]]}}, "zh": {"senet": {"kf": ["在3排×10格、共30格的棋盘上移动棋子，是世界上最古老的棋类之一", "名字意为“经过”，新王国时期被看作灵魂穿越冥界的旅程", "没有留下玩法记录，今天的规则是20世纪学者的复原"], "more": [{"h": "30格棋盘与特殊格", "p": ["塞尼特棋盘有3排，每排10格，共30格。一般认为棋子在第1排从左到右、第2排从右到左、第3排再从左到右，画出S形前进。", "最后5格常画有特别的记号。第26格是“美丽之屋”，第27格是“水”，多数复原认为掉进水里的棋子要退回。第28到30格画着数字或冥界诸神。"], "cap": ["塞尼特棋盘。棋子呈S形前进，最后5格（26—30）有特殊记号"]}, {"h": "掷棍前进", "p": ["代替骰子的是4根一面平、一面圆的棍子，或动物的距骨。许多学者认为按平面朝上的根数前进，0根时走5步。", "这种算法和遥远韩国掷柶的棍子完全一样。在博物馆的“偶然的道具”展厅掷投掷棒，就能看出1到5出现的难易差别。"], "cap": ["埃及的投掷棒（可在“偶然的道具”展厅里掷）"]}, {"h": "图坦卡蒙的游戏箱", "p": ["1922年霍华德·卡特打开的图坦卡蒙墓中，至少放着5个游戏箱。最大的一个用乌木和象牙制成，抽屉里可以收放棋子和投掷棒。", "这个时期常做两面都是棋盘的箱子：一面是塞尼特，另一面是与乌尔王家游戏相同的20格棋盘。人们大概希望国王在另一个世界里两种游戏都能玩。"], "cap": ["图坦卡蒙的塞尼特箱（可在馆藏展厅以3D观看并对弈）"]}], "tl": [["约前3100年", "第1王朝墓中出土类似塞尼特的棋盘残片"], ["约前2600年", "古王国墓室壁画描绘下塞尼特的人"], ["约前1550年起", "新王国时期，塞尼特与冥界之旅相连"], ["约前1323年", "图坦卡蒙墓中放入5个游戏箱"], ["约前1250年", "奈菲尔塔利墓壁上画着面对塞尼特的王后"], ["1922年", "卡特打开图坦卡蒙墓"], ["1978年", "肯德尔发表玩法复原"]]}}, "zh-TW": {"senet": {"kf": ["在3排×10格、共30格的棋盤上移動棋子，是世界上最古老的棋類之一", "名字意為「經過」，新王國時期被看作靈魂穿越冥界的旅程", "沒有留下玩法記錄，今天的規則是20世紀學者的復原"], "more": [{"h": "30格棋盤與特殊格", "p": ["塞尼特棋盤有3排，每排10格，共30格。一般認為棋子在第1排從左到右、第2排從右到左、第3排再從左到右，畫出S形前進。", "最後5格常畫有特別的記號。第26格是「美麗之屋」，第27格是「水」，多數復原認為掉進水裡的棋子要退回。第28到30格畫著數字或冥界諸神。"], "cap": ["塞尼特棋盤。棋子呈S形前進，最後5格（26—30）有特殊記號"]}, {"h": "擲棍前進", "p": ["代替骰子的是4根一面平、一面圓的棍子，或動物的距骨。許多學者認為按平面朝上的根數前進，0根時走5步。", "這種算法和遙遠韓國擲柶的棍子完全一樣。在博物館的「偶然的道具」展廳擲投擲棒，就能看出1到5出現的難易差別。"], "cap": ["埃及的投擲棒（可在「偶然的道具」展廳裡擲）"]}, {"h": "圖坦卡門的遊戲箱", "p": ["1922年霍華德·卡特打開的圖坦卡門墓中，至少放著5個遊戲箱。最大的一個用烏木和象牙製成，抽屜裡可以收放棋子和投擲棒。", "這個時期常做兩面都是棋盤的箱子：一面是塞尼特，另一面是與烏爾王家遊戲相同的20格棋盤。人們大概希望國王在另一個世界裡兩種遊戲都能玩。"], "cap": ["圖坦卡門的塞尼特箱（可在館藏展廳以3D觀看並對弈）"]}], "tl": [["約前3100年", "第1王朝墓中出土類似塞尼特的棋盤殘片"], ["約前2600年", "古王國墓室壁畫描繪下塞尼特的人"], ["約前1550年起", "新王國時期，塞尼特與冥界之旅相連"], ["約前1323年", "圖坦卡門墓中放入5個遊戲箱"], ["約前1250年", "奈菲爾塔利墓壁上畫著面對塞尼特的王后"], ["1922年", "卡特打開圖坦卡門墓"], ["1978年", "肯德爾發表玩法復原"]]}}, "ko": {"senet": {"kf": ["3줄×10칸, 30칸 판에서 말을 나아가게 하는, 세계에서 가장 오래된 보드게임 가운데 하나", "이름은 ‘지나감’. 신왕국 시대에는 영혼이 저승을 지나는 여행과 겹쳐졌다", "놀이 방법의 기록은 남지 않았고, 지금의 규칙은 20세기 학자들의 복원"], "more": [{"h": "30칸 판과 특별한 칸", "p": ["세네트 판은 10칸씩 3줄, 모두 30칸입니다. 말은 첫 줄을 왼쪽에서 오른쪽으로, 둘째 줄을 오른쪽에서 왼쪽으로, 셋째 줄을 다시 왼쪽에서 오른쪽으로 S자를 그리며 나아갔다고 봅니다.", "마지막 5칸에는 특별한 표시가 그려지는 일이 많았습니다. 26번째는 ‘아름다운 집’, 27번째는 ‘물’ 칸으로, 물에 빠진 말은 되돌아간다는 복원이 일반적입니다. 28~30번째에는 숫자나 저승의 신들이 그려졌습니다."], "cap": ["세네트 판. 말은 S자로 나아가고, 마지막 5칸(26~30)에는 특별한 표시가 있다"]}, {"h": "던지는 막대로 나아간다", "p": ["주사위 대신 쓴 것은 한쪽이 평평하고 한쪽이 둥근 막대 4개나 동물의 거골이었습니다. 평평한 면이 위로 온 개수만큼 나아가고, 0개면 5칸 간다고 보는 학자가 많습니다.", "이 세는 법은 멀리 떨어진 한국 윷놀이의 윷과 똑같습니다. 박물관 ‘우연의 도구’ 전시실에서 막대를 던져 1~5가 나오는 정도의 차이를 확인해 보세요."], "cap": ["이집트의 던지는 막대(우연의 도구 전시실에서 던질 수 있습니다)"]}, {"h": "투탕카멘의 게임 상자", "p": ["1922년 하워드 카터가 연 투탕카멘의 무덤에는 적어도 5개의 게임 상자가 들어 있었습니다. 가장 큰 상자는 흑단과 상아로 만들어졌고, 서랍에 말과 막대를 넣을 수 있습니다.", "앞뒤가 모두 판인 상자가 이 시대에 흔히 만들어졌습니다. 한쪽은 세네트, 다른 쪽은 우르 왕실 게임과 같은 20칸 판입니다. 왕이 저승에서도 두 게임을 다 할 수 있기를 바랐겠지요."], "cap": ["투탕카멘의 세네트 상자(소장품 전시실에서 3D로 보고 둘 수 있습니다)"]}], "tl": [["기원전 3100년경", "제1왕조 무덤에서 세네트로 보이는 판 조각"], ["기원전 2600년경", "고왕국 무덤 벽화에 세네트를 두는 사람들"], ["기원전 1550년경~", "신왕국 시대. 세네트가 저승 여행과 이어진다"], ["기원전 1323년경", "투탕카멘 무덤에 게임 상자 5개가 들어간다"], ["기원전 1250년경", "네페르타리 무덤 벽에 세네트 앞의 왕비가 그려진다"], ["1922년", "카터가 투탕카멘 무덤을 연다"], ["1978년", "켄들이 놀이 방법의 복원을 발표한다"]]}}, "es": {"senet": {"kf": ["Uno de los juegos de tablero más antiguos: las piezas corren por un tablero de 3 × 10 casillas", "Su nombre significa «paso»; en el Imperio Nuevo se volvió el viaje del alma por el más allá", "No se conservan las reglas; las formas de jugar actuales son reconstrucciones del siglo XX"], "more": [{"h": "Treinta casillas y las especiales", "p": ["El tablero de senet tiene tres filas de diez, treinta casillas. Se cree que las piezas iban de izquierda a derecha por la primera fila, de derecha a izquierda por la segunda y otra vez de izquierda a derecha por la tercera, trazando una S.", "Las cinco últimas casillas solían llevar signos especiales. La 26 es la «casa bella», la 27 el «agua», y en la mayoría de las reconstrucciones la pieza que cae al agua retrocede. De la 28 a la 30 había números o dioses del más allá."], "cap": ["Un tablero de senet. Las piezas avanzan en S; las cinco últimas casillas (26–30) llevan signos especiales"]}, {"h": "Avanzar con palos", "p": ["En vez de dados se lanzaban cuatro palos, planos por un lado y redondos por el otro, o tabas de animales. Muchos estudiosos creen que se avanzaba según los lados planos hacia arriba, y que ninguno valía cinco.", "Esa cuenta es exactamente la de los palos yut de la lejana Corea. Lánzalos en la sala Azar del museo y verás cuánto más salen unos números que otros."], "cap": ["Palos de lanzar egipcios (lánzalos en la sala Azar)"]}, {"h": "Las cajas de juego de Tutankamón", "p": ["La tumba de Tutankamón, abierta por Howard Carter en 1922, contenía al menos cinco cajas de juego. La mayor es de ébano y marfil, con un cajón para las piezas y los palos.", "En esta época eran comunes las cajas con tablero por ambas caras: senet en una y, en la otra, el mismo juego de veinte casillas que el Juego Real de Ur. Se quería que el rey pudiera jugar a ambos en el otro mundo."], "cap": ["La caja de senet de Tutankamón: mírala en 3D y juega en la sala Colección"]}], "tl": [["h. 3100 a. C.", "Fragmentos de un tablero parecido al senet en una tumba de la I dinastía"], ["h. 2600 a. C.", "Pinturas de tumbas del Imperio Antiguo muestran a gente jugando"], ["Desde h. 1550 a. C.", "Imperio Nuevo: el senet se une al viaje al más allá"], ["h. 1323 a. C.", "Cinco cajas de juego en la tumba de Tutankamón"], ["h. 1250 a. C.", "Nefertari aparece pintada ante un tablero de senet"], ["1922", "Carter abre la tumba de Tutankamón"], ["1978", "Kendall publica una reconstrucción de las reglas"]]}}, "fr": {"senet": {"kf": ["L’un des plus anciens jeux de plateau : des pions courent sur un plateau de 3 × 10 cases", "Son nom signifie « passer » ; au Nouvel Empire, il devint le voyage de l’âme dans l’au-delà", "Aucune règle n’a survécu ; les façons de jouer actuelles sont des reconstitutions du XXe siècle"], "more": [{"h": "Trente cases et les cases spéciales", "p": ["Le plateau de senet compte trois rangées de dix, soit trente cases. Les pions allaient sans doute de gauche à droite sur la première rangée, de droite à gauche sur la deuxième, puis de nouveau de gauche à droite, en dessinant un S.", "Les cinq dernières cases portaient souvent des signes particuliers. La 26 est la « belle maison », la 27 l’« eau », et dans la plupart des reconstitutions un pion tombé dans l’eau recule. Les cases 28 à 30 portaient des nombres ou des dieux de l’au-delà."], "cap": ["Un plateau de senet. Les pions avancent en S ; les cinq dernières cases (26–30) portent des signes"]}, {"h": "Avancer avec des bâtons", "p": ["Au lieu de dés, on lançait quatre bâtons plats d’un côté et ronds de l’autre, ou des osselets. Beaucoup de chercheurs pensent qu’on avançait du nombre de faces plates visibles, aucune valant cinq.", "C’est exactement le compte des bâtons de yut de la lointaine Corée. Lancez-les dans la salle Hasard du musée et voyez combien certains nombres sortent plus souvent."], "cap": ["Bâtons de lancer égyptiens (lancez-les dans la salle Hasard)"]}, {"h": "Les boîtes de jeu de Toutânkhamon", "p": ["La tombe de Toutânkhamon, ouverte par Howard Carter en 1922, renfermait au moins cinq boîtes de jeu. La plus grande, en ébène et ivoire, a un tiroir pour les pions et les bâtons.", "Les boîtes à double plateau étaient courantes à l’époque : le senet d’un côté et, de l’autre, le même jeu de vingt cases que le jeu royal d’Ur. Le roi devait pouvoir jouer à l’un comme à l’autre dans l’au-delà."], "cap": ["La boîte de senet de Toutânkhamon — à voir en 3D et à jouer dans la salle Collection"]}], "tl": [["v. 3100 av. J.-C.", "Fragments d’un plateau de type senet dans une tombe de la Ire dynastie"], ["v. 2600 av. J.-C.", "Des peintures de l’Ancien Empire montrent des joueurs"], ["Dès v. 1550 av. J.-C.", "Nouvel Empire : le senet se lie au voyage dans l’au-delà"], ["v. 1323 av. J.-C.", "Cinq boîtes de jeu dans la tombe de Toutânkhamon"], ["v. 1250 av. J.-C.", "Néfertari est peinte devant un plateau de senet"], ["1922", "Carter ouvre la tombe de Toutânkhamon"], ["1978", "Kendall publie une reconstitution des règles"]]}}, "pt": {"senet": {"kf": ["Um dos jogos de tabuleiro mais antigos: peças correm num tabuleiro de 3 × 10 casas", "O nome significa “passar”; no Império Novo virou a viagem da alma pelo além", "Nenhuma regra sobreviveu; as formas de jogar atuais são reconstruções do século XX"], "more": [{"h": "Trinta casas e as especiais", "p": ["O tabuleiro de senet tem três fileiras de dez, trinta casas. Acredita-se que as peças iam da esquerda para a direita na primeira fileira, da direita para a esquerda na segunda e de novo da esquerda para a direita na terceira, desenhando um S.", "As cinco últimas casas costumavam ter sinais especiais. A 26 é a “casa bela”, a 27 a “água”, e na maioria das reconstruções a peça que cai na água volta. Da 28 à 30 havia números ou deuses do além."], "cap": ["Um tabuleiro de senet. As peças avançam em S; as cinco últimas casas (26–30) têm sinais especiais"]}, {"h": "Andar com varetas", "p": ["Em vez de dados lançavam-se quatro varetas, planas de um lado e redondas do outro, ou astrágalos. Muitos estudiosos acham que se andava conforme as faces planas para cima, e que nenhuma valia cinco.", "Essa contagem é exatamente a das varetas do yut, da distante Coreia. Lance-as na sala Acaso do museu e veja como alguns números saem bem mais que outros."], "cap": ["Varetas de lançar egípcias (lance-as na sala Acaso)"]}, {"h": "As caixas de jogo de Tutancâmon", "p": ["O túmulo de Tutancâmon, aberto por Howard Carter em 1922, tinha pelo menos cinco caixas de jogo. A maior é de ébano e marfim, com uma gaveta para as peças e as varetas.", "Caixas com tabuleiro dos dois lados eram comuns na época: senet de um lado e, do outro, o mesmo jogo de vinte casas do Jogo Real de Ur. Queria-se que o rei pudesse jogar os dois no outro mundo."], "cap": ["A caixa de senet de Tutancâmon — veja em 3D e jogue na sala Acervo"]}], "tl": [["c. 3100 a.C.", "Fragmentos de um tabuleiro parecido com o senet num túmulo da I dinastia"], ["c. 2600 a.C.", "Pinturas de túmulos do Império Antigo mostram jogadores"], ["Desde c. 1550 a.C.", "Império Novo: o senet se liga à viagem ao além"], ["c. 1323 a.C.", "Cinco caixas de jogo no túmulo de Tutancâmon"], ["c. 1250 a.C.", "Nefertari é pintada diante de um tabuleiro de senet"], ["1922", "Carter abre o túmulo de Tutancâmon"], ["1978", "Kendall publica uma reconstrução das regras"]]}}, "de": {"senet": {"kf": ["Eines der ältesten Brettspiele: Steine laufen über ein Brett aus 3 × 10 Feldern", "Der Name bedeutet „Vorübergehen“; im Neuen Reich wurde es zur Reise der Seele durchs Jenseits", "Regeln sind nicht überliefert; heutige Spielweisen sind Rekonstruktionen des 20. Jahrhunderts"], "more": [{"h": "Dreißig Felder und die besonderen", "p": ["Das Senet-Brett hat drei Reihen zu zehn, dreißig Felder. Die Steine liefen vermutlich in der ersten Reihe von links nach rechts, in der zweiten von rechts nach links und in der dritten wieder von links nach rechts – ein S.", "Die letzten fünf Felder trugen oft besondere Zeichen. Feld 26 ist das „schöne Haus“, 27 das „Wasser“, und in den meisten Rekonstruktionen muss ein Stein, der ins Wasser fällt, zurück. Auf 28 bis 30 standen Zahlen oder Götter des Jenseits."], "cap": ["Ein Senet-Brett. Die Steine laufen in einem S; die letzten fünf Felder (26–30) tragen Zeichen"]}, {"h": "Ziehen mit Wurfstäben", "p": ["Statt Würfeln warf man vier Stäbe, flach auf einer und rund auf der anderen Seite, oder Tierknöchel. Viele Forscher meinen, man zog so viele Felder, wie flache Seiten oben lagen, und keine zählte fünf.", "Genau so zählt man auch die Yut-Stäbe im fernen Korea. Wirf sie im Museumsraum „Zufall“ und sieh, wie viel öfter manche Zahlen kommen als andere."], "cap": ["Ägyptische Wurfstäbe (wirf sie im Raum „Zufall“)"]}, {"h": "Tutanchamuns Spielkästen", "p": ["Das Grab Tutanchamuns, 1922 von Howard Carter geöffnet, enthielt mindestens fünf Spielkästen. Der größte ist aus Ebenholz und Elfenbein, mit einer Schublade für Steine und Stäbe.", "Kästen mit Brettern auf beiden Seiten waren damals üblich: Senet auf der einen, auf der anderen dasselbe Zwanzig-Felder-Spiel wie das Königliche Spiel von Ur. Der König sollte im Jenseits beide spielen können."], "cap": ["Tutanchamuns Senet-Kasten – im Raum „Sammlung“ in 3D anzusehen und zu bespielen"]}], "tl": [["um 3100 v. Chr.", "Bruchstücke eines Senet-artigen Bretts in einem Grab der 1. Dynastie"], ["um 2600 v. Chr.", "Grabmalereien des Alten Reichs zeigen Spieler"], ["ab um 1550 v. Chr.", "Neues Reich: Senet wird mit der Jenseitsreise verbunden"], ["um 1323 v. Chr.", "Fünf Spielkästen im Grab Tutanchamuns"], ["um 1250 v. Chr.", "Nefertari wird vor einem Senet-Brett gemalt"], ["1922", "Carter öffnet das Grab Tutanchamuns"], ["1978", "Kendall veröffentlicht eine Regelrekonstruktion"]]}}, "ru": {"senet": {"kf": ["Одна из древнейших настольных игр: фишки бегут по доске 3 × 10 клеток", "Название значит «прохождение»; в Новом царстве игра стала путешествием души через загробный мир", "Правила не сохранились; нынешние способы игры — реконструкции XX века"], "more": [{"h": "Тридцать клеток и особые", "p": ["На доске сенета три ряда по десять — тридцать клеток. Считается, что фишки шли по первому ряду слева направо, по второму справа налево и по третьему снова слева направо, описывая букву S.", "На последних пяти клетках часто рисовали особые знаки. Клетка 26 — «прекрасный дом», 27 — «вода»; в большинстве реконструкций упавшая в воду фишка отступает. На 28–30 были числа или боги загробного мира."], "cap": ["Доска сенета. Фишки идут змейкой; на последних пяти клетках (26–30) особые знаки"]}, {"h": "Ход по палочкам", "p": ["Вместо костей бросали четыре палочки — плоские с одной стороны и круглые с другой — или звериные бабки. Многие учёные считают, что ходили на число плоских сторон сверху, а ни одной — это пять.", "Точно так же считают и палочки ют в далёкой Корее. Бросьте их в зале «Случай» и посмотрите, насколько одни числа выпадают чаще других."], "cap": ["Египетские метательные палочки (бросайте их в зале «Случай»)"]}, {"h": "Игровые ларцы Тутанхамона", "p": ["В гробнице Тутанхамона, вскрытой Говардом Картером в 1922 году, было не меньше пяти игровых ларцов. Самый большой — из эбенового дерева и слоновой кости, с ящичком для фишек и палочек.", "В ту эпоху часто делали ларцы с досками с двух сторон: на одной — сенет, на другой — та же игра на двадцать клеток, что и царская игра Ура. Царь должен был играть в обе и на том свете."], "cap": ["Ларец для сенета Тутанхамона — его можно рассмотреть в 3D и сыграть в зале «Собрание»"]}], "tl": [["ок. 3100 до н. э.", "Обломки похожей на сенет доски в гробнице I династии"], ["ок. 2600 до н. э.", "Росписи гробниц Древнего царства показывают игроков"], ["с ок. 1550 до н. э.", "Новое царство: сенет связывают с путешествием в загробный мир"], ["ок. 1323 до н. э.", "Пять игровых ларцов кладут в гробницу Тутанхамона"], ["ок. 1250 до н. э.", "Нефертари изображена у доски для сенета"], ["1922", "Картер вскрывает гробницу Тутанхамона"], ["1978", "Кендалл публикует реконструкцию правил"]]}}, "tr": {"senet": {"kf": ["Dünyanın en eski tahta oyunlarından: taşlar 3 × 10 haneli bir tahtada yarışır", "Adı “geçmek” demektir; Yeni Krallık’ta ruhun öteki dünyadan geçiş yolculuğuyla özdeşleşti", "Kurallar günümüze kalmadı; bugünkü oynanışlar 20. yüzyıl yeniden kurulumlarıdır"], "more": [{"h": "Otuz hane ve özel haneler", "p": ["Senet tahtasında onar haneli üç sıra, yani otuz hane vardır. Taşların ilk sırada soldan sağa, ikincide sağdan sola, üçüncüde yine soldan sağa giderek bir S çizdiği düşünülür.", "Son beş haneye çoğu zaman özel işaretler çizilirdi. 26. hane “güzel ev”, 27. hane “su”dur; çoğu yeniden kurulumda suya düşen taş geri döner. 28–30. hanelerde sayılar ya da öteki dünyanın tanrıları vardı."], "cap": ["Bir senet tahtası. Taşlar S çizerek ilerler; son beş hanede (26–30) özel işaretler vardır"]}, {"h": "Atma çubuklarıyla ilerlemek", "p": ["Zar yerine bir yüzü düz, öbür yüzü yuvarlak dört çubuk ya da hayvan aşık kemikleri atılırdı. Pek çok araştırmacıya göre yukarı bakan düz yüz sayısı kadar ilerlenir, hiç yoksa beş sayılırdı.", "Bu sayım, uzaktaki Kore’nin yut çubuklarınınkiyle tıpatıp aynıdır. Müzenin Şans odasında çubukları at ve bazı sayıların ne kadar daha sık geldiğini gör."], "cap": ["Mısır atma çubukları (Şans odasında atabilirsin)"]}, {"h": "Tutankamon’un oyun kutuları", "p": ["Howard Carter’ın 1922’de açtığı Tutankamon mezarında en az beş oyun kutusu vardı. En büyüğü abanoz ve fildişidendir; taşlar ve çubuklar için bir çekmecesi vardır.", "O dönemde iki yüzü de oyun tahtası olan kutular yaygındı: bir yüzde senet, öbüründe Ur’un Kraliyet Oyunu’yla aynı yirmi haneli oyun. Kral öteki dünyada ikisini de oynayabilsin istenmişti."], "cap": ["Tutankamon’un senet kutusu — Koleksiyon odasında 3D olarak görüp oynayabilirsin"]}], "tl": [["MÖ y. 3100", "I. Hanedan mezarında senete benzer bir tahtanın parçaları"], ["MÖ y. 2600", "Eski Krallık mezar resimlerinde oyuncular"], ["MÖ y. 1550’den", "Yeni Krallık: senet öteki dünya yolculuğuyla bağlanır"], ["MÖ y. 1323", "Tutankamon’un mezarına beş oyun kutusu konur"], ["MÖ y. 1250", "Nefertari bir senet tahtasının başında resmedilir"], ["1922", "Carter Tutankamon’un mezarını açar"], ["1978", "Kendall kuralların yeniden kurulumunu yayımlar"]]}}, "id": {"senet": {"kf": ["Salah satu permainan papan tertua: bidak berpacu di papan 3 × 10 petak", "Namanya berarti “melintas”; di Kerajaan Baru ia menjadi perjalanan jiwa melewati alam baka", "Aturannya tak tersisa; cara main kini adalah rekonstruksi abad ke-20"], "more": [{"h": "Tiga puluh petak dan petak khusus", "p": ["Papan senet punya tiga baris berisi sepuluh, tiga puluh petak. Bidak diduga bergerak dari kiri ke kanan di baris pertama, kanan ke kiri di baris kedua, lalu kiri ke kanan lagi di baris ketiga, membentuk huruf S.", "Lima petak terakhir sering diberi tanda khusus. Petak 26 adalah “rumah indah”, 27 “air”, dan dalam kebanyakan rekonstruksi bidak yang jatuh ke air harus mundur. Petak 28–30 memuat angka atau dewa-dewa alam baka."], "cap": ["Papan senet. Bidak bergerak membentuk S; lima petak terakhir (26–30) bertanda khusus"]}, {"h": "Melangkah dengan tongkat lempar", "p": ["Sebagai ganti dadu, dilempar empat tongkat yang datar di satu sisi dan bulat di sisi lain, atau tulang tumit hewan. Banyak peneliti menduga langkahnya sesuai jumlah sisi datar yang menghadap ke atas, dan nol dihitung lima.", "Hitungan ini persis sama dengan tongkat yut dari Korea yang jauh. Lempar tongkatnya di ruang Peluang museum dan lihat betapa angka tertentu lebih sering muncul."], "cap": ["Tongkat lempar Mesir (lempar di ruang Peluang)"]}, {"h": "Kotak permainan Tutankhamun", "p": ["Makam Tutankhamun yang dibuka Howard Carter pada 1922 berisi sedikitnya lima kotak permainan. Yang terbesar dari kayu eboni dan gading, dengan laci untuk bidak dan tongkat.", "Kotak dengan papan di kedua sisi lazim saat itu: senet di satu sisi, dan di sisi lain permainan dua puluh petak yang sama dengan Permainan Kerajaan Ur. Sang raja diharapkan bisa memainkan keduanya di alam baka."], "cap": ["Kotak senet Tutankhamun — lihat dalam 3D dan mainkan di ruang Koleksi"]}], "tl": [["sekitar 3100 SM", "Pecahan papan mirip senet di makam Dinasti I"], ["sekitar 2600 SM", "Lukisan makam Kerajaan Lama menampilkan para pemain"], ["sejak sekitar 1550 SM", "Kerajaan Baru: senet dikaitkan dengan perjalanan ke alam baka"], ["sekitar 1323 SM", "Lima kotak permainan masuk makam Tutankhamun"], ["sekitar 1250 SM", "Nefertari dilukis di depan papan senet"], ["1922", "Carter membuka makam Tutankhamun"], ["1978", "Kendall menerbitkan rekonstruksi aturan"]]}}, "hi": {"senet": {"kf": ["दुनिया के सबसे पुराने बोर्ड‑खेलों में से एक: 3 × 10 ख़ानों के बोर्ड पर गोटियाँ दौड़ती हैं", "नाम का अर्थ है \"गुज़रना\"; नए साम्राज्य में यह परलोक से आत्मा की यात्रा बन गया", "नियम बचे नहीं; आज के खेलने के तरीक़े 20वीं सदी के पुनर्निर्माण हैं"], "more": [{"h": "तीस ख़ाने और ख़ास ख़ाने", "p": ["सेनेट के बोर्ड में दस‑दस ख़ानों की तीन पंक्तियाँ, यानी तीस ख़ाने होते हैं। माना जाता है कि गोटियाँ पहली पंक्ति में बाएँ से दाएँ, दूसरी में दाएँ से बाएँ और तीसरी में फिर बाएँ से दाएँ — S बनाते हुए चलती थीं।", "आख़िरी पाँच ख़ानों पर अक्सर ख़ास निशान होते थे। 26वाँ \"सुंदर घर\", 27वाँ \"पानी\" है; ज़्यादातर पुनर्निर्माणों में पानी में गिरी गोटी पीछे लौटती है। 28–30 पर अंक या परलोक के देवता बने होते थे।"], "cap": ["सेनेट का बोर्ड। गोटियाँ S‑आकार में चलती हैं; आख़िरी पाँच ख़ानों (26–30) पर ख़ास निशान"]}, {"h": "फेंकने वाली छड़ियों से चाल", "p": ["पासों की जगह चार छड़ियाँ फेंकी जाती थीं — एक ओर सपाट, दूसरी ओर गोल — या जानवरों की टखने की हड्डियाँ। कई विद्वान मानते हैं कि ऊपर आई सपाट तरफ़ों जितनी चाल होती थी, और कोई न हो तो पाँच।", "यही गिनती दूर कोरिया की युत छड़ियों की भी है। संग्रहालय के \"संयोग\" कक्ष में छड़ियाँ फेंककर देखें कि कुछ अंक कितने ज़्यादा आते हैं।"], "cap": ["मिस्र की फेंकने वाली छड़ियाँ (\"संयोग\" कक्ष में फेंकें)"]}, {"h": "तूतनख़ामुन के खेल‑बक्से", "p": ["1922 में हॉवर्ड कार्टर द्वारा खोले गए तूतनख़ामुन के मक़बरे में कम से कम पाँच खेल‑बक्से थे। सबसे बड़ा आबनूस और हाथीदाँत का है, जिसमें गोटियों और छड़ियों के लिए दराज़ है।", "उस दौर में दोनों ओर बोर्ड वाले बक्से आम थे: एक ओर सेनेट, दूसरी ओर उर के शाही खेल जैसा बीस ख़ानों का खेल। चाहा गया कि राजा परलोक में भी दोनों खेल सके।"], "cap": ["तूतनख़ामुन का सेनेट बक्सा — संग्रह कक्ष में 3D में देखें और खेलें"]}], "tl": [["लगभग 3100 ई.पू.", "पहले राजवंश के मक़बरे में सेनेट‑जैसे बोर्ड के टुकड़े"], ["लगभग 2600 ई.पू.", "पुराने साम्राज्य के मक़बरा‑चित्रों में खिलाड़ी"], ["लगभग 1550 ई.पू. से", "नया साम्राज्य: सेनेट परलोक‑यात्रा से जुड़ा"], ["लगभग 1323 ई.पू.", "तूतनख़ामुन के मक़बरे में पाँच खेल‑बक्से"], ["लगभग 1250 ई.पू.", "नेफ़र्तारी सेनेट के बोर्ड के सामने चित्रित"], ["1922", "कार्टर ने तूतनख़ामुन का मक़बरा खोला"], ["1978", "केंडल ने नियमों का पुनर्निर्माण छापा"]]}}, "ar": {"senet": {"kf": ["من أقدم ألعاب اللوحة في العالم: تتسابق القطع على لوحة من 3 × 10 خانات", "اسمها يعني «العبور»، وفي الدولة الحديثة صارت رحلة الروح عبر العالم الآخر", "لم تبقَ قواعدها؛ وطرق اللعب الحالية إعادة بناء من القرن العشرين"], "more": [{"h": "ثلاثون خانة وخانات خاصة", "p": ["لوحة السينيت ثلاثة صفوف من عشر خانات، أي ثلاثون خانة. ويُعتقد أن القطع كانت تسير في الصف الأول من اليسار إلى اليمين، وفي الثاني من اليمين إلى اليسار، ثم في الثالث من اليسار إلى اليمين، فترسم حرف S.", "وكثيرًا ما رُسمت على الخانات الخمس الأخيرة علامات خاصة؛ فالخانة 26 «البيت الجميل»، و27 «الماء»، وفي أغلب إعادات البناء تعود القطعة التي تسقط في الماء. وعلى الخانات 28–30 أرقام أو آلهة العالم الآخر."], "cap": ["لوحة سينيت. تسير القطع على هيئة S، وعلى الخانات الخمس الأخيرة (26–30) علامات خاصة"]}, {"h": "التقدّم بعصيّ الرمي", "p": ["بدل النرد كانت تُرمى أربع عصيّ مسطحة من جهة ومستديرة من الأخرى، أو عظام كعاب الحيوانات. ويرى كثير من الباحثين أن القطعة تتقدّم بعدد الوجوه المسطحة المتجهة إلى أعلى، وأن انعدامها يُحسب خمسة.", "وهذا العدّ هو نفسه تمامًا في عصيّ اليوت في كوريا البعيدة. ارمِ العصيّ في قاعة الحظ بالمتحف وانظر كم تظهر بعض الأرقام أكثر من غيرها."], "cap": ["عصيّ الرمي المصرية (ارمها في قاعة الحظ)"]}, {"h": "صناديق ألعاب توت عنخ آمون", "p": ["ضمّ قبر توت عنخ آمون، الذي فتحه هوارد كارتر سنة 1922، خمسة صناديق ألعاب على الأقل. أكبرها من الأبنوس والعاج، وله درج للقطع والعصيّ.", "وكانت الصناديق ذات اللوحتين على الوجهين شائعة آنذاك: سينيت على وجه، وعلى الآخر لعبة العشرين خانة نفسها التي في لعبة أور الملكية. أُريد للملك أن يلعب الاثنتين في العالم الآخر."], "cap": ["صندوق سينيت توت عنخ آمون — شاهده ثلاثي الأبعاد والعب عليه في قاعة المقتنيات"]}], "tl": [["نحو 3100 ق.م", "شظايا لوحة شبيهة بالسينيت في قبر من الأسرة الأولى"], ["نحو 2600 ق.م", "رسوم قبور الدولة القديمة تُظهر اللاعبين"], ["منذ نحو 1550 ق.م", "الدولة الحديثة: ترتبط السينيت برحلة العالم الآخر"], ["نحو 1323 ق.م", "خمسة صناديق ألعاب في قبر توت عنخ آمون"], ["نحو 1250 ق.م", "تُرسم نفرتاري أمام لوحة سينيت"], ["1922", "كارتر يفتح قبر توت عنخ آمون"], ["1978", "كيندال ينشر إعادة بناء للقواعد"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
