(T => { const D = {"ja": {"lewis": {"kf": ["1831年にスコットランドのルイス島で見つかった、93点の駒と円盤", "12世紀後半ごろノルウェーで、主にセイウチの牙から彫られた", "いまは大英博物館とスコットランド国立博物館に分かれて展示されている"], "more": [{"h": "78の駒の顔ぶれ", "p": ["チェスの駒78は、王8、女王8、司教16、騎士15、城兵12、ポーン19。少なくとも4組分のセットがまじっていたと考えられています。", "司教の駒は、司教冠をかぶった姿で彫られています。チェスの「象」が「司教」に変わったのはヨーロッパでのことで、ルイス島の駒はその最も早い例のひとつです。城兵の何人かは盾をかんでいて、戦いの前に我を忘れて暴れる戦士「ベルセルク」を表しているといわれます。"], "cap": ["ルイス島のチェス駒（所蔵品の部屋で3Dで見られます）", "78のチェス駒の内訳"]}, {"h": "セイウチの牙と北の海", "p": ["駒の多くはセイウチの牙、いくつかはクジラの歯で作られています。セイウチの牙は、グリーンランドやノルウェー北部から運ばれてくる北の海の宝でした。", "そのころのルイス島は、ノルウェー王の支配する島々の一部でした。1266年のパース条約で、スコットランドに渡されます。トロンハイムの大聖堂の近くからは、同じような彫りの駒のかけらも見つかっていて、駒の故郷を示す手がかりになっています。"], "cap": []}, {"h": "発見の伝説と、いまの人気", "p": ["誰が見つけたのかについては、砂浜で牛が掘り出した、地元の農夫マルコム・マクラウドが見つけた――など、いくつもの話が伝わっています。持ち主はすぐに駒を売り、エディンバラを経て大英博物館が買い入れました。", "とぼけた表情の駒は今も大人気で、レプリカは世界中で売られています。映画『ハリー・ポッターと賢者の石』（2001年）の魔法使いのチェスにも、ルイス島の駒をもとにした駒が登場しました。"], "cap": []}], "tl": [["12世紀後半", "ノルウェー（トロンハイム周辺）で駒が作られる"], ["1266年", "パース条約で、ルイス島を含む島々がスコットランド領に"], ["1831年", "ルイス島で93点がまとめて見つかる"], ["1831〜32年", "大英博物館が82点を買い入れる"], ["1888年", "スコットランドの博物館が11点を手に入れる"], ["2001年", "映画『ハリー・ポッター』の魔法使いのチェスに登場"], ["2019年", "5ポンドで買われていた城兵が73万5000ポンドで落札"]]}}, "en": {"lewis": {"kf": ["93 pieces and discs found on the Isle of Lewis, Scotland, in 1831", "Carved mostly from walrus ivory in Norway in the later 12th century", "Now split between the British Museum and National Museums Scotland"], "more": [{"h": "The line-up of 78 chessmen", "p": ["The 78 chessmen are 8 kings, 8 queens, 16 bishops, 15 knights, 12 warders and 19 pawns — parts of at least four sets.", "The bishops wear mitres. The change of the chess “elephant” into a bishop happened in Europe, and the Lewis pieces are among its earliest examples. Some warders bite their shields, and are thought to show berserkers — warriors who fought in a frenzy."], "cap": ["The Lewis chessmen (see them in 3D in the Collection room)", "The 78 chessmen by kind"]}, {"h": "Walrus ivory and the northern seas", "p": ["Most pieces are of walrus ivory, a few of whale’s tooth. Walrus ivory was a treasure of the northern seas, shipped from Greenland and northern Norway.", "Lewis then belonged to the islands ruled by the king of Norway; it passed to Scotland by the Treaty of Perth in 1266. Fragments carved in the same way have been found near Trondheim Cathedral — a clue to where the pieces were made."], "cap": []}, {"h": "The legend of the find, and fame today", "p": ["There are many stories of who found them: a cow that scraped them out of the sand, or a local man, Malcolm MacLeod. The finder soon sold them, and by way of Edinburgh the British Museum bought most of the hoard.", "With their glum and comic faces the pieces are hugely popular, and replicas sell all over the world. The wizard’s chess in the film Harry Potter and the Philosopher’s Stone (2001) used pieces based on the Lewis chessmen."], "cap": []}], "tl": [["Late 12th century", "The pieces are made in Norway (around Trondheim)"], ["1266", "The Treaty of Perth hands the isles, Lewis among them, to Scotland"], ["1831", "The 93 pieces are found together on Lewis"], ["1831–32", "The British Museum buys 82"], ["1888", "The Scottish national museum acquires 11"], ["2001", "The pieces appear in the wizard’s chess of the Harry Potter film"], ["2019", "A warder bought for £5 sells for £735,000"]]}}, "zh": {"lewis": {"kf": ["1831年在苏格兰刘易斯岛发现的93件棋子与圆盘", "12世纪后半叶在挪威制作，主要用海象牙雕成", "如今分别收藏在大英博物馆和苏格兰国家博物馆"], "more": [{"h": "78枚棋子的阵容", "p": ["78枚棋子包括王8、后8、主教16、骑士15、城堡卫士12、兵19，一般认为至少混有4副棋。", "主教戴着主教冠。棋中的“象”变成“主教”是在欧洲发生的，刘易斯岛棋子是最早的例子之一。有几个卫士咬着盾牌，据说表现的是战前陷入狂暴的战士“狂战士”。"], "cap": ["刘易斯岛棋子（可在馆藏展厅以3D观看）", "78枚国际象棋棋子的构成"]}, {"h": "海象牙与北方的海", "p": ["大多数棋子用海象牙、少数用鲸齿制成。海象牙是从格陵兰和挪威北部运来的北方海洋之宝。", "当时刘易斯岛属于挪威国王统治的群岛，1266年依《珀斯条约》归苏格兰。特隆赫姆大教堂附近也发现过雕法相同的棋子残片，是棋子故乡的线索。"], "cap": []}, {"h": "发现的传说与今日的人气", "p": ["关于谁发现了棋子，流传着许多说法：有说是牛从沙里刨出来的，也有说是当地人马尔科姆·麦克劳德发现的。发现者很快卖掉棋子，经爱丁堡辗转，大英博物馆买下了大部分。", "表情滑稽的棋子至今很受欢迎，复制品销往世界各地。电影《哈利·波特与魔法石》（2001年）里的巫师棋，也用了以刘易斯岛棋子为原型的棋子。"], "cap": []}], "tl": [["12世纪后半叶", "棋子在挪威（特隆赫姆一带）制成"], ["1266年", "依《珀斯条约》，包括刘易斯岛的群岛归苏格兰"], ["1831年", "在刘易斯岛一起发现93件"], ["1831—32年", "大英博物馆购入82件"], ["1888年", "苏格兰的博物馆取得11件"], ["2001年", "出现在电影《哈利·波特》的巫师棋中"], ["2019年", "当年5英镑买下的卫士以73.5万英镑拍出"]]}}, "zh-TW": {"lewis": {"kf": ["1831年在蘇格蘭劉易斯島發現的93件棋子與圓盤", "12世紀後半葉在挪威製作，主要用海象牙雕成", "如今分別收藏在大英博物館和蘇格蘭國家博物館"], "more": [{"h": "78枚棋子的陣容", "p": ["78枚棋子包括王8、后8、主教16、騎士15、城堡衛士12、兵19，一般認為至少混有4副棋。", "主教戴著主教冠。棋中的「象」變成「主教」是在歐洲發生的，劉易斯島棋子是最早的例子之一。有幾個衛士咬著盾牌，據說表現的是戰前陷入狂暴的戰士「狂戰士」。"], "cap": ["劉易斯島棋子（可在館藏展廳以3D觀看）", "78枚西洋棋棋子的構成"]}, {"h": "海象牙與北方的海", "p": ["大多數棋子用海象牙、少數用鯨齒製成。海象牙是從格陵蘭和挪威北部運來的北方海洋之寶。", "當時劉易斯島屬於挪威國王統治的群島，1266年依《伯斯條約》歸蘇格蘭。特隆赫姆大教堂附近也發現過雕法相同的棋子殘片，是棋子故鄉的線索。"], "cap": []}, {"h": "發現的傳說與今日的人氣", "p": ["關於誰發現了棋子，流傳著許多說法：有說是牛從沙裡刨出來的，也有說是當地人馬爾科姆·麥克勞德發現的。發現者很快賣掉棋子，經愛丁堡輾轉，大英博物館買下了大部分。", "表情滑稽的棋子至今很受歡迎，複製品銷往世界各地。電影《哈利波特：神秘的魔法石》（2001年）裡的巫師棋，也用了以劉易斯島棋子為原型的棋子。"], "cap": []}], "tl": [["12世紀後半葉", "棋子在挪威（特隆赫姆一帶）製成"], ["1266年", "依《伯斯條約》，包括劉易斯島的群島歸蘇格蘭"], ["1831年", "在劉易斯島一起發現93件"], ["1831—32年", "大英博物館購入82件"], ["1888年", "蘇格蘭的博物館取得11件"], ["2001年", "出現在電影《哈利波特》的巫師棋中"], ["2019年", "當年5英鎊買下的衛士以73.5萬英鎊拍出"]]}}, "ko": {"lewis": {"kf": ["1831년 스코틀랜드 루이스섬에서 발견된 말과 원반 93점", "12세기 후반 노르웨이에서, 주로 바다코끼리 엄니로 깎았다", "지금은 대영박물관과 스코틀랜드 국립박물관에 나뉘어 있다"], "more": [{"h": "78개 말의 면면", "p": ["체스 말 78개는 왕 8, 여왕 8, 주교 16, 기사 15, 성 지기 12, 폰 19. 적어도 4벌이 섞여 있었다고 봅니다.", "주교는 주교관을 쓴 모습입니다. 체스의 ‘코끼리’가 ‘주교’로 바뀐 것은 유럽에서였고, 루이스섬의 말은 그 가장 이른 예 가운데 하나입니다. 성 지기 몇은 방패를 물고 있는데, 싸움 전에 광란에 빠지는 전사 ‘베르세르크’를 나타낸다고 합니다."], "cap": ["루이스섬 체스 말(소장품 전시실에서 3D로 볼 수 있습니다)", "체스 말 78개의 구성"]}, {"h": "바다코끼리 엄니와 북쪽 바다", "p": ["말 대부분은 바다코끼리 엄니, 몇 개는 고래 이빨로 만들었습니다. 바다코끼리 엄니는 그린란드와 노르웨이 북부에서 실어 오던 북쪽 바다의 보물이었습니다.", "그 무렵 루이스섬은 노르웨이 왕이 다스리는 섬들의 일부였고, 1266년 퍼스 조약으로 스코틀랜드에 넘어갑니다. 트론헤임 대성당 근처에서도 같은 솜씨의 말 조각이 나와, 말의 고향을 짐작하게 합니다."], "cap": []}, {"h": "발견의 전설과 지금의 인기", "p": ["누가 찾았는지에 대해서는, 모래밭에서 소가 파냈다, 마을 사람 맬컴 매클라우드가 찾았다 등 여러 이야기가 전해집니다. 발견자는 곧 말을 팔았고, 에든버러를 거쳐 대영박물관이 대부분을 사들였습니다.", "시무룩하고 익살스러운 얼굴의 말은 지금도 큰 인기여서, 복제품이 세계 곳곳에서 팔립니다. 영화 『해리 포터와 마법사의 돌』(2001)의 마법사 체스에도 루이스섬 말을 본뜬 말이 나왔습니다."], "cap": []}], "tl": [["12세기 후반", "노르웨이(트론헤임 일대)에서 말이 만들어진다"], ["1266년", "퍼스 조약으로 루이스섬 등이 스코틀랜드령이 된다"], ["1831년", "루이스섬에서 93점이 한꺼번에 발견된다"], ["1831~32년", "대영박물관이 82점을 사들인다"], ["1888년", "스코틀랜드의 박물관이 11점을 얻는다"], ["2001년", "영화 『해리 포터』의 마법사 체스에 나온다"], ["2019년", "5파운드에 산 성 지기가 73만 5000파운드에 낙찰된다"]]}}, "es": {"lewis": {"kf": ["93 piezas y discos hallados en la isla de Lewis (Escocia) en 1831", "Tallados sobre todo en marfil de morsa en Noruega, a finales del siglo XII", "Hoy repartidos entre el Museo Británico y los Museos Nacionales de Escocia"], "more": [{"h": "Las 78 piezas de ajedrez", "p": ["Las 78 piezas son 8 reyes, 8 damas, 16 obispos, 15 caballeros, 12 guardianes y 19 peones: restos de al menos cuatro juegos.", "Los obispos llevan mitra. El paso del «elefante» al obispo ocurrió en Europa, y las piezas de Lewis están entre sus primeros ejemplos. Algunos guardianes muerden el escudo; se cree que son berserkers, guerreros que luchaban en trance."], "cap": ["Las piezas de Lewis (míralas en 3D en la sala Colección)", "Las 78 piezas por tipo"]}, {"h": "Marfil de morsa y mares del norte", "p": ["La mayoría son de marfil de morsa y unas pocas de diente de ballena. El marfil de morsa era un tesoro de los mares del norte, traído de Groenlandia y el norte de Noruega.", "Lewis pertenecía entonces a las islas del rey de Noruega; pasó a Escocia por el Tratado de Perth en 1266. Cerca de la catedral de Trondheim se han hallado fragmentos tallados del mismo modo, una pista de dónde se hicieron."], "cap": []}, {"h": "La leyenda del hallazgo y la fama actual", "p": ["Circulan muchas versiones del hallazgo: una vaca que las sacó de la arena, o un vecino, Malcolm MacLeod. El descubridor las vendió pronto y, vía Edimburgo, el Museo Británico compró la mayor parte.", "Con sus caras cómicas y enfurruñadas son hoy muy populares y sus réplicas se venden en todo el mundo. El ajedrez mágico de la película Harry Potter y la piedra filosofal (2001) usó piezas basadas en las de Lewis."], "cap": []}], "tl": [["Finales del siglo XII", "Se hacen las piezas en Noruega (cerca de Trondheim)"], ["1266", "El Tratado de Perth entrega las islas, entre ellas Lewis, a Escocia"], ["1831", "Se hallan juntas las 93 piezas en Lewis"], ["1831–32", "El Museo Británico compra 82"], ["1888", "El museo nacional escocés adquiere 11"], ["2001", "Aparecen en el ajedrez mágico de Harry Potter"], ["2019", "Un guardián comprado por 5 £ se vende por 735.000 £"]]}}, "fr": {"lewis": {"kf": ["93 pièces et disques trouvés sur l’île de Lewis (Écosse) en 1831", "Sculptés surtout dans l’ivoire de morse, en Norvège, à la fin du XIIe siècle", "Aujourd’hui partagés entre le British Museum et les National Museums Scotland"], "more": [{"h": "Les 78 pièces d’échecs", "p": ["Les 78 pièces comptent 8 rois, 8 dames, 16 évêques, 15 cavaliers, 12 gardiens et 19 pions — les restes d’au moins quatre jeux.", "Les évêques portent la mitre. Le passage de l’« éléphant » à l’évêque (notre fou) s’est fait en Europe, et les pièces de Lewis en sont parmi les premiers exemples. Certains gardiens mordent leur bouclier : on y voit des berserkers, guerriers combattant en transe."], "cap": ["Les échecs de Lewis (à voir en 3D dans la salle Collection)", "Les 78 pièces par type"]}, {"h": "Ivoire de morse et mers du Nord", "p": ["La plupart sont en ivoire de morse, quelques-unes en dent de baleine. L’ivoire de morse était un trésor des mers du Nord, venu du Groenland et du nord de la Norvège.", "Lewis appartenait alors aux îles du roi de Norvège ; elle passa à l’Écosse par le traité de Perth en 1266. Près de la cathédrale de Trondheim, on a trouvé des fragments sculptés de la même manière — un indice sur leur lieu de fabrication."], "cap": []}, {"h": "La légende de la découverte et la célébrité d’aujourd’hui", "p": ["On raconte bien des versions : une vache qui les aurait déterrées du sable, ou un habitant, Malcolm MacLeod. Le découvreur les vendit vite et, via Édimbourg, le British Museum en acheta la plupart.", "Avec leurs mines bougonnes et comiques, elles sont très populaires et leurs répliques se vendent partout. Les échecs version sorcier du film Harry Potter à l’école des sorciers (2001) s’inspiraient des pièces de Lewis."], "cap": []}], "tl": [["Fin du XIIe siècle", "Les pièces sont faites en Norvège (vers Trondheim)"], ["1266", "Le traité de Perth cède les îles, dont Lewis, à l’Écosse"], ["1831", "Les 93 pièces sont trouvées ensemble à Lewis"], ["1831–32", "Le British Museum en achète 82"], ["1888", "Le musée national écossais en acquiert 11"], ["2001", "Elles apparaissent dans les échecs version sorcier de Harry Potter"], ["2019", "Un gardien acheté 5 £ est vendu 735 000 £"]]}}, "pt": {"lewis": {"kf": ["93 peças e discos achados na ilha de Lewis (Escócia) em 1831", "Esculpidos sobretudo em marfim de morsa, na Noruega, no fim do século XII", "Hoje divididos entre o Museu Britânico e os Museus Nacionais da Escócia"], "more": [{"h": "As 78 peças de xadrez", "p": ["As 78 peças são 8 reis, 8 damas, 16 bispos, 15 cavaleiros, 12 guardiões e 19 peões — restos de pelo menos quatro jogos.", "Os bispos usam mitra. A troca do “elefante” pelo bispo aconteceu na Europa, e as peças de Lewis estão entre os primeiros exemplos. Alguns guardiões mordem o escudo; acredita-se que sejam berserkers, guerreiros que lutavam em fúria."], "cap": ["As peças de Lewis (veja-as em 3D na sala Acervo)", "As 78 peças por tipo"]}, {"h": "Marfim de morsa e mares do norte", "p": ["A maioria é de marfim de morsa, algumas de dente de baleia. O marfim de morsa era um tesouro dos mares do norte, trazido da Groenlândia e do norte da Noruega.", "Lewis pertencia então às ilhas do rei da Noruega; passou à Escócia pelo Tratado de Perth em 1266. Perto da catedral de Trondheim acharam-se fragmentos esculpidos da mesma maneira — uma pista de onde foram feitas."], "cap": []}, {"h": "A lenda da descoberta e a fama de hoje", "p": ["Há muitas versões: uma vaca que as desenterrou da areia, ou um morador, Malcolm MacLeod. O descobridor logo as vendeu e, via Edimburgo, o Museu Britânico comprou a maior parte.", "Com seus rostos emburrados e cômicos, são muito populares e réplicas vendem-se no mundo todo. O xadrez de bruxo do filme Harry Potter e a Pedra Filosofal (2001) usou peças baseadas nas de Lewis."], "cap": []}], "tl": [["Fim do século XII", "As peças são feitas na Noruega (perto de Trondheim)"], ["1266", "O Tratado de Perth entrega as ilhas, Lewis entre elas, à Escócia"], ["1831", "As 93 peças são achadas juntas em Lewis"], ["1831–32", "O Museu Britânico compra 82"], ["1888", "O museu nacional escocês adquire 11"], ["2001", "Aparecem no xadrez de bruxo de Harry Potter"], ["2019", "Um guardião comprado por £5 é vendido por £735.000"]]}}, "de": {"lewis": {"kf": ["93 Figuren und Spielsteine, 1831 auf der Isle of Lewis (Schottland) gefunden", "Im späten 12. Jahrhundert in Norwegen meist aus Walrosszahn geschnitzt", "Heute zwischen dem British Museum und den National Museums Scotland aufgeteilt"], "more": [{"h": "Die 78 Schachfiguren", "p": ["Die 78 Figuren sind 8 Könige, 8 Damen, 16 Bischöfe, 15 Ritter, 12 Wächter und 19 Bauern – Teile von mindestens vier Spielen.", "Die Bischöfe tragen Mitra. Dass aus dem „Elefanten“ ein Bischof (unser Läufer) wurde, geschah in Europa, und die Lewis-Figuren gehören zu den frühesten Beispielen. Manche Wächter beißen in ihren Schild – man sieht in ihnen Berserker, Krieger im Kampfrausch."], "cap": ["Die Lewis-Schachfiguren (im Raum „Sammlung“ in 3D)", "Die 78 Schachfiguren nach Art"]}, {"h": "Walrosszahn und die nördlichen Meere", "p": ["Die meisten sind aus Walrosszahn, einige aus Walzahn. Walrosselfenbein war ein Schatz der Nordmeere, aus Grönland und Nordnorwegen herangeschafft.", "Lewis gehörte damals zu den Inseln des norwegischen Königs; durch den Vertrag von Perth 1266 kam es an Schottland. Nahe dem Dom von Trondheim fand man gleich geschnitzte Bruchstücke – ein Hinweis auf den Herstellungsort."], "cap": []}, {"h": "Die Legende des Funds und der Ruhm heute", "p": ["Es gibt viele Geschichten: eine Kuh, die sie aus dem Sand scharrte, oder ein Einheimischer, Malcolm MacLeod. Der Finder verkaufte sie bald, und über Edinburgh kaufte das British Museum die meisten.", "Mit ihren mürrisch-komischen Gesichtern sind sie heute sehr beliebt, Nachbildungen werden weltweit verkauft. Das Zauberschach im Film Harry Potter und der Stein der Weisen (2001) nutzte Figuren nach dem Vorbild der Lewis-Figuren."], "cap": []}], "tl": [["spätes 12. Jh.", "Die Figuren entstehen in Norwegen (um Trondheim)"], ["1266", "Der Vertrag von Perth gibt die Inseln samt Lewis an Schottland"], ["1831", "Die 93 Stücke werden zusammen auf Lewis gefunden"], ["1831–32", "Das British Museum kauft 82"], ["1888", "Das schottische Nationalmuseum erwirbt 11"], ["2001", "Sie erscheinen im Zauberschach von Harry Potter"], ["2019", "Ein für 5 £ gekaufter Wächter bringt 735.000 £"]]}}, "ru": {"lewis": {"kf": ["93 фигуры и диска, найденные на острове Льюис (Шотландия) в 1831 году", "Вырезаны в основном из моржового клыка в Норвегии в конце XII века", "Сейчас разделены между Британским музеем и Национальными музеями Шотландии"], "more": [{"h": "78 шахматных фигур", "p": ["78 фигур — это 8 королей, 8 королев, 16 епископов, 15 рыцарей, 12 стражей и 19 пешек: части как минимум четырёх комплектов.", "Епископы — в митрах. Превращение шахматного «слона» в епископа произошло в Европе, и фигуры с Льюиса — одни из самых ранних примеров. Некоторые стражи кусают щиты: в них видят берсерков — воинов, впадавших в боевое неистовство."], "cap": ["Шахматы с острова Льюис (смотрите в 3D в зале «Собрание»)", "78 шахматных фигур по видам"]}, {"h": "Моржовый клык и северные моря", "p": ["Большинство фигур — из моржового клыка, несколько — из китового зуба. Моржовый клык был сокровищем северных морей, его везли из Гренландии и северной Норвегии.", "Льюис тогда принадлежал островам норвежского короля; по Пертскому договору 1266 года он отошёл Шотландии. У собора в Тронхейме нашли обломки той же резьбы — подсказка, где делали фигуры."], "cap": []}, {"h": "Легенда о находке и слава сегодня", "p": ["Рассказов о находке много: корова, выкопавшая фигуры из песка, или местный житель Малкольм Маклауд. Нашедший быстро их продал, и через Эдинбург большую часть купил Британский музей.", "Хмурые и смешные лица сделали их очень популярными, копии продаются по всему миру. Волшебные шахматы в фильме «Гарри Поттер и философский камень» (2001) были сделаны по образцу фигур с Льюиса."], "cap": []}], "tl": [["конец XII в.", "Фигуры делают в Норвегии (около Тронхейма)"], ["1266", "По Пертскому договору острова, в том числе Льюис, переходят Шотландии"], ["1831", "93 предмета находят вместе на Льюисе"], ["1831–32", "Британский музей покупает 82"], ["1888", "Шотландский национальный музей получает 11"], ["2001", "Фигуры появляются в волшебных шахматах «Гарри Поттера»"], ["2019", "Страж, купленный за 5 фунтов, продан за 735 000"]]}}, "tr": {"lewis": {"kf": ["1831’de İskoçya’daki Lewis Adası’nda bulunan 93 taş ve disk", "12. yüzyılın sonlarında Norveç’te, çoğu mors dişinden oyuldu", "Bugün British Museum ile İskoçya Ulusal Müzeleri arasında paylaşılıyor"], "more": [{"h": "78 satranç taşı", "p": ["78 taş: 8 şah, 8 vezir/kraliçe, 16 piskopos, 15 şövalye, 12 muhafız ve 19 piyon — en az dört takımın parçaları.", "Piskoposlar mitra takar. Satrançtaki “fil”in piskoposa dönüşmesi Avrupa’da oldu ve Lewis taşları bunun en erken örneklerindendir. Bazı muhafızlar kalkanlarını ısırır; bunların savaş öncesi kendinden geçen “berserk” savaşçılar olduğu düşünülür."], "cap": ["Lewis satranç taşları (Koleksiyon odasında 3D olarak görebilirsin)", "78 satranç taşının türleri"]}, {"h": "Mors dişi ve kuzey denizleri", "p": ["Taşların çoğu mors dişinden, birkaçı balina dişindendir. Mors dişi, Grönland’dan ve kuzey Norveç’ten getirilen kuzey denizlerinin hazinesiydi.", "Lewis o zaman Norveç kralının adalarındandı; 1266’daki Perth Antlaşması’yla İskoçya’ya geçti. Trondheim Katedrali yakınında aynı oymacılıkta parçalar bulunmuştur — taşların nerede yapıldığına dair bir ipucu."], "cap": []}, {"h": "Buluşun efsanesi ve bugünkü ünü", "p": ["Bulunuşu hakkında pek çok anlatı var: kumdan çıkaran bir inek ya da yerli Malcolm MacLeod. Bulan kişi onları hemen sattı ve Edinburgh üzerinden çoğunu British Museum satın aldı.", "Somurtkan ve komik yüzleriyle bugün çok sevilirler, kopyaları dünyanın her yerinde satılır. Harry Potter ve Felsefe Taşı (2001) filmindeki büyücü satrancında Lewis taşlarından esinlenen taşlar kullanıldı."], "cap": []}], "tl": [["12. yy sonu", "Taşlar Norveç’te (Trondheim çevresi) yapılır"], ["1266", "Perth Antlaşması, Lewis’in de olduğu adaları İskoçya’ya verir"], ["1831", "93 parça Lewis’te birlikte bulunur"], ["1831–32", "British Museum 82 tanesini alır"], ["1888", "İskoç ulusal müzesi 11 tanesini edinir"], ["2001", "Harry Potter’ın büyücü satrancında görünürler"], ["2019", "5 sterline alınmış bir muhafız 735.000 sterline satılır"]]}}, "id": {"lewis": {"kf": ["93 bidak dan cakram yang ditemukan di Pulau Lewis, Skotlandia, pada 1831", "Diukir sebagian besar dari gading walrus di Norwegia akhir abad ke-12", "Kini terbagi antara British Museum dan National Museums Scotland"], "more": [{"h": "78 bidak catur", "p": ["78 bidak itu terdiri dari 8 raja, 8 ratu, 16 uskup, 15 kesatria, 12 penjaga, dan 19 pion — bagian dari sedikitnya empat set.", "Para uskup memakai mitra. Perubahan “gajah” catur menjadi uskup terjadi di Eropa, dan bidak Lewis termasuk contoh paling awal. Beberapa penjaga menggigit perisainya; mereka diduga menggambarkan berserker, prajurit yang bertarung dalam amukan."], "cap": ["Bidak catur Lewis (lihat dalam 3D di ruang Koleksi)", "78 bidak catur menurut jenisnya"]}, {"h": "Gading walrus dan laut utara", "p": ["Sebagian besar dari gading walrus, beberapa dari gigi paus. Gading walrus adalah harta laut utara yang didatangkan dari Greenland dan Norwegia utara.", "Saat itu Lewis termasuk pulau-pulau milik raja Norwegia; lewat Perjanjian Perth tahun 1266 pulau itu berpindah ke Skotlandia. Di dekat Katedral Trondheim ditemukan pecahan berukiran serupa — petunjuk tempat pembuatannya."], "cap": []}, {"h": "Legenda penemuan dan ketenaran kini", "p": ["Ada banyak cerita: seekor sapi yang menggalinya dari pasir, atau warga setempat bernama Malcolm MacLeod. Penemunya segera menjualnya, dan lewat Edinburgh sebagian besar dibeli British Museum.", "Dengan wajah cemberut nan lucu, bidak ini sangat populer dan replikanya dijual di seluruh dunia. Catur sihir dalam film Harry Potter dan Batu Bertuah (2001) memakai bidak yang meniru bidak Lewis."], "cap": []}], "tl": [["akhir abad ke-12", "Bidak dibuat di Norwegia (sekitar Trondheim)"], ["1266", "Perjanjian Perth menyerahkan pulau-pulau, termasuk Lewis, kepada Skotlandia"], ["1831", "93 benda ditemukan bersama di Lewis"], ["1831–32", "British Museum membeli 82"], ["1888", "Museum nasional Skotlandia memperoleh 11"], ["2001", "Muncul dalam catur sihir Harry Potter"], ["2019", "Penjaga yang dibeli seharga £5 terjual £735.000"]]}}, "hi": {"lewis": {"kf": ["1831 में स्कॉटलैंड के लुईस द्वीप पर मिले 93 मोहरे और चकतियाँ", "12वीं सदी के आख़िर में नॉर्वे में, ज़्यादातर वालरस के दाँत से तराशे गए", "आज ब्रिटिश संग्रहालय और स्कॉटलैंड के राष्ट्रीय संग्रहालयों में बँटे हैं"], "more": [{"h": "78 शतरंज‑मोहरे", "p": ["78 मोहरों में 8 राजा, 8 रानियाँ, 16 बिशप, 15 घुड़सवार, 12 पहरेदार और 19 प्यादे हैं — कम से कम चार सेटों के हिस्से।", "बिशप मुकुटनुमा टोपी (माइटर) पहने हैं। शतरंज का \"हाथी\" बिशप में यूरोप में बदला, और लुईस के मोहरे इसके सबसे शुरुआती उदाहरणों में हैं। कुछ पहरेदार अपनी ढाल चबाते हैं — माना जाता है कि ये उन्माद में लड़ने वाले \"बर्सर्कर\" योद्धा हैं।"], "cap": ["लुईस द्वीप के शतरंज‑मोहरे (संग्रह कक्ष में 3D में देखें)", "78 मोहरे क़िस्म के हिसाब से"]}, {"h": "वालरस का दाँत और उत्तरी समुद्र", "p": ["ज़्यादातर मोहरे वालरस के दाँत के, कुछ व्हेल के दाँत के हैं। वालरस‑दाँत उत्तरी समुद्रों का ख़ज़ाना था, जो ग्रीनलैंड और उत्तरी नॉर्वे से लाया जाता था।", "तब लुईस नॉर्वे के राजा के द्वीपों में था; 1266 की पर्थ संधि से यह स्कॉटलैंड को मिला। त्रोंहाइम के गिरजाघर के पास उसी तरह तराशे टुकड़े मिले हैं — यह सुराग़ कि मोहरे कहाँ बने।"], "cap": []}, {"h": "खोज की किंवदंती और आज की लोकप्रियता", "p": ["खोज के कई क़िस्से हैं: रेत से उन्हें खोद निकालने वाली गाय, या स्थानीय निवासी मैल्कम मैकलाउड। खोजने वाले ने जल्दी ही उन्हें बेच दिया और एडिनबरा होते हुए ज़्यादातर ब्रिटिश संग्रहालय ने ख़रीदे।", "रूठे और मज़ेदार चेहरों वाले ये मोहरे आज बेहद लोकप्रिय हैं और इनकी नक़लें दुनिया भर में बिकती हैं। फ़िल्म \"हैरी पॉटर एंड द फ़िलॉसफ़र्स स्टोन\" (2001) की जादुई शतरंज में लुईस के मोहरों पर आधारित मोहरे थे।"], "cap": []}], "tl": [["12वीं सदी का अंत", "मोहरे नॉर्वे (त्रोंहाइम के आसपास) में बने"], ["1266", "पर्थ संधि से लुईस समेत द्वीप स्कॉटलैंड को मिले"], ["1831", "लुईस पर 93 वस्तुएँ एक साथ मिलीं"], ["1831–32", "ब्रिटिश संग्रहालय ने 82 ख़रीदीं"], ["1888", "स्कॉटलैंड के राष्ट्रीय संग्रहालय को 11 मिलीं"], ["2001", "\"हैरी पॉटर\" की जादुई शतरंज में दिखे"], ["2019", "5 पाउंड में ख़रीदा गया पहरेदार 7,35,000 पाउंड में बिका"]]}}, "ar": {"lewis": {"kf": ["93 قطعة وقرصًا عُثر عليها في جزيرة لويس باسكتلندا سنة 1831", "نُحتت غالبًا من ناب الفظ في النرويج أواخر القرن الثاني عشر", "وهي اليوم موزعة بين المتحف البريطاني والمتاحف الوطنية في اسكتلندا"], "more": [{"h": "قطع الشطرنج الـ78", "p": ["القطع الـ78 هي 8 ملوك و8 ملكات و16 أسقفًا و15 فارسًا و12 حارسًا و19 بيدقًا — أجزاء من أربعة أطقم على الأقل.", "يلبس الأساقفة التاج الأسقفي. وتحوّل «الفيل» في الشطرنج إلى أسقف حدث في أوروبا، وقطع لويس من أقدم أمثلته. وبعض الحراس يعضّون دروعهم، ويُعتقد أنهم يمثلون «البيرسركر»، المحاربين الذين يقاتلون في هياج."], "cap": ["قطع شطرنج لويس (شاهدها ثلاثية الأبعاد في قاعة المقتنيات)", "قطع الشطرنج الـ78 بحسب النوع"]}, {"h": "ناب الفظ وبحار الشمال", "p": ["أغلب القطع من ناب الفظ وبعضها من سن الحوت. وكان ناب الفظ كنزًا من كنوز بحار الشمال يُجلب من غرينلاند وشمال النرويج.", "وكانت لويس آنذاك من جزر ملك النرويج، وانتقلت إلى اسكتلندا بمعاهدة بيرث سنة 1266. وقد وُجدت قرب كاتدرائية تروندهايم شظايا منحوتة بالطريقة نفسها، وهي دليل على موطن صنعها."], "cap": []}, {"h": "أسطورة الاكتشاف وشهرتها اليوم", "p": ["تُروى حكايات كثيرة: بقرة نبشتها من الرمل، أو أحد السكان ويُدعى مالكوم ماكلاود. وباعها مكتشفها سريعًا، واشترى المتحف البريطاني أكثرها عن طريق إدنبرة.", "وبوجوهها العابسة الطريفة صارت شديدة الشعبية، وتُباع نسخها في أنحاء العالم. واستُخدمت في شطرنج السحرة بفيلم «هاري بوتر وحجر الفيلسوف» (2001) قطع مستوحاة منها."], "cap": []}], "tl": [["أواخر القرن الثاني عشر", "تُصنع القطع في النرويج (قرب تروندهايم)"], ["1266", "معاهدة بيرث تمنح الجزر، ومنها لويس، لاسكتلندا"], ["1831", "يُعثر على القطع الـ93 معًا في لويس"], ["1831–32", "المتحف البريطاني يشتري 82"], ["1888", "المتحف الوطني الاسكتلندي يقتني 11"], ["2001", "تظهر في شطرنج السحرة في «هاري بوتر»"], ["2019", "حارس اشتُري بخمسة جنيهات يُباع بـ735 ألفًا"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
