(T => { const D = {"ja": {"tafl": {"kf": ["中央の王と少数の守り手が、多数の攻め手に囲まれて戦う、数のちがう2軍のゲーム", "ヴァイキングの時代の北ヨーロッパで遊ばれ、盤は7×7から19×19まで大きさがいろいろ", "遊び方の手がかりは、1732年のリンネの旅日記と、その誤りのある英訳"], "more": [{"h": "バリンダリーの盤", "p": ["アイルランド中部の湖の住居跡（クラノグ）から見つかったバリンダリーの盤は、イチイの木でできています。7×7の49の穴に、駒の底の突起をさしこんで遊んだと考えられています。", "盤のふちには、人の頭の形の取っ手が彫られています。持ち運べる盤だったのでしょう。アイルランドには「ブランドゥヴ（黒いカラス）」という7×7のタフルの名前が伝わっていて、この盤で遊ばれたのかもしれません。"], "cap": ["バリンダリーの盤（7×7）に、アイルランドの「ブランドゥヴ」のはじめの並びを置いたところ。金の輪は中央と四すみの印"]}, {"h": "リンネのタブルト", "p": ["リンネが書きとめたタブルトは9×9の盤です。中央の玉座に王が立ち、守る側の「スウェーデン人」8人と、攻める側の「モスクワ人」16人が戦います。", "駒はみな飛車のようにまっすぐ何マスでも進み、敵の駒を前後や左右からはさんで取ります。王が盤のふちにたどり着けば守る側の勝ち、王を四方から囲めば攻める側の勝ちです。リンネはラテン語とスウェーデン語をまぜて書いていて、英訳ではいくつかの点が原文と変わってしまいました。"], "cap": ["リンネが書きとめたタブルト（9×9）。中央の玉座に王、守り手8、攻め手16。緑のふちのマスに王が着けば守る側の勝ち"]}, {"h": "大きくなる盤、消えていくゲーム", "p": ["タフルの盤は7×7のほか、9×9、ウェールズの11×11、そして19×19まであります。いちばん大きい「アレア・エヴァンゲリイ」は、12世紀の写本に図が描かれ、10世紀のイングランドのアゼルスタン王の宮廷から伝わったと書かれています。", "12〜13世紀にチェスが北ヨーロッパに広まると、タフルは次第に遊ばれなくなりました。遠いラップランドにだけ残ったタブルトを、リンネが偶然書きとめたのです。いまは11×11の盤を使う国際大会も開かれ、ふたたび遊ぶ人が増えています。"], "cap": ["ルイス島の発見物（12世紀）。チェスの駒といっしょに、盤上ゲーム用の円盤14枚が見つかっています"]}], "tl": [["10世紀", "アイルランドでバリンダリーの盤が作られる"], ["924〜939年", "アゼルスタン王の宮廷でアレア・エヴァンゲリイが遊ばれたと伝わる"], ["12世紀", "アレア・エヴァンゲリイの図が写本に描かれる"], ["12〜13世紀", "北ヨーロッパでチェスが広まり、タフルが姿を消していく"], ["1732年", "リンネがラップランドでタブルトを書きとめる"], ["1811年", "リンネの日記の英訳『ラケシス・ラッポニカ』が出る"], ["1913年", "マリーが『チェスの歴史』でタフルを復元"], ["1932年", "バリンダリーの盤が見つかる"]]}}, "en": {"tafl": {"kf": ["A king and a few defenders in the centre, surrounded by a larger army — a game of two unequal sides", "Played in Viking-age northern Europe, on boards from 7×7 up to 19×19", "The rules come down to us through Linnaeus’s 1732 travel diary — and its flawed English translation"], "more": [{"h": "The Ballinderry board", "p": ["Found in a lake dwelling (crannog) in the Irish midlands, the Ballinderry board is made of yew. Its 49 holes in a 7×7 grid probably held pieces with pegs on their bases.", "A handle carved as a human head sticks out from the frame — this was a board you could carry. Irish sources name a 7×7 tafl game, brandubh (“black raven”), which may well have been played on it."], "cap": ["The Ballinderry board (7×7) set up for brandubh, an Irish tafl game. The gold rings mark the centre and the four corners"]}, {"h": "Linnaeus’s tablut", "p": ["The tablut Linnaeus recorded uses a 9×9 board. The king stands on the central throne; his 8 “Swedes” face 16 “Muscovites”.", "Every piece moves any distance in a straight line, like a rook, and is captured by being sandwiched between two enemies. The defenders win if the king reaches the edge; the attackers win by surrounding him on all four sides. Linnaeus wrote in a mix of Latin and Swedish, and several points shifted in the English translation."], "cap": ["Tablut as Linnaeus recorded it (9×9): the king on the central throne, 8 defenders, 16 attackers. The defenders win if the king reaches a green edge square"]}, {"h": "Growing boards, a fading game", "p": ["Besides 7×7 there were 9×9 boards, the Welsh 11×11, and even 19×19. The largest, Alea Evangelii, is drawn in a 12th-century manuscript that says it came from the court of King Æthelstan of England in the 10th century.", "As chess spread through northern Europe in the 12th and 13th centuries, tafl slowly fell out of use. Only in distant Lapland did tablut survive — and Linnaeus happened to write it down. Today international tournaments are played on 11×11 boards, and the game is winning new players."], "cap": ["The Lewis hoard (12th century): alongside the chessmen were 14 discs for a board game"]}], "tl": [["10th c.", "The Ballinderry board is made in Ireland"], ["924–939", "Alea Evangelii is said to be played at King Æthelstan’s court"], ["12th c.", "Alea Evangelii is drawn in a manuscript"], ["12th–13th c.", "Chess spreads in northern Europe and tafl fades away"], ["1732", "Linnaeus records tablut in Lapland"], ["1811", "Lachesis Lapponica, the English translation of his diary"], ["1913", "Murray reconstructs tafl in A History of Chess"], ["1932", "The Ballinderry board is found"]]}}, "zh": {"tafl": {"kf": ["中央的国王和少数守卫，被人数更多的进攻方包围——双方兵力不对等的游戏", "流行于维京时代的北欧，棋盘从7×7到19×19大小不一", "玩法的线索来自林奈1732年的旅行日记，以及它有误的英译本"], "more": [{"h": "巴林德里棋盘", "p": ["巴林德里棋盘出土于爱尔兰中部湖上住所（克兰诺格）遗址，用紫杉木制成。7×7共49个孔，大概是把棋子底部的小柱插进去来下的。", "棋盘边上雕着人头形状的把手，可见是一副便于携带的棋盘。爱尔兰文献里记有一种7×7的塔夫棋，名叫“布兰杜夫”（黑乌鸦），也许就是在这样的棋盘上下的。"], "cap": ["在巴林德里棋盘（7×7）上摆出爱尔兰“布兰杜夫”的初始布局。金色圆圈标出中央和四角"]}, {"h": "林奈记下的塔布尔特", "p": ["林奈记下的塔布尔特用9×9的棋盘。国王站在中央的王座上，守方8名“瑞典人”对阵攻方16名“莫斯科人”。", "所有棋子都像车一样沿直线走任意格，被两个敌子前后或左右夹住就被吃掉。国王到达棋盘边缘则守方胜；从四面围住国王则攻方胜。林奈用拉丁语夹杂瑞典语写成，英译本里有几处与原文不同。"], "cap": ["林奈记下的塔布尔特（9×9）：国王在中央王座，守卫8名，进攻方16名。国王走到绿色边缘格，守方获胜"]}, {"h": "越来越大的棋盘，渐渐消失的游戏", "p": ["塔夫棋盘除了7×7，还有9×9、威尔士的11×11，甚至19×19。最大的“阿莱亚·埃万杰利”画在一部12世纪的抄本里，书中说它来自10世纪英格兰埃塞尔斯坦国王的宫廷。", "12至13世纪国际象棋传遍北欧后，塔夫渐渐无人再玩，只有遥远的拉普兰保留了塔布尔特，碰巧被林奈记了下来。如今已有使用11×11棋盘的国际比赛，玩的人又多了起来。"], "cap": ["刘易斯岛出土文物（12世纪）：与国际象棋棋子一起发现了14枚棋盘游戏用的圆片"]}], "tl": [["10世纪", "爱尔兰制作巴林德里棋盘"], ["924–939年", "相传埃塞尔斯坦国王的宫廷里下阿莱亚·埃万杰利"], ["12世纪", "阿莱亚·埃万杰利的棋图被画进抄本"], ["12–13世纪", "国际象棋传遍北欧，塔夫逐渐消失"], ["1732年", "林奈在拉普兰记下塔布尔特"], ["1811年", "林奈日记的英译本《拉刻西斯·拉波尼卡》出版"], ["1913年", "默里在《国际象棋史》中复原塔夫"], ["1932年", "巴林德里棋盘出土"]]}}, "zh-TW": {"tafl": {"kf": ["中央的國王和少數守衛，被人數更多的進攻方包圍——雙方兵力不對等的遊戲", "流行於維京時代的北歐，棋盤從7×7到19×19大小不一", "玩法的線索來自林奈1732年的旅行日記，以及它有誤的英譯本"], "more": [{"h": "巴林德里棋盤", "p": ["巴林德里棋盤出土於愛爾蘭中部湖上住所（克蘭諾格）遺址，用紫杉木製成。7×7共49個孔，大概是把棋子底部的小柱插進去來下的。", "棋盤邊上雕著人頭形狀的把手，可見是一副便於攜帶的棋盤。愛爾蘭文獻裡記有一種7×7的塔夫棋，名叫「布蘭杜夫」（黑烏鴉），也許就是在這樣的棋盤上下的。"], "cap": ["在巴林德里棋盤（7×7）上擺出愛爾蘭「布蘭杜夫」的初始佈局。金色圓圈標出中央和四角"]}, {"h": "林奈記下的塔布爾特", "p": ["林奈記下的塔布爾特用9×9的棋盤。國王站在中央的王座上，守方8名「瑞典人」對陣攻方16名「莫斯科人」。", "所有棋子都像車一樣沿直線走任意格，被兩個敵子前後或左右夾住就被吃掉。國王到達棋盤邊緣則守方勝；從四面圍住國王則攻方勝。林奈用拉丁語夾雜瑞典語寫成，英譯本裡有幾處與原文不同。"], "cap": ["林奈記下的塔布爾特（9×9）：國王在中央王座，守衛8名，進攻方16名。國王走到綠色邊緣格，守方獲勝"]}, {"h": "越來越大的棋盤，漸漸消失的遊戲", "p": ["塔夫棋盤除了7×7，還有9×9、威爾斯的11×11，甚至19×19。最大的「阿萊亞·埃萬傑利」畫在一部12世紀的抄本裡，書中說它來自10世紀英格蘭埃塞爾斯坦國王的宮廷。", "12至13世紀西洋棋傳遍北歐後，塔夫漸漸無人再玩，只有遙遠的拉普蘭保留了塔布爾特，碰巧被林奈記了下來。如今已有使用11×11棋盤的國際比賽，玩的人又多了起來。"], "cap": ["路易斯島出土文物（12世紀）：與西洋棋棋子一起發現了14枚棋盤遊戲用的圓片"]}], "tl": [["10世紀", "愛爾蘭製作巴林德里棋盤"], ["924–939年", "相傳埃塞爾斯坦國王的宮廷裡下阿萊亞·埃萬傑利"], ["12世紀", "阿萊亞·埃萬傑利的棋圖被畫進抄本"], ["12–13世紀", "西洋棋傳遍北歐，塔夫逐漸消失"], ["1732年", "林奈在拉普蘭記下塔布爾特"], ["1811年", "林奈日記的英譯本《拉刻西斯·拉波尼卡》出版"], ["1913年", "默里在《西洋棋史》中復原塔夫"], ["1932年", "巴林德里棋盤出土"]]}}, "ko": {"tafl": {"kf": ["가운데의 왕과 소수의 수비군이 더 많은 공격군에게 둘러싸여 싸우는, 병력이 다른 두 군대의 게임", "바이킹 시대 북유럽에서 즐겼고, 판은 7×7부터 19×19까지 크기가 다양하다", "놀이법의 단서는 1732년 린네의 여행 일기와 오류가 있는 그 영어 번역"], "more": [{"h": "밸린데리 판", "p": ["아일랜드 중부의 호수 위 주거지(크래녹) 유적에서 나온 밸린데리 판은 주목 나무로 만들어졌습니다. 7×7, 49개의 구멍에 말 밑의 돌기를 꽂아 놀았던 것으로 보입니다.", "판 가장자리에는 사람 머리 모양의 손잡이가 새겨져 있어, 들고 다닐 수 있는 판이었던 듯합니다. 아일랜드에는 ‘브란두브(검은 까마귀)’라는 7×7 타플의 이름이 전해지는데, 이 판에서 놀았을지도 모릅니다."], "cap": ["밸린데리 판(7×7)에 아일랜드 ‘브란두브’의 처음 배치를 놓은 모습. 금색 고리는 가운데와 네 귀퉁이 표시"]}, {"h": "린네의 타블루트", "p": ["린네가 기록한 타블루트는 9×9 판을 씁니다. 가운데 왕좌에 왕이 서고, 수비 쪽 ‘스웨덴인’ 8명과 공격 쪽 ‘모스크바인’ 16명이 싸웁니다.", "모든 말은 장기의 차처럼 곧게 몇 칸이든 움직이고, 적의 말 둘 사이에 앞뒤나 좌우로 끼이면 잡힙니다. 왕이 판 가장자리에 닿으면 수비 쪽, 왕을 사방에서 에워싸면 공격 쪽이 이깁니다. 린네는 라틴어와 스웨덴어를 섞어 썼고, 영어 번역에서는 몇 가지가 원문과 달라졌습니다."], "cap": ["린네가 기록한 타블루트(9×9). 가운데 왕좌에 왕, 수비 8, 공격 16. 왕이 초록색 가장자리 칸에 닿으면 수비 쪽 승리"]}, {"h": "커지는 판, 사라져 가는 게임", "p": ["타플 판은 7×7 말고도 9×9, 웨일스의 11×11, 그리고 19×19까지 있습니다. 가장 큰 ‘알레아 에반젤리’는 12세기 필사본에 그려져 있고, 10세기 잉글랜드 애설스탠 왕의 궁정에서 전해졌다고 적혀 있습니다.", "12~13세기에 체스가 북유럽에 퍼지자 타플은 점점 사라졌습니다. 먼 라플란드에만 남은 타블루트를 린네가 우연히 기록한 것입니다. 지금은 11×11 판으로 겨루는 국제 대회도 열리며 다시 즐기는 사람이 늘고 있습니다."], "cap": ["루이스섬 발견물(12세기). 체스 말과 함께 판 게임용 원반 14개가 나왔습니다"]}], "tl": [["10세기", "아일랜드에서 밸린데리 판이 만들어짐"], ["924~939년", "애설스탠 왕의 궁정에서 알레아 에반젤리를 즐겼다고 전해짐"], ["12세기", "알레아 에반젤리 그림이 필사본에 그려짐"], ["12~13세기", "체스가 북유럽에 퍼지고 타플이 사라져 감"], ["1732년", "린네가 라플란드에서 타블루트를 기록"], ["1811년", "린네 일기의 영어 번역 『라케시스 라포니카』 출간"], ["1913년", "머리가 『체스의 역사』에서 타플을 복원"], ["1932년", "밸린데리 판 발견"]]}}, "es": {"tafl": {"kf": ["Un rey y unos pocos defensores en el centro, rodeados por un ejército mayor: un juego de dos bandos desiguales", "Se jugaba en el norte de Europa en la época vikinga, en tableros de 7×7 hasta 19×19", "Las reglas nos llegan por el diario de viaje de Linneo de 1732… y por su traducción inglesa con errores"], "more": [{"h": "El tablero de Ballinderry", "p": ["Hallado en una vivienda lacustre (crannog) del centro de Irlanda, el tablero de Ballinderry es de tejo. Sus 49 agujeros, en una cuadrícula de 7×7, probablemente sujetaban piezas con una espiga en la base.", "Del marco sale un asa tallada en forma de cabeza humana: era un tablero para llevar. Las fuentes irlandesas mencionan un tafl de 7×7, el brandubh («cuervo negro»), que bien pudo jugarse en él."], "cap": ["El tablero de Ballinderry (7×7) con la posición inicial del brandubh irlandés. Los anillos dorados marcan el centro y las cuatro esquinas"]}, {"h": "El tablut de Linneo", "p": ["El tablut que anotó Linneo usa un tablero de 9×9. El rey está en el trono central; sus 8 «suecos» se enfrentan a 16 «moscovitas».", "Todas las piezas se mueven en línea recta cuantas casillas quieran, como una torre, y se capturan atrapándolas entre dos enemigas. Los defensores ganan si el rey llega al borde; los atacantes, si lo rodean por los cuatro lados. Linneo escribió mezclando latín y sueco, y varios puntos cambiaron en la traducción inglesa."], "cap": ["El tablut tal como lo anotó Linneo (9×9): el rey en el trono central, 8 defensores y 16 atacantes. Los defensores ganan si el rey llega a una casilla verde del borde"]}, {"h": "Tableros que crecen, un juego que se apaga", "p": ["Además del 7×7 había tableros de 9×9, el galés de 11×11 e incluso de 19×19. El mayor, el Alea Evangelii, aparece dibujado en un manuscrito del siglo XII que dice que vino de la corte del rey Æthelstan de Inglaterra, en el siglo X.", "Cuando el ajedrez se extendió por el norte de Europa en los siglos XII y XIII, el tafl fue cayendo en desuso. Solo en la lejana Laponia sobrevivió el tablut, y Linneo lo anotó por casualidad. Hoy se juegan torneos internacionales en tableros de 11×11 y el juego gana nuevos jugadores."], "cap": ["El tesoro de Lewis (siglo XII): junto a las piezas de ajedrez había 14 discos para un juego de tablero"]}], "tl": [["s. X", "Se fabrica en Irlanda el tablero de Ballinderry"], ["924–939", "Se dice que en la corte de Æthelstan se jugaba al Alea Evangelii"], ["s. XII", "El Alea Evangelii se dibuja en un manuscrito"], ["ss. XII–XIII", "El ajedrez se extiende por el norte de Europa y el tafl desaparece"], ["1732", "Linneo anota el tablut en Laponia"], ["1811", "Sale Lachesis Lapponica, la traducción inglesa de su diario"], ["1913", "Murray reconstruye el tafl en A History of Chess"], ["1932", "Se halla el tablero de Ballinderry"]]}}, "fr": {"tafl": {"kf": ["Un roi et quelques défenseurs au centre, encerclés par une armée plus nombreuse : un jeu à deux camps inégaux", "Joué dans l’Europe du Nord à l’époque viking, sur des plateaux de 7×7 à 19×19", "Les règles nous sont parvenues par le journal de voyage de Linné (1732)… et sa traduction anglaise fautive"], "more": [{"h": "Le plateau de Ballinderry", "p": ["Découvert dans un habitat lacustre (crannog) du centre de l’Irlande, le plateau de Ballinderry est en if. Ses 49 trous, en grille de 7×7, recevaient sans doute des pions munis d’un tenon.", "Une poignée sculptée en forme de tête humaine dépasse du cadre : c’était un plateau qu’on emportait. Les sources irlandaises nomment un tafl de 7×7, le brandubh (« corbeau noir »), qui a pu s’y jouer."], "cap": ["Le plateau de Ballinderry (7×7) avec la position de départ du brandubh irlandais. Les anneaux dorés marquent le centre et les quatre coins"]}, {"h": "Le tablut de Linné", "p": ["Le tablut noté par Linné se joue sur 9×9. Le roi occupe le trône central ; ses 8 « Suédois » affrontent 16 « Moscovites ».", "Toutes les pièces avancent en ligne droite d’autant de cases qu’elles veulent, comme une tour, et sont capturées lorsque deux ennemies les prennent en tenaille. Les défenseurs gagnent si le roi atteint le bord ; les attaquants, s’ils l’encerclent des quatre côtés. Linné mêlait latin et suédois, et plusieurs points ont changé dans la traduction anglaise."], "cap": ["Le tablut tel que Linné l’a noté (9×9) : le roi sur le trône central, 8 défenseurs, 16 attaquants. Les défenseurs gagnent si le roi atteint une case verte du bord"]}, {"h": "Des plateaux qui grandissent, un jeu qui s’efface", "p": ["Outre le 7×7, il existait des plateaux de 9×9, le 11×11 gallois et même du 19×19. Le plus grand, l’Alea Evangelii, est dessiné dans un manuscrit du XIIe siècle qui le dit venu de la cour du roi Æthelstan d’Angleterre, au Xe siècle.", "Quand les échecs se répandent en Europe du Nord aux XIIe et XIIIe siècles, le tafl tombe peu à peu dans l’oubli. Seul le tablut survit, dans la lointaine Laponie — et Linné l’a noté par hasard. Aujourd’hui, des tournois internationaux se jouent sur 11×11 et le jeu séduit de nouveaux joueurs."], "cap": ["Le trésor de Lewis (XIIe siècle) : avec les pièces d’échecs, 14 disques pour un jeu de plateau"]}], "tl": [["Xe s.", "Fabrication du plateau de Ballinderry en Irlande"], ["924–939", "On jouerait à l’Alea Evangelii à la cour d’Æthelstan"], ["XIIe s.", "L’Alea Evangelii est dessiné dans un manuscrit"], ["XIIe–XIIIe s.", "Les échecs gagnent l’Europe du Nord, le tafl disparaît"], ["1732", "Linné note le tablut en Laponie"], ["1811", "Parution de Lachesis Lapponica, traduction anglaise de son journal"], ["1913", "Murray reconstitue le tafl dans A History of Chess"], ["1932", "Découverte du plateau de Ballinderry"]]}}, "pt": {"tafl": {"kf": ["Um rei e poucos defensores no centro, cercados por um exército maior: um jogo de dois lados desiguais", "Jogado no norte da Europa na era viking, em tabuleiros de 7×7 até 19×19", "As regras chegaram até nós pelo diário de viagem de Lineu (1732) — e por sua tradução inglesa com erros"], "more": [{"h": "O tabuleiro de Ballinderry", "p": ["Encontrado numa habitação lacustre (crannog) no centro da Irlanda, o tabuleiro de Ballinderry é de teixo. Seus 49 furos, numa grade de 7×7, provavelmente prendiam peças com um pino na base.", "Do contorno sai uma alça esculpida em forma de cabeça humana: era um tabuleiro para levar consigo. Fontes irlandesas citam um tafl de 7×7, o brandubh («corvo negro»), que pode ter sido jogado nele."], "cap": ["O tabuleiro de Ballinderry (7×7) com a posição inicial do brandubh irlandês. Os anéis dourados marcam o centro e os quatro cantos"]}, {"h": "O tablut de Lineu", "p": ["O tablut registrado por Lineu usa um tabuleiro de 9×9. O rei fica no trono central; seus 8 «suecos» enfrentam 16 «moscovitas».", "Todas as peças andam em linha reta quantas casas quiserem, como uma torre, e são capturadas quando ficam entre duas inimigas. Os defensores vencem se o rei chegar à borda; os atacantes, se o cercarem pelos quatro lados. Lineu escreveu misturando latim e sueco, e vários pontos mudaram na tradução inglesa."], "cap": ["O tablut como Lineu o registrou (9×9): o rei no trono central, 8 defensores e 16 atacantes. Os defensores vencem se o rei chegar a uma casa verde da borda"]}, {"h": "Tabuleiros que crescem, um jogo que se apaga", "p": ["Além do 7×7, havia tabuleiros de 9×9, o galês de 11×11 e até de 19×19. O maior, o Alea Evangelii, aparece desenhado num manuscrito do século XII que diz ter vindo da corte do rei Æthelstan da Inglaterra, no século X.", "Quando o xadrez se espalhou pelo norte da Europa nos séculos XII e XIII, o tafl foi caindo em desuso. Só na distante Lapônia o tablut sobreviveu — e Lineu o anotou por acaso. Hoje há torneios internacionais em tabuleiros de 11×11, e o jogo conquista novos jogadores."], "cap": ["O tesouro de Lewis (século XII): junto das peças de xadrez havia 14 discos para um jogo de tabuleiro"]}], "tl": [["séc. X", "O tabuleiro de Ballinderry é feito na Irlanda"], ["924–939", "Diz-se que se jogava Alea Evangelii na corte de Æthelstan"], ["séc. XII", "O Alea Evangelii é desenhado num manuscrito"], ["sécs. XII–XIII", "O xadrez se espalha pelo norte da Europa e o tafl desaparece"], ["1732", "Lineu registra o tablut na Lapônia"], ["1811", "Sai Lachesis Lapponica, a tradução inglesa do diário"], ["1913", "Murray reconstrói o tafl em A History of Chess"], ["1932", "O tabuleiro de Ballinderry é encontrado"]]}}, "de": {"tafl": {"kf": ["Ein König und wenige Verteidiger in der Mitte, umringt von einem größeren Heer – ein Spiel zweier ungleicher Parteien", "Gespielt im Nordeuropa der Wikingerzeit, auf Brettern von 7×7 bis 19×19", "Die Regeln kennen wir aus Linnés Reisetagebuch von 1732 – und seiner fehlerhaften englischen Übersetzung"], "more": [{"h": "Das Brett von Ballinderry", "p": ["Das Brett von Ballinderry stammt aus einer Seesiedlung (Crannog) in Mittelirland und ist aus Eibenholz. In seinen 49 Löchern im 7×7-Raster steckten wohl Steine mit einem Zapfen am Boden.", "Am Rahmen sitzt ein Griff in Form eines Menschenkopfes – ein Brett zum Mitnehmen. Irische Quellen nennen ein 7×7-Tafl namens Brandubh („schwarzer Rabe“), das darauf gespielt worden sein könnte."], "cap": ["Das Brett von Ballinderry (7×7) mit der Anfangsstellung des irischen Brandubh. Die goldenen Ringe markieren Mitte und Ecken"]}, {"h": "Linnés Tablut", "p": ["Linnés Tablut wird auf 9×9 Feldern gespielt. Der König steht auf dem Thron in der Mitte; seine 8 „Schweden“ kämpfen gegen 16 „Moskowiter“.", "Alle Steine ziehen wie ein Turm beliebig weit geradeaus und werden geschlagen, wenn zwei Gegner sie einklemmen. Die Verteidiger gewinnen, wenn der König den Rand erreicht; die Angreifer, wenn sie ihn von allen vier Seiten einschließen. Linné schrieb in einer Mischung aus Latein und Schwedisch, und in der englischen Übersetzung verschoben sich mehrere Punkte."], "cap": ["Tablut, wie Linné es aufschrieb (9×9): der König auf dem Thron in der Mitte, 8 Verteidiger, 16 Angreifer. Erreicht der König ein grünes Randfeld, gewinnen die Verteidiger"]}, {"h": "Wachsende Bretter, ein verschwindendes Spiel", "p": ["Neben 7×7 gab es Bretter mit 9×9, das walisische 11×11 und sogar 19×19. Das größte, Alea Evangelii, ist in einer Handschrift des 12. Jahrhunderts gezeichnet, die es auf den Hof des englischen Königs Æthelstan im 10. Jahrhundert zurückführt.", "Als sich das Schach im 12. und 13. Jahrhundert in Nordeuropa verbreitete, geriet Tafl allmählich in Vergessenheit. Nur im fernen Lappland überlebte Tablut – und Linné schrieb es zufällig auf. Heute gibt es internationale Turniere auf 11×11-Brettern, und das Spiel gewinnt neue Anhänger."], "cap": ["Der Fund von Lewis (12. Jahrhundert): neben den Schachfiguren lagen 14 Spielsteine für ein Brettspiel"]}], "tl": [["10. Jh.", "In Irland entsteht das Brett von Ballinderry"], ["924–939", "Am Hof Æthelstans soll Alea Evangelii gespielt worden sein"], ["12. Jh.", "Alea Evangelii wird in einer Handschrift gezeichnet"], ["12.–13. Jh.", "Schach verbreitet sich in Nordeuropa, Tafl verschwindet"], ["1732", "Linné schreibt in Lappland Tablut auf"], ["1811", "Lachesis Lapponica, die englische Übersetzung seines Tagebuchs, erscheint"], ["1913", "Murray rekonstruiert Tafl in A History of Chess"], ["1932", "Das Brett von Ballinderry wird gefunden"]]}}, "ru": {"tafl": {"kf": ["Король и немногие защитники в центре, окружённые бо́льшим войском, — игра двух неравных сторон", "В неё играли в Северной Европе эпохи викингов, на досках от 7×7 до 19×19", "Правила дошли до нас через путевой дневник Линнея 1732 года — и его неточный английский перевод"], "more": [{"h": "Доска из Баллиндерри", "p": ["Доска из Баллиндерри найдена на месте свайного поселения (кранног) в центре Ирландии и сделана из тиса. В её 49 отверстий сетки 7×7, вероятно, вставляли фигуры со штырьком в основании.", "Из рамки выступает ручка в виде человеческой головы — доску можно было носить с собой. Ирландские источники называют тафл 7×7 — брандуб («чёрный ворон»); возможно, в него играли именно на ней."], "cap": ["Доска из Баллиндерри (7×7) с начальной расстановкой ирландского брандуба. Золотые кольца отмечают центр и четыре угла"]}, {"h": "Таблут Линнея", "p": ["Таблут, записанный Линнеем, играется на доске 9×9. Король стоит на центральном троне; его 8 «шведов» сражаются с 16 «московитами».", "Все фигуры ходят по прямой на любое число клеток, как ладья, и берутся, когда их зажимают с двух сторон. Защитники побеждают, если король доберётся до края; нападающие — если окружат его со всех четырёх сторон. Линней писал на смеси латыни и шведского, и в английском переводе несколько мест изменилось."], "cap": ["Таблут в записи Линнея (9×9): король на центральном троне, 8 защитников, 16 нападающих. Защитники побеждают, если король дойдёт до зелёной клетки края"]}, {"h": "Доски растут, игра уходит", "p": ["Кроме 7×7 были доски 9×9, валлийская 11×11 и даже 19×19. Самая большая, Alea Evangelii, нарисована в рукописи XII века, где сказано, что игра пришла от двора английского короля Этельстана в X веке.", "Когда в XII–XIII веках по Северной Европе распространились шахматы, тафл понемногу забылся. Лишь в далёкой Лапландии уцелел таблут — и Линней случайно его записал. Сегодня проводятся международные турниры на досках 11×11, и у игры появляются новые поклонники."], "cap": ["Клад с острова Льюис (XII век): вместе с шахматами нашли 14 дисков для настольной игры"]}], "tl": [["X в.", "В Ирландии сделана доска из Баллиндерри"], ["924–939", "При дворе Этельстана, по преданию, играют в Alea Evangelii"], ["XII в.", "Alea Evangelii нарисована в рукописи"], ["XII–XIII вв.", "Шахматы распространяются по Северной Европе, тафл исчезает"], ["1732", "Линней записывает таблут в Лапландии"], ["1811", "Выходит Lachesis Lapponica — английский перевод его дневника"], ["1913", "Мюррей реконструирует тафл в «Истории шахмат»"], ["1932", "Найдена доска из Баллиндерри"]]}}, "tr": {"tafl": {"kf": ["Ortadaki kral ve birkaç savunucu, daha kalabalık bir orduyla çevrilidir: eşit olmayan iki tarafın oyunu", "Viking çağında Kuzey Avrupa’da oynanırdı; tahtalar 7×7’den 19×19’a kadar çeşitliydi", "Kurallar bize Linnaeus’un 1732 tarihli gezi günlüğü ve onun hatalı İngilizce çevirisi yoluyla ulaştı"], "more": [{"h": "Ballinderry tahtası", "p": ["İrlanda’nın ortasındaki bir göl yerleşiminden (crannog) çıkan Ballinderry tahtası porsuk ağacından yapılmıştır. 7×7 düzendeki 49 deliğe, altında çivisi olan taşlar takılarak oynandığı düşünülür.", "Çerçeveden insan başı biçiminde oyulmuş bir sap çıkar: yanınızda taşıyabileceğiniz bir tahtaydı. İrlanda kaynakları brandubh (“kara kuzgun”) adlı 7×7’lik bir tafl’dan söz eder; belki de bu tahtada oynanıyordu."], "cap": ["Ballinderry tahtası (7×7) üzerinde İrlanda oyunu brandubh’un başlangıç dizilişi. Altın halkalar ortayı ve dört köşeyi gösterir"]}, {"h": "Linnaeus’un tablut’u", "p": ["Linnaeus’un kaydettiği tablut 9×9’luk bir tahtada oynanır. Kral ortadaki tahtta durur; 8 “İsveçli”si 16 “Moskovalı”ya karşı savaşır.", "Bütün taşlar kale gibi düz bir çizgide istediği kadar ilerler ve iki düşman arasında sıkıştırılınca alınır. Kral kenara ulaşırsa savunanlar, kralı dört yandan kuşatırlarsa saldıranlar kazanır. Linnaeus Latince ile İsveççeyi karıştırarak yazmıştı; İngilizce çeviride birkaç nokta değişti."], "cap": ["Linnaeus’un kaydettiği tablut (9×9): ortadaki tahtta kral, 8 savunucu, 16 saldırgan. Kral yeşil kenar karelerinden birine ulaşırsa savunan taraf kazanır"]}, {"h": "Büyüyen tahtalar, kaybolan bir oyun", "p": ["7×7’nin yanında 9×9, Galler’in 11×11’i ve hatta 19×19’luk tahtalar vardı. En büyüğü Alea Evangelii, 12. yüzyıldan bir el yazmasında çizilmiştir; el yazması oyunun 10. yüzyılda İngiltere Kralı Æthelstan’ın sarayından geldiğini söyler.", "Satranç 12. ve 13. yüzyıllarda Kuzey Avrupa’ya yayılınca tafl yavaş yavaş unutuldu. Tablut yalnızca uzak Laponya’da yaşadı ve Linnaeus onu tesadüfen kaydetti. Bugün 11×11 tahtalarda uluslararası turnuvalar düzenleniyor ve oyun yeni oyuncular kazanıyor."], "cap": ["Lewis buluntusu (12. yüzyıl): satranç taşlarının yanında bir tahta oyununa ait 14 disk bulundu"]}], "tl": [["10. yy", "Ballinderry tahtası İrlanda’da yapılır"], ["924–939", "Æthelstan’ın sarayında Alea Evangelii oynandığı anlatılır"], ["12. yy", "Alea Evangelii bir el yazmasına çizilir"], ["12.–13. yy", "Satranç Kuzey Avrupa’ya yayılır, tafl kaybolur"], ["1732", "Linnaeus Laponya’da tablut’u kaydeder"], ["1811", "Günlüğün İngilizce çevirisi Lachesis Lapponica yayımlanır"], ["1913", "Murray, A History of Chess’te tafl’ı yeniden kurar"], ["1932", "Ballinderry tahtası bulunur"]]}}, "id": {"tafl": {"kf": ["Seorang raja dan sedikit pembela di tengah, dikepung pasukan yang lebih besar — permainan dua pihak yang tidak seimbang", "Dimainkan di Eropa Utara pada zaman Viking, di papan berukuran 7×7 hingga 19×19", "Aturannya sampai kepada kita lewat catatan perjalanan Linnaeus tahun 1732 — dan terjemahan Inggrisnya yang keliru"], "more": [{"h": "Papan Ballinderry", "p": ["Ditemukan di permukiman danau (crannog) di Irlandia tengah, papan Ballinderry terbuat dari kayu yew. Ke-49 lubangnya, dalam kisi 7×7, mungkin dipakai untuk menancapkan bidak berpasak di bagian bawahnya.", "Dari bingkainya menonjol pegangan berukir kepala manusia: papan ini bisa dibawa ke mana-mana. Sumber Irlandia menyebut tafl 7×7 bernama brandubh (“gagak hitam”), yang mungkin dimainkan di papan ini."], "cap": ["Papan Ballinderry (7×7) dengan susunan awal brandubh dari Irlandia. Cincin emas menandai bagian tengah dan keempat sudut"]}, {"h": "Tablut catatan Linnaeus", "p": ["Tablut yang dicatat Linnaeus memakai papan 9×9. Raja berdiri di takhta tengah; 8 “orang Swedia”-nya melawan 16 “orang Moskow”.", "Semua bidak bergerak lurus sejauh berapa petak pun, seperti benteng, dan ditangkap bila terjepit di antara dua musuh. Pembela menang bila raja mencapai tepi papan; penyerang menang bila mengepungnya dari empat sisi. Linnaeus menulis dengan campuran bahasa Latin dan Swedia, dan beberapa hal berubah dalam terjemahan Inggris."], "cap": ["Tablut seperti dicatat Linnaeus (9×9): raja di takhta tengah, 8 pembela, 16 penyerang. Pembela menang bila raja mencapai petak hijau di tepi"]}, {"h": "Papan yang membesar, permainan yang memudar", "p": ["Selain 7×7, ada papan 9×9, 11×11 dari Wales, bahkan 19×19. Yang terbesar, Alea Evangelii, digambar dalam naskah abad ke-12 yang menyebut permainan itu berasal dari istana Raja Æthelstan dari Inggris pada abad ke-10.", "Ketika catur menyebar di Eropa Utara pada abad ke-12 dan ke-13, tafl perlahan ditinggalkan. Hanya di Lapland yang jauh tablut bertahan — dan Linnaeus kebetulan mencatatnya. Kini ada turnamen internasional di papan 11×11, dan permainan ini mendapat pemain baru."], "cap": ["Temuan Lewis (abad ke-12): bersama bidak catur ditemukan 14 cakram untuk permainan papan"]}], "tl": [["Abad ke-10", "Papan Ballinderry dibuat di Irlandia"], ["924–939", "Alea Evangelii konon dimainkan di istana Æthelstan"], ["Abad ke-12", "Alea Evangelii digambar dalam naskah"], ["Abad ke-12–13", "Catur menyebar di Eropa Utara, tafl menghilang"], ["1732", "Linnaeus mencatat tablut di Lapland"], ["1811", "Terbit Lachesis Lapponica, terjemahan Inggris catatannya"], ["1913", "Murray merekonstruksi tafl dalam A History of Chess"], ["1932", "Papan Ballinderry ditemukan"]]}}, "hi": {"tafl": {"kf": ["बीच में एक राजा और कुछ रक्षक, जिन्हें बड़ी सेना घेरे रहती है — दो असमान पक्षों का खेल", "वाइकिंग युग के उत्तरी यूरोप में खेला जाता था; बिसात 7×7 से 19×19 तक अलग-अलग आकार की", "नियमों का सुराग लिनियस की 1732 की यात्रा-डायरी और उसका ग़लतियों वाला अंग्रेज़ी अनुवाद है"], "more": [{"h": "बैलिंडेरी की बिसात", "p": ["आयरलैंड के मध्य भाग में झील पर बनी बस्ती (क्रैनॉग) से मिली बैलिंडेरी की बिसात यू की लकड़ी की है। 7×7 के 49 छेदों में शायद ऐसी गोटियाँ लगाई जाती थीं जिनके नीचे खूँटी होती थी।", "किनारे से इंसानी सिर के आकार का एक हत्था निकला है — यानी इसे साथ ले जाया जा सकता था। आयरिश स्रोतों में 7×7 के एक तफ़्ल ‘ब्रानडुव’ (काला कौआ) का नाम मिलता है; हो सकता है वह इसी बिसात पर खेला जाता हो।"], "cap": ["बैलिंडेरी की बिसात (7×7) पर आयरलैंड के ‘ब्रानडुव’ की शुरुआती चाल। सुनहरे छल्ले बीच और चारों कोनों के निशान हैं"]}, {"h": "लिनियस का तबलुत", "p": ["लिनियस ने जो तबलुत दर्ज किया, वह 9×9 की बिसात पर खेला जाता है। राजा बीच के सिंहासन पर खड़ा होता है; उसके 8 ‘स्वीडिश’ 16 ‘मस्कोवी’ से लड़ते हैं।", "सभी गोटियाँ हाथी (रूक) की तरह सीधी रेखा में कितने भी खाने चलती हैं, और दो दुश्मनों के बीच फँसने पर मारी जाती हैं। राजा किनारे तक पहुँच जाए तो रक्षक जीतते हैं; उसे चारों ओर से घेर लें तो हमलावर। लिनियस ने लैटिन और स्वीडिश मिलाकर लिखा था, और अंग्रेज़ी अनुवाद में कई बातें बदल गईं।"], "cap": ["लिनियस का दर्ज किया तबलुत (9×9): बीच के सिंहासन पर राजा, 8 रक्षक, 16 हमलावर। राजा किनारे के हरे खाने पर पहुँचे तो रक्षक जीतते हैं"]}, {"h": "बड़ी होती बिसातें, मिटता खेल", "p": ["7×7 के अलावा 9×9, वेल्स की 11×11 और 19×19 तक की बिसातें थीं। सबसे बड़ी, ‘अलेआ एवांजेली’, 12वीं सदी की एक पांडुलिपि में बनी है, जिसमें लिखा है कि यह 10वीं सदी में इंग्लैंड के राजा एथेलस्टन के दरबार से आई।", "12वीं–13वीं सदी में जब शतरंज उत्तरी यूरोप में फैला, तफ़्ल धीरे-धीरे भुला दिया गया। सिर्फ़ दूर लैपलैंड में तबलुत बचा रहा — और लिनियस ने संयोग से उसे लिख लिया। आज 11×11 की बिसात पर अंतरराष्ट्रीय टूर्नामेंट होते हैं और खेल को नए खिलाड़ी मिल रहे हैं।"], "cap": ["लुईस द्वीप की खोज (12वीं सदी): शतरंज के मोहरों के साथ बिसात के खेल की 14 टिकियाँ मिलीं"]}], "tl": [["10वीं सदी", "आयरलैंड में बैलिंडेरी की बिसात बनी"], ["924–939", "कहा जाता है कि एथेलस्टन के दरबार में अलेआ एवांजेली खेला गया"], ["12वीं सदी", "अलेआ एवांजेली एक पांडुलिपि में बनाया गया"], ["12वीं–13वीं सदी", "शतरंज उत्तरी यूरोप में फैला, तफ़्ल मिटता गया"], ["1732", "लिनियस ने लैपलैंड में तबलुत दर्ज किया"], ["1811", "डायरी का अंग्रेज़ी अनुवाद ‘लैकेसिस लैपोनिका’ छपा"], ["1913", "मरे ने ‘ए हिस्ट्री ऑफ़ चेस’ में तफ़्ल का पुनर्निर्माण किया"], ["1932", "बैलिंडेरी की बिसात मिली"]]}}, "ar": {"tafl": {"kf": ["ملك وقلة من المدافعين في الوسط، يحيط بهم جيش أكبر عددًا: لعبة طرفين غير متكافئين", "لُعبت في شمال أوروبا في عصر الفايكنغ، على ألواح من 7×7 حتى 19×19", "وصلتنا القواعد عبر يوميات رحلة لينيوس عام 1732، وعبر ترجمتها الإنجليزية التي فيها أخطاء"], "more": [{"h": "لوح بالينديري", "p": ["عُثر على لوح بالينديري في مسكن بُني فوق بحيرة (كرانوغ) في وسط أيرلندا، وهو من خشب الطقسوس. وفي ثقوبه الـ49 المرتبة 7×7 كانت تُثبَّت على الأرجح قطع لها وتد في أسفلها.", "ويبرز من إطاره مقبض منحوت على هيئة رأس إنسان، فهو لوح يُحمل في السفر. وتذكر المصادر الأيرلندية لعبة تافل 7×7 اسمها «براندوف» (الغراب الأسود)، وربما لُعبت عليه."], "cap": ["لوح بالينديري (7×7) وعليه الوضع الابتدائي للعبة «براندوف» الأيرلندية. الحلقات الذهبية تعلّم الوسط والزوايا الأربع"]}, {"h": "تابلوت لينيوس", "p": ["التابلوت الذي دوّنه لينيوس يُلعب على لوح 9×9. يقف الملك على العرش في الوسط، ويواجه «سويديوه» الثمانية ستة عشر «موسكوفيًا».", "تتحرك كل القطع في خط مستقيم أي عدد من المربعات كالرخ، وتؤسر إذا حُصرت بين قطعتين للعدو. يفوز المدافعون إذا بلغ الملك الحافة، والمهاجمون إذا أحاطوا به من الجهات الأربع. كتب لينيوس بخليط من اللاتينية والسويدية، فتغيرت عدة نقاط في الترجمة الإنجليزية."], "cap": ["التابلوت كما دوّنه لينيوس (9×9): الملك على العرش في الوسط، و8 مدافعين، و16 مهاجمًا. يفوز المدافعون إذا بلغ الملك مربعًا أخضر على الحافة"]}, {"h": "ألواح تكبر، ولعبة تختفي", "p": ["إلى جانب 7×7 كانت هناك ألواح 9×9، ولوح ويلزي 11×11، بل و19×19. وأكبرها «أليا إيفانجيلي» مرسوم في مخطوط من القرن الثاني عشر يقول إنها جاءت من بلاط الملك الإنجليزي أثلستان في القرن العاشر.", "ومع انتشار الشطرنج في شمال أوروبا في القرنين الثاني عشر والثالث عشر، تراجعت التافل شيئًا فشيئًا. ولم يبقَ التابلوت إلا في لابلاند البعيدة، فدوّنه لينيوس مصادفة. واليوم تُقام بطولات دولية على ألواح 11×11، وتكسب اللعبة لاعبين جددًا."], "cap": ["كنز جزيرة لويس (القرن الثاني عشر): وُجدت مع قطع الشطرنج 14 قرصًا للعبة لوحية"]}], "tl": [["القرن 10", "صنع لوح بالينديري في أيرلندا"], ["924–939", "يُروى أن «أليا إيفانجيلي» لُعبت في بلاط أثلستان"], ["القرن 12", "رسم «أليا إيفانجيلي» في مخطوط"], ["القرنان 12–13", "انتشار الشطرنج في شمال أوروبا واختفاء التافل"], ["1732", "لينيوس يدوّن التابلوت في لابلاند"], ["1811", "صدور «لاكيسيس لابونيكا»، الترجمة الإنجليزية ليومياته"], ["1913", "موراي يعيد بناء التافل في «تاريخ الشطرنج»"], ["1932", "العثور على لوح بالينديري"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (16): story 9 (goose) made fuller */
(T => { const D = {"ja": {"goose": {"kf": ["らせんの63マスを、さいころを振って中央のゴールまで進む競走ゲーム", "16世紀のイタリアで生まれ、メディチ家からスペイン王に贈られたと伝わる", "紙に印刷されて広まり、題材を変えた版が数えきれないほど作られた"], "more": [{"h": "らせんの63マス", "p": ["よく知られた版では、ガチョウのマスのほかにいくつかの特別なマスがあります。6の「橋」に止まると12まで進み、19の「宿屋」では1回休み、31の「井戸」と52の「牢屋」では、ほかの人が来て助けてくれるまで動けません。", "42の「迷路」に止まると30まで戻され、58の「死神」に止まるとふりだしからやり直しです。ゴールの63にはぴったりの目で止まらなければならず、多すぎた分は引き返します。最後の一歩がいちばん難しいゲームです。"], "cap": ["63マスを外から内へのらせんに並べた図。緑がガチョウ、青が橋、黄が足止め（宿屋・井戸・牢屋）、赤が戻り（迷路・死神）、金がゴール"]}, {"h": "9の目のふしぎ", "p": ["ガチョウのマスは5、9、14、18……と、4つと5つおきに交互に並んでいます。9の倍数のマスにはいつもガチョウがいるので、9の目で9に止まると、9、18、27……と跳びつづけて、そのまま63に着いてしまいます。", "そこで、2つのさいころで遊ぶ版には「最初に6と3が出たら26へ、5と4が出たら53へ」という特別なきまりがあります。63という数は7×9で、当時は人生で最も危ない年とされた63歳に重ねられていたともいわれます。"], "cap": ["ガチョウのマスは4つ・5つおきに並び、9ごとに必ずガチョウがある。最初に9が出ると、ガチョウからガチョウへ跳んで一気に63へ"]}, {"h": "印刷されて広まる", "p": ["盤は銅版や木版で刷られ、安く手に入るようになりました。フランスでは「ジュ・ド・ロワ」、スペインでは「フエゴ・デ・ラ・オカ」と呼ばれ、スペインには「ガチョウからガチョウへ、出た目で進む」という決まり文句が今も残っています。", "絵柄を変えた版も次々と作られました。地理や歴史を学ぶ盤、フランス革命やナポレオンを題材にした盤、商品の宣伝の盤まであります。同じ63マスのしくみの上に、その時代の関心ごとが描かれてきたのです。"], "cap": []}], "tl": [["16世紀", "イタリアで生まれたと考えられる"], ["1574〜87年", "メディチ家のフランチェスコ1世がスペイン王フェリペ2世に贈ったと伝わる"], ["16世紀後半", "インドのグジャラートで、表がガチョウ・裏がチェスの両面盤が作られる"], ["1597年", "ロンドンのジョン・ウルフが出版物として登録"], ["17〜18世紀", "ヨーロッパ中で大流行し、題材を変えた版が増える"], ["1790年代", "フランス革命を題材にした盤が作られる"], ["19世紀", "子どもの遊びとして各国で大量に印刷される"]]}}, "en": {"goose": {"kf": ["A race along a spiral of 63 squares to the goal in the centre, by the throw of the dice", "Born in 16th-century Italy and, it is said, sent by the Medici to the King of Spain", "Spread as printed sheets, in countless versions with new pictures and themes"], "more": [{"h": "A spiral of 63 squares", "p": ["In the best-known version there are a few special squares besides the geese. The bridge on 6 carries you to 12; at the inn on 19 you miss a turn; in the well on 31 and the prison on 52 you are stuck until another player comes to free you.", "The maze on 42 sends you back to 30, and death on 58 sends you back to the start. You must land on 63 with the exact throw — any extra and you bounce back. The last step is the hardest of all."], "cap": ["The 63 squares laid out as a spiral from the outside in. Green: geese; blue: the bridge; yellow: hold-ups (inn, well, prison); red: setbacks (maze, death); gold: the goal"]}, {"h": "The puzzle of nine", "p": ["The geese stand on 5, 9, 14, 18… at alternate gaps of 4 and 5. Every multiple of 9 has a goose, so a 9 landing on 9 would carry you on to 18, 27… and straight to 63.", "That is why versions played with two dice have a special rule: a first throw of 6 and 3 goes to 26, and 5 and 4 goes to 53. The number 63 is 7×9, and it has been linked to the age of 63, then thought the most dangerous year of a life."], "cap": ["Geese stand every 4 and 5 squares, so there is always a goose on a multiple of 9. A first throw of 9 would hop from goose to goose straight to 63"]}, {"h": "Spread by the printing press", "p": ["Boards were printed from copper plates and woodblocks and became cheap to buy. In France it was the jeu de l’oie, in Spain the juego de la oca, where a rhyme about hopping “from goose to goose” is still a common saying.", "New versions with new pictures kept appearing: boards for learning geography and history, boards about the French Revolution or Napoleon, even boards advertising products. On the same 63-square track, each age drew its own concerns."], "cap": []}], "tl": [["16th c.", "Thought to be born in Italy"], ["1574–87", "Francesco I de’ Medici is said to send it to Philip II of Spain"], ["late 16th c.", "A double-sided board, goose on one side and chess on the other, is made in Gujarat, India"], ["1597", "John Wolfe registers it for printing in London"], ["17th–18th c.", "A craze across Europe, with ever more themed versions"], ["1790s", "Boards about the French Revolution are made"], ["19th c.", "Printed in huge numbers in many countries as a children’s game"]]}}, "zh": {"goose": {"kf": ["掷骰子沿着63格的螺旋走向中央终点的竞速游戏", "16世纪诞生于意大利，相传由美第奇家族赠给西班牙国王", "以印刷品的形式传开，换了题材的版本数不胜数"], "more": [{"h": "63格的螺旋", "p": ["在最常见的版本里，除了鹅格还有几个特殊格。停在6号“桥”上可以前进到12；19号“客栈”要停一回合；掉进31号“井”或52号“牢房”，要等别人过来解救才能动。", "停在42号“迷宫”要退回30，停在58号“死神”就得从头再来。终点63必须正好掷到，多出的点数要往回走。最后一步往往最难。"], "cap": ["把63格由外向内排成螺旋的图。绿色是鹅，蓝色是桥，黄色是受阻（客栈、井、牢房），红色是倒退（迷宫、死神），金色是终点"]}, {"h": "9点的奥妙", "p": ["鹅格排在5、9、14、18……，间隔4格和5格交替。9的倍数格上总有鹅，所以掷9停在9上，就会一路跳到18、27……直达63。", "因此用两颗骰子的版本有一条特别规则：第一次掷出6和3走到26，掷出5和4走到53。63等于7×9，据说当时人们把63岁看作一生中最危险的年龄，两者常被联系在一起。"], "cap": ["鹅格隔4格、5格交替排列，9的倍数上总有鹅。第一次掷出9，就会从鹅跳到鹅，一口气到达63"]}, {"h": "靠印刷传开", "p": ["棋盘用铜版和木版印刷，价格变得低廉。法国叫它“鹅棋”（jeu de l’oie），西班牙叫“juego de la oca”，西班牙至今还流传着“从鹅到鹅”的顺口溜。", "换了图案的新版本层出不穷：学地理和历史的棋盘，以法国大革命或拿破仑为题材的棋盘，甚至还有商品广告的棋盘。同样的63格之上，画着每个时代关心的事。"], "cap": []}], "tl": [["16世纪", "被认为诞生于意大利"], ["1574–87年", "相传美第奇家族的弗朗切斯科一世把它送给西班牙国王腓力二世"], ["16世纪后半", "印度古吉拉特制作了正面鹅棋、背面国际象棋的双面棋盘"], ["1597年", "伦敦的约翰·沃尔夫登记出版"], ["17–18世纪", "风靡欧洲，题材各异的版本越来越多"], ["1790年代", "出现以法国大革命为题材的棋盘"], ["19世纪", "作为儿童游戏在各国大量印刷"]]}}, "zh-TW": {"goose": {"kf": ["擲骰子沿著63格的螺旋走向中央終點的競速遊戲", "16世紀誕生於義大利，相傳由梅迪奇家族贈給西班牙國王", "以印刷品的形式傳開，換了題材的版本數不勝數"], "more": [{"h": "63格的螺旋", "p": ["在最常見的版本裡，除了鵝格還有幾個特殊格。停在6號「橋」上可以前進到12；19號「客棧」要停一回合；掉進31號「井」或52號「牢房」，要等別人過來解救才能動。", "停在42號「迷宮」要退回30，停在58號「死神」就得從頭再來。終點63必須正好擲到，多出的點數要往回走。最後一步往往最難。"], "cap": ["把63格由外向內排成螺旋的圖。綠色是鵝，藍色是橋，黃色是受阻（客棧、井、牢房），紅色是倒退（迷宮、死神），金色是終點"]}, {"h": "9點的奧妙", "p": ["鵝格排在5、9、14、18……，間隔4格和5格交替。9的倍數格上總有鵝，所以擲9停在9上，就會一路跳到18、27……直達63。", "因此用兩顆骰子的版本有一條特別規則：第一次擲出6和3走到26，擲出5和4走到53。63等於7×9，據說當時人們把63歲看作一生中最危險的年齡，兩者常被聯繫在一起。"], "cap": ["鵝格隔4格、5格交替排列，9的倍數上總有鵝。第一次擲出9，就會從鵝跳到鵝，一口氣到達63"]}, {"h": "靠印刷傳開", "p": ["棋盤用銅版和木版印刷，價格變得低廉。法國叫它「鵝棋」（jeu de l’oie），西班牙叫「juego de la oca」，西班牙至今還流傳著「從鵝到鵝」的順口溜。", "換了圖案的新版本層出不窮：學地理和歷史的棋盤，以法國大革命或拿破崙為題材的棋盤，甚至還有商品廣告的棋盤。同樣的63格之上，畫著每個時代關心的事。"], "cap": []}], "tl": [["16世紀", "被認為誕生於義大利"], ["1574–87年", "相傳梅迪奇家族的法蘭切斯科一世把它送給西班牙國王腓力二世"], ["16世紀後半", "印度古吉拉特製作了正面鵝棋、背面西洋棋的雙面棋盤"], ["1597年", "倫敦的約翰·沃爾夫登記出版"], ["17–18世紀", "風靡歐洲，題材各異的版本越來越多"], ["1790年代", "出現以法國大革命為題材的棋盤"], ["19世紀", "作為兒童遊戲在各國大量印刷"]]}}, "ko": {"goose": {"kf": ["주사위를 굴려 63칸의 나선을 따라 가운데 결승점까지 가는 경주 게임", "16세기 이탈리아에서 태어나 메디치 가문이 스페인 왕에게 선물했다고 전해진다", "종이에 인쇄되어 퍼졌고, 주제를 바꾼 판이 셀 수 없이 만들어졌다"], "more": [{"h": "나선의 63칸", "p": ["잘 알려진 판에는 거위 칸 말고도 특별한 칸이 몇 개 있습니다. 6번 ‘다리’에 서면 12까지 나아가고, 19번 ‘여관’에서는 한 번 쉬며, 31번 ‘우물’과 52번 ‘감옥’에서는 다른 사람이 와서 구해 줄 때까지 움직일 수 없습니다.", "42번 ‘미로’에 서면 30으로 돌아가고, 58번 ‘죽음’에 서면 처음부터 다시 시작합니다. 결승점 63에는 꼭 맞는 눈으로 멈춰야 하고, 넘친 만큼은 되돌아갑니다. 마지막 한 걸음이 가장 어려운 게임입니다."], "cap": ["63칸을 바깥에서 안쪽으로 나선형으로 늘어놓은 그림. 초록은 거위, 파랑은 다리, 노랑은 발묶임(여관·우물·감옥), 빨강은 후퇴(미로·죽음), 금색은 결승점"]}, {"h": "9의 수수께끼", "p": ["거위 칸은 5, 9, 14, 18……처럼 4칸과 5칸 간격으로 번갈아 놓여 있습니다. 9의 배수 칸에는 늘 거위가 있으므로, 9가 나와 9에 서면 18, 27……로 계속 뛰어 곧장 63에 닿아 버립니다.", "그래서 주사위 두 개로 하는 판에는 “처음에 6과 3이 나오면 26으로, 5와 4가 나오면 53으로”라는 특별한 규칙이 있습니다. 63은 7×9로, 당시 일생에서 가장 위험한 해로 여겨진 63세와 겹쳐 보았다고도 합니다."], "cap": ["거위 칸은 4칸·5칸 걸러 번갈아 있어서 9의 배수에는 늘 거위가 있다. 처음에 9가 나오면 거위에서 거위로 뛰어 단숨에 63으로"]}, {"h": "인쇄로 퍼지다", "p": ["판은 동판과 목판으로 찍혀 싸게 살 수 있게 되었습니다. 프랑스에서는 ‘죄 드 루아’, 스페인에서는 ‘후에고 데 라 오카’라 불렸고, 스페인에는 “거위에서 거위로”라는 관용구가 지금도 남아 있습니다.", "그림을 바꾼 판도 잇달아 만들어졌습니다. 지리와 역사를 배우는 판, 프랑스 혁명이나 나폴레옹을 소재로 한 판, 상품 광고 판까지 있습니다. 같은 63칸 위에 시대마다의 관심사가 그려져 온 것입니다."], "cap": []}], "tl": [["16세기", "이탈리아에서 태어난 것으로 여겨짐"], ["1574~87년", "메디치가의 프란체스코 1세가 스페인 왕 펠리페 2세에게 선물했다고 전해짐"], ["16세기 후반", "인도 구자라트에서 앞면은 거위, 뒷면은 체스인 양면 판이 만들어짐"], ["1597년", "런던의 존 울프가 출판물로 등록"], ["17~18세기", "유럽 전역에서 크게 유행하고 주제를 바꾼 판이 늘어남"], ["1790년대", "프랑스 혁명을 소재로 한 판이 만들어짐"], ["19세기", "어린이 놀이로 여러 나라에서 대량 인쇄됨"]]}}, "es": {"goose": {"kf": ["Una carrera por una espiral de 63 casillas hasta la meta central, a golpe de dado", "Nacido en la Italia del siglo XVI y, según se cuenta, enviado por los Médici al rey de España", "Se difundió en láminas impresas, en innumerables versiones con nuevos dibujos y temas"], "more": [{"h": "Una espiral de 63 casillas", "p": ["En la versión más conocida hay, además de las ocas, algunas casillas especiales. El puente del 6 te lleva al 12; en la posada del 19 pierdes un turno; en el pozo del 31 y la cárcel del 52 quedas atrapado hasta que otro jugador llega a liberarte.", "El laberinto del 42 te devuelve al 30, y la muerte del 58 te manda a la salida. Hay que caer en el 63 con la tirada exacta: lo que sobra, se retrocede. El último paso es el más difícil."], "cap": ["Las 63 casillas en espiral de fuera hacia dentro. Verde: ocas; azul: el puente; amarillo: esperas (posada, pozo, cárcel); rojo: retrocesos (laberinto, muerte); dorado: la meta"]}, {"h": "El enigma del nueve", "p": ["Las ocas están en el 5, 9, 14, 18…, alternando saltos de 4 y 5. Todos los múltiplos de 9 tienen oca, de modo que un 9 que cae en el 9 te llevaría al 18, al 27… y directo al 63.", "Por eso las versiones con dos dados tienen una regla especial: si la primera tirada es 6 y 3, se va al 26; si es 5 y 4, al 53. El 63 es 7×9 y se ha relacionado con los 63 años, considerados entonces la edad más peligrosa de la vida."], "cap": ["Las ocas están cada 4 y 5 casillas, así que siempre hay una oca en los múltiplos de 9. Un 9 en la primera tirada saltaría de oca en oca hasta el 63"]}, {"h": "La imprenta lo difunde", "p": ["Los tableros se imprimían con planchas de cobre y tacos de madera y se volvieron baratos. En Francia era el jeu de l’oie; en España, el juego de la oca, donde «de oca a oca y tiro porque me toca» sigue siendo un dicho popular.", "No dejaron de aparecer versiones con nuevos dibujos: tableros para aprender geografía e historia, sobre la Revolución francesa o Napoleón, e incluso anuncios de productos. Sobre la misma pista de 63 casillas, cada época dibujó sus propias preocupaciones."], "cap": []}], "tl": [["s. XVI", "Se cree que nace en Italia"], ["1574–87", "Francisco I de Médici lo habría enviado a Felipe II de España"], ["finales s. XVI", "En Guyarat (India) se hace un tablero de dos caras: oca por un lado y ajedrez por el otro"], ["1597", "John Wolfe lo registra para imprimirlo en Londres"], ["ss. XVII–XVIII", "Furor en toda Europa, con cada vez más versiones temáticas"], ["década de 1790", "Se hacen tableros sobre la Revolución francesa"], ["s. XIX", "Se imprime en masa en muchos países como juego infantil"]]}}, "fr": {"goose": {"kf": ["Une course le long d’une spirale de 63 cases jusqu’au but central, au gré des dés", "Né dans l’Italie du XVIe siècle et, dit-on, offert par les Médicis au roi d’Espagne", "Diffusé en feuilles imprimées, en d’innombrables versions aux images et thèmes nouveaux"], "more": [{"h": "Une spirale de 63 cases", "p": ["Dans la version la plus connue, il y a quelques cases spéciales en plus des oies. Le pont du 6 vous porte au 12 ; à l’hôtellerie du 19 on passe un tour ; dans le puits du 31 et la prison du 52, on reste bloqué jusqu’à ce qu’un autre joueur vienne vous délivrer.", "Le labyrinthe du 42 renvoie au 30, et la mort du 58 renvoie au départ. Il faut tomber pile sur le 63 : les points en trop font reculer. Le dernier pas est le plus difficile."], "cap": ["Les 63 cases disposées en spirale de l’extérieur vers l’intérieur. Vert : les oies ; bleu : le pont ; jaune : les attentes (hôtellerie, puits, prison) ; rouge : les reculs (labyrinthe, mort) ; or : le but"]}, {"h": "L’énigme du neuf", "p": ["Les oies occupent le 5, le 9, le 14, le 18…, à des intervalles alternés de 4 et 5. Chaque multiple de 9 porte une oie : un 9 tombant sur le 9 vous mènerait au 18, au 27… et droit au 63.", "D’où la règle spéciale des versions à deux dés : un premier coup de 6 et 3 mène au 26, et de 5 et 4 au 53. Le nombre 63 vaut 7×9 et a été rapproché de l’âge de 63 ans, tenu alors pour l’année la plus périlleuse de la vie."], "cap": ["Les oies se suivent tous les 4 et 5 cases : il y a toujours une oie sur les multiples de 9. Un 9 au premier coup sauterait d’oie en oie jusqu’au 63"]}, {"h": "L’imprimerie le répand", "p": ["Les plateaux étaient tirés sur cuivre ou sur bois et devinrent bon marché. En France, c’était le jeu de l’oie ; en Espagne, le juego de la oca, où une comptine « d’oie en oie » reste une expression courante.", "Les versions illustrées se multiplièrent : plateaux pour apprendre la géographie et l’histoire, sur la Révolution ou Napoléon, et même réclames pour des produits. Sur la même piste de 63 cases, chaque époque a dessiné ses propres préoccupations."], "cap": []}], "tl": [["XVIe s.", "Naissance supposée en Italie"], ["1574–87", "François Ier de Médicis l’aurait offert à Philippe II d’Espagne"], ["fin XVIe s.", "Au Gujarat (Inde), un plateau double face : l’oie d’un côté, les échecs de l’autre"], ["1597", "John Wolfe l’enregistre pour l’imprimer à Londres"], ["XVIIe–XVIIIe s.", "Engouement dans toute l’Europe, versions à thème de plus en plus nombreuses"], ["années 1790", "Plateaux consacrés à la Révolution française"], ["XIXe s.", "Imprimé en masse dans de nombreux pays comme jeu d’enfants"]]}}, "pt": {"goose": {"kf": ["Uma corrida por uma espiral de 63 casas até a meta no centro, ao sabor dos dados", "Nascido na Itália do século XVI e, segundo se conta, enviado pelos Médici ao rei da Espanha", "Espalhou-se em folhas impressas, em incontáveis versões com novas imagens e temas"], "more": [{"h": "Uma espiral de 63 casas", "p": ["Na versão mais conhecida há, além dos gansos, algumas casas especiais. A ponte do 6 leva ao 12; na estalagem do 19 perde-se uma vez; no poço do 31 e na prisão do 52 fica-se preso até outro jogador chegar para libertar.", "O labirinto do 42 manda de volta ao 30, e a morte do 58 manda para o início. É preciso cair exatamente no 63: o que sobra, volta. O último passo é o mais difícil."], "cap": ["As 63 casas em espiral de fora para dentro. Verde: gansos; azul: a ponte; amarelo: esperas (estalagem, poço, prisão); vermelho: recuos (labirinto, morte); dourado: a meta"]}, {"h": "O enigma do nove", "p": ["Os gansos estão no 5, 9, 14, 18…, alternando intervalos de 4 e 5. Todo múltiplo de 9 tem um ganso, então um 9 que cai no 9 levaria ao 18, ao 27… e direto ao 63.", "Por isso as versões com dois dados têm uma regra especial: se o primeiro lance for 6 e 3, vai-se ao 26; se for 5 e 4, ao 53. O 63 é 7×9 e já foi associado aos 63 anos, tidos então como a idade mais perigosa da vida."], "cap": ["Os gansos ficam a cada 4 e 5 casas, então sempre há um ganso nos múltiplos de 9. Um 9 no primeiro lance pularia de ganso em ganso até o 63"]}, {"h": "A imprensa o espalha", "p": ["Os tabuleiros eram impressos em chapas de cobre e blocos de madeira e ficaram baratos. Na França era o jeu de l’oie; na Espanha, o juego de la oca, onde um versinho sobre ir «de ganso em ganso» ainda é dito popular.", "Versões com novos desenhos não pararam de surgir: tabuleiros para aprender geografia e história, sobre a Revolução Francesa ou Napoleão, e até propaganda de produtos. Sobre a mesma pista de 63 casas, cada época desenhou suas próprias preocupações."], "cap": []}], "tl": [["séc. XVI", "Teria nascido na Itália"], ["1574–87", "Francisco I de Médici o teria enviado a Filipe II da Espanha"], ["fim do séc. XVI", "Em Gujarate (Índia), faz-se um tabuleiro de dois lados: ganso de um lado, xadrez do outro"], ["1597", "John Wolfe o registra para impressão em Londres"], ["sécs. XVII–XVIII", "Febre em toda a Europa, com cada vez mais versões temáticas"], ["década de 1790", "Surgem tabuleiros sobre a Revolução Francesa"], ["séc. XIX", "Impresso em massa em muitos países como jogo infantil"]]}}, "de": {"goose": {"kf": ["Ein Wettlauf über eine Spirale aus 63 Feldern zum Ziel in der Mitte, nach dem Wurf der Würfel", "Im Italien des 16. Jahrhunderts entstanden und, so heißt es, von den Medici dem König von Spanien geschenkt", "Als gedruckte Bögen verbreitet, in unzähligen Fassungen mit neuen Bildern und Themen"], "more": [{"h": "Eine Spirale aus 63 Feldern", "p": ["In der bekanntesten Fassung gibt es neben den Gänsen einige besondere Felder. Die Brücke auf 6 bringt einen auf 12; im Wirtshaus auf 19 setzt man eine Runde aus; im Brunnen auf 31 und im Gefängnis auf 52 sitzt man fest, bis ein anderer Spieler kommt und einen befreit.", "Das Labyrinth auf 42 schickt zurück auf 30, der Tod auf 58 zurück zum Start. Auf 63 muss man genau landen – überzählige Augen geht man zurück. Der letzte Schritt ist der schwerste."], "cap": ["Die 63 Felder als Spirale von außen nach innen. Grün: Gänse; blau: die Brücke; gelb: Aufenthalte (Wirtshaus, Brunnen, Gefängnis); rot: Rückschläge (Labyrinth, Tod); gold: das Ziel"]}, {"h": "Das Rätsel der Neun", "p": ["Die Gänse stehen auf 5, 9, 14, 18 … in abwechselnden Abständen von 4 und 5. Jedes Vielfache von 9 hat eine Gans – eine 9, die auf der 9 landet, trüge einen weiter auf 18, 27 … und geradewegs auf 63.", "Darum gibt es bei Fassungen mit zwei Würfeln eine Sonderregel: Ein erster Wurf von 6 und 3 führt auf 26, einer von 5 und 4 auf 53. Die 63 ist 7×9 und wurde mit dem 63. Lebensjahr in Verbindung gebracht, das damals als das gefährlichste galt."], "cap": ["Die Gänse stehen abwechselnd alle 4 und 5 Felder, darum steht auf jedem Vielfachen von 9 eine Gans. Eine 9 im ersten Wurf hüpfte von Gans zu Gans bis 63"]}, {"h": "Verbreitet durch den Druck", "p": ["Die Spielpläne wurden von Kupferplatten und Holzstöcken gedruckt und wurden billig. In Frankreich hieß es jeu de l’oie, in Spanien juego de la oca, wo ein Reim vom Hüpfen „von Gans zu Gans“ bis heute eine Redensart ist.", "Immer neue Fassungen mit neuen Bildern erschienen: Pläne zum Lernen von Erdkunde und Geschichte, über die Französische Revolution oder Napoleon, sogar Werbung für Waren. Auf derselben Bahn aus 63 Feldern zeichnete jede Zeit ihre eigenen Themen."], "cap": []}], "tl": [["16. Jh.", "Entsteht vermutlich in Italien"], ["1574–87", "Francesco I. de’ Medici soll es Philipp II. von Spanien geschenkt haben"], ["spätes 16. Jh.", "In Gujarat (Indien) entsteht ein doppelseitiges Brett: Gänsespiel auf der einen, Schach auf der anderen Seite"], ["1597", "John Wolfe lässt es in London zum Druck eintragen"], ["17.–18. Jh.", "Eine Mode in ganz Europa, mit immer mehr Themenfassungen"], ["1790er", "Pläne über die Französische Revolution entstehen"], ["19. Jh.", "In vielen Ländern massenhaft als Kinderspiel gedruckt"]]}}, "ru": {"goose": {"kf": ["Гонка по спирали из 63 клеток к цели в центре — как выпадут кости", "Родилась в Италии XVI века и, по преданию, была подарена Медичи испанскому королю", "Распространялась в виде печатных листов, в бесчисленных вариантах с новыми картинками и темами"], "more": [{"h": "Спираль из 63 клеток", "p": ["В самом известном варианте, кроме гусей, есть несколько особых клеток. Мост на 6 переносит на 12; на постоялом дворе на 19 пропускают ход; в колодце на 31 и в тюрьме на 52 сидят, пока не придёт другой игрок и не выручит.", "Лабиринт на 42 отбрасывает на 30, а смерть на 58 — к самому началу. На 63 нужно попасть точно: лишние очки отсчитывают назад. Последний шаг — самый трудный."], "cap": ["63 клетки, выложенные спиралью снаружи внутрь. Зелёные — гуси; синяя — мост; жёлтые — задержки (постоялый двор, колодец, тюрьма); красные — откаты (лабиринт, смерть); золотая — цель"]}, {"h": "Загадка девятки", "p": ["Гуси стоят на 5, 9, 14, 18…, чередуя промежутки в 4 и 5 клеток. На каждой клетке, кратной 9, есть гусь, и девятка, попавшая на 9, понесла бы дальше на 18, 27… и прямо на 63.", "Поэтому в вариантах с двумя костями есть особое правило: первый бросок 6 и 3 ведёт на 26, а 5 и 4 — на 53. Число 63 — это 7×9; его связывали с 63-летним возрастом, который тогда считался самым опасным годом жизни."], "cap": ["Гуси стоят через 4 и 5 клеток по очереди, поэтому на каждой клетке, кратной 9, есть гусь. Девятка при первом броске перенесла бы от гуся к гусю прямо на 63"]}, {"h": "Её разнесла печать", "p": ["Доски печатали с медных досок и деревянных форм, и они стали дешёвыми. Во Франции это jeu de l’oie, в Испании — juego de la oca, где присказка «от гуся к гусю» до сих пор в ходу.", "Новые варианты с новыми картинками появлялись постоянно: доски для изучения географии и истории, о Французской революции или Наполеоне, даже реклама товаров. На одной и той же дорожке из 63 клеток каждая эпоха рисовала свои заботы."], "cap": []}], "tl": [["XVI в.", "Предположительно появляется в Италии"], ["1574–87", "Франческо I Медичи, по преданию, дарит её Филиппу II Испанскому"], ["конец XVI в.", "В Гуджарате (Индия) делают двустороннюю доску: гусь с одной стороны, шахматы с другой"], ["1597", "Джон Вулф регистрирует её для печати в Лондоне"], ["XVII–XVIII вв.", "Мода по всей Европе, всё больше тематических вариантов"], ["1790-е", "Появляются доски о Французской революции"], ["XIX в.", "Массово печатается во многих странах как детская игра"]]}}, "tr": {"goose": {"kf": ["Zarla, 63 karelik bir sarmal boyunca ortadaki hedefe koşulan bir yarış oyunu", "16. yüzyıl İtalya’sında doğdu; Medicilerin İspanya kralına hediye ettiği anlatılır", "Basılı kâğıtlarla yayıldı; yeni resim ve konularla sayısız sürümü yapıldı"], "more": [{"h": "63 karelik sarmal", "p": ["En bilinen sürümde kazların yanında birkaç özel kare vardır. 6’daki köprü sizi 12’ye taşır; 19’daki handa bir tur beklersiniz; 31’deki kuyuda ve 52’deki zindanda başka bir oyuncu gelip kurtarana kadar kalırsınız.", "42’deki labirent 30’a, 58’deki ölüm başlangıca geri gönderir. 63’e tam zarla gelmek gerekir; fazlası kadar geri dönülür. En zor adım son adımdır."], "cap": ["63 karenin dıştan içe sarmal dizilişi. Yeşil: kazlar; mavi: köprü; sarı: bekletenler (han, kuyu, zindan); kırmızı: geri gönderenler (labirent, ölüm); altın: hedef"]}, {"h": "Dokuzun bilmecesi", "p": ["Kazlar 5, 9, 14, 18… karelerindedir; aralıklar 4 ve 5 olarak değişir. 9’un her katında kaz bulunduğundan, 9’a gelen bir 9 sizi 18’e, 27’ye… ve dosdoğru 63’e taşırdı.", "Bu yüzden iki zarla oynanan sürümlerde özel bir kural vardır: ilk atış 6 ve 3 ise 26’ya, 5 ve 4 ise 53’e gidilir. 63 sayısı 7×9’dur ve o dönemde ömrün en tehlikeli yılı sayılan 63 yaşla ilişkilendirilmiştir."], "cap": ["Kazlar sırayla 4 ve 5 kare arayla durur, bu yüzden 9’un her katında bir kaz vardır. İlk atışta gelen 9, kazdan kaza zıplayarak doğrudan 63’e götürürdü"]}, {"h": "Matbaayla yayılış", "p": ["Oyun tahtaları bakır levhalardan ve tahta kalıplardan basıldı ve ucuzladı. Fransa’da jeu de l’oie, İspanya’da juego de la oca denildi; İspanya’da “kazdan kaza” diye başlayan bir tekerleme hâlâ deyim olarak kullanılır.", "Yeni resimli sürümler ardı ardına çıktı: coğrafya ve tarih öğreten tahtalar, Fransız Devrimi’ni ya da Napolyon’u anlatanlar, hatta ürün reklamları. Aynı 63 karelik yolun üzerine her çağ kendi dertlerini çizdi."], "cap": []}], "tl": [["16. yy", "İtalya’da doğduğu düşünülür"], ["1574–87", "I. Francesco de’ Medici’nin İspanya Kralı II. Felipe’ye hediye ettiği anlatılır"], ["16. yy sonu", "Hindistan’ın Gucerat bölgesinde bir yüzü kaz oyunu, öbür yüzü satranç olan çift yüzlü tahta yapılır"], ["1597", "John Wolfe oyunu Londra’da basım için kaydettirir"], ["17.–18. yy", "Avrupa’da büyük moda; konulu sürümler çoğalır"], ["1790’lar", "Fransız Devrimi konulu tahtalar yapılır"], ["19. yy", "Birçok ülkede çocuk oyunu olarak toplu basılır"]]}}, "id": {"goose": {"kf": ["Lomba menyusuri spiral 63 petak menuju garis akhir di tengah, menurut lemparan dadu", "Lahir di Italia abad ke-16 dan, konon, dihadiahkan keluarga Medici kepada Raja Spanyol", "Menyebar lewat lembaran cetak, dalam versi tak terhitung dengan gambar dan tema baru"], "more": [{"h": "Spiral 63 petak", "p": ["Dalam versi paling terkenal, selain angsa ada beberapa petak khusus. Jembatan di 6 membawa ke 12; di penginapan 19 kamu kehilangan satu giliran; di sumur 31 dan penjara 52 kamu terjebak sampai pemain lain datang membebaskan.", "Labirin di 42 mengembalikan ke 30, dan maut di 58 mengembalikan ke awal. Petak 63 harus dicapai dengan lemparan pas; kelebihannya dihitung mundur. Langkah terakhir adalah yang tersulit."], "cap": ["Ke-63 petak disusun spiral dari luar ke dalam. Hijau: angsa; biru: jembatan; kuning: tertahan (penginapan, sumur, penjara); merah: mundur (labirin, maut); emas: garis akhir"]}, {"h": "Teka-teki angka sembilan", "p": ["Angsa berada di 5, 9, 14, 18…, dengan jarak 4 dan 5 bergantian. Setiap kelipatan 9 berisi angsa, sehingga angka 9 yang mendarat di 9 akan membawamu ke 18, 27… dan langsung ke 63.", "Karena itu versi dengan dua dadu punya aturan khusus: lemparan pertama 6 dan 3 menuju 26, sedangkan 5 dan 4 menuju 53. Angka 63 adalah 7×9 dan dikaitkan dengan usia 63 tahun, yang waktu itu dianggap tahun paling berbahaya dalam hidup."], "cap": ["Angsa berselang 4 dan 5 petak bergantian, jadi selalu ada angsa di kelipatan 9. Angka 9 di lemparan pertama akan melompat dari angsa ke angsa langsung ke 63"]}, {"h": "Menyebar lewat percetakan", "p": ["Papan dicetak dari pelat tembaga dan balok kayu sehingga menjadi murah. Di Prancis namanya jeu de l’oie, di Spanyol juego de la oca, dan di sana sajak tentang melompat “dari angsa ke angsa” masih jadi ungkapan sehari-hari.", "Versi bergambar baru terus bermunculan: papan untuk belajar geografi dan sejarah, tentang Revolusi Prancis atau Napoleon, bahkan iklan barang. Di atas lintasan 63 petak yang sama, setiap zaman menggambar perhatiannya sendiri."], "cap": []}], "tl": [["Abad ke-16", "Diperkirakan lahir di Italia"], ["1574–87", "Francesco I de’ Medici konon menghadiahkannya kepada Felipe II dari Spanyol"], ["Akhir abad ke-16", "Di Gujarat (India) dibuat papan dua sisi: angsa di satu sisi, catur di sisi lain"], ["1597", "John Wolfe mendaftarkannya untuk dicetak di London"], ["Abad ke-17–18", "Digemari di seluruh Eropa, versi bertema makin banyak"], ["1790-an", "Dibuat papan bertema Revolusi Prancis"], ["Abad ke-19", "Dicetak massal di banyak negara sebagai permainan anak"]]}}, "hi": {"goose": {"kf": ["पासा फेंककर 63 खानों की कुंडली पर बीच की मंज़िल तक पहुँचने की दौड़", "16वीं सदी के इटली में जन्मा; कहा जाता है कि मेदिची परिवार ने इसे स्पेन के राजा को भेंट किया", "छपे पन्नों के रूप में फैला; नए चित्रों और विषयों वाले अनगिनत संस्करण बने"], "more": [{"h": "63 खानों की कुंडली", "p": ["सबसे प्रसिद्ध संस्करण में हंसों के अलावा कुछ ख़ास खाने हैं। 6 पर पुल आपको 12 तक ले जाता है; 19 की सराय में एक बारी छूटती है; 31 के कुएँ और 52 की जेल में तब तक फँसे रहते हैं जब तक कोई दूसरा खिलाड़ी आकर छुड़ा न दे।", "42 की भूलभुलैया 30 पर लौटा देती है, और 58 की मृत्यु शुरुआत पर। 63 पर ठीक-ठीक अंक से पहुँचना होता है; जितने अंक ज़्यादा हों, उतना पीछे लौटना पड़ता है। आख़िरी क़दम सबसे कठिन है।"], "cap": ["63 खाने बाहर से भीतर की कुंडली में। हरा: हंस; नीला: पुल; पीला: रुकावटें (सराय, कुआँ, जेल); लाल: पीछे भेजने वाले (भूलभुलैया, मृत्यु); सुनहरा: मंज़िल"]}, {"h": "नौ की पहेली", "p": ["हंस 5, 9, 14, 18… पर हैं, 4 और 5 के बदलते अंतर से। 9 के हर गुणज पर हंस है, इसलिए 9 पर पहुँचा 9 का अंक आपको 18, 27… और सीधे 63 तक ले जाता।", "इसीलिए दो पासों वाले संस्करणों में एक ख़ास नियम है: पहली चाल में 6 और 3 आए तो 26 पर, 5 और 4 आए तो 53 पर जाते हैं। 63 यानी 7×9; इसे 63 वर्ष की उम्र से जोड़ा गया है, जिसे तब जीवन का सबसे ख़तरनाक साल माना जाता था।"], "cap": ["हंस बारी-बारी से 4 और 5 खानों के अंतर पर हैं, इसलिए 9 के हर गुणज पर हंस है। पहली चाल में 9 आए तो हंस से हंस पर कूदते हुए सीधे 63"]}, {"h": "छपाई से फैलाव", "p": ["बिसातें ताँबे की प्लेटों और लकड़ी के ठप्पों से छपीं और सस्ती हो गईं। फ़्रांस में इसे जू द ल्वा, स्पेन में ख़ुएगो दे ला ओका कहा गया; स्पेन में “हंस से हंस तक” वाली तुकबंदी आज भी कहावत है।", "नए चित्रों वाले संस्करण लगातार आते रहे: भूगोल और इतिहास सिखाने वाली बिसातें, फ़्रांसीसी क्रांति या नेपोलियन पर बनी बिसातें, यहाँ तक कि सामान के विज्ञापन भी। उसी 63 खानों के रास्ते पर हर युग ने अपनी चिंताएँ उकेरीं।"], "cap": []}], "tl": [["16वीं सदी", "इटली में जन्म माना जाता है"], ["1574–87", "कहा जाता है कि फ़्रांचेस्को प्रथम दे मेदिची ने इसे स्पेन के फ़िलिप द्वितीय को भेंट किया"], ["16वीं सदी का अंत", "गुजरात (भारत) में दोतरफ़ा बिसात बनी: एक ओर हंस का खेल, दूसरी ओर शतरंज"], ["1597", "जॉन वुल्फ़ ने लंदन में इसे छपाई के लिए दर्ज कराया"], ["17वीं–18वीं सदी", "पूरे यूरोप में लोकप्रिय, विषय-आधारित संस्करण बढ़े"], ["1790 का दशक", "फ़्रांसीसी क्रांति पर बिसातें बनीं"], ["19वीं सदी", "कई देशों में बच्चों के खेल के रूप में बड़े पैमाने पर छपा"]]}}, "ar": {"goose": {"kf": ["سباق على حلزون من 63 مربعًا نحو الهدف في الوسط، بحسب رمية النرد", "نشأت في إيطاليا في القرن السادس عشر، ويُروى أن آل ميديتشي أهدوها إلى ملك إسبانيا", "انتشرت في أوراق مطبوعة، بنسخ لا تُحصى ذات صور وموضوعات جديدة"], "more": [{"h": "حلزون من 63 مربعًا", "p": ["في النسخة الأشهر توجد إلى جانب الإوز بضعة مربعات خاصة. الجسر في 6 ينقلك إلى 12، وفي النُّزُل عند 19 تخسر دورًا، وفي البئر عند 31 والسجن عند 52 تبقى عالقًا حتى يأتي لاعب آخر فيحررك.", "المتاهة في 42 تعيدك إلى 30، والموت في 58 يعيدك إلى البداية. ويجب بلوغ 63 بالرمية المضبوطة، وما زاد يُعَدّ إلى الوراء. والخطوة الأخيرة هي الأصعب."], "cap": ["المربعات الـ63 مرتبة حلزونيًا من الخارج إلى الداخل. الأخضر: الإوز؛ الأزرق: الجسر؛ الأصفر: مواضع الانتظار (النُّزُل، البئر، السجن)؛ الأحمر: مواضع الرجوع (المتاهة، الموت)؛ الذهبي: الهدف"]}, {"h": "لغز التسعة", "p": ["يقف الإوز على 5 و9 و14 و18…، بفواصل متناوبة من 4 و5. وعلى كل مضاعف للعدد 9 إوزة، فإذا وقعت رمية 9 على المربع 9 حملتك إلى 18 ثم 27… ومباشرة إلى 63.", "لذلك في النسخ التي تُلعب بنردين قاعدة خاصة: إذا كانت الرمية الأولى 6 و3 تذهب إلى 26، وإذا كانت 5 و4 تذهب إلى 53. والعدد 63 هو 7×9، وقد رُبط بسن الثالثة والستين التي كانت تُعدّ آنذاك أخطر أعوام العمر."], "cap": ["الإوز يقف كل 4 ثم 5 مربعات بالتناوب، فثمة إوزة دائمًا على مضاعفات 9. لو جاءت 9 في الرمية الأولى لقفز اللاعب من إوزة إلى إوزة حتى 63"]}, {"h": "المطبعة تنشرها", "p": ["طُبعت الألواح من صفائح النحاس وقوالب الخشب فصارت رخيصة. سُمّيت في فرنسا «لعبة الإوزة» (jeu de l’oie) وفي إسبانيا juego de la oca، وما زالت في إسبانيا أهزوجة عن القفز «من إوزة إلى إوزة» مثلًا شائعًا.", "وتوالت النسخ ذات الرسوم الجديدة: ألواح لتعلّم الجغرافيا والتاريخ، وأخرى عن الثورة الفرنسية أو نابليون، بل وإعلانات لسلع. وعلى المسار نفسه ذي المربعات الـ63 رسم كل عصر شواغله."], "cap": []}], "tl": [["القرن 16", "يُعتقد أنها نشأت في إيطاليا"], ["1574–87", "يُروى أن فرانشيسكو الأول دي ميديتشي أهداها إلى فيليب الثاني ملك إسبانيا"], ["أواخر القرن 16", "صُنع في كجرات (الهند) لوح بوجهين: الإوزة على وجه والشطرنج على الآخر"], ["1597", "جون وولف يسجّلها للطباعة في لندن"], ["القرنان 17–18", "رواج في أوروبا كلها وتكاثر النسخ ذات الموضوعات"], ["تسعينيات القرن 18", "صُنعت ألواح عن الثورة الفرنسية"], ["القرن 19", "طُبعت بكميات كبيرة في بلدان كثيرة لعبةً للأطفال"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (17): story 10 (shogi) made fuller */
(T => { const D = {"ja": {"shogi": {"kf": ["インドで生まれたチェスの仲間が日本で育った、9×9の盤のゲーム", "いちばん古い駒は、天喜六年（1058）の札とともに興福寺の旧境内から出た", "取った駒を自分の駒として打てる「持ち駒」は、16世紀ごろに生まれたとされる"], "more": [{"h": "同じ色の駒、向きで分ける", "p": ["チェスの駒は白と黒に塗り分けられていますが、将棋の駒は敵も味方も同じ木の色で、五角形のとがった先がどちらを向いているかで見分けます。取った駒を向きだけ変えて打てるのは、この形のおかげです。", "駒には名前が書かれ、敵の陣地に入ると裏返して「成る」ことができます。歩は裏の「と」になり、金将と同じ動きになります。駒が立体の人形ではなく字を書いた板なのも、中国のシャンチーや朝鮮のチャンギと同じ、東アジアの将棋の仲間の特徴です。"], "cap": ["将棋の駒は敵味方とも同じ色。とがった先の向きで見分ける。右は裏返して「成った」歩（と金）"]}, {"h": "大きな将棋の時代", "p": ["鎌倉・室町時代から江戸時代にかけて、駒の種類と数をどんどん増やした大きな将棋が作られました。12×12の中将棋は江戸時代までよく遊ばれ、今も愛好者がいます。", "さらに15×15の大将棋、25×25の泰将棋、そして36×36の盤に804枚の駒を並べる大局将棋まで記録に残っています。けれども、ふだん遊ばれたのは9×9の小将棋で、持ち駒のルールを得て、今の将棋になりました。"], "cap": ["盤の大きさくらべ（左下をそろえて描いたもの）。9×9が今の将棋（駒40枚）、12×12が中将棋（92枚）、15×15が大将棋（130枚）、25×25が泰将棋（354枚）、36×36が大局将棋（804枚）"]}, {"h": "江戸の将棋", "p": ["江戸時代には、幕府から禄をもらう将棋の家元が生まれ、大橋宗桂がその初代とされます。毎年、将軍の前で対局する「御城将棋」も開かれ、のちに11月17日に行う決まりになりました。今の「将棋の日」はこの日にちなんでいます。", "将棋は町の人々の楽しみでもありました。春信の錦絵には、蚊帳のそばで将棋をさす若い男女が描かれています。伊藤看寿の『将棋図巧』（1755年）のように、芸術品のような詰将棋の作品集も生まれました。"], "cap": ["鈴木春信の錦絵（1767〜69年頃）。蚊帳のそばで将棋をさす若い男女"]}], "tl": [["1058年", "興福寺の旧境内の駒（天喜六年の札とともに出土）"], ["11世紀なかば", "『新猿楽記』に将棋の名が出る"], ["鎌倉時代初め", "『二中歴』に平安将棋の駒が書かれる"], ["16世紀ごろ", "持ち駒のルールが生まれたとされる"], ["1612年", "大橋宗桂らが幕府から禄を受けたとされる"], ["1716年", "御城将棋を11月17日に行う決まりになる"], ["1755年", "伊藤看寿『将棋図巧』"], ["1975年", "11月17日が「将棋の日」になる"]]}}, "en": {"shogi": {"kf": ["A chess relative born in India that grew up in Japan, played on a 9×9 board", "The oldest pieces come from the old Kōfukuji precinct, found with a tag dated 1058", "“Pieces in hand” — dropping captured pieces as your own — probably began around the 16th century"], "more": [{"h": "One colour, told apart by direction", "p": ["Chess pieces are painted white and black, but shogi pieces are all the same natural wood. You tell whose they are by which way the point of the five-sided piece faces. That shape is what lets a captured piece simply be turned around and dropped back in.", "Each piece has its name written on it, and on entering the enemy camp it can turn over and “promote”. A pawn becomes the と on its back and moves like a gold general. Flat, lettered pieces rather than carved figures are something shogi shares with its East Asian cousins, Chinese xiangqi and Korean janggi."], "cap": ["Shogi pieces are the same colour for both sides and are told apart by which way the point faces. Right: a pawn turned over, “promoted” (tokin)"]}, {"h": "The age of giant shogi", "p": ["From the Kamakura and Muromachi periods into the Edo period, larger and larger forms of shogi were made, with ever more kinds of pieces. The 12×12 chū shogi was widely played through the Edo period and still has fans today.", "Records go further still: 15×15 dai shogi, 25×25 tai shogi, and taikyoku shogi with 804 pieces on a 36×36 board. Yet the everyday game was the 9×9 shō shogi — which gained pieces in hand and became the shogi we play now."], "cap": ["Board sizes compared, drawn from one corner: 9×9 is modern shogi (40 pieces), 12×12 chū shogi (92), 15×15 dai shogi (130), 25×25 tai shogi (354), 36×36 taikyoku shogi (804)"]}, {"h": "Shogi in Edo", "p": ["In the Edo period, shogi houses were paid stipends by the shogunate; Ōhashi Sōkei is counted as the first master. Each year the best players met before the shogun in the “castle games”, later fixed for 17 November — the origin of today’s Shogi Day.", "Shogi was a pleasure for townspeople too: Harunobu’s print shows a young couple playing beside a mosquito net. Collections of tsume-shogi problems as fine as works of art also appeared, such as Itō Kanju’s Shōgi Zukō (1755)."], "cap": ["A colour woodblock print by Suzuki Harunobu (c. 1767–69): a young woman and man playing shogi beside a mosquito net"]}], "tl": [["1058", "Pieces from the old Kōfukuji precinct (found with a tag dated Tengi 6)"], ["mid-11th c.", "Shogi is named in the Shinsarugakuki"], ["early Kamakura", "The Nichūreki lists the pieces of Heian shogi"], ["c. 16th c.", "Pieces in hand are thought to begin"], ["1612", "Ōhashi Sōkei and others are said to receive stipends from the shogunate"], ["1716", "The castle games are fixed for 17 November"], ["1755", "Itō Kanju’s Shōgi Zukō"], ["1975", "17 November becomes Shogi Day"]]}}, "zh": {"shogi": {"kf": ["源于印度的象棋家族成员在日本成长而成，在9×9棋盘上对弈", "最古老的棋子出土于兴福寺旧址，同时出土了天喜六年（1058）的木签", "把吃掉的棋子当作己方棋子打入的“持驹”，被认为始于16世纪前后"], "more": [{"h": "同色的棋子，靠方向区分", "p": ["国际象棋的棋子分涂黑白两色，将棋的棋子却敌我都是同样的木色，靠五角形尖端朝哪边来区分。吃掉的棋子只要掉转方向就能打回盘上，靠的正是这种形状。", "棋子上写着名字，进入敌阵后可以翻面“升变”。步翻过来是背面的“と”，走法和金将一样。棋子是写字的木片而不是立体的人偶，这一点与中国象棋、朝鲜象棋相同，是东亚象棋家族的特征。"], "cap": ["将棋的棋子双方同色，靠尖端朝向区分。右边是翻面“升变”后的步（成金）"]}, {"h": "大型将棋的时代", "p": ["从镰仓、室町时代到江户时代，人们造出了棋子种类和数量越来越多的大型将棋。12×12的中将棋直到江户时代都很流行，至今仍有爱好者。", "记录里还有15×15的大将棋、25×25的泰将棋，以及在36×36棋盘上摆804枚棋子的大局将棋。不过平常下的是9×9的小将棋，它加上持驹规则，成了今天的将棋。"], "cap": ["棋盘大小比较（左下角对齐）：9×9是现在的将棋（40枚），12×12是中将棋（92枚），15×15是大将棋（130枚），25×25是泰将棋（354枚），36×36是大局将棋（804枚）"]}, {"h": "江户时代的将棋", "p": ["江户时代出现了领取幕府俸禄的将棋世家，大桥宗桂被视为第一代名人。每年在将军面前对局的“御城将棋”后来定在11月17日举行，今天的“将棋日”就由此而来。", "将棋也是市井百姓的乐趣。春信的锦绘画着一对年轻男女在蚊帐旁下棋。还出现了像伊藤看寿《将棋图巧》（1755年）那样宛如艺术品的诘将棋作品集。"], "cap": ["铃木春信的锦绘（约1767–69年）：在蚊帐旁下将棋的年轻男女"]}], "tl": [["1058年", "兴福寺旧址的棋子（与天喜六年木签一同出土）"], ["11世纪中叶", "《新猿乐记》中出现将棋之名"], ["镰仓时代初", "《二中历》记下平安将棋的棋子"], ["约16世纪", "持驹规则被认为由此开始"], ["1612年", "相传大桥宗桂等人开始领取幕府俸禄"], ["1716年", "御城将棋定在11月17日举行"], ["1755年", "伊藤看寿《将棋图巧》"], ["1975年", "11月17日定为“将棋日”"]]}}, "zh-TW": {"shogi": {"kf": ["源於印度的象棋家族成員在日本成長而成，在9×9棋盤上對弈", "最古老的棋子出土於興福寺舊址，同時出土了天喜六年（1058）的木簽", "把吃掉的棋子當作己方棋子打入的「持駒」，被認為始於16世紀前後"], "more": [{"h": "同色的棋子，靠方向區分", "p": ["西洋棋的棋子分塗黑白兩色，將棋的棋子卻敵我都是同樣的木色，靠五角形尖端朝哪邊來區分。吃掉的棋子只要掉轉方向就能打回盤上，靠的正是這種形狀。", "棋子上寫著名字，進入敵陣後可以翻面「升變」。步翻過來是背面的「と」，走法和金將一樣。棋子是寫字的木片而不是立體的人偶，這一點與中國象棋、朝鮮象棋相同，是東亞象棋家族的特徵。"], "cap": ["將棋的棋子雙方同色，靠尖端朝向區分。右邊是翻面「升變」後的步（成金）"]}, {"h": "大型將棋的時代", "p": ["從鎌倉、室町時代到江戶時代，人們造出了棋子種類和數量越來越多的大型將棋。12×12的中將棋直到江戶時代都很流行，至今仍有愛好者。", "記錄裡還有15×15的大將棋、25×25的泰將棋，以及在36×36棋盤上擺804枚棋子的大局將棋。不過平常下的是9×9的小將棋，它加上持駒規則，成了今天的將棋。"], "cap": ["棋盤大小比較（左下角對齊）：9×9是現在的將棋（40枚），12×12是中將棋（92枚），15×15是大將棋（130枚），25×25是泰將棋（354枚），36×36是大局將棋（804枚）"]}, {"h": "江戶時代的將棋", "p": ["江戶時代出現了領取幕府俸祿的將棋世家，大橋宗桂被視為第一代名人。每年在將軍面前對局的「御城將棋」後來定在11月17日舉行，今天的「將棋日」就由此而來。", "將棋也是市井百姓的樂趣。春信的錦繪畫著一對年輕男女在蚊帳旁下棋。還出現了像伊藤看壽《將棋圖巧》（1755年）那樣宛如藝術品的詰將棋作品集。"], "cap": ["鈴木春信的錦繪（約1767–69年）：在蚊帳旁下將棋的年輕男女"]}], "tl": [["1058年", "興福寺舊址的棋子（與天喜六年木簽一同出土）"], ["11世紀中葉", "《新猿樂記》中出現將棋之名"], ["鎌倉時代初", "《二中歷》記下平安將棋的棋子"], ["約16世紀", "持駒規則被認為由此開始"], ["1612年", "相傳大橋宗桂等人開始領取幕府俸祿"], ["1716年", "御城將棋定在11月17日舉行"], ["1755年", "伊藤看壽《將棋圖巧》"], ["1975年", "11月17日定為「將棋日」"]]}}, "ko": {"shogi": {"kf": ["인도에서 태어난 체스의 친척이 일본에서 자라난, 9×9 판의 게임", "가장 오래된 말은 덴키 6년(1058)의 패와 함께 고후쿠지 옛 경내에서 나왔다", "잡은 말을 자기 말로 놓을 수 있는 ‘지고마’는 16세기 무렵 생겼다고 여겨진다"], "more": [{"h": "같은 색의 말, 방향으로 구별", "p": ["체스 말은 흰색과 검은색으로 칠해져 있지만, 쇼기 말은 적과 아군 모두 같은 나무 색이고, 오각형의 뾰족한 끝이 어느 쪽을 향하는지로 구별합니다. 잡은 말을 방향만 바꿔 다시 놓을 수 있는 것은 이 모양 덕분입니다.", "말에는 이름이 적혀 있고, 적진에 들어가면 뒤집어 ‘승격’할 수 있습니다. 보는 뒷면의 ‘と’가 되어 금장과 같이 움직입니다. 말이 입체 인형이 아니라 글자를 쓴 판인 것은 중국의 샹치, 한국의 장기와 같은 동아시아 장기 가족의 특징입니다."], "cap": ["쇼기 말은 양쪽 모두 같은 색. 뾰족한 끝의 방향으로 구별한다. 오른쪽은 뒤집어 ‘승격’한 보(도킨)"]}, {"h": "큰 쇼기의 시대", "p": ["가마쿠라·무로마치 시대부터 에도 시대에 걸쳐, 말의 종류와 수를 계속 늘린 큰 쇼기가 만들어졌습니다. 12×12의 주쇼기는 에도 시대까지 널리 즐겼고, 지금도 애호가가 있습니다.", "기록에는 15×15의 다이쇼기, 25×25의 타이쇼기, 그리고 36×36 판에 804개의 말을 놓는 다이쿄쿠쇼기까지 남아 있습니다. 하지만 평소에 즐긴 것은 9×9의 쇼쇼기였고, 지고마 규칙을 얻어 지금의 쇼기가 되었습니다."], "cap": ["판 크기 비교(왼쪽 아래를 맞춰 그림). 9×9가 지금의 쇼기(말 40개), 12×12가 주쇼기(92개), 15×15가 다이쇼기(130개), 25×25가 타이쇼기(354개), 36×36이 다이쿄쿠쇼기(804개)"]}, {"h": "에도의 쇼기", "p": ["에도 시대에는 막부에서 녹봉을 받는 쇼기 가문이 생겼고, 오하시 소케이가 그 초대로 꼽힙니다. 해마다 쇼군 앞에서 두는 ‘오시로 쇼기’는 뒷날 11월 17일에 열기로 정해졌고, 지금의 ‘쇼기의 날’은 이 날에서 왔습니다.", "쇼기는 서민의 즐거움이기도 했습니다. 하루노부의 판화에는 모기장 옆에서 쇼기를 두는 젊은 남녀가 그려져 있습니다. 이토 간주의 『쇼기 즈코』(1755년)처럼 예술품 같은 박보 쇼기 작품집도 나왔습니다."], "cap": ["스즈키 하루노부의 니시키에(1767~69년경). 모기장 옆에서 쇼기를 두는 젊은 남녀"]}], "tl": [["1058년", "고후쿠지 옛 경내의 말(덴키 6년의 패와 함께 출토)"], ["11세기 중엽", "『신사루가쿠키』에 쇼기의 이름이 나옴"], ["가마쿠라 시대 초", "『니추레키』에 헤이안 쇼기의 말이 적힘"], ["16세기 무렵", "지고마 규칙이 생긴 것으로 여겨짐"], ["1612년", "오하시 소케이 등이 막부에서 녹봉을 받았다고 전해짐"], ["1716년", "오시로 쇼기를 11월 17일에 열기로 정함"], ["1755년", "이토 간주 『쇼기 즈코』"], ["1975년", "11월 17일이 ‘쇼기의 날’이 됨"]]}}, "es": {"shogi": {"kf": ["Un pariente del ajedrez nacido en la India que creció en Japón, en un tablero de 9×9", "Las piezas más antiguas salieron del antiguo recinto de Kōfuku-ji junto a una tablilla fechada en 1058", "Las «piezas en mano» —usar como propias las piezas capturadas— habrían nacido hacia el siglo XVI"], "more": [{"h": "Un solo color, se distinguen por la dirección", "p": ["Las piezas de ajedrez se pintan de blanco y negro, pero las de shogi son todas del mismo color de la madera: se sabe de quién son por hacia dónde apunta la punta de la pieza de cinco lados. Esa forma es la que permite girar una pieza capturada y soltarla de nuevo en el tablero.", "Cada pieza lleva su nombre escrito, y al entrar en el campo enemigo puede darse la vuelta y «promocionar». El peón se convierte en el と de su reverso y se mueve como un general de oro. Que las piezas sean fichas planas con letras y no figuras talladas es algo que el shogi comparte con sus primos de Asia oriental, el xiangqi chino y el janggi coreano."], "cap": ["Las piezas de shogi son del mismo color para ambos bandos y se distinguen por hacia dónde apunta la punta. A la derecha, un peón dado la vuelta: «promocionado» (tokin)"]}, {"h": "La era de los shogi gigantes", "p": ["Desde los periodos Kamakura y Muromachi hasta el periodo Edo se crearon shogi cada vez mayores, con más clases de piezas. El chū shogi de 12×12 se jugó mucho durante todo el periodo Edo y aún tiene aficionados.", "Los registros van más allá: el dai shogi de 15×15, el tai shogi de 25×25 y el taikyoku shogi, con 804 piezas en un tablero de 36×36. Pero el juego cotidiano era el shō shogi de 9×9, que ganó las piezas en mano y se convirtió en el shogi actual."], "cap": ["Tamaños de tablero comparados, dibujados desde una esquina: 9×9 es el shogi actual (40 piezas), 12×12 el chū shogi (92), 15×15 el dai shogi (130), 25×25 el tai shogi (354) y 36×36 el taikyoku shogi (804)"]}, {"h": "El shogi en Edo", "p": ["En el periodo Edo surgieron casas de shogi pagadas por el shogunato; Ōhashi Sōkei se considera el primer maestro. Cada año los mejores jugaban ante el shōgun en las «partidas del castillo», fijadas más tarde para el 17 de noviembre: de ahí viene el actual Día del Shogi.", "El shogi también era un placer del pueblo: la estampa de Harunobu muestra a una pareja joven jugando junto a un mosquitero. Y aparecieron colecciones de problemas de tsume-shogi dignas de obras de arte, como el Shōgi Zukō de Itō Kanju (1755)."], "cap": ["Estampa a color de Suzuki Harunobu (h. 1767–69): una joven y un joven juegan al shogi junto a un mosquitero"]}], "tl": [["1058", "Piezas del antiguo recinto de Kōfuku-ji (halladas con una tablilla del año Tengi 6)"], ["med. s. XI", "El Shinsarugakuki menciona el shogi"], ["inicios de Kamakura", "El Nichūreki enumera las piezas del shogi Heian"], ["h. s. XVI", "Se cree que nacen las piezas en mano"], ["1612", "Ōhashi Sōkei y otros reciben, según se dice, un estipendio del shogunato"], ["1716", "Las partidas del castillo se fijan para el 17 de noviembre"], ["1755", "Shōgi Zukō de Itō Kanju"], ["1975", "El 17 de noviembre pasa a ser el Día del Shogi"]]}}, "fr": {"shogi": {"kf": ["Un cousin des échecs né en Inde et devenu japonais, joué sur un plateau de 9×9", "Les plus anciennes pièces viennent de l’ancien enclos du Kōfuku-ji, trouvées avec une étiquette datée de 1058", "Les « pièces en main » — rejouer pour soi les pièces capturées — seraient apparues vers le XVIe siècle"], "more": [{"h": "Une seule couleur, la direction fait la différence", "p": ["Les pièces d’échecs sont peintes en blanc et en noir, mais celles du shogi ont toutes la couleur du bois : on sait à qui elles appartiennent selon le sens de la pointe de la pièce à cinq côtés. C’est cette forme qui permet de retourner une pièce capturée et de la parachuter sur le plateau.", "Chaque pièce porte son nom, et en entrant dans le camp adverse elle peut se retourner et « se promouvoir ». Le pion devient le と de son revers et se déplace comme un général d’or. Des jetons plats et inscrits plutôt que des figurines sculptées : un trait que le shogi partage avec ses cousins d’Asie orientale, le xiangqi chinois et le janggi coréen."], "cap": ["Les pièces de shogi ont la même couleur dans les deux camps ; on les distingue par le sens de leur pointe. À droite : un pion retourné, « promu » (tokin)"]}, {"h": "L’âge des shogi géants", "p": ["Des époques de Kamakura et de Muromachi jusqu’à celle d’Edo, on inventa des shogi de plus en plus grands, aux pièces toujours plus variées. Le chū shogi de 12×12 fut très joué durant toute l’époque d’Edo et a encore ses amateurs.", "Les textes vont plus loin encore : le dai shogi de 15×15, le tai shogi de 25×25 et le taikyoku shogi, avec 804 pièces sur 36×36 cases. Mais le jeu de tous les jours était le shō shogi de 9×9, qui gagna les pièces en main et devint le shogi d’aujourd’hui."], "cap": ["Tailles de plateau comparées depuis un même coin : 9×9 pour le shogi actuel (40 pièces), 12×12 pour le chū shogi (92), 15×15 pour le dai shogi (130), 25×25 pour le tai shogi (354), 36×36 pour le taikyoku shogi (804)"]}, {"h": "Le shogi à Edo", "p": ["À l’époque d’Edo apparurent des maisons de shogi pensionnées par le shogunat ; Ōhashi Sōkei passe pour le premier maître. Chaque année, les meilleurs jouaient devant le shōgun lors des « parties du château », fixées ensuite au 17 novembre — d’où l’actuelle Journée du shogi.", "Le shogi était aussi un plaisir populaire : l’estampe de Harunobu montre un jeune couple jouant près d’une moustiquaire. On vit aussi paraître des recueils de problèmes de tsume-shogi dignes d’œuvres d’art, comme le Shōgi Zukō d’Itō Kanju (1755)."], "cap": ["Estampe en couleurs de Suzuki Harunobu (vers 1767–69) : une jeune femme et un jeune homme jouent au shogi près d’une moustiquaire"]}], "tl": [["1058", "Pièces de l’ancien enclos du Kōfuku-ji (trouvées avec une étiquette de l’an Tengi 6)"], ["milieu XIe s.", "Le Shinsarugakuki cite le shogi"], ["début de Kamakura", "Le Nichūreki énumère les pièces du shogi de Heian"], ["vers le XVIe s.", "Naissance supposée des pièces en main"], ["1612", "Ōhashi Sōkei et d’autres reçoivent, dit-on, une pension du shogunat"], ["1716", "Les parties du château sont fixées au 17 novembre"], ["1755", "Shōgi Zukō d’Itō Kanju"], ["1975", "Le 17 novembre devient la Journée du shogi"]]}}, "pt": {"shogi": {"kf": ["Um parente do xadrez nascido na Índia que cresceu no Japão, jogado num tabuleiro de 9×9", "As peças mais antigas vêm do antigo recinto do Kōfuku-ji, achadas com uma etiqueta datada de 1058", "As «peças na mão» — usar como suas as peças capturadas — teriam surgido por volta do século XVI"], "more": [{"h": "Uma só cor, distinguidas pela direção", "p": ["As peças de xadrez são pintadas de branco e preto, mas as de shogi têm todas a cor da madeira: sabe-se de quem são pela direção da ponta da peça de cinco lados. É essa forma que permite virar uma peça capturada e soltá-la de novo no tabuleiro.", "Cada peça traz o nome escrito e, ao entrar no campo inimigo, pode virar e «promover». O peão vira o と do verso e passa a mover-se como um general de ouro. Peças planas com letras em vez de figuras esculpidas: é algo que o shogi compartilha com seus primos do Leste Asiático, o xiangqi chinês e o janggi coreano."], "cap": ["As peças de shogi têm a mesma cor para os dois lados e se distinguem pela direção da ponta. À direita, um peão virado, «promovido» (tokin)"]}, {"h": "A era dos shogi gigantes", "p": ["Dos períodos Kamakura e Muromachi até o período Edo, criaram-se shogi cada vez maiores, com cada vez mais tipos de peças. O chū shogi de 12×12 foi muito jogado durante todo o período Edo e ainda tem fãs.", "Os registros vão além: o dai shogi de 15×15, o tai shogi de 25×25 e o taikyoku shogi, com 804 peças num tabuleiro de 36×36. Mas o jogo do dia a dia era o shō shogi de 9×9, que ganhou as peças na mão e virou o shogi de hoje."], "cap": ["Tamanhos de tabuleiro comparados a partir de um canto: 9×9 é o shogi atual (40 peças), 12×12 o chū shogi (92), 15×15 o dai shogi (130), 25×25 o tai shogi (354) e 36×36 o taikyoku shogi (804)"]}, {"h": "O shogi em Edo", "p": ["No período Edo surgiram casas de shogi pagas pelo xogunato; Ōhashi Sōkei é tido como o primeiro mestre. Todo ano os melhores jogavam diante do xógum nas «partidas do castelo», depois fixadas em 17 de novembro — origem do atual Dia do Shogi.", "O shogi também era diversão do povo: a gravura de Harunobu mostra um jovem casal jogando junto a um mosquiteiro. Surgiram ainda coletâneas de problemas de tsume-shogi dignas de obras de arte, como o Shōgi Zukō de Itō Kanju (1755)."], "cap": ["Xilogravura colorida de Suzuki Harunobu (c. 1767–69): uma jovem e um jovem jogam shogi junto a um mosquiteiro"]}], "tl": [["1058", "Peças do antigo recinto do Kōfuku-ji (achadas com uma etiqueta do ano Tengi 6)"], ["meados do séc. XI", "O Shinsarugakuki cita o shogi"], ["início de Kamakura", "O Nichūreki lista as peças do shogi Heian"], ["c. séc. XVI", "Teriam surgido as peças na mão"], ["1612", "Ōhashi Sōkei e outros recebem, diz-se, um estipêndio do xogunato"], ["1716", "As partidas do castelo são fixadas em 17 de novembro"], ["1755", "Shōgi Zukō, de Itō Kanju"], ["1975", "17 de novembro vira o Dia do Shogi"]]}}, "de": {"shogi": {"kf": ["Ein in Indien geborener Verwandter des Schachs, der in Japan heranwuchs – gespielt auf 9×9 Feldern", "Die ältesten Steine stammen vom alten Gelände des Kōfuku-ji, gefunden mit einem Holztäfelchen von 1058", "Die „Steine in der Hand“ – geschlagene Steine als eigene einsetzen – entstanden wohl um das 16. Jahrhundert"], "more": [{"h": "Eine Farbe, die Richtung entscheidet", "p": ["Schachfiguren sind weiß und schwarz bemalt, Shogi-Steine dagegen haben alle die Farbe des Holzes: Wem ein Stein gehört, zeigt die Richtung der Spitze des fünfeckigen Steins. Genau diese Form erlaubt es, einen geschlagenen Stein einfach umzudrehen und wieder einzusetzen.", "Auf jedem Stein steht sein Name, und im gegnerischen Lager kann er umgedreht und „befördert“ werden. Der Bauer wird zum と auf seiner Rückseite und zieht wie ein Goldgeneral. Flache, beschriftete Steine statt geschnitzter Figuren – das teilt Shogi mit seinen ostasiatischen Verwandten, dem chinesischen Xiangqi und dem koreanischen Janggi."], "cap": ["Shogi-Steine haben für beide Seiten dieselbe Farbe; man unterscheidet sie an der Richtung der Spitze. Rechts: ein umgedrehter, „beförderter“ Bauer (Tokin)"]}, {"h": "Die Zeit der Riesen-Shogi", "p": ["Von der Kamakura- und Muromachi-Zeit bis in die Edo-Zeit entstanden immer größere Shogi-Formen mit immer mehr Steinarten. Das 12×12-Chū-Shogi wurde die ganze Edo-Zeit hindurch viel gespielt und hat bis heute Liebhaber.", "Die Quellen gehen noch weiter: Dai-Shogi auf 15×15, Tai-Shogi auf 25×25 und Taikyoku-Shogi mit 804 Steinen auf 36×36 Feldern. Das Alltagsspiel aber war das Shō-Shogi auf 9×9 – es bekam die Steine in der Hand und wurde zum heutigen Shogi."], "cap": ["Brettgrößen im Vergleich, von einer Ecke aus gezeichnet: 9×9 ist das heutige Shogi (40 Steine), 12×12 Chū-Shogi (92), 15×15 Dai-Shogi (130), 25×25 Tai-Shogi (354), 36×36 Taikyoku-Shogi (804)"]}, {"h": "Shogi in Edo", "p": ["In der Edo-Zeit entstanden vom Shogunat besoldete Shogi-Häuser; Ōhashi Sōkei gilt als erster Meister. Jedes Jahr spielten die Besten vor dem Shōgun die „Burgpartien“, die später auf den 17. November gelegt wurden – daher der heutige Shogi-Tag.", "Shogi war auch ein Vergnügen der Stadtleute: Harunobus Holzschnitt zeigt ein junges Paar beim Spiel neben einem Moskitonetz. Zudem erschienen Sammlungen von Tsume-Shogi-Aufgaben, die wie Kunstwerke wirken, etwa Itō Kanjus Shōgi Zukō (1755)."], "cap": ["Farbholzschnitt von Suzuki Harunobu (um 1767–69): eine junge Frau und ein junger Mann spielen Shogi neben einem Moskitonetz"]}], "tl": [["1058", "Steine vom alten Gelände des Kōfuku-ji (gefunden mit einem Täfelchen aus dem Jahr Tengi 6)"], ["Mitte 11. Jh.", "Das Shinsarugakuki nennt Shogi"], ["frühe Kamakura-Zeit", "Das Nichūreki zählt die Steine des Heian-Shogi auf"], ["um 16. Jh.", "Die Steine in der Hand kommen vermutlich auf"], ["1612", "Ōhashi Sōkei und andere sollen Bezüge vom Shogunat erhalten"], ["1716", "Die Burgpartien werden auf den 17. November gelegt"], ["1755", "Itō Kanjus Shōgi Zukō"], ["1975", "Der 17. November wird zum Shogi-Tag"]]}}, "ru": {"shogi": {"kf": ["Родственник шахмат, родившийся в Индии и выросший в Японии; играют на доске 9×9", "Древнейшие фигуры найдены на старой территории храма Кофукудзи вместе с табличкой 1058 года", "«Фигуры в руке» — ставить взятые фигуры как свои — появились, по-видимому, около XVI века"], "more": [{"h": "Один цвет, различие — в направлении", "p": ["Шахматные фигуры окрашены в белый и чёрный, а фигуры сёги — все цвета дерева: чья фигура, видно по тому, куда направлен острый конец пятиугольной фишки. Именно эта форма позволяет просто развернуть взятую фигуру и снова выставить её на доску.", "На каждой фигуре написано её имя, а в лагере противника её можно перевернуть и «превратить». Пешка становится знаком と на обороте и ходит как золотой генерал. Плоские фишки с надписями вместо резных фигурок — черта, общая у сёги с восточноазиатскими родственниками: китайскими сянци и корейскими чангги."], "cap": ["Фигуры сёги одного цвета у обеих сторон; их различают по тому, куда смотрит острый конец. Справа — перевёрнутая, «превращённая» пешка (токин)"]}, {"h": "Эпоха гигантских сёги", "p": ["С эпох Камакура и Муромати до эпохи Эдо создавались всё более крупные сёги со всё новыми видами фигур. В тю-сёги на доске 12×12 много играли на протяжении всей эпохи Эдо, у них и сегодня есть поклонники.", "Источники идут ещё дальше: дай-сёги 15×15, тай-сёги 25×25 и тайкёку-сёги — 804 фигуры на доске 36×36. Но повседневной игрой оставались сё-сёги 9×9: получив «фигуры в руке», они и стали нынешними сёги."], "cap": ["Размеры досок в сравнении, от одного угла: 9×9 — нынешние сёги (40 фигур), 12×12 — тю-сёги (92), 15×15 — дай-сёги (130), 25×25 — тай-сёги (354), 36×36 — тайкёку-сёги (804)"]}, {"h": "Сёги в эпоху Эдо", "p": ["В эпоху Эдо появились дома сёги на жалованье сёгуната; первым мастером считается Охаси Сокэй. Каждый год лучшие игроки сражались перед сёгуном в «замковых партиях», которые позже приурочили к 17 ноября, — отсюда нынешний День сёги.", "Сёги были и забавой горожан: на гравюре Харунобу юная пара играет у москитной сетки. Появились и сборники задач цумэ-сёги, похожие на произведения искусства, например «Сёги дзуко» Ито Кандзю (1755)."], "cap": ["Цветная гравюра Судзуки Харунобу (около 1767–69): юноша и девушка играют в сёги у москитной сетки"]}], "tl": [["1058", "Фигуры со старой территории Кофукудзи (найдены с табличкой года Тэнги 6)"], ["сер. XI в.", "Сёги упомянуты в «Синсаругаку-ки»"], ["начало Камакуры", "В «Нитюрэки» перечислены фигуры сёги эпохи Хэйан"], ["ок. XVI в.", "Предположительно появляются «фигуры в руке»"], ["1612", "Охаси Сокэй и другие, по преданию, получают жалованье сёгуната"], ["1716", "Замковые партии приурочены к 17 ноября"], ["1755", "«Сёги дзуко» Ито Кандзю"], ["1975", "17 ноября становится Днём сёги"]]}}, "tr": {"shogi": {"kf": ["Hindistan’da doğup Japonya’da gelişen bir satranç akrabası; 9×9 tahtada oynanır", "En eski taşlar, 1058 tarihli bir etiketle birlikte Kōfuku-ji’nin eski alanında bulundu", "Alınan taşları kendi taşı gibi sürmek, yani “eldeki taşlar”, muhtemelen 16. yüzyıl civarında doğdu"], "more": [{"h": "Tek renk, yönle ayırt etme", "p": ["Satranç taşları beyaz ve siyaha boyanır, ama shogi taşlarının hepsi ahşap rengindedir: taşın kime ait olduğu, beşgen taşın sivri ucunun hangi yöne baktığından anlaşılır. Alınan bir taşı çevirip yeniden tahtaya sürmeyi mümkün kılan da bu biçimdir.", "Her taşın üzerinde adı yazılıdır ve rakip bölgeye girince ters çevrilip “terfi” edebilir. Piyon arka yüzündeki と olur ve altın general gibi hareket eder. Oyma figürler yerine yazılı yassı taşlar kullanmak, shogi’nin Doğu Asya’daki akrabaları Çin xiangqi’si ve Kore janggi’siyle ortak özelliğidir."], "cap": ["Shogi taşları iki taraf için de aynı renktedir; sivri ucun yönüyle ayırt edilir. Sağda: ters çevrilip “terfi etmiş” piyon (tokin)"]}, {"h": "Dev shogilerin çağı", "p": ["Kamakura ve Muromachi dönemlerinden Edo dönemine kadar, taş türleri ve sayısı giderek artan büyük shogiler yapıldı. 12×12’lik chū shogi Edo dönemi boyunca çok oynandı ve bugün de meraklıları var.", "Kayıtlar daha da ileri gider: 15×15 dai shogi, 25×25 tai shogi ve 36×36 tahtada 804 taşlı taikyoku shogi. Ama gündelik oyun 9×9’luk shō shogi idi; eldeki taşları kazanarak bugünkü shogi oldu."], "cap": ["Tahta boyutlarının karşılaştırması (tek köşeden çizildi): 9×9 bugünkü shogi (40 taş), 12×12 chū shogi (92), 15×15 dai shogi (130), 25×25 tai shogi (354), 36×36 taikyoku shogi (804)"]}, {"h": "Edo’da shogi", "p": ["Edo döneminde şogunluktan maaş alan shogi aileleri ortaya çıktı; Ōhashi Sōkei ilk usta sayılır. Her yıl en iyiler şogunun önünde “kale oyunları”nda karşılaştı; bunlar sonradan 17 Kasım’a sabitlendi — bugünkü Shogi Günü buradan gelir.", "Shogi halkın da eğlencesiydi: Harunobu’nun baskısında cibinliğin yanında oynayan genç bir çift görülür. Itō Kanju’nun Shōgi Zukō’su (1755) gibi sanat eseri değerinde tsume-shogi problem kitapları da çıktı."], "cap": ["Suzuki Harunobu’nun renkli baskısı (y. 1767–69): cibinliğin yanında shogi oynayan genç bir kadın ve erkek"]}], "tl": [["1058", "Kōfuku-ji’nin eski alanından taşlar (Tengi 6 yılı etiketiyle bulundu)"], ["11. yy ortası", "Shinsarugakuki shogi’den söz eder"], ["Kamakura başı", "Nichūreki, Heian shogisinin taşlarını sayar"], ["y. 16. yy", "Eldeki taşlar kuralının doğduğu düşünülür"], ["1612", "Ōhashi Sōkei ve diğerlerinin şogunluktan maaş aldığı anlatılır"], ["1716", "Kale oyunları 17 Kasım’a sabitlenir"], ["1755", "Itō Kanju’nun Shōgi Zukō’su"], ["1975", "17 Kasım Shogi Günü olur"]]}}, "id": {"shogi": {"kf": ["Kerabat catur yang lahir di India lalu tumbuh di Jepang, dimainkan di papan 9×9", "Bidak tertua berasal dari bekas lahan Kōfuku-ji, ditemukan bersama label bertanggal 1058", "“Bidak di tangan” — memakai bidak tangkapan sebagai milik sendiri — diduga lahir sekitar abad ke-16"], "more": [{"h": "Satu warna, dibedakan oleh arah", "p": ["Bidak catur dicat putih dan hitam, tetapi bidak shogi semuanya berwarna kayu: pemiliknya terlihat dari arah ujung bidak bersisi lima itu. Bentuk inilah yang memungkinkan bidak tangkapan cukup diputar lalu diturunkan lagi ke papan.", "Setiap bidak bertuliskan namanya, dan saat masuk wilayah lawan ia boleh dibalik untuk “promosi”. Pion menjadi と di sisi belakangnya dan bergerak seperti jenderal emas. Bidak pipih bertulisan, bukan patung ukir, adalah ciri yang sama dengan kerabatnya di Asia Timur: xiangqi Tiongkok dan janggi Korea."], "cap": ["Bidak shogi berwarna sama untuk kedua pihak dan dibedakan dari arah ujungnya. Kanan: pion yang dibalik, “dipromosikan” (tokin)"]}, {"h": "Zaman shogi raksasa", "p": ["Dari zaman Kamakura dan Muromachi hingga zaman Edo, dibuat shogi yang makin besar dengan jenis bidak yang makin banyak. Chū shogi 12×12 banyak dimainkan sepanjang zaman Edo dan masih punya penggemar.", "Catatan bahkan menyebut dai shogi 15×15, tai shogi 25×25, dan taikyoku shogi dengan 804 bidak di papan 36×36. Namun permainan sehari-hari adalah shō shogi 9×9, yang kemudian mendapat aturan bidak di tangan dan menjadi shogi masa kini."], "cap": ["Perbandingan ukuran papan, digambar dari satu sudut: 9×9 shogi masa kini (40 bidak), 12×12 chū shogi (92), 15×15 dai shogi (130), 25×25 tai shogi (354), 36×36 taikyoku shogi (804)"]}, {"h": "Shogi di zaman Edo", "p": ["Pada zaman Edo muncul keluarga shogi yang digaji keshogunan; Ōhashi Sōkei dianggap sebagai master pertama. Setiap tahun para pemain terbaik bertanding di depan shogun dalam “pertandingan istana”, yang kemudian ditetapkan tanggal 17 November — asal Hari Shogi sekarang.", "Shogi juga hiburan rakyat: cetakan Harunobu menggambarkan pasangan muda bermain di dekat kelambu. Lahir pula kumpulan soal tsume-shogi seindah karya seni, seperti Shōgi Zukō karya Itō Kanju (1755)."], "cap": ["Cetakan kayu berwarna karya Suzuki Harunobu (sekitar 1767–69): seorang pemuda dan pemudi bermain shogi di dekat kelambu"]}], "tl": [["1058", "Bidak dari bekas lahan Kōfuku-ji (ditemukan bersama label tahun Tengi 6)"], ["Pertengahan abad ke-11", "Shinsarugakuki menyebut shogi"], ["Awal Kamakura", "Nichūreki mencatat bidak shogi Heian"], ["Sekitar abad ke-16", "Aturan bidak di tangan diduga lahir"], ["1612", "Ōhashi Sōkei dkk. konon menerima gaji dari keshogunan"], ["1716", "Pertandingan istana ditetapkan pada 17 November"], ["1755", "Shōgi Zukō karya Itō Kanju"], ["1975", "17 November menjadi Hari Shogi"]]}}, "hi": {"shogi": {"kf": ["भारत में जन्मे शतरंज का एक रिश्तेदार, जो जापान में पला-बढ़ा; 9×9 की बिसात पर खेला जाता है", "सबसे पुराने मोहरे कोफ़ुकु‑जी के पुराने परिसर से 1058 की तारीख़ वाली पट्टी के साथ मिले", "पकड़े गए मोहरों को अपने मोहरे की तरह रखना — “हाथ के मोहरे” — शायद 16वीं सदी के आसपास शुरू हुआ"], "more": [{"h": "एक ही रंग, दिशा से पहचान", "p": ["शतरंज के मोहरे सफ़ेद और काले रंगे होते हैं, पर शोगी के सभी मोहरे लकड़ी के रंग के हैं: पाँच कोनों वाले मोहरे का नुकीला सिरा किस ओर है, इसी से पता चलता है कि वह किसका है। यही आकार पकड़े गए मोहरे को बस घुमाकर फिर बिसात पर रखने देता है।", "हर मोहरे पर उसका नाम लिखा होता है, और दुश्मन के इलाक़े में पहुँचकर वह पलटकर “पदोन्नत” हो सकता है। प्यादा पीछे लिखा と बन जाता है और सोने के सेनापति जैसा चलता है। तराशी हुई आकृतियों की जगह लिखे हुए चपटे मोहरे — यह बात शोगी में उसके पूर्वी एशियाई रिश्तेदारों, चीनी शियांगची और कोरियाई जांगी, जैसी ही है।"], "cap": ["शोगी के मोहरे दोनों पक्षों के लिए एक ही रंग के होते हैं; नुकीले सिरे की दिशा से पहचाने जाते हैं। दाईं ओर: पलटकर “पदोन्नत” प्यादा (तोकिन)"]}, {"h": "विशाल शोगी का दौर", "p": ["कामाकुरा और मुरोमाची काल से एदो काल तक, मोहरों की क़िस्में और गिनती बढ़ाते हुए बड़ी-बड़ी शोगी बनाई गईं। 12×12 की चू शोगी पूरे एदो काल में ख़ूब खेली गई और आज भी इसके शौक़ीन हैं।", "अभिलेख इससे भी आगे जाते हैं: 15×15 की दाई शोगी, 25×25 की ताई शोगी, और 36×36 की बिसात पर 804 मोहरों वाली ताइक्योकु शोगी। फिर भी रोज़ का खेल 9×9 की शो शोगी थी, जिसने हाथ के मोहरों का नियम पाकर आज की शोगी का रूप लिया।"], "cap": ["बिसातों के आकार की तुलना (एक कोने से): 9×9 आज की शोगी (40 मोहरे), 12×12 चू शोगी (92), 15×15 दाई शोगी (130), 25×25 ताई शोगी (354), 36×36 ताइक्योकु शोगी (804)"]}, {"h": "एदो की शोगी", "p": ["एदो काल में शोगुनशाही से वेतन पाने वाले शोगी घराने बने; ओहाशी सोकेई को पहला उस्ताद माना जाता है। हर साल सर्वश्रेष्ठ खिलाड़ी शोगुन के सामने “क़िले के मुक़ाबलों” में खेलते थे, जिन्हें बाद में 17 नवंबर को तय किया गया — आज का शोगी दिवस यहीं से आया।", "शोगी आम लोगों का भी मनोरंजन था: हारुनोबु के छापे में एक युवा जोड़ा मच्छरदानी के पास खेल रहा है। कलाकृति जैसे त्सुमे-शोगी पहेली-संग्रह भी बने, जैसे इतो कान्जू का ‘शोगी ज़ुको’ (1755)।"], "cap": ["सुज़ुकी हारुनोबु का रंगीन काष्ठ-छापा (लगभग 1767–69): मच्छरदानी के पास शोगी खेलते एक युवती और युवक"]}], "tl": [["1058", "कोफ़ुकु‑जी के पुराने परिसर के मोहरे (तेंगी 6 वर्ष की पट्टी के साथ मिले)"], ["11वीं सदी का मध्य", "‘शिनसारुगाकुकी’ में शोगी का नाम"], ["कामाकुरा का आरंभ", "‘निचूरेकी’ में हेइआन शोगी के मोहरे दर्ज"], ["लगभग 16वीं सदी", "हाथ के मोहरों का नियम शुरू हुआ माना जाता है"], ["1612", "कहा जाता है कि ओहाशी सोकेई आदि को शोगुनशाही से वेतन मिला"], ["1716", "क़िले के मुक़ाबले 17 नवंबर को तय हुए"], ["1755", "इतो कान्जू की ‘शोगी ज़ुको’"], ["1975", "17 नवंबर शोगी दिवस बना"]]}}, "ar": {"shogi": {"kf": ["قريب للشطرنج وُلد في الهند ونشأ في اليابان، ويُلعب على رقعة 9×9", "أقدم القطع جاءت من الحرم القديم لمعبد كوفوكو-جي، ووُجدت مع بطاقة مؤرخة بعام 1058", "«القطع في اليد» — استعمال القطع المأسورة كأنها لك — نشأت على الأرجح نحو القرن السادس عشر"], "more": [{"h": "لون واحد، والاتجاه هو الفارق", "p": ["تُطلى قطع الشطرنج بالأبيض والأسود، أما قطع الشوغي فكلها بلون الخشب، ويُعرف صاحب القطعة من اتجاه رأس القطعة الخماسية. وهذا الشكل هو ما يتيح تدوير القطعة المأسورة وإنزالها على الرقعة من جديد.", "يُكتب على كل قطعة اسمها، وإذا دخلت معسكر الخصم جاز قلبها «لترقيتها». فيصير البيدق الحرفَ と المكتوب على ظهره ويتحرك كالقائد الذهبي. وكون القطع ألواحًا مسطحة مكتوبة لا تماثيل منحوتة سمةٌ يتشارك فيها الشوغي مع أقاربه في شرق آسيا: الشيانغتشي الصيني والجانغي الكوري."], "cap": ["قطع الشوغي بلون واحد للطرفين، وتُميَّز باتجاه رأسها المدبب. على اليمين: بيدق مقلوب «مُرقّى» (توكين)"]}, {"h": "عصر الشوغي العملاق", "p": ["من عصري كاماكورا وموروماتشي حتى عصر إيدو، صُنعت أشكال من الشوغي تكبر شيئًا فشيئًا وتزداد أنواع قطعها. وقد لُعب تشو شوغي ذو الرقعة 12×12 كثيرًا طوال عصر إيدو، وما زال له محبون.", "وتذهب السجلات أبعد: داي شوغي 15×15، وتاي شوغي 25×25، وتايكيوكو شوغي بـ804 قطع على رقعة 36×36. لكن اللعبة اليومية كانت شو شوغي 9×9، التي اكتسبت قاعدة القطع في اليد فصارت الشوغي الذي نعرفه."], "cap": ["مقارنة أحجام الرقاع مرسومة من زاوية واحدة: 9×9 الشوغي الحالي (40 قطعة)، 12×12 تشو شوغي (92)، 15×15 داي شوغي (130)، 25×25 تاي شوغي (354)، 36×36 تايكيوكو شوغي (804)"]}, {"h": "الشوغي في إيدو", "p": ["في عصر إيدو نشأت بيوت للشوغي تتقاضى رواتب من الشوغونية، ويُعدّ أوهاشي سوكيي أول أساتذتها. وكل عام كان الأفضل يلعبون أمام الشوغون في «مباريات القلعة»، التي ثُبّتت لاحقًا في 17 نوفمبر، ومنها جاء «يوم الشوغي» الحالي.", "وكان الشوغي متعة لعامة الناس أيضًا: ففي طبعة هارونوبو زوجان شابان يلعبان بجوار ناموسية. وظهرت كذلك مجموعات من مسائل تسوميه-شوغي كأنها أعمال فنية، مثل «شوغي زوكو» لإيتو كانجو (1755)."], "cap": ["طبعة خشبية ملونة لسوزوكي هارونوبو (نحو 1767–69): فتاة وفتى يلعبان الشوغي بجوار ناموسية"]}], "tl": [["1058", "قطع من الحرم القديم لكوفوكو-جي (وُجدت مع بطاقة من سنة تنغي 6)"], ["منتصف القرن 11", "ذكر الشوغي في «شينساروغاكوكي»"], ["أوائل كاماكورا", "«نيتشوريكي» يعدّد قطع شوغي هييان"], ["نحو القرن 16", "يُعتقد أن قاعدة القطع في اليد نشأت"], ["1612", "يُروى أن أوهاشي سوكيي وآخرين تلقوا رواتب من الشوغونية"], ["1716", "تثبيت مباريات القلعة في 17 نوفمبر"], ["1755", "«شوغي زوكو» لإيتو كانجو"], ["1975", "17 نوفمبر يصبح يوم الشوغي"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (18): story 11 (pachisi) made fuller */
(T => { const D = {"ja": {"pachisi": {"kf": ["インドの十字形の盤で、4人が2人ずつ組んで駒を一周させる競走ゲーム", "名前は「25」の意味。子安貝を投げて出る、いちばん大きな数から", "19世紀に海を渡り、パーチージ、ルドーなど名前を変えて世界中に広まった"], "more": [{"h": "十字の盤と道すじ", "p": ["パチーシの盤は、中央の「チャルコーニ」から4本の腕がのびる十字形です。腕は3列×8マスで、マスは全部で96。盤は布に刺繍して作ることが多く、使わないときは丸めてしまっておけました。", "駒は中央から出て、自分の腕のまん中の列を下り、盤のまわりを反時計回りにひとめぐりして、またまん中の列を上って中央に帰ります。向かい合う2人が味方になり、2人とも4つの駒をすべて帰らせたら勝ちです。"], "cap": ["十字形の盤（腕は3列×8マス）。青い線は1人の駒の道すじ：自分の腕のまん中を下り、反時計回りに一周して、まん中を上って中央へ戻る"]}, {"h": "子安貝の数え方", "p": ["パチーシでは6つの子安貝を投げ、口が上を向いた数で進む数を決めます。2〜6個ならその数だけ進みますが、1個なら10、ひとつも上を向かなければ25進めます。", "25は64回に1回しか出ない、いちばんまれで大きな数で、これがゲームの名前になりました。6・10・25が出ると、もう一度投げられます。一方チャウパルでは、1・2・5・6の目が刻まれた細長い棒のさいころを3本振って遊びます。"], "cap": ["6つの子安貝のうち、口が上を向いた数（上の段）と、そのときに進める数（下の段）。棒の高さは、どの貝も表と裏が同じくらいの確率で出るとしたときの出やすさ"]}, {"h": "名前を変えて世界へ", "p": ["インドに住んだイギリス人を通じて、このゲームは19世紀に欧米へ渡りました。アメリカでは「パーチージ」として商標になり、イギリスでは1896年に「ルドー」が特許を取ります。子安貝の代わりに立方体のさいころ1つを使う、簡単なルールになりました。", "ドイツでは1914年に「メンシュ・エルゲレ・ディッヒ・ニヒト（怒らないで）」が売り出され、スペインでは「パルチス」として親しまれています。国ごとに名前やルールが少しずつ違っても、十字の盤を一周して家に帰るという骨組みは変わりません。"], "cap": []}], "tl": [["16世紀", "アクバル帝のファテープル・シークリーに、十字形の盤の中庭が作られる"], ["17〜18世紀", "インドの細密画に、チャウパルを囲む人々がたびたび描かれる"], ["1694〜95年", "デーヴィーダーサがチャウパルを打つシヴァとパールヴァティーを描く"], ["1874年", "アメリカで「パーチージ」が商標になる"], ["1896年", "イギリスで「ルドー」が特許を取る"], ["1914年", "ドイツで「メンシュ・エルゲレ・ディッヒ・ニヒト」が発売"]]}}, "en": {"pachisi": {"kf": ["A race game on a cross-shaped Indian board, four players in two teams bringing their pieces round", "The name means “25” — the biggest throw of the cowrie shells", "In the 19th century it travelled abroad and spread worldwide as Parcheesi, Ludo and more"], "more": [{"h": "The cross and the road", "p": ["A pachisi board is a cross with four arms reaching out from the central charkoni. Each arm is 3 × 8 squares, 96 squares in all. Boards were often embroidered on cloth, so they could be rolled up and put away.", "Pieces leave the centre, go down the middle column of their own arm, travel once round the board anticlockwise, and come back up the middle column to the centre. Players sitting opposite are partners, and a team wins when both have brought all four pieces home."], "cap": ["A cross-shaped board (each arm 3 × 8 squares). The blue line is one player’s road: down the middle of their own arm, anticlockwise all the way round, and back up the middle to the centre"]}, {"h": "Counting cowries", "p": ["In pachisi six cowrie shells are thrown, and the number landing mouth up decides the move. Two to six up move that many squares; but one up moves 10, and none up moves 25.", "At 1 in 64, 25 is the rarest and biggest throw — and it gave the game its name. A 6, 10 or 25 earns another throw. Chaupar instead uses three long stick dice marked 1, 2, 5 and 6."], "cap": ["Of six cowries, how many land mouth up (top row) and how far that moves you (bottom row). Bar heights show how often each happens if every shell falls either way equally"]}, {"h": "New names, new countries", "p": ["Through the British in India, the game reached Europe and America in the 19th century. In the US it became the trademark Parcheesi; in Britain Ludo was patented in 1896, with simpler rules and a single cube die in place of the cowries.", "Germany got Mensch ärgere dich nicht (“Don’t get annoyed”) in 1914, and Spain plays parchís. Names and details differ from country to country, but the frame is the same: round the cross and home again."], "cap": []}], "tl": [["16th c.", "A courtyard with a giant cross board is laid out at Akbar’s Fatehpur Sikri"], ["17th–18th c.", "Indian miniatures often show people gathered around chaupar"], ["1694–95", "Devidasa paints Shiva and Parvati playing chaupar"], ["1874", "Parcheesi becomes a trademark in the US"], ["1896", "Ludo is patented in Britain"], ["1914", "Mensch ärgere dich nicht goes on sale in Germany"]]}}, "zh": {"pachisi": {"kf": ["在印度十字形棋盘上，四人两两结队、让棋子绕行一周的竞速游戏", "名字意为“25”，来自掷宝贝壳时最大的点数", "19世纪漂洋过海，以帕奇西（Parcheesi）、鲁多等名字传遍世界"], "more": [{"h": "十字棋盘与路线", "p": ["帕奇西的棋盘是从中央“查尔科尼”伸出四条臂的十字形。每条臂3列×8格，共96格。棋盘多是绣在布上的，不用时可以卷起来收好。", "棋子从中央出发，沿自己那条臂的中列走下去，绕棋盘逆时针走一圈，再沿中列回到中央。对面的两人是同伴，两人的四枚棋子全部回家就获胜。"], "cap": ["十字形棋盘（每条臂3列×8格）。蓝线是一名玩家的棋子路线：沿自己臂的中列走下去，逆时针绕一圈，再沿中列回到中央"]}, {"h": "宝贝壳的算法", "p": ["帕奇西掷六枚宝贝壳，以开口朝上的个数决定步数。2到6枚朝上就走相应的步数；只有1枚朝上走10步，一枚都不朝上走25步。", "25每64次才出现1次，是最罕见也最大的点数，游戏也因此得名。掷出6、10、25可以再掷一次。乔帕尔则是掷三根刻着1、2、5、6的长条骰子。"], "cap": ["六枚宝贝壳中开口朝上的个数（上排）和可走的步数（下排）。柱高表示假设每枚贝壳正反面出现机会相同时的出现频率"]}, {"h": "换个名字走向世界", "p": ["经由住在印度的英国人，这种游戏在19世纪传到欧美。在美国成为“帕奇西”（Parcheesi）商标，在英国“鲁多”于1896年取得专利，规则变简单，用一颗正方体骰子代替宝贝壳。", "德国在1914年推出“别生气”（Mensch ärgere dich nicht），西班牙则流行“帕尔奇斯”（parchís）。各国的名字和细节虽有不同，绕十字棋盘一周回家的骨架始终不变。"], "cap": []}], "tl": [["16世纪", "阿克巴的法塔赫布尔西格里建起画着巨大十字棋盘的庭院"], ["17–18世纪", "印度细密画中常画围着乔帕尔的人们"], ["1694–95年", "德维达萨画下下乔帕尔的湿婆与帕尔瓦蒂"], ["1874年", "“帕奇西”在美国注册商标"], ["1896年", "“鲁多”在英国取得专利"], ["1914年", "“别生气”在德国发售"]]}}, "zh-TW": {"pachisi": {"kf": ["在印度十字形棋盤上，四人兩兩結隊、讓棋子繞行一周的競速遊戲", "名字意為「25」，來自擲寶貝殼時最大的點數", "19世紀漂洋過海，以帕奇西（Parcheesi）、魯多等名字傳遍世界"], "more": [{"h": "十字棋盤與路線", "p": ["帕奇西的棋盤是從中央「查爾科尼」伸出四條臂的十字形。每條臂3列×8格，共96格。棋盤多是繡在布上的，不用時可以捲起來收好。", "棋子從中央出發，沿自己那條臂的中列走下去，繞棋盤逆時針走一圈，再沿中列回到中央。對面的兩人是同伴，兩人的四枚棋子全部回家就獲勝。"], "cap": ["十字形棋盤（每條臂3列×8格）。藍線是一名玩家的棋子路線：沿自己臂的中列走下去，逆時針繞一圈，再沿中列回到中央"]}, {"h": "寶貝殼的算法", "p": ["帕奇西擲六枚寶貝殼，以開口朝上的個數決定步數。2到6枚朝上就走相應的步數；只有1枚朝上走10步，一枚都不朝上走25步。", "25每64次才出現1次，是最罕見也最大的點數，遊戲也因此得名。擲出6、10、25可以再擲一次。喬帕爾則是擲三根刻著1、2、5、6的長條骰子。"], "cap": ["六枚寶貝殼中開口朝上的個數（上排）和可走的步數（下排）。柱高表示假設每枚貝殼正反面出現機會相同時的出現頻率"]}, {"h": "換個名字走向世界", "p": ["經由住在印度的英國人，這種遊戲在19世紀傳到歐美。在美國成為「帕奇西」（Parcheesi）商標，在英國「魯多」於1896年取得專利，規則變簡單，用一顆正方體骰子代替寶貝殼。", "德國在1914年推出「別生氣」（Mensch ärgere dich nicht），西班牙則流行「帕爾奇斯」（parchís）。各國的名字和細節雖有不同，繞十字棋盤一周回家的骨架始終不變。"], "cap": []}], "tl": [["16世紀", "阿克巴的法塔赫布爾西格里建起畫著巨大十字棋盤的庭院"], ["17–18世紀", "印度細密畫中常畫圍著喬帕爾的人們"], ["1694–95年", "德維達薩畫下下喬帕爾的濕婆與帕爾瓦蒂"], ["1874年", "「帕奇西」在美國註冊商標"], ["1896年", "「魯多」在英國取得專利"], ["1914年", "「別生氣」在德國發售"]]}}, "ko": {"pachisi": {"kf": ["인도의 십자 모양 판에서 네 사람이 둘씩 편을 짜 말을 한 바퀴 돌리는 경주 게임", "이름은 ‘25’라는 뜻. 개오지 조개를 던져 나오는 가장 큰 수에서 왔다", "19세기에 바다를 건너 파치지, 루도 등 이름을 바꿔 세계로 퍼졌다"], "more": [{"h": "십자 판과 길", "p": ["파치시 판은 가운데의 ‘차르코니’에서 팔 네 개가 뻗은 십자 모양입니다. 팔은 3줄×8칸으로, 칸은 모두 96개입니다. 판은 천에 수를 놓아 만드는 일이 많아, 쓰지 않을 때는 둘둘 말아 둘 수 있었습니다.", "말은 중앙에서 나와 자기 팔의 가운데 줄을 내려가고, 판 둘레를 시계 반대 방향으로 한 바퀴 돈 뒤, 다시 가운데 줄을 올라 중앙으로 돌아옵니다. 마주 앉은 두 사람이 한편이며, 둘 다 말 네 개를 모두 돌려보내면 이깁니다."], "cap": ["십자 모양 판(팔마다 3줄×8칸). 파란 선은 한 사람의 말이 가는 길: 자기 팔의 가운데 줄을 내려가 시계 반대 방향으로 한 바퀴 돌고, 가운데 줄을 올라 중앙으로 돌아온다"]}, {"h": "개오지 조개 세는 법", "p": ["파치시에서는 개오지 조개 6개를 던져, 입이 위를 향한 개수로 나아갈 칸 수를 정합니다. 2~6개면 그 수만큼 가지만, 1개면 10칸, 하나도 위를 향하지 않으면 25칸을 갑니다.", "25는 64번에 1번밖에 나오지 않는 가장 드물고 큰 수로, 이것이 게임의 이름이 되었습니다. 6·10·25가 나오면 한 번 더 던집니다. 한편 차우파르는 1·2·5·6이 새겨진 길쭉한 막대 주사위 3개를 굴려 놉니다."], "cap": ["조개 6개 중 입이 위를 향한 개수(윗줄)와 그때 나아가는 칸 수(아랫줄). 막대 높이는 조개마다 앞뒤가 같은 확률로 나온다고 할 때의 나오기 쉬움"]}, {"h": "이름을 바꿔 세계로", "p": ["인도에 살던 영국인을 통해 이 게임은 19세기에 유럽과 미국으로 건너갔습니다. 미국에서는 ‘파치지’라는 상표가 되었고, 영국에서는 1896년에 ‘루도’가 특허를 받았습니다. 조개 대신 정육면체 주사위 하나를 쓰는 간단한 규칙이 되었습니다.", "독일에서는 1914년에 ‘멘슈 에르게레 디히 니히트(화내지 마)’가 나왔고, 스페인에서는 ‘파르치스’로 사랑받습니다. 나라마다 이름과 규칙이 조금씩 달라도, 십자 판을 한 바퀴 돌아 집으로 돌아온다는 뼈대는 그대로입니다."], "cap": []}], "tl": [["16세기", "아크바르의 파테푸르 시크리에 십자 판이 그려진 안뜰이 만들어짐"], ["17~18세기", "인도 세밀화에 차우파르를 둘러싼 사람들이 자주 그려짐"], ["1694~95년", "데비다사가 차우파르를 두는 시바와 파르바티를 그림"], ["1874년", "미국에서 ‘파치지’가 상표가 됨"], ["1896년", "영국에서 ‘루도’가 특허를 받음"], ["1914년", "독일에서 ‘멘슈 에르게레 디히 니히트’ 발매"]]}}, "es": {"pachisi": {"kf": ["Un juego de carreras en un tablero indio en forma de cruz: cuatro jugadores, en dos equipos, dan la vuelta con sus fichas", "El nombre significa «25», la tirada más alta de las conchas de cauri", "En el siglo XIX cruzó los mares y se extendió por el mundo como Parcheesi, ludo y otros"], "more": [{"h": "La cruz y el camino", "p": ["El tablero del pachisi es una cruz con cuatro brazos que salen del charkoni central. Cada brazo tiene 3 × 8 casillas, 96 en total. Los tableros solían bordarse en tela, así que podían enrollarse y guardarse.", "Las fichas salen del centro, bajan por la columna central de su propio brazo, recorren el tablero una vez en sentido antihorario y vuelven a subir por la columna central. Los jugadores sentados frente a frente son compañeros, y un equipo gana cuando ambos han llevado a casa sus cuatro fichas."], "cap": ["Un tablero en cruz (cada brazo de 3 × 8 casillas). La línea azul es el camino de un jugador: baja por el centro de su brazo, da la vuelta completa en sentido antihorario y vuelve a subir por el centro"]}, {"h": "Contar los cauris", "p": ["En el pachisi se lanzan seis conchas de cauri, y el número que cae boca arriba decide el avance. De dos a seis se avanza ese número; pero con una se avanzan 10, y con ninguna, 25.", "Con una probabilidad de 1 entre 64, el 25 es la tirada más rara y más alta, y dio nombre al juego. Un 6, un 10 o un 25 dan otra tirada. El chaupar, en cambio, usa tres dados alargados de palo marcados con 1, 2, 5 y 6."], "cap": ["De seis cauris, cuántos caen boca arriba (fila superior) y cuánto se avanza (fila inferior). La altura de las barras muestra la frecuencia si cada concha cae de un lado u otro por igual"]}, {"h": "Nuevos nombres, nuevos países", "p": ["A través de los británicos en la India, el juego llegó a Europa y América en el siglo XIX. En Estados Unidos se convirtió en la marca Parcheesi; en Gran Bretaña, el ludo se patentó en 1896, con reglas más sencillas y un solo dado cúbico en lugar de los cauris.", "Alemania tuvo en 1914 el Mensch ärgere dich nicht («No te enfades»), y en España se juega al parchís. Nombres y detalles cambian de un país a otro, pero el armazón es el mismo: dar la vuelta a la cruz y volver a casa."], "cap": []}], "tl": [["s. XVI", "Se traza un patio con una cruz gigante en la Fatehpur Sikri de Akbar"], ["ss. XVII–XVIII", "Las miniaturas indias muestran a menudo gente reunida en torno al chaupar"], ["1694–95", "Devidasa pinta a Shiva y Parvati jugando al chaupar"], ["1874", "Parcheesi se registra como marca en EE. UU."], ["1896", "Se patenta el ludo en Gran Bretaña"], ["1914", "Sale a la venta en Alemania el Mensch ärgere dich nicht"]]}}, "fr": {"pachisi": {"kf": ["Un jeu de course sur un plateau indien en croix : quatre joueurs, en deux équipes, font faire le tour à leurs pions", "Le nom signifie « 25 », le plus fort coup des cauris", "Au XIXe siècle, il a voyagé et s’est répandu dans le monde sous les noms de Parcheesi, ludo et d’autres"], "more": [{"h": "La croix et le chemin", "p": ["Le plateau du pachisi est une croix dont les quatre bras partent du charkoni central. Chaque bras compte 3 × 8 cases, soit 96 en tout. Les plateaux étaient souvent brodés sur tissu : on pouvait les rouler et les ranger.", "Les pions quittent le centre, descendent la colonne du milieu de leur bras, font une fois le tour du plateau dans le sens inverse des aiguilles d’une montre et remontent la colonne du milieu jusqu’au centre. Les joueurs assis face à face sont partenaires ; une équipe gagne quand tous deux ont ramené leurs quatre pions."], "cap": ["Un plateau en croix (chaque bras de 3 × 8 cases). La ligne bleue est le chemin d’un joueur : descendre au milieu de son bras, faire tout le tour dans le sens inverse des aiguilles d’une montre, puis remonter au centre"]}, {"h": "Compter les cauris", "p": ["Au pachisi, on lance six coquillages cauris : le nombre tombé ouverture en haut fixe le déplacement. De deux à six, on avance d’autant ; mais avec un seul, on avance de 10, et avec aucun, de 25.", "À 1 chance sur 64, le 25 est le coup le plus rare et le plus fort — il a donné son nom au jeu. Un 6, un 10 ou un 25 donnent droit à un nouveau lancer. Le chaupar, lui, se joue avec trois longs dés en bâtonnet marqués 1, 2, 5 et 6."], "cap": ["Sur six cauris, combien tombent ouverture en haut (rangée du haut) et de combien on avance (rangée du bas). La hauteur des barres montre la fréquence si chaque coquillage tombe d’un côté ou de l’autre à égalité"]}, {"h": "Nouveaux noms, nouveaux pays", "p": ["Par l’intermédiaire des Britanniques en Inde, le jeu gagna l’Europe et l’Amérique au XIXe siècle. Aux États-Unis, il devint la marque Parcheesi ; en Grande-Bretagne, le ludo fut breveté en 1896, avec des règles simplifiées et un seul dé cubique à la place des cauris.", "L’Allemagne eut en 1914 le Mensch ärgere dich nicht (« Ne t’énerve pas »), et l’Espagne joue au parchís ; en France, on connaît les petits chevaux. Noms et détails changent d’un pays à l’autre, mais l’ossature reste : faire le tour de la croix et rentrer à la maison."], "cap": []}], "tl": [["XVIe s.", "Une cour à croix géante est tracée à Fatehpur Sikri, la ville d’Akbar"], ["XVIIe–XVIIIe s.", "Les miniatures indiennes montrent souvent des joueurs autour du chaupar"], ["1694–95", "Devidasa peint Shiva et Parvati jouant au chaupar"], ["1874", "Parcheesi devient une marque aux États-Unis"], ["1896", "Le ludo est breveté en Grande-Bretagne"], ["1914", "Le Mensch ärgere dich nicht est mis en vente en Allemagne"]]}}, "pt": {"pachisi": {"kf": ["Um jogo de corrida num tabuleiro indiano em cruz: quatro jogadores, em duas equipes, levam suas peças para dar a volta", "O nome significa «25», o maior lance das conchas de búzio", "No século XIX cruzou os mares e se espalhou pelo mundo como Parcheesi, ludo e outros"], "more": [{"h": "A cruz e o caminho", "p": ["O tabuleiro do pachisi é uma cruz com quatro braços saindo do charkoni central. Cada braço tem 3 × 8 casas, 96 no total. Os tabuleiros costumavam ser bordados em tecido, para serem enrolados e guardados.", "As peças saem do centro, descem pela coluna do meio do próprio braço, dão uma volta no tabuleiro no sentido anti-horário e sobem de novo pela coluna do meio até o centro. Os jogadores sentados frente a frente são parceiros, e uma equipe vence quando os dois levam para casa suas quatro peças."], "cap": ["Um tabuleiro em cruz (cada braço com 3 × 8 casas). A linha azul é o caminho de um jogador: desce pelo meio do próprio braço, dá a volta inteira no sentido anti-horário e sobe de novo pelo meio até o centro"]}, {"h": "Contando os búzios", "p": ["No pachisi lançam-se seis conchas de búzio, e o número que cai com a abertura para cima decide o lance. De dois a seis, anda-se esse número; mas com um, andam-se 10, e com nenhum, 25.", "Com chance de 1 em 64, o 25 é o lance mais raro e mais alto — e deu nome ao jogo. Um 6, 10 ou 25 dá direito a outro lance. Já o chaupar usa três dados compridos de bastão marcados com 1, 2, 5 e 6."], "cap": ["De seis búzios, quantos caem com a abertura para cima (fileira de cima) e quanto se anda (fileira de baixo). A altura das barras mostra a frequência se cada concha cair de um lado ou de outro por igual"]}, {"h": "Novos nomes, novos países", "p": ["Por meio dos britânicos na Índia, o jogo chegou à Europa e à América no século XIX. Nos EUA virou a marca Parcheesi; na Grã-Bretanha, o ludo foi patenteado em 1896, com regras mais simples e um único dado cúbico no lugar dos búzios.", "A Alemanha ganhou em 1914 o Mensch ärgere dich nicht («Não se irrite»), e na Espanha joga-se parchís. Nomes e detalhes mudam de país para país, mas a estrutura é a mesma: dar a volta na cruz e voltar para casa."], "cap": []}], "tl": [["séc. XVI", "Um pátio com uma cruz gigante é traçado em Fatehpur Sikri, a cidade de Akbar"], ["sécs. XVII–XVIII", "Miniaturas indianas mostram com frequência pessoas em volta do chaupar"], ["1694–95", "Devidasa pinta Shiva e Parvati jogando chaupar"], ["1874", "Parcheesi vira marca registrada nos EUA"], ["1896", "O ludo é patenteado na Grã-Bretanha"], ["1914", "O Mensch ärgere dich nicht chega às lojas na Alemanha"]]}}, "de": {"pachisi": {"kf": ["Ein Wettlaufspiel auf einem kreuzförmigen indischen Brett: vier Spieler in zwei Teams bringen ihre Figuren einmal herum", "Der Name bedeutet „25“ – der höchste Wurf der Kaurischnecken", "Im 19. Jahrhundert reiste es übers Meer und verbreitete sich als Parcheesi, Ludo und mehr weltweit"], "more": [{"h": "Das Kreuz und der Weg", "p": ["Das Pachisi-Brett ist ein Kreuz, dessen vier Arme vom mittleren Charkoni ausgehen. Jeder Arm hat 3 × 8 Felder, zusammen 96. Oft war das Brett auf Stoff gestickt, sodass man es zusammenrollen und wegräumen konnte.", "Die Figuren verlassen die Mitte, ziehen die mittlere Spalte ihres eigenen Arms hinab, umrunden das Brett einmal gegen den Uhrzeigersinn und kehren über die mittlere Spalte ins Zentrum zurück. Gegenübersitzende sind Partner; ein Team gewinnt, wenn beide alle vier Figuren heimgebracht haben."], "cap": ["Ein kreuzförmiges Brett (jeder Arm 3 × 8 Felder). Die blaue Linie ist der Weg eines Spielers: in der Mitte des eigenen Arms hinunter, einmal gegen den Uhrzeigersinn herum und über die Mitte zurück ins Zentrum"]}, {"h": "Kauris zählen", "p": ["Beim Pachisi wirft man sechs Kaurischnecken; wie viele mit der Öffnung nach oben liegen, bestimmt den Zug. Bei zwei bis sechs zieht man so viele Felder; bei einer aber 10, und bei keiner 25.", "Mit einer Chance von 1 zu 64 ist die 25 der seltenste und höchste Wurf – und gab dem Spiel seinen Namen. Eine 6, 10 oder 25 bringt einen weiteren Wurf. Chaupar dagegen spielt man mit drei langen Stabwürfeln mit den Augen 1, 2, 5 und 6."], "cap": ["Von sechs Kauris: wie viele mit der Öffnung nach oben fallen (obere Reihe) und wie weit man dann zieht (untere Reihe). Die Balkenhöhe zeigt die Häufigkeit, wenn jede Schnecke gleich oft auf jede Seite fällt"]}, {"h": "Neue Namen, neue Länder", "p": ["Über die Briten in Indien gelangte das Spiel im 19. Jahrhundert nach Europa und Amerika. In den USA wurde es zur Marke Parcheesi; in Großbritannien wurde Ludo 1896 patentiert, mit einfacheren Regeln und einem einzigen Würfel statt der Kauris.", "Deutschland bekam 1914 „Mensch ärgere dich nicht“, in Spanien spielt man Parchís. Namen und Einzelheiten wechseln von Land zu Land, doch das Gerüst bleibt: einmal ums Kreuz und wieder nach Hause."], "cap": []}], "tl": [["16. Jh.", "In Akbars Fatehpur Sikri entsteht ein Hof mit einem riesigen Kreuzbrett"], ["17.–18. Jh.", "Indische Miniaturen zeigen oft Menschen beim Chaupar"], ["1694–95", "Devidasa malt Shiva und Parvati beim Chaupar"], ["1874", "Parcheesi wird in den USA zur Marke"], ["1896", "Ludo wird in Großbritannien patentiert"], ["1914", "„Mensch ärgere dich nicht“ kommt in Deutschland auf den Markt"]]}}, "ru": {"pachisi": {"kf": ["Гонка на индийской крестообразной доске: четверо игроков в двух командах проводят фишки по кругу", "Название значит «25» — самый крупный бросок раковин каури", "В XIX веке игра пересекла моря и разошлась по миру как «Парчизи», «Лудо» и другие"], "more": [{"h": "Крест и путь", "p": ["Доска пачиси — это крест, четыре крыла которого расходятся от центрального чаркони. В каждом крыле 3 × 8 клеток, всего 96. Доски часто вышивали на ткани, так что их можно было свернуть и убрать.", "Фишки выходят из центра, спускаются по среднему ряду своего крыла, один раз обходят доску против часовой стрелки и возвращаются по среднему ряду в центр. Сидящие друг напротив друга — партнёры; команда побеждает, когда оба приведут домой все четыре фишки."], "cap": ["Крестообразная доска (каждое крыло — 3 × 8 клеток). Синяя линия — путь одного игрока: вниз по середине своего крыла, полный круг против часовой стрелки и обратно вверх по середине к центру"]}, {"h": "Счёт по каури", "p": ["В пачиси бросают шесть раковин каури, и число раковин, легших устьем вверх, определяет ход. От двух до шести — ходят на столько же клеток; но при одной ходят на 10, а если ни одной — на 25.", "Выпадая в 1 случае из 64, 25 — самый редкий и самый крупный бросок, и он дал игре имя. За 6, 10 или 25 полагается ещё один бросок. В чаупаре же бросают три длинные палочковые кости с метками 1, 2, 5 и 6."], "cap": ["Из шести раковин каури: сколько легло устьем вверх (верхний ряд) и на сколько клеток ходить (нижний ряд). Высота столбцов — как часто это выпадает, если каждая раковина ложится на любую сторону одинаково часто"]}, {"h": "Новые имена, новые страны", "p": ["Через британцев, живших в Индии, игра в XIX веке попала в Европу и Америку. В США она стала товарным знаком «Парчизи», в Британии в 1896 году запатентовали «Лудо» — с упрощёнными правилами и одной кубической костью вместо каури.", "В Германии в 1914 году вышла «Mensch ärgere dich nicht» («Не сердись»), в Испании играют в парчис. Названия и подробности меняются от страны к стране, но каркас один: обойти крест и вернуться домой."], "cap": []}], "tl": [["XVI в.", "В Фатехпур-Сикри Акбара устраивают двор с гигантской доской-крестом"], ["XVII–XVIII вв.", "Индийские миниатюры часто изображают людей за чаупаром"], ["1694–95", "Девидаса пишет Шиву и Парвати за игрой в чаупар"], ["1874", "«Парчизи» регистрируют как товарный знак в США"], ["1896", "В Британии патентуют «Лудо»"], ["1914", "В Германии поступает в продажу «Mensch ärgere dich nicht»"]]}}, "tr": {"pachisi": {"kf": ["Haç biçimli bir Hint tahtasında, iki takım hâlinde dört oyuncunun taşlarını bir tur dolaştırdığı yarış oyunu", "Adı “25” demektir: deniz kabuklarıyla gelen en büyük sayı", "19. yüzyılda denizleri aşıp Parcheesi, Ludo ve başka adlarla dünyaya yayıldı"], "more": [{"h": "Haç ve yol", "p": ["Paçisi tahtası, ortadaki çarkoniden dört kolun uzandığı bir haçtır. Her kol 3 × 8 karedir, toplam 96 kare. Tahtalar çoğu zaman kumaşa işlenirdi; böylece katlanıp kaldırılabilirdi.", "Taşlar merkezden çıkar, kendi kolunun orta sütunundan aşağı iner, tahtayı saat yönünün tersine bir kez dolaşır ve orta sütundan merkeze döner. Karşılıklı oturanlar ortaktır; ikisi de dört taşını eve getirince takım kazanır."], "cap": ["Haç biçimli tahta (her kol 3 × 8 kare). Mavi çizgi bir oyuncunun yolu: kendi kolunun ortasından aşağı iner, saat yönünün tersine tam tur atar ve ortadan merkeze geri çıkar"]}, {"h": "Kabukları saymak", "p": ["Paçisi’de altı kauri kabuğu atılır; ağzı yukarı düşenlerin sayısı hamleyi belirler. İkiden altıya kadar o kadar gidilir; ama yalnız biri yukarıdaysa 10, hiçbiri değilse 25 kare gidilir.", "64’te 1 olasılıkla 25 en nadir ve en büyük atıştır ve oyuna adını vermiştir. 6, 10 ya da 25 gelirse bir kez daha atılır. Çaupar ise üzerinde 1, 2, 5 ve 6 yazan üç uzun çubuk zarla oynanır."], "cap": ["Altı kauri kabuğundan kaçının ağzı yukarı düştüğü (üst sıra) ve kaç kare gidildiği (alt sıra). Çubuk yüksekliği, her kabuk iki yüze eşit olasılıkla düşerse ne sıklıkta geldiğini gösterir"]}, {"h": "Yeni adlar, yeni ülkeler", "p": ["Hindistan’daki İngilizler aracılığıyla oyun 19. yüzyılda Avrupa’ya ve Amerika’ya ulaştı. ABD’de Parcheesi markası oldu; Britanya’da Ludo 1896’da patent aldı, kurallar sadeleşti ve kabukların yerini tek bir küp zar aldı.", "Almanya’da 1914’te “Mensch ärgere dich nicht” (“Kızma”) çıktı, İspanya’da parchís oynanır. Adlar ve ayrıntılar ülkeden ülkeye değişse de iskelet aynıdır: haçın çevresini dolaşıp eve dönmek."], "cap": []}], "tl": [["16. yy", "Ekber’in Fatehpur Sikri’sinde dev bir haç tahtalı avlu yapılır"], ["17.–18. yy", "Hint minyatürlerinde çaupar başında toplanmış insanlar sıkça çizilir"], ["1694–95", "Devidasa, çaupar oynayan Şiva ve Parvati’yi resmeder"], ["1874", "Parcheesi ABD’de marka olur"], ["1896", "Ludo Britanya’da patent alır"], ["1914", "“Mensch ärgere dich nicht” Almanya’da satışa çıkar"]]}}, "id": {"pachisi": {"kf": ["Permainan balapan di papan India berbentuk salib: empat pemain dalam dua tim membawa bidaknya berkeliling", "Namanya berarti “25” — lemparan terbesar dari kerang cowrie", "Pada abad ke-19 menyeberang lautan dan menyebar ke seluruh dunia sebagai Parcheesi, ludo, dan lainnya"], "more": [{"h": "Salib dan jalurnya", "p": ["Papan pachisi berbentuk salib dengan empat lengan yang memanjang dari charkoni di tengah. Setiap lengan berukuran 3 × 8 petak, total 96 petak. Papannya sering disulam di atas kain sehingga bisa digulung dan disimpan.", "Bidak keluar dari pusat, turun lewat kolom tengah lengannya sendiri, mengelilingi papan sekali berlawanan arah jarum jam, lalu naik lagi lewat kolom tengah ke pusat. Pemain yang duduk berhadapan adalah kawan; satu tim menang bila keduanya membawa pulang keempat bidaknya."], "cap": ["Papan berbentuk salib (setiap lengan 3 × 8 petak). Garis biru adalah jalur seorang pemain: turun lewat tengah lengannya sendiri, berkeliling penuh berlawanan arah jarum jam, lalu naik lagi lewat tengah ke pusat"]}, {"h": "Menghitung cowrie", "p": ["Dalam pachisi dilempar enam kerang cowrie, dan jumlah yang jatuh dengan mulut ke atas menentukan langkah. Dua sampai enam berarti maju sebanyak itu; tetapi satu berarti maju 10, dan tak satu pun berarti maju 25.", "Dengan peluang 1 banding 64, angka 25 adalah lemparan paling langka dan terbesar — dan menjadi nama permainan ini. Angka 6, 10, atau 25 memberi lemparan tambahan. Chaupar sebaliknya memakai tiga dadu batang panjang bertanda 1, 2, 5, dan 6."], "cap": ["Dari enam cowrie, berapa yang jatuh dengan mulut menghadap ke atas (baris atas) dan berapa petak melangkah (baris bawah). Tinggi batang menunjukkan seberapa sering itu terjadi bila setiap kerang jatuh ke sisi mana pun sama mungkinnya"]}, {"h": "Nama baru, negeri baru", "p": ["Melalui orang Inggris di India, permainan ini tiba di Eropa dan Amerika pada abad ke-19. Di AS menjadi merek Parcheesi; di Inggris ludo dipatenkan pada 1896, dengan aturan lebih sederhana dan satu dadu kubus sebagai pengganti cowrie.", "Jerman mendapat Mensch ärgere dich nicht (“Jangan kesal”) pada 1914, dan Spanyol memainkan parchís. Nama dan detail berbeda di tiap negara, tetapi kerangkanya tetap: mengelilingi salib dan pulang ke rumah."], "cap": []}], "tl": [["Abad ke-16", "Halaman bergambar papan salib raksasa dibuat di Fatehpur Sikri milik Akbar"], ["Abad ke-17–18", "Lukisan miniatur India sering menggambarkan orang berkumpul di sekitar chaupar"], ["1694–95", "Devidasa melukis Siwa dan Parwati bermain chaupar"], ["1874", "Parcheesi menjadi merek dagang di AS"], ["1896", "Ludo dipatenkan di Inggris"], ["1914", "Mensch ärgere dich nicht mulai dijual di Jerman"]]}}, "hi": {"pachisi": {"kf": ["क्रॉस के आकार की भारतीय बिसात पर दौड़ का खेल: दो टीमों में चार खिलाड़ी अपनी गोटियों को पूरा चक्कर लगवाते हैं", "नाम का अर्थ है “पच्चीस” — कौड़ियों से आने वाली सबसे बड़ी संख्या", "19वीं सदी में यह समंदर पार गया और पारचीज़ी, लूडो जैसे नामों से दुनिया भर में फैला"], "more": [{"h": "क्रॉस और रास्ता", "p": ["पचीसी की बिसात एक क्रॉस है, जिसकी चार भुजाएँ बीच के ‘चारकोनी’ से निकलती हैं। हर भुजा में 3 × 8 खाने हैं, कुल 96। बिसात अक्सर कपड़े पर कढ़ाई से बनती थी, ताकि उसे लपेटकर रखा जा सके।", "गोटियाँ केंद्र से निकलकर अपनी भुजा के बीच वाले स्तंभ से नीचे जाती हैं, घड़ी की उल्टी दिशा में बिसात का एक चक्कर लगाती हैं और बीच वाले स्तंभ से ऊपर चढ़कर केंद्र लौटती हैं। आमने-सामने बैठे खिलाड़ी साथी होते हैं; जब दोनों अपनी चारों गोटियाँ घर ले आएँ, तो टीम जीतती है।"], "cap": ["क्रॉस के आकार की बिसात (हर भुजा 3 × 8 खाने)। नीली रेखा एक खिलाड़ी का रास्ता है: अपनी भुजा के बीच से नीचे, घड़ी की उल्टी दिशा में पूरा चक्कर, और फिर बीच से ऊपर केंद्र तक"]}, {"h": "कौड़ियों की गिनती", "p": ["पचीसी में छह कौड़ियाँ फेंकी जाती हैं, और जितनी मुँह ऊपर गिरें, उससे चाल तय होती है। दो से छह हों तो उतने खाने; पर एक हो तो 10, और एक भी न हो तो 25 खाने।", "64 में 1 बार आने वाला 25 सबसे दुर्लभ और सबसे बड़ा दाँव है — इसी से खेल का नाम पड़ा। 6, 10 या 25 आने पर एक और बार फेंकने को मिलता है। चौपड़ में इसके बजाय 1, 2, 5 और 6 अंकों वाले तीन लंबे पासे फेंके जाते हैं।"], "cap": ["छह कौड़ियों में से कितनी मुँह ऊपर गिरीं (ऊपर की पंक्ति) और तब कितने खाने चलना है (नीचे की पंक्ति)। डंडों की ऊँचाई बताती है कि हर कौड़ी के दोनों ओर बराबर गिरने पर यह कितनी बार आता है"]}, {"h": "नए नाम, नए देश", "p": ["भारत में रहे अंग्रेज़ों के ज़रिए यह खेल 19वीं सदी में यूरोप और अमेरिका पहुँचा। अमेरिका में यह पारचीज़ी ट्रेडमार्क बना; ब्रिटेन में 1896 में लूडो का पेटेंट हुआ — आसान नियमों और कौड़ियों की जगह एक घनाकार पासे के साथ।", "जर्मनी में 1914 में ‘मेन्श एर्गेरे दिश निष्ट’ (“नाराज़ मत हो”) आया, और स्पेन में पारचीस खेला जाता है। देश-देश में नाम और ब्यौरे बदलते हैं, पर ढाँचा वही है: क्रॉस का चक्कर लगाकर घर लौटना।"], "cap": []}], "tl": [["16वीं सदी", "अकबर की फ़तेहपुर सीकरी में विशाल क्रॉस-बिसात वाला आँगन बना"], ["17वीं–18वीं सदी", "भारतीय लघुचित्रों में चौपड़ के इर्द-गिर्द बैठे लोग अक्सर दिखते हैं"], ["1694–95", "देवीदास ने चौपड़ खेलते शिव और पार्वती को चित्रित किया"], ["1874", "अमेरिका में पारचीज़ी ट्रेडमार्क बना"], ["1896", "ब्रिटेन में लूडो का पेटेंट हुआ"], ["1914", "जर्मनी में ‘मेन्श एर्गेरे दिश निष्ट’ बिक्री में आया"]]}}, "ar": {"pachisi": {"kf": ["لعبة سباق على لوح هندي على شكل صليب: أربعة لاعبين في فريقين يُكملون بقطعهم دورة كاملة", "معنى الاسم «25»، وهي أكبر رمية بأصداف الودع", "في القرن التاسع عشر عبرت البحار وانتشرت في العالم باسم بارتشيزي ولودو وغيرهما"], "more": [{"h": "الصليب والطريق", "p": ["لوح البتشيسي صليب تمتد أذرعه الأربع من «التشاركوني» في الوسط. في كل ذراع 3 × 8 مربعات، أي 96 مربعًا في المجموع. وكثيرًا ما كان اللوح يُطرَّز على قماش، فيُلفّ ويُحفظ.", "تخرج القطع من المركز، وتنزل في العمود الأوسط من ذراع صاحبها، وتدور حول اللوح مرة عكس عقارب الساعة، ثم تصعد العمود الأوسط عائدة إلى المركز. واللاعبان المتقابلان شريكان، ويفوز الفريق حين يُعيد كلاهما قطعه الأربع."], "cap": ["لوح على شكل صليب (كل ذراع 3 × 8 مربعات). الخط الأزرق طريق لاعب واحد: ينزل من وسط ذراعه، ويدور دورة كاملة عكس عقارب الساعة، ثم يصعد من الوسط إلى المركز"]}, {"h": "عدّ أصداف الودع", "p": ["في البتشيسي تُرمى ست أصداف ودع، ويحدد عدد ما سقط منها وفمه إلى أعلى مقدار الحركة. من اثنتين إلى ست يتقدم اللاعب بالعدد نفسه، أما إن كانت واحدة فيتقدم 10، وإن لم تكن أي منها فيتقدم 25.", "وباحتمال 1 من 64 يكون 25 أندر الرميات وأكبرها، ومنه أخذت اللعبة اسمها. ورمية 6 أو 10 أو 25 تمنح رمية إضافية. أما التشوبار فيُلعب بثلاثة أحجار نرد طويلة كالعصيّ عليها 1 و2 و5 و6."], "cap": ["من ست أصداف ودع: كم واحدة سقطت وفمها إلى أعلى (الصف العلوي)، وكم مربعًا يتقدم اللاعب (الصف السفلي). يُظهر ارتفاع الأعمدة تكرار كل حالة لو سقطت كل صدفة على أي وجه بالتساوي"]}, {"h": "أسماء جديدة وبلدان جديدة", "p": ["عن طريق البريطانيين في الهند وصلت اللعبة إلى أوروبا وأمريكا في القرن التاسع عشر. ففي الولايات المتحدة صارت علامة «بارتشيزي» التجارية، وفي بريطانيا سُجّلت براءة «لودو» عام 1896 بقواعد أبسط ونرد مكعب واحد بدل الأصداف.", "وفي ألمانيا ظهرت عام 1914 لعبة «منش إرغره دِش نِشت» («لا تغضب»)، وفي إسبانيا تُلعب «بارتشيس». تتبدل الأسماء والتفاصيل من بلد إلى آخر، لكن الهيكل واحد: الدوران حول الصليب والعودة إلى البيت."], "cap": []}], "tl": [["القرن 16", "إنشاء فناء بلوح صليبي عملاق في فتحبور سيكري مدينة أكبر"], ["القرنان 17–18", "كثيرًا ما تُصوّر المنمنمات الهندية أناسًا حول التشوبار"], ["1694–95", "ديفيداسا يرسم شيفا وبارفاتي يلعبان التشوبار"], ["1874", "«بارتشيزي» علامة تجارية في الولايات المتحدة"], ["1896", "تسجيل براءة «لودو» في بريطانيا"], ["1914", "طرح «منش إرغره دِش نِشت» في ألمانيا"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (19): story 12 (go) made fuller */
(T => { const D = {"ja": {"go": {"kf": ["黒と白の石を線の交わる点に置き、囲んだ陣地の広さを競う、古代中国生まれのゲーム", "盤は17路の時代を経て19路に。正倉院には8世紀の19路の碁盤が残る", "江戸時代には家元が幕府に仕え、21世紀にはAIが人間の第一人者に勝った"], "more": [{"h": "囲んで取る、陣地を広げる", "p": ["碁では、黒と白が交互に、盤の線が交わる点に石を置いていきます。一度置いた石は動きません。石のとなりの空いた点がすべて相手の石でふさがれると、その石は取られて盤から取り除かれます。", "最後に、自分の石で囲んだ陣地の広さと取った石の数を合わせて、多いほうが勝ちです。ルールはわずかでも、盤が広いため打ち方は無数にあり、19路盤でありうる局面の数は10の170乗ほどと計算されています。"], "cap": ["石の取り方。左：黒石のまわりの空いた点（赤）は4つ。中：白に3方を囲まれ、残り1つ。右：最後の1つもふさがれ、黒石は取られる"]}, {"h": "17路から19路へ", "p": ["中国の河北省望都の後漢時代の墓からは、17路の石の碁盤が見つかっています。一方、6世紀ごろのものとされる敦煌の『碁経』には、361の交点、つまり19路の盤のことが書かれています。この間に盤が大きくなったと考えられています。", "正倉院の碁盤は19路ですが、今の9つの星とはちがって、17か所に花の印があります。交点が289から361に増えただけで、ゲームはずっと奥深くなりました。"], "cap": ["17路と19路の盤の交点の数くらべ。今の19路盤の黒い点は9つの「星」"]}, {"h": "仙人の碁、家元の碁", "p": ["中国には、山で仙人の碁を見物していた木こりが、ふと気づくと斧の柄が腐るほどの年月がたっていた、という「爛柯」の言い伝えがあります。碁は仙人の遊びとして、皿や絵にもよく描かれました。", "日本では江戸時代、本因坊家などの家元が幕府から禄を受け、碁は芸として磨かれました。1938年の本因坊秀哉の引退碁は、川端康成の小説『名人』になっています。2016年には、AIのアルファ碁が世界の第一人者イ・セドルに4勝1敗で勝ち、世界を驚かせました。"], "cap": ["碁を打つ仙人を彫った漆の皿（明・宣徳年間、1425〜36年）"]}], "tl": [["紀元前4世紀ごろ", "『孟子』に碁の名人・弈秋の名が出る"], ["後漢時代", "望都の墓に17路の石の碁盤が納められる"], ["6世紀ごろ", "敦煌の『碁経』に19路・361の交点が書かれる"], ["8世紀", "正倉院の「木画紫檀棊局」"], ["1612年", "本因坊算砂らが幕府から禄を受けたとされる"], ["1938年", "本因坊秀哉の引退碁。のちに川端康成の『名人』に"], ["2016年", "アルファ碁がイ・セドルに4勝1敗"]]}}, "en": {"go": {"kf": ["Black and white stones on the points where lines cross, competing for the larger territory — a game born in ancient China", "After an age of 17-line boards came 19 lines; the Shōsōin keeps an 8th-century 19-line board", "In Edo Japan, go houses served the shogunate; in the 21st century an AI beat the world’s top player"], "more": [{"h": "Surround to capture, enclose to win", "p": ["In go, Black and White take turns placing stones on the points where the lines cross. Once placed, a stone never moves. When every empty point next to a stone (or group) is filled by the opponent, it is captured and removed from the board.", "At the end, the territory you have walled in plus the stones you have taken decides the winner. The rules are few, but the board is wide: the number of possible positions on a 19-line board has been calculated at about 10 to the power 170."], "cap": ["How stones are captured. Left: the black stone has four empty points beside it (red). Middle: White closes in on three sides, leaving one. Right: the last is filled and the black stone is taken"]}, {"h": "From 17 lines to 19", "p": ["A 17-line stone go board was found in an Eastern Han tomb at Wangdu in Hebei, China. The Dunhuang Classic of Go, thought to date from around the 6th century, describes 361 points — a 19-line board. The board seems to have grown in between.", "The Shōsōin board has 19 lines, but instead of today’s nine star points it has flower marks in 17 places. Going from 289 points to 361 made the game far deeper."], "cap": ["The 17-line and 19-line boards compared by number of points. The nine black dots on today’s board are the “star points”"]}, {"h": "Go of the immortals, go of the masters", "p": ["A Chinese tale tells of a woodcutter who stopped in the mountains to watch immortals playing go — and found that so many years had passed that his axe handle had rotted away. Go as a pastime of immortals was a favourite subject for dishes and paintings.", "In Edo Japan, go houses such as the Hon’inbō were paid by the shogunate and go was polished into an art. Hon’inbō Shūsai’s retirement game of 1938 became Kawabata Yasunari’s novel The Master of Go. In 2016 the AI AlphaGo beat the world’s leading player, Lee Sedol, four games to one, astonishing the world."], "cap": ["A carved lacquer dish with immortals playing go (Ming dynasty, Xuande period, 1425–36)"]}], "tl": [["c. 4th c. BC", "Mencius names the go master Yi Qiu"], ["Eastern Han", "A 17-line stone board is placed in a tomb at Wangdu"], ["c. 6th c.", "The Dunhuang Classic of Go describes 19 lines and 361 points"], ["8th c.", "The Shōsōin go board of sandalwood with marquetry"], ["1612", "Hon’inbō Sansa and others are said to receive stipends from the shogunate"], ["1938", "Hon’inbō Shūsai’s retirement game, later Kawabata’s The Master of Go"], ["2016", "AlphaGo beats Lee Sedol four games to one"]]}}, "zh": {"go": {"kf": ["在棋盘线的交叉点上落黑白棋子，比谁围住的地盘大——诞生于古代中国的游戏", "棋盘经过17路的时代变成19路；正仓院保存着8世纪的19路棋盘", "江户时代家元为幕府效力；21世纪AI战胜了人类第一人"], "more": [{"h": "围而提之，扩大地盘", "p": ["围棋由黑白双方轮流在棋盘线的交叉点上落子，落下的棋子不再移动。一颗棋子（或一块棋）相邻的空点全被对方棋子堵住时，就会被提走，从盘上拿掉。", "最后比较各自围住的地盘加上提掉的子，多者为胜。规则虽少，棋盘却很大：19路棋盘上可能出现的局面数被算出约为10的170次方。"], "cap": ["提子的方法。左：黑子旁边的空点（红色）有4个。中：被白子三面包围，只剩1个。右：最后一个也被堵住，黑子被提走"]}, {"h": "从17路到19路", "p": ["河北望都的东汉墓中出土过17路的石制棋盘。另一方面，被认为约成书于6世纪的敦煌《棋经》写的是361个交叉点，也就是19路棋盘。棋盘大概是在这期间变大的。", "正仓院的棋盘是19路，但不同于今天的9个星位，它在17处有花形标记。交叉点从289增加到361，棋就深奥了许多。"], "cap": ["17路与19路棋盘的交叉点数比较。今天19路棋盘上的9个黑点是“星位”"]}, {"h": "仙人的棋，家元的棋", "p": ["中国有“烂柯”的传说：樵夫在山中看仙人下棋，回过神来，斧柄都已朽烂，不知过了多少年。围棋作为仙人的游戏，常被画在盘子和画作上。", "在日本江户时代，本因坊家等家元领取幕府俸禄，把围棋磨炼成一门技艺。1938年本因坊秀哉的引退棋，后来成为川端康成的小说《名人》。2016年，AI“阿尔法围棋”以4比1战胜世界顶尖棋手李世石，震惊世界。"], "cap": ["雕着仙人对弈的漆盘（明宣德年间，1425–36年）"]}], "tl": [["约公元前4世纪", "《孟子》提到围棋名手弈秋"], ["东汉", "望都墓中放入17路石棋盘"], ["约6世纪", "敦煌《棋经》记载19路、361个交叉点"], ["8世纪", "正仓院的“木画紫檀棋局”"], ["1612年", "相传本因坊算砂等人领取幕府俸禄"], ["1938年", "本因坊秀哉的引退棋，后成为川端康成《名人》"], ["2016年", "阿尔法围棋以4比1战胜李世石"]]}}, "zh-TW": {"go": {"kf": ["在棋盤線的交叉點上落黑白棋子，比誰圍住的地盤大——誕生於古代中國的遊戲", "棋盤經過17路的時代變成19路；正倉院保存著8世紀的19路棋盤", "江戶時代家元為幕府效力；21世紀AI戰勝了人類第一人"], "more": [{"h": "圍而提之，擴大地盤", "p": ["圍棋由黑白雙方輪流在棋盤線的交叉點上落子，落下的棋子不再移動。一顆棋子（或一塊棋）相鄰的空點全被對方棋子堵住時，就會被提走，從盤上拿掉。", "最後比較各自圍住的地盤加上提掉的子，多者為勝。規則雖少，棋盤卻很大：19路棋盤上可能出現的局面數被算出約為10的170次方。"], "cap": ["提子的方法。左：黑子旁邊的空點（紅色）有4個。中：被白子三面包圍，只剩1個。右：最後一個也被堵住，黑子被提走"]}, {"h": "從17路到19路", "p": ["河北望都的東漢墓中出土過17路的石製棋盤。另一方面，被認為約成書於6世紀的敦煌《棋經》寫的是361個交叉點，也就是19路棋盤。棋盤大概是在這期間變大的。", "正倉院的棋盤是19路，但不同於今天的9個星位，它在17處有花形標記。交叉點從289增加到361，棋就深奧了許多。"], "cap": ["17路與19路棋盤的交叉點數比較。今天19路棋盤上的9個黑點是「星位」"]}, {"h": "仙人的棋，家元的棋", "p": ["中國有「爛柯」的傳說：樵夫在山中看仙人下棋，回過神來，斧柄都已朽爛，不知過了多少年。圍棋作為仙人的遊戲，常被畫在盤子和畫作上。", "在日本江戶時代，本因坊家等家元領取幕府俸祿，把圍棋磨練成一門技藝。1938年本因坊秀哉的引退棋，後來成為川端康成的小說《名人》。2016年，AI「AlphaGo」以4比1戰勝世界頂尖棋士李世乭，震驚世界。"], "cap": ["雕著仙人對弈的漆盤（明宣德年間，1425–36年）"]}], "tl": [["約公元前4世紀", "《孟子》提到圍棋名手弈秋"], ["東漢", "望都墓中放入17路石棋盤"], ["約6世紀", "敦煌《棋經》記載19路、361個交叉點"], ["8世紀", "正倉院的「木畫紫檀棋局」"], ["1612年", "相傳本因坊算砂等人領取幕府俸祿"], ["1938年", "本因坊秀哉的引退棋，後成為川端康成《名人》"], ["2016年", "AlphaGo以4比1戰勝李世乭"]]}}, "ko": {"go": {"kf": ["흑과 백의 돌을 줄이 만나는 점에 놓고, 둘러싼 집의 넓이를 겨루는 고대 중국 태생의 게임", "판은 17줄 시대를 거쳐 19줄로. 쇼소인에는 8세기의 19줄 바둑판이 남아 있다", "에도 시대에는 가문이 막부를 섬겼고, 21세기에는 AI가 인간 최고수를 이겼다"], "more": [{"h": "둘러싸서 잡고, 집을 넓힌다", "p": ["바둑은 흑과 백이 번갈아 판의 줄이 만나는 점에 돌을 놓습니다. 한 번 놓은 돌은 움직이지 않습니다. 돌(또는 돌 무리) 옆의 빈 점이 모두 상대 돌로 막히면, 그 돌은 잡혀서 판에서 들어냅니다.", "마지막에 자기 돌로 둘러싼 집과 잡은 돌을 합쳐 많은 쪽이 이깁니다. 규칙은 몇 개 안 되지만 판이 넓어서, 19줄 판에서 나올 수 있는 국면의 수는 10의 170제곱 정도로 계산되었습니다."], "cap": ["돌을 잡는 법. 왼쪽: 흑돌 둘레의 빈 점(빨강)은 4개. 가운데: 백에게 세 방향을 막혀 1개 남음. 오른쪽: 마지막 하나도 막혀 흑돌이 잡힘"]}, {"h": "17줄에서 19줄로", "p": ["중국 허베이성 왕두의 후한 시대 무덤에서 17줄 돌 바둑판이 나왔습니다. 한편 6세기 무렵의 것으로 여겨지는 둔황의 『기경』에는 361개의 교점, 즉 19줄 판이 적혀 있습니다. 그 사이에 판이 커진 것으로 보입니다.", "쇼소인의 바둑판은 19줄이지만, 지금의 화점 9개와 달리 17곳에 꽃 표시가 있습니다. 교점이 289에서 361로 늘어난 것만으로 게임은 훨씬 깊어졌습니다."], "cap": ["17줄과 19줄 판의 교점 수 비교. 지금 19줄 판의 검은 점 9개는 ‘화점’"]}, {"h": "신선의 바둑, 가문의 바둑", "p": ["중국에는 산에서 신선의 바둑을 구경하던 나무꾼이 정신을 차려 보니 도끼 자루가 썩을 만큼 세월이 흘러 있었다는 ‘난가’ 전설이 있습니다. 바둑은 신선의 놀이로 접시나 그림에 자주 그려졌습니다.", "일본 에도 시대에는 혼인보가 등의 가문이 막부에서 녹봉을 받아 바둑을 예능으로 갈고닦았습니다. 1938년 혼인보 슈사이의 은퇴 대국은 가와바타 야스나리의 소설 『명인』이 되었습니다. 2016년에는 AI 알파고가 세계 최고수 이세돌에게 4승 1패로 이겨 세계를 놀라게 했습니다."], "cap": ["바둑 두는 신선을 새긴 칠기 접시(명 선덕 연간, 1425~36년)"]}], "tl": [["기원전 4세기 무렵", "『맹자』에 바둑 명수 혁추의 이름이 나옴"], ["후한 시대", "왕두의 무덤에 17줄 돌 바둑판이 묻힘"], ["6세기 무렵", "둔황 『기경』에 19줄·361개 교점이 적힘"], ["8세기", "쇼소인의 ‘목화자단 바둑판’"], ["1612년", "혼인보 산사 등이 막부에서 녹봉을 받았다고 전해짐"], ["1938년", "혼인보 슈사이의 은퇴 대국, 뒷날 가와바타의 『명인』으로"], ["2016년", "알파고가 이세돌에게 4승 1패"]]}}, "es": {"go": {"kf": ["Piedras negras y blancas en los puntos donde se cruzan las líneas, para rodear el mayor territorio: un juego nacido en la antigua China", "Tras una época de tableros de 17 líneas llegaron las 19; el Shōsōin guarda un tablero de 19 líneas del siglo VIII", "En el Japón de Edo, las casas de go servían al shogunato; en el siglo XXI una IA venció al mejor jugador del mundo"], "more": [{"h": "Rodear para capturar, cercar para ganar", "p": ["En el go, negras y blancas colocan por turnos piedras en los puntos donde se cruzan las líneas. Una vez puesta, la piedra no se mueve. Cuando todos los puntos vacíos junto a una piedra (o un grupo) quedan ocupados por el rival, es capturada y se retira del tablero.", "Al final gana quien sume más territorio cercado y piedras capturadas. Las reglas son pocas, pero el tablero es amplio: se ha calculado que en uno de 19 líneas caben unas 10 elevado a 170 posiciones posibles."], "cap": ["Cómo se captura. Izquierda: la piedra negra tiene cuatro puntos vacíos al lado (rojo). Centro: las blancas la cercan por tres lados y le queda uno. Derecha: se tapa el último y la piedra negra es capturada"]}, {"h": "De 17 líneas a 19", "p": ["En una tumba de los Han Orientales en Wangdu (Hebei, China) se halló un tablero de go de piedra de 17 líneas. El Clásico del go de Dunhuang, de hacia el siglo VI, describe 361 puntos: un tablero de 19 líneas. Parece que entre ambos el tablero creció.", "El tablero del Shōsōin tiene 19 líneas, pero en lugar de los nueve puntos estrella actuales lleva marcas de flor en 17 lugares. Pasar de 289 puntos a 361 hizo el juego mucho más profundo."], "cap": ["Los tableros de 17 y 19 líneas comparados por número de puntos. Los nueve puntos negros del tablero actual son los «puntos estrella»"]}, {"h": "El go de los inmortales, el go de los maestros", "p": ["Un cuento chino habla de un leñador que se detuvo en la montaña a mirar a unos inmortales jugar al go y descubrió que habían pasado tantos años que el mango de su hacha se había podrido. El go como pasatiempo de inmortales fue tema favorito de platos y pinturas.", "En el Japón de Edo, casas de go como la Hon’inbō recibían un estipendio del shogunato y el go se pulió como un arte. La partida de retirada de Hon’inbō Shūsai, en 1938, inspiró la novela de Kawabata Yasunari El maestro de go. En 2016 la IA AlphaGo venció por 4 a 1 al primer jugador del mundo, Lee Sedol, y asombró al mundo."], "cap": ["Plato de laca tallada con inmortales jugando al go (dinastía Ming, periodo Xuande, 1425–36)"]}], "tl": [["h. s. IV a. C.", "Mencio nombra al maestro de go Yi Qiu"], ["Han Orientales", "Se deposita en una tumba de Wangdu un tablero de piedra de 17 líneas"], ["h. s. VI", "El Clásico del go de Dunhuang describe 19 líneas y 361 puntos"], ["s. VIII", "El tablero de sándalo con marquetería del Shōsōin"], ["1612", "Hon’inbō Sansa y otros reciben, según se dice, un estipendio del shogunato"], ["1938", "Partida de retirada de Hon’inbō Shūsai, luego El maestro de go de Kawabata"], ["2016", "AlphaGo vence a Lee Sedol por 4 a 1"]]}}, "fr": {"go": {"kf": ["Des pierres noires et blanches posées aux intersections des lignes, pour encercler le plus grand territoire : un jeu né dans la Chine antique", "Après une époque de goban à 17 lignes vinrent les 19 lignes ; le Shōsōin conserve un goban de 19 lignes du VIIIe siècle", "À Edo, des maisons de go servaient le shogunat ; au XXIe siècle, une IA a battu le meilleur joueur du monde"], "more": [{"h": "Encercler pour capturer, enclore pour gagner", "p": ["Au go, Noir et Blanc posent à tour de rôle des pierres sur les intersections des lignes. Une pierre posée ne bouge plus. Quand tous les points libres voisins d’une pierre (ou d’un groupe) sont occupés par l’adversaire, elle est capturée et retirée du plateau.", "À la fin, le territoire enclos plus les pierres capturées désignent le vainqueur. Les règles sont peu nombreuses, mais le plateau est vaste : on a calculé qu’un goban de 19 lignes admet environ 10 puissance 170 positions possibles."], "cap": ["La capture. À gauche : la pierre noire a quatre points libres autour d’elle (en rouge). Au centre : Blanc l’entoure sur trois côtés, il en reste un. À droite : le dernier est bouché, la pierre noire est prise"]}, {"h": "De 17 lignes à 19", "p": ["Un goban en pierre de 17 lignes a été découvert dans une tombe des Han orientaux à Wangdu (Hebei, Chine). Le Classique du go de Dunhuang, daté vers le VIe siècle, décrit 361 intersections : un goban de 19 lignes. Le plateau semble avoir grandi entre-temps.", "Le goban du Shōsōin compte 19 lignes, mais au lieu des neuf hoshi actuels il porte des fleurs à 17 endroits. Passer de 289 à 361 intersections a rendu le jeu bien plus profond."], "cap": ["Les goban de 17 et de 19 lignes comparés par nombre d’intersections. Les neuf points noirs du goban actuel sont les « hoshi » (points étoiles)"]}, {"h": "Le go des immortels, le go des maîtres", "p": ["Un conte chinois parle d’un bûcheron qui s’arrêta dans la montagne pour regarder des immortels jouer au go — et s’aperçut que tant d’années avaient passé que le manche de sa hache avait pourri. Le go, passe-temps des immortels, ornait volontiers plats et peintures.", "À l’époque d’Edo, des maisons de go comme les Hon’inbō étaient pensionnées par le shogunat, et le go fut poli comme un art. La partie d’adieu de Hon’inbō Shūsai, en 1938, devint le roman de Kawabata Yasunari Le Maître ou le tournoi de go. En 2016, l’IA AlphaGo battit le meilleur joueur du monde, Lee Sedol, par quatre victoires à une, à la stupeur générale."], "cap": ["Plat en laque sculptée montrant des immortels jouant au go (dynastie Ming, ère Xuande, 1425–36)"]}], "tl": [["vers le IVe s. av. J.-C.", "Mencius nomme le maître de go Yi Qiu"], ["Han orientaux", "Un goban de pierre de 17 lignes est déposé dans une tombe de Wangdu"], ["vers le VIe s.", "Le Classique du go de Dunhuang décrit 19 lignes et 361 intersections"], ["VIIIe s.", "Le goban en santal marqueté du Shōsōin"], ["1612", "Hon’inbō Sansa et d’autres reçoivent, dit-on, une pension du shogunat"], ["1938", "Partie d’adieu de Hon’inbō Shūsai, futur roman de Kawabata"], ["2016", "AlphaGo bat Lee Sedol quatre à un"]]}}, "pt": {"go": {"kf": ["Pedras pretas e brancas nos pontos onde as linhas se cruzam, disputando o maior território — um jogo nascido na China antiga", "Depois de uma época de tabuleiros de 17 linhas vieram as 19; o Shōsōin guarda um tabuleiro de 19 linhas do século VIII", "No Japão de Edo, casas de go serviam ao xogunato; no século XXI uma IA venceu o melhor jogador do mundo"], "more": [{"h": "Cercar para capturar, cercar para vencer", "p": ["No go, pretas e brancas colocam pedras alternadamente nos pontos onde as linhas se cruzam. Uma vez colocada, a pedra não se move. Quando todos os pontos vazios ao lado de uma pedra (ou grupo) são ocupados pelo adversário, ela é capturada e retirada do tabuleiro.", "No fim, vence quem somar mais território cercado e pedras capturadas. As regras são poucas, mas o tabuleiro é amplo: calcula-se que num tabuleiro de 19 linhas caibam cerca de 10 elevado a 170 posições possíveis."], "cap": ["Como se captura. Esquerda: a pedra preta tem quatro pontos vazios ao lado (vermelho). Meio: as brancas a cercam por três lados, resta um. Direita: o último é fechado e a pedra preta é capturada"]}, {"h": "De 17 linhas para 19", "p": ["Numa tumba dos Han Orientais em Wangdu (Hebei, China) achou-se um tabuleiro de go de pedra com 17 linhas. O Clássico do go de Dunhuang, de por volta do século VI, descreve 361 pontos — um tabuleiro de 19 linhas. Parece que entre um e outro o tabuleiro cresceu.", "O tabuleiro do Shōsōin tem 19 linhas, mas em vez dos nove pontos-estrela atuais traz marcas de flor em 17 lugares. Passar de 289 para 361 pontos tornou o jogo muito mais profundo."], "cap": ["Os tabuleiros de 17 e 19 linhas comparados pelo número de pontos. Os nove pontos pretos do tabuleiro atual são os «pontos-estrela»"]}, {"h": "O go dos imortais, o go dos mestres", "p": ["Um conto chinês fala de um lenhador que parou na montanha para ver imortais jogando go — e descobriu que haviam passado tantos anos que o cabo do seu machado apodrecera. O go como passatempo de imortais era tema querido de pratos e pinturas.", "No Japão de Edo, casas de go como a Hon’inbō recebiam estipêndio do xogunato, e o go foi lapidado como arte. A partida de despedida de Hon’inbō Shūsai, em 1938, virou o romance de Kawabata Yasunari O mestre de go. Em 2016, a IA AlphaGo venceu o melhor jogador do mundo, Lee Sedol, por quatro a um, espantando o mundo."], "cap": ["Prato de laca entalhada com imortais jogando go (dinastia Ming, período Xuande, 1425–36)"]}], "tl": [["c. séc. IV a.C.", "Mêncio cita o mestre de go Yi Qiu"], ["Han Orientais", "Um tabuleiro de pedra de 17 linhas é posto numa tumba em Wangdu"], ["c. séc. VI", "O Clássico do go de Dunhuang descreve 19 linhas e 361 pontos"], ["séc. VIII", "O tabuleiro de sândalo marchetado do Shōsōin"], ["1612", "Hon’inbō Sansa e outros recebem, diz-se, estipêndio do xogunato"], ["1938", "Partida de despedida de Hon’inbō Shūsai, depois o romance de Kawabata"], ["2016", "AlphaGo vence Lee Sedol por quatro a um"]]}}, "de": {"go": {"kf": ["Schwarze und weiße Steine auf den Kreuzungspunkten der Linien, um das größere Gebiet einzuschließen – ein Spiel aus dem alten China", "Auf Bretter mit 17 Linien folgten 19; im Shōsōin liegt ein 19-Linien-Brett aus dem 8. Jahrhundert", "Im Edo-Japan dienten Go-Häuser dem Shogunat; im 21. Jahrhundert schlug eine KI den besten Spieler der Welt"], "more": [{"h": "Umzingeln, schlagen, Gebiet gewinnen", "p": ["Beim Go setzen Schwarz und Weiß abwechselnd Steine auf die Kreuzungspunkte der Linien. Ein gesetzter Stein bewegt sich nicht mehr. Sind alle freien Nachbarpunkte eines Steins (oder einer Gruppe) vom Gegner besetzt, wird er geschlagen und vom Brett genommen.", "Am Ende entscheiden eingeschlossenes Gebiet und geschlagene Steine. Die Regeln sind wenige, das Brett aber ist weit: Für ein 19-Linien-Brett wurde die Zahl möglicher Stellungen auf etwa 10 hoch 170 berechnet."], "cap": ["So wird geschlagen. Links: Der schwarze Stein hat vier freie Punkte neben sich (rot). Mitte: Weiß schließt ihn von drei Seiten ein, einer bleibt. Rechts: Auch der letzte wird besetzt – der schwarze Stein ist geschlagen"]}, {"h": "Von 17 Linien zu 19", "p": ["In einem Grab der Östlichen Han-Dynastie in Wangdu (Hebei, China) fand man ein steinernes Go-Brett mit 17 Linien. Der Go-Klassiker von Dunhuang, um das 6. Jahrhundert datiert, beschreibt 361 Punkte – ein 19-Linien-Brett. Dazwischen ist das Brett offenbar gewachsen.", "Das Brett im Shōsōin hat 19 Linien, trägt aber statt der heutigen neun Sternpunkte an 17 Stellen Blütenzeichen. Allein der Schritt von 289 auf 361 Punkte machte das Spiel viel tiefer."], "cap": ["Bretter mit 17 und 19 Linien im Vergleich der Schnittpunkte. Die neun schwarzen Punkte des heutigen Bretts sind die „Sternpunkte“"]}, {"h": "Go der Unsterblichen, Go der Meister", "p": ["Eine chinesische Erzählung handelt von einem Holzfäller, der im Gebirge Unsterblichen beim Go zusah – und merkte, dass so viele Jahre vergangen waren, dass sein Axtstiel verrottet war. Go als Zeitvertreib der Unsterblichen war ein beliebtes Motiv auf Schalen und Bildern.", "Im Edo-Japan erhielten Go-Häuser wie die Hon’inbō Bezüge vom Shogunat, und Go wurde zur Kunst verfeinert. Hon’inbō Shūsais Abschiedspartie von 1938 wurde zu Kawabata Yasunaris Roman „Meijin“. 2016 besiegte die KI AlphaGo den weltbesten Spieler Lee Sedol mit vier zu eins und verblüffte die Welt."], "cap": ["Schnitzlackschale mit Go spielenden Unsterblichen (Ming-Dynastie, Xuande-Zeit, 1425–36)"]}], "tl": [["um 4. Jh. v. Chr.", "Menzius nennt den Go-Meister Yi Qiu"], ["Östliche Han", "Ein steinernes 17-Linien-Brett kommt in ein Grab in Wangdu"], ["um 6. Jh.", "Der Go-Klassiker von Dunhuang beschreibt 19 Linien und 361 Punkte"], ["8. Jh.", "Das Sandelholz-Go-Brett mit Intarsien im Shōsōin"], ["1612", "Hon’inbō Sansa und andere sollen Bezüge vom Shogunat erhalten"], ["1938", "Hon’inbō Shūsais Abschiedspartie, später Kawabatas „Meijin“"], ["2016", "AlphaGo schlägt Lee Sedol mit vier zu eins"]]}}, "ru": {"go": {"kf": ["Чёрные и белые камни ставят на пересечения линий, соревнуясь, кто окружит большую территорию, — игра из древнего Китая", "После эпохи досок в 17 линий пришли 19; в Сёсоине хранится доска в 19 линий VIII века", "В эпоху Эдо дома го служили сёгунату, а в XXI веке ИИ победил сильнейшего игрока мира"], "more": [{"h": "Окружить, взять, отгородить", "p": ["В го чёрные и белые по очереди ставят камни на пересечения линий. Поставленный камень больше не двигается. Если все свободные соседние пункты камня (или группы) заняты противником, он взят и снимается с доски.", "В конце побеждает тот, у кого больше окружённой территории вместе со взятыми камнями. Правил немного, но доска велика: число возможных позиций на доске 19×19 оценено примерно в 10 в 170-й степени."], "cap": ["Как берут камни. Слева: у чёрного камня четыре свободных пункта рядом (красные). В середине: белые окружили его с трёх сторон, остался один. Справа: закрыт и последний — чёрный камень снят"]}, {"h": "От 17 линий к 19", "p": ["В гробнице эпохи Восточная Хань в Ванду (провинция Хэбэй, Китай) нашли каменную доску для го в 17 линий. А «Канон го» из Дуньхуана, датируемый примерно VI веком, описывает 361 пункт — доску в 19 линий. Видимо, за это время доска выросла.", "Доска из Сёсоина — в 19 линий, но вместо нынешних девяти звёздных пунктов на ней цветы в 17 местах. Переход от 289 пунктов к 361 сделал игру гораздо глубже."], "cap": ["Доски в 17 и 19 линий в сравнении по числу пунктов. Девять чёрных точек на нынешней доске — «звёздные пункты»"]}, {"h": "Го бессмертных, го мастеров", "p": ["Китайское предание рассказывает о дровосеке, который засмотрелся в горах на игру бессмертных в го — и обнаружил, что прошло столько лет, что топорище его сгнило. Го как забава бессмертных было любимым сюжетом блюд и картин.", "В Японии эпохи Эдо дома го, такие как Хонъимбо, получали жалованье от сёгуната, и го оттачивалось как искусство. Прощальная партия Хонъимбо Сюсая 1938 года легла в основу романа Кавабаты Ясунари «Мастер игры в го». В 2016 году ИИ AlphaGo победил сильнейшего игрока мира Ли Седоля со счётом 4:1, поразив весь мир."], "cap": ["Блюдо из резного лака с бессмертными за игрой в го (династия Мин, эпоха Сюаньдэ, 1425–36)"]}], "tl": [["ок. IV в. до н. э.", "Мэн-цзы называет мастера го Ицю"], ["Восточная Хань", "В гробницу в Ванду кладут каменную доску в 17 линий"], ["ок. VI в.", "«Канон го» из Дуньхуана описывает 19 линий и 361 пункт"], ["VIII в.", "Сандаловая доска с инкрустацией в Сёсоине"], ["1612", "Хонъимбо Санса и другие, по преданию, получают жалованье сёгуната"], ["1938", "Прощальная партия Хонъимбо Сюсая, позже роман Кавабаты"], ["2016", "AlphaGo побеждает Ли Седоля со счётом 4:1"]]}}, "tr": {"go": {"kf": ["Siyah ve beyaz taşlar çizgilerin kesiştiği noktalara konur; daha geniş alanı çevirmek için yarışılır — eski Çin’de doğmuş bir oyun", "17 çizgili tahtalar devrinin ardından 19 çizgiye geçildi; Shōsōin’de 8. yüzyıldan 19 çizgili bir tahta durur", "Edo Japonya’sında go aileleri şogunluğa hizmet etti; 21. yüzyılda bir yapay zekâ dünyanın en iyi oyuncusunu yendi"], "more": [{"h": "Kuşat, al, alanı genişlet", "p": ["Go’da siyah ve beyaz sırayla, çizgilerin kesiştiği noktalara taş koyar. Konan taş bir daha oynamaz. Bir taşın (ya da grubun) yanındaki bütün boş noktalar rakip taşlarla dolarsa, taş alınır ve tahtadan kaldırılır.", "Sonunda çevrilen alan ile alınan taşların toplamı fazla olan kazanır. Kurallar azdır ama tahta geniştir: 19 çizgili bir tahtada olabilecek konumların sayısı yaklaşık 10 üzeri 170 olarak hesaplanmıştır."], "cap": ["Taş alma. Solda: siyah taşın yanında dört boş nokta (kırmızı) var. Ortada: beyaz onu üç yandan kuşatmış, bir nokta kalmış. Sağda: sonuncusu da kapanır ve siyah taş alınır"]}, {"h": "17 çizgiden 19’a", "p": ["Çin’in Hebei eyaletindeki Wangdu’da, Doğu Han dönemine ait bir mezardan 17 çizgili taş bir go tahtası çıktı. Yaklaşık 6. yüzyıla tarihlenen Dunhuang Go Klasiği ise 361 noktadan, yani 19 çizgili tahtadan söz eder. Tahta bu arada büyümüş görünüyor.", "Shōsōin tahtası 19 çizgilidir, ama bugünkü dokuz yıldız noktası yerine 17 yerde çiçek işaretleri taşır. 289 noktadan 361’e geçiş, oyunu çok daha derin yaptı."], "cap": ["17 ve 19 çizgili tahtaların kesişim noktası sayısıyla karşılaştırması. Bugünkü tahtadaki dokuz siyah nokta “yıldız noktaları”dır"]}, {"h": "Ölümsüzlerin go’su, ustaların go’su", "p": ["Bir Çin masalı, dağda ölümsüzlerin go oynayışını seyreden bir oduncunun, kendine geldiğinde baltasının sapı çürüyecek kadar yıl geçtiğini fark ettiğini anlatır. Ölümsüzlerin eğlencesi olarak go, tabaklarda ve resimlerde sevilen bir konuydu.", "Edo Japonya’sında Hon’inbō gibi go aileleri şogunluktan maaş aldı ve go bir sanat olarak inceltildi. Hon’inbō Shūsai’nin 1938’deki veda oyunu, Kawabata Yasunari’nin “Go Ustası” romanına dönüştü. 2016’da yapay zekâ AlphaGo, dünyanın en iyi oyuncusu Lee Sedol’ü 4–1 yenerek dünyayı şaşırttı."], "cap": ["Go oynayan ölümsüzlerin oyulduğu lake tabak (Ming hanedanı, Xuande dönemi, 1425–36)"]}], "tl": [["y. MÖ 4. yy", "Mencius go ustası Yi Qiu’nun adını anar"], ["Doğu Han", "Wangdu’daki bir mezara 17 çizgili taş tahta konur"], ["y. 6. yy", "Dunhuang Go Klasiği 19 çizgi ve 361 noktayı anlatır"], ["8. yy", "Shōsōin’in kakmalı sandal ağacı go tahtası"], ["1612", "Hon’inbō Sansa ve diğerlerinin şogunluktan maaş aldığı anlatılır"], ["1938", "Hon’inbō Shūsai’nin veda oyunu; sonra Kawabata’nın romanı"], ["2016", "AlphaGo, Lee Sedol’ü 4–1 yener"]]}}, "id": {"go": {"kf": ["Batu hitam dan putih diletakkan di titik persilangan garis, berlomba mengepung wilayah terluas — permainan yang lahir di Tiongkok kuno", "Setelah masa papan 17 garis datanglah 19 garis; Shōsōin menyimpan papan 19 garis dari abad ke-8", "Di Jepang zaman Edo keluarga go mengabdi pada keshogunan; pada abad ke-21 AI mengalahkan pemain terbaik dunia"], "more": [{"h": "Kepung untuk menangkap, kurung untuk menang", "p": ["Dalam go, hitam dan putih bergantian meletakkan batu di titik persilangan garis. Batu yang sudah diletakkan tidak bergerak lagi. Bila semua titik kosong di sebelah sebuah batu (atau kelompok) terisi batu lawan, batu itu ditangkap dan diangkat dari papan.", "Pada akhirnya, wilayah yang dikurung ditambah batu tangkapan menentukan pemenang. Aturannya sedikit, tetapi papannya luas: jumlah posisi yang mungkin di papan 19 garis dihitung sekitar 10 pangkat 170."], "cap": ["Cara menangkap batu. Kiri: batu hitam punya empat titik kosong di sebelahnya (merah). Tengah: putih mengepungnya dari tiga sisi, tersisa satu. Kanan: yang terakhir pun tertutup dan batu hitam ditangkap"]}, {"h": "Dari 17 garis ke 19", "p": ["Di makam masa Han Timur di Wangdu, Hebei, Tiongkok, ditemukan papan go batu 17 garis. Sementara itu Kitab Go Dunhuang, yang diperkirakan dari sekitar abad ke-6, menyebut 361 titik — papan 19 garis. Rupanya papan membesar di antara keduanya.", "Papan Shōsōin bergaris 19, tetapi alih-alih sembilan titik bintang masa kini, ia punya tanda bunga di 17 tempat. Peralihan dari 289 ke 361 titik saja sudah membuat permainan jauh lebih dalam."], "cap": ["Papan 17 dan 19 garis dibandingkan menurut jumlah titiknya. Sembilan titik hitam di papan masa kini adalah “titik bintang”"]}, {"h": "Go para dewa, go para master", "p": ["Sebuah kisah Tiongkok bercerita tentang penebang kayu yang berhenti di gunung untuk menonton para dewa bermain go — lalu sadar bahwa begitu banyak tahun telah lewat sampai gagang kapaknya lapuk. Go sebagai hiburan para dewa menjadi tema kesukaan piring dan lukisan.", "Di Jepang zaman Edo, keluarga go seperti Hon’inbō digaji keshogunan dan go diasah menjadi seni. Pertandingan perpisahan Hon’inbō Shūsai pada 1938 menjadi novel Kawabata Yasunari “Sang Master Go”. Pada 2016, AI AlphaGo mengalahkan pemain terbaik dunia Lee Sedol 4–1 dan mengejutkan dunia."], "cap": ["Piring pernis ukir bergambar para dewa bermain go (dinasti Ming, masa Xuande, 1425–36)"]}], "tl": [["Sekitar abad ke-4 SM", "Mencius menyebut master go Yi Qiu"], ["Han Timur", "Papan batu 17 garis dimasukkan ke makam di Wangdu"], ["Sekitar abad ke-6", "Kitab Go Dunhuang menyebut 19 garis dan 361 titik"], ["Abad ke-8", "Papan go cendana bertatah di Shōsōin"], ["1612", "Hon’inbō Sansa dkk. konon menerima gaji dari keshogunan"], ["1938", "Pertandingan perpisahan Hon’inbō Shūsai, kelak novel Kawabata"], ["2016", "AlphaGo mengalahkan Lee Sedol 4–1"]]}}, "hi": {"go": {"kf": ["रेखाओं के मिलन-बिंदुओं पर काले और सफ़ेद पत्थर रखकर ज़्यादा इलाक़ा घेरने की होड़ — प्राचीन चीन में जन्मा खेल", "17 रेखाओं वाले बोर्डों के दौर के बाद 19 रेखाएँ आईं; शोसोइन में 8वीं सदी का 19 रेखाओं वाला बोर्ड है", "एदो जापान में गो घराने शोगुनशाही की सेवा में थे; 21वीं सदी में एक AI ने दुनिया के सबसे अच्छे खिलाड़ी को हराया"], "more": [{"h": "घेरो, पकड़ो, इलाक़ा बढ़ाओ", "p": ["गो में काला और सफ़ेद बारी-बारी से रेखाओं के मिलन-बिंदुओं पर पत्थर रखते हैं। रखा गया पत्थर फिर नहीं हिलता। जब किसी पत्थर (या समूह) के पास के सारे ख़ाली बिंदु विरोधी के पत्थरों से भर जाएँ, तो वह पकड़ा जाता है और बोर्ड से हटा दिया जाता है।", "आख़िर में घेरा गया इलाक़ा और पकड़े गए पत्थर मिलाकर जिसका ज़्यादा हो, वह जीतता है। नियम कम हैं, पर बोर्ड बड़ा है: 19 रेखाओं वाले बोर्ड पर संभव स्थितियों की संख्या लगभग 10 की घात 170 आँकी गई है।"], "cap": ["पत्थर पकड़ने का तरीक़ा। बाएँ: काले पत्थर के पास चार ख़ाली बिंदु (लाल)। बीच में: सफ़ेद ने तीन ओर से घेरा, एक बचा। दाएँ: आख़िरी भी बंद, काला पत्थर पकड़ा गया"]}, {"h": "17 रेखाओं से 19 तक", "p": ["चीन के हबेई प्रांत के वांगदू में पूर्वी हान काल की एक क़ब्र से 17 रेखाओं वाला पत्थर का गो बोर्ड मिला है। वहीं लगभग 6वीं सदी का माना जाने वाला दुनहुआंग का ‘गो ग्रंथ’ 361 बिंदुओं, यानी 19 रेखाओं वाले बोर्ड का वर्णन करता है। लगता है इस बीच बोर्ड बड़ा हुआ।", "शोसोइन का बोर्ड 19 रेखाओं का है, पर आज के नौ तारा-बिंदुओं की जगह उस पर 17 जगह फूलों के निशान हैं। 289 से 361 बिंदु होने भर से खेल कहीं ज़्यादा गहरा हो गया।"], "cap": ["17 और 19 रेखाओं वाले बोर्डों की बिंदुओं की संख्या से तुलना। आज के बोर्ड के नौ काले बिंदु “तारा-बिंदु” हैं"]}, {"h": "अमरों का गो, उस्तादों का गो", "p": ["एक चीनी कथा में एक लकड़हारा पहाड़ पर अमरों को गो खेलते देखता रहता है — और होश आने पर पाता है कि इतने बरस बीत गए कि उसकी कुल्हाड़ी का हत्था सड़ चुका है। अमरों के खेल के रूप में गो तश्तरियों और चित्रों का प्रिय विषय रहा।", "एदो जापान में होनइम्बो जैसे गो घराने शोगुनशाही से वेतन पाते थे, और गो एक कला की तरह निखरा। 1938 में होनइम्बो शूसाई का विदाई मुक़ाबला कावाबाता यासुनारी के उपन्यास ‘द मास्टर ऑफ़ गो’ का आधार बना। 2016 में AI अल्फ़ागो ने दुनिया के शीर्ष खिलाड़ी ली सेडोल को 4–1 से हराकर दुनिया को चौंका दिया।"], "cap": ["गो खेलते अमरों वाली नक़्क़ाशीदार लाख की तश्तरी (मिंग वंश, शुआनदे काल, 1425–36)"]}], "tl": [["लगभग चौथी सदी ई.पू.", "मेंशियस में गो उस्ताद यी चिउ का नाम"], ["पूर्वी हान", "वांगदू की क़ब्र में 17 रेखाओं वाला पत्थर का बोर्ड रखा गया"], ["लगभग 6वीं सदी", "दुनहुआंग का ‘गो ग्रंथ’ 19 रेखाएँ और 361 बिंदु बताता है"], ["8वीं सदी", "शोसोइन का जड़ाऊ चंदन का गो बोर्ड"], ["1612", "कहा जाता है कि होनइम्बो सान्सा आदि को शोगुनशाही से वेतन मिला"], ["1938", "होनइम्बो शूसाई का विदाई मुक़ाबला, बाद में कावाबाता का उपन्यास"], ["2016", "अल्फ़ागो ने ली सेडोल को 4–1 से हराया"]]}}, "ar": {"go": {"kf": ["حجارة سوداء وبيضاء تُوضع على نقاط تقاطع الخطوط، ويتنافس اللاعبان على تطويق أوسع أرض — لعبة وُلدت في الصين القديمة", "بعد عهد ألواح الـ17 خطًا جاءت الـ19؛ ويحفظ شوسوئين لوحًا من 19 خطًا من القرن الثامن", "في يابان إيدو خدمت بيوت الغو الشوغونية، وفي القرن الحادي والعشرين هزم ذكاء اصطناعي أفضل لاعب في العالم"], "more": [{"h": "طوِّق لتأسر، وسيِّج لتفوز", "p": ["في الغو يضع الأسود والأبيض بالتناوب حجارة على نقاط تقاطع الخطوط، ولا يتحرك الحجر بعد وضعه. وإذا امتلأت كل النقاط الخالية المجاورة لحجر (أو مجموعة) بحجارة الخصم أُسر ورُفع عن اللوح.", "وفي النهاية يفوز من كان مجموع أرضه المطوَّقة وأسراه أكبر. القواعد قليلة لكن اللوح واسع: فقد حُسب عدد الأوضاع الممكنة على لوح من 19 خطًا بنحو 10 أس 170."], "cap": ["طريقة الأسر. يسارًا: للحجر الأسود أربع نقاط خالية بجانبه (بالأحمر). وسطًا: الأبيض يطوّقه من ثلاث جهات فتبقى نقطة. يمينًا: تُسدّ الأخيرة فيؤسر الحجر الأسود"]}, {"h": "من 17 خطًا إلى 19", "p": ["عُثر في قبر من عهد هان الشرقية في وانغدو بإقليم خبي الصيني على لوح غو حجري من 17 خطًا. أما «كتاب الغو» من دونهوانغ، المؤرخ بنحو القرن السادس، فيصف 361 نقطة، أي لوحًا من 19 خطًا. ويبدو أن اللوح كبر فيما بينهما.", "لوح شوسوئين من 19 خطًا، لكن بدل نقاط النجوم التسع الحالية فيه علامات زهور في 17 موضعًا. ومجرد الانتقال من 289 نقطة إلى 361 جعل اللعبة أعمق بكثير."], "cap": ["مقارنة لوحي الـ17 والـ19 خطًا بعدد النقاط. النقاط السوداء التسع على لوح اليوم هي «نقاط النجوم»"]}, {"h": "غو الخالدين، وغو الأساتذة", "p": ["تحكي قصة صينية عن حطّاب توقف في الجبل يشاهد خالدين يلعبون الغو، ثم انتبه فإذا بسنين كثيرة قد مضت حتى تعفّن مقبض فأسه. وكان الغو بوصفه تسلية الخالدين موضوعًا محببًا على الأطباق واللوحات.", "وفي يابان إيدو تلقت بيوت الغو مثل هون-إنبو رواتب من الشوغونية، فصُقل الغو فنًا. وصارت مباراة الوداع التي لعبها هون-إنبو شوساي عام 1938 رواية كاواباتا ياسوناري «معلّم الغو». وفي 2016 هزم الذكاء الاصطناعي ألفاغو أفضل لاعب في العالم لي سي-دول بأربع مباريات مقابل واحدة، فأدهش العالم."], "cap": ["طبق من اللك المنحوت عليه خالدون يلعبون الغو (سلالة مينغ، عهد شيوانده، 1425–36)"]}], "tl": [["نحو القرن 4 ق.م", "منشيوس يذكر أستاذ الغو يي تشيو"], ["هان الشرقية", "وضع لوح حجري من 17 خطًا في قبر بوانغدو"], ["نحو القرن 6", "«كتاب الغو» من دونهوانغ يصف 19 خطًا و361 نقطة"], ["القرن 8", "لوح الغو المطعّم من خشب الصندل في شوسوئين"], ["1612", "يُروى أن هون-إنبو سانسا وآخرين تلقوا رواتب من الشوغونية"], ["1938", "مباراة وداع هون-إنبو شوساي، ثم رواية كاواباتا"], ["2016", "ألفاغو يهزم لي سي-دول 4–1"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (20): story 13 (draughts) made fuller */
(T => { const D = {"ja": {"draughts": {"kf": ["アラビアのアルケルケの駒を、チェス盤の上で動かすようになって生まれたゲーム", "ななめに進み、相手の駒を跳びこえて取る。奥まで進めば「成って」強くなる", "1535年ごろ「強制取り」が加わり、2007年には完全に読み切られた"], "more": [{"h": "点と線の盤から、チェス盤へ", "p": ["アルケルケの盤は、5×5の25の点を線で結んだものです。両者が12個ずつ駒を並べ、空いた中央の点から動き始めます。駒は線にそって進み、となりの相手の駒を跳びこえて取ります。", "この駒をチェス盤の上に移すとき、使うのは片方の色のマスだけになりました。8×8の盤の黒いマスは32。それぞれ手前の3列に12個ずつ並べると、駒の数はアルケルケと同じ12個になります。"], "cap": ["アルケルケの盤とはじめの並び。5×5の点を縦・横・ななめの線で結び、12個ずつの駒を置いて中央だけ空ける"]}, {"h": "跳んで取る、成って強くなる", "p": ["駒はななめ前に1マスずつ進み、となりの相手の駒の向こうが空いていれば跳びこえて取ります。取ったあとにまた取れる駒があれば、続けて跳びつづけます。取れる駒があれば必ず取らなければならないのが、今のチェッカーのきまりです。", "相手の陣地のいちばん奥まで進むと、駒を2枚重ねて「キング」になり、後ろにも進めるようになります。10×10の盤で遊ぶ国際ルールでは、キングはななめに何マスでも走れるので、終盤の戦い方ががらりと変わります。"], "cap": ["チェッカーの取り方と成り。赤い駒が白い駒を2つ続けて跳びこえて取り（×）、のちに奥の列に着いて、駒を2枚重ねた「キング」になる"]}, {"h": "読み切られたゲーム、広がる家族", "p": ["カナダのジョナサン・シェーファーらは、チェッカーのプログラム「チヌーク」を作りました。1992年には、40年以上ほとんど負けなかった名人マリオン・ティンズリーと対戦し、ティンズリーが勝っています。シェーファーらはその後も計算を続け、2007年、おたがいが最善を尽くせばチェッカーは引き分けになることを証明しました。", "一方で、同じ祖先から生まれた仲間は世界中に残っています。10×10の国際ルール、ロシアのシャシキ、縦横に動くトルコのダマ、12×12で遊ぶカナダのチェッカーなど、それぞれの国で今も大会が開かれています。"], "cap": []}], "tl": [["10世紀", "『歌の書』にキルク（アルケルケ）の名が出る"], ["12世紀ごろ", "南フランスでフィエルジュが生まれる"], ["1283年", "アルフォンソ10世の『遊戯の書』にアルケルケの遊び方"], ["1535年ごろ", "フランスで「強制取り」が加わる"], ["1547年", "スペインのトルケマーダが、ダマの最初の本を出す"], ["18世紀", "フランスやオランダで10×10の盤が広まる"], ["1992年", "ティンズリーがプログラム「チヌーク」との対戦に勝つ"], ["2007年", "チェッカーは最善を尽くせば引き分けと証明される"]]}}, "en": {"draughts": {"kf": ["Born when the pieces of the Arabic game alquerque were moved onto a chessboard", "Pieces move diagonally and capture by jumping; reach the far row and they promote", "Compulsory capture came in around 1535, and in 2007 the game was solved"], "more": [{"h": "From points and lines to the chessboard", "p": ["An alquerque board is 25 points in a 5 × 5 grid joined by lines. Each side sets out 12 pieces, and play begins from the one empty point in the middle. Pieces move along the lines and capture by jumping over an enemy next to them.", "When the pieces moved onto a chessboard, only the squares of one colour were used. An 8 × 8 board has 32 dark squares; fill the first three rows on each side and you have 12 pieces each — the same number as alquerque."], "cap": ["The alquerque board and its starting position: 5 × 5 points joined by lines across and diagonally, 12 pieces a side, only the centre empty"]}, {"h": "Jump to capture, crown to grow strong", "p": ["Men move one square diagonally forward and capture by jumping an enemy next to them if the square beyond is empty. If another capture is then possible, they keep jumping. In today’s checkers, if you can capture, you must.", "A man that reaches the far row is crowned — a second piece is stacked on it — and as a king it may move backwards too. In the international game on a 10 × 10 board, kings fly any distance along a diagonal, which transforms the endgame."], "cap": ["Capturing and crowning in checkers. The red man jumps two white men in a row (×), and later reaches the far row to become a king, two pieces stacked"]}, {"h": "A solved game and a spreading family", "p": ["In Canada, Jonathan Schaeffer and his team built the checkers program Chinook. In 1992 it played Marion Tinsley, who had barely lost a game in over 40 years, and Tinsley won. The team kept computing, and in 2007 they proved that with perfect play by both sides, checkers is a draw.", "Meanwhile the family descended from the same ancestor lives on worldwide: international draughts on 10 × 10, Russian shashki, Turkish dama with its orthogonal moves, Canadian checkers on 12 × 12 — each still played in tournaments today."], "cap": []}], "tl": [["10th c.", "The Book of Songs names qirq (alquerque)"], ["c. 12th c.", "Fierges is born, probably in southern France"], ["1283", "Alfonso X’s Book of Games describes alquerque"], ["c. 1535", "Compulsory capture is added in France"], ["1547", "Torquemada in Spain publishes the first book on draughts"], ["18th c.", "The 10 × 10 board spreads in France and the Netherlands"], ["1992", "Tinsley beats the program Chinook"], ["2007", "Checkers is proved a draw with perfect play"]]}}, "zh": {"draughts": {"kf": ["把阿拉伯游戏阿尔奎克的棋子搬到国际象棋棋盘上走，由此诞生的游戏", "斜着走，跳过对方棋子吃子；走到底线就“升变”变强", "约1535年加入“强制吃子”，2007年被完全算尽"], "more": [{"h": "从点与线的棋盘到国际象棋棋盘", "p": ["阿尔奎克的棋盘是用线连起的5×5共25个点。双方各摆12枚棋子，从空着的中央那一点开始走。棋子沿线移动，跳过相邻的对方棋子把它吃掉。", "把这些棋子搬到国际象棋棋盘上时，只用一种颜色的格子。8×8棋盘的深色格有32个，双方各在靠自己的3行摆满，就正好是各12枚——和阿尔奎克一样。"], "cap": ["阿尔奎克的棋盘和初始布局：5×5个点用横、竖、斜线相连，双方各摆12枚，只空出中央"]}, {"h": "跳吃与升变", "p": ["棋子每次向斜前方走一格；相邻的对方棋子后面若是空格，就可以跳过去吃掉它。吃完还能再吃，就继续跳。能吃就必须吃，是今天跳棋的规则。", "走到对方底线的棋子叠上第二枚，成为“王”，也能向后走。在10×10棋盘的国际规则里，王可以沿斜线走任意格，残局的打法因此大不相同。"], "cap": ["跳棋的吃子与升变。红子连续跳过两枚白子吃掉（×），之后走到底线，叠上第二枚成为“王”"]}, {"h": "被算尽的游戏，扩散的家族", "p": ["加拿大的乔纳森·谢弗等人做出了跳棋程序“奇努克”。1992年它与40多年几乎没输过的名手马里恩·廷斯利对战，廷斯利获胜。谢弗等人继续计算，2007年证明：双方都下出最佳着法时，跳棋是和棋。", "另一方面，同一祖先的家族成员遍布世界：10×10的国际跳棋、俄罗斯的沙什基、横竖走的土耳其达马、12×12的加拿大跳棋等，在各国至今都有比赛。"], "cap": []}], "tl": [["10世纪", "《诗歌集》中出现基尔克（阿尔奎克）之名"], ["约12世纪", "菲耶尔日大概诞生于法国南部"], ["1283年", "阿方索十世的《游戏之书》记载阿尔奎克的玩法"], ["约1535年", "法国加入“强制吃子”"], ["1547年", "西班牙的托尔克马达出版第一本跳棋书"], ["18世纪", "10×10棋盘在法国和荷兰流行"], ["1992年", "廷斯利战胜程序“奇努克”"], ["2007年", "证明跳棋在最佳着法下为和棋"]]}}, "zh-TW": {"draughts": {"kf": ["把阿拉伯遊戲阿爾奎克的棋子搬到西洋棋棋盤上走，由此誕生的遊戲", "斜著走，跳過對方棋子吃子；走到底線就「升變」變強", "約1535年加入「強制吃子」，2007年被完全算盡"], "more": [{"h": "從點與線的棋盤到西洋棋棋盤", "p": ["阿爾奎克的棋盤是用線連起的5×5共25個點。雙方各擺12枚棋子，從空著的中央那一點開始走。棋子沿線移動，跳過相鄰的對方棋子把它吃掉。", "把這些棋子搬到西洋棋棋盤上時，只用一種顏色的格子。8×8棋盤的深色格有32個，雙方各在靠自己的3行擺滿，就正好是各12枚——和阿爾奎克一樣。"], "cap": ["阿爾奎克的棋盤和初始佈局：5×5個點用橫、豎、斜線相連，雙方各擺12枚，只空出中央"]}, {"h": "跳吃與升變", "p": ["棋子每次向斜前方走一格；相鄰的對方棋子後面若是空格，就可以跳過去吃掉它。吃完還能再吃，就繼續跳。能吃就必須吃，是今天跳棋的規則。", "走到對方底線的棋子疊上第二枚，成為「王」，也能向後走。在10×10棋盤的國際規則裡，王可以沿斜線走任意格，殘局的打法因此大不相同。"], "cap": ["跳棋的吃子與升變。紅子連續跳過兩枚白子吃掉（×），之後走到底線，疊上第二枚成為「王」"]}, {"h": "被算盡的遊戲，擴散的家族", "p": ["加拿大的喬納森·謝弗等人做出了跳棋程式「奇努克」。1992年它與40多年幾乎沒輸過的名手馬里恩·廷斯利對戰，廷斯利獲勝。謝弗等人繼續計算，2007年證明：雙方都下出最佳著法時，跳棋是和棋。", "另一方面，同一祖先的家族成員遍布世界：10×10的國際跳棋、俄羅斯的沙什基、橫豎走的土耳其達馬、12×12的加拿大跳棋等，在各國至今都有比賽。"], "cap": []}], "tl": [["10世紀", "《詩歌集》中出現基爾克（阿爾奎克）之名"], ["約12世紀", "菲耶爾日大概誕生於法國南部"], ["1283年", "阿方索十世的《遊戲之書》記載阿爾奎克的玩法"], ["約1535年", "法國加入「強制吃子」"], ["1547年", "西班牙的托爾克馬達出版第一本跳棋書"], ["18世紀", "10×10棋盤在法國和荷蘭流行"], ["1992年", "廷斯利戰勝程式「奇努克」"], ["2007年", "證明跳棋在最佳著法下為和棋"]]}}, "ko": {"draughts": {"kf": ["아랍의 알케르케 말을 체스판 위에서 움직이게 되면서 생겨난 게임", "대각선으로 나아가고 상대 말을 뛰어넘어 잡는다. 끝까지 가면 ‘승격’해 강해진다", "1535년 무렵 ‘강제 잡기’가 더해졌고, 2007년에는 완전히 풀렸다"], "more": [{"h": "점과 선의 판에서 체스판으로", "p": ["알케르케 판은 5×5, 25개의 점을 선으로 이은 것입니다. 양쪽이 12개씩 말을 놓고, 비어 있는 가운데 점부터 움직이기 시작합니다. 말은 선을 따라 나아가며 옆의 상대 말을 뛰어넘어 잡습니다.", "이 말을 체스판 위로 옮기면서 한쪽 색의 칸만 쓰게 되었습니다. 8×8 판의 검은 칸은 32개. 저마다 자기 앞의 3줄에 채우면 12개씩이 되어, 알케르케와 같은 수가 됩니다."], "cap": ["알케르케 판과 처음 배치. 5×5 점을 가로·세로·대각선으로 잇고, 12개씩 말을 놓아 가운데만 비운다"]}, {"h": "뛰어넘어 잡고, 승격해 강해진다", "p": ["말은 대각선 앞으로 한 칸씩 나아가고, 옆의 상대 말 너머가 비어 있으면 뛰어넘어 잡습니다. 잡은 뒤에도 잡을 말이 있으면 계속 뜁니다. 잡을 수 있으면 반드시 잡아야 하는 것이 지금 체커의 규칙입니다.", "상대 진영 맨 끝까지 가면 말을 두 개 겹쳐 ‘킹’이 되고, 뒤로도 갈 수 있습니다. 10×10 판의 국제 규칙에서는 킹이 대각선으로 몇 칸이든 달릴 수 있어 종반 싸움이 확 달라집니다."], "cap": ["체커의 잡기와 승격. 빨간 말이 흰 말 두 개를 잇달아 뛰어넘어 잡고(×), 나중에 맨 끝 줄에 닿아 말을 두 개 겹친 ‘킹’이 된다"]}, {"h": "풀린 게임, 퍼져 가는 가족", "p": ["캐나다의 조너선 섀퍼 등은 체커 프로그램 ‘치누크’를 만들었습니다. 1992년에는 40년 넘게 거의 지지 않은 명인 매리언 틴슬리와 대결했고, 틴슬리가 이겼습니다. 섀퍼 등은 계산을 이어가, 2007년 양쪽이 최선을 다하면 체커는 무승부가 된다는 것을 증명했습니다.", "한편 같은 조상에서 나온 가족은 세계 곳곳에 남아 있습니다. 10×10 국제 규칙, 러시아의 샤시키, 가로세로로 움직이는 튀르키예의 다마, 12×12로 하는 캐나다 체커 등이 지금도 나라마다 대회를 엽니다."], "cap": []}], "tl": [["10세기", "《노래의 책》에 키르크(알케르케)의 이름이 나옴"], ["12세기 무렵", "남프랑스에서 피에르주가 생겨남"], ["1283년", "알폰소 10세의 『놀이의 책』에 알케르케 놀이법"], ["1535년 무렵", "프랑스에서 ‘강제 잡기’가 더해짐"], ["1547년", "스페인의 토르케마다가 다마에 관한 첫 책을 냄"], ["18세기", "프랑스와 네덜란드에서 10×10 판이 퍼짐"], ["1992년", "틴슬리가 프로그램 ‘치누크’와의 대결에서 승리"], ["2007년", "최선을 다하면 체커는 무승부임이 증명됨"]]}}, "es": {"draughts": {"kf": ["Nació cuando las piezas del juego árabe del alquerque pasaron a un tablero de ajedrez", "Las piezas avanzan en diagonal y capturan saltando; al llegar a la última fila, coronan", "Hacia 1535 llegó la captura obligatoria, y en 2007 el juego quedó resuelto"], "more": [{"h": "De puntos y líneas al tablero de ajedrez", "p": ["El tablero de alquerque son 25 puntos en una cuadrícula de 5 × 5 unidos por líneas. Cada bando coloca 12 piezas y se empieza desde el único punto vacío del centro. Las piezas avanzan por las líneas y capturan saltando sobre una enemiga contigua.", "Al pasar las piezas a un tablero de ajedrez, solo se usaron las casillas de un color. Un tablero de 8 × 8 tiene 32 casillas oscuras; llenando las tres primeras filas de cada lado salen 12 piezas por bando: las mismas que en el alquerque."], "cap": ["El tablero de alquerque y su posición inicial: 5 × 5 puntos unidos por líneas rectas y diagonales, 12 piezas por bando y solo el centro vacío"]}, {"h": "Saltar para capturar, coronar para crecer", "p": ["Las piezas avanzan una casilla en diagonal y capturan saltando sobre una enemiga contigua si la casilla de detrás está libre. Si después pueden capturar otra, siguen saltando. En las damas actuales, si se puede capturar, hay que hacerlo.", "La pieza que llega a la última fila corona —se le pone otra encima— y, como dama, puede ir también hacia atrás. En el juego internacional de 10 × 10, la dama recorre cualquier distancia en diagonal, lo que transforma el final."], "cap": ["Captura y coronación. La pieza roja salta dos blancas seguidas (×) y después llega a la última fila para convertirse en dama, con dos piezas apiladas"]}, {"h": "Un juego resuelto y una familia que crece", "p": ["En Canadá, Jonathan Schaeffer y su equipo crearon el programa de damas Chinook. En 1992 se enfrentó a Marion Tinsley, que en más de 40 años apenas había perdido partidas, y ganó Tinsley. El equipo siguió calculando y en 2007 demostró que, si ambos juegan perfectamente, las damas acaban en tablas.", "Mientras tanto, la familia del mismo antepasado sigue viva en todo el mundo: las damas internacionales de 10 × 10, las shashki rusas, la dama turca de movimientos ortogonales, las damas canadienses de 12 × 12… y en cada país se siguen jugando torneos."], "cap": []}], "tl": [["s. X", "El Libro de las canciones nombra el qirq (alquerque)"], ["h. s. XII", "Nace el fierges, probablemente en el sur de Francia"], ["1283", "El Libro de los juegos de Alfonso X describe el alquerque"], ["h. 1535", "En Francia se añade la captura obligatoria"], ["1547", "Torquemada publica en España el primer libro de damas"], ["s. XVIII", "El tablero de 10 × 10 se extiende por Francia y los Países Bajos"], ["1992", "Tinsley vence al programa Chinook"], ["2007", "Se demuestra que las damas son tablas con juego perfecto"]]}}, "fr": {"draughts": {"kf": ["Né quand les pions du jeu arabe de l’alquerque passèrent sur un échiquier", "Les pions avancent en diagonale et prennent en sautant ; arrivés au fond, ils vont à dame", "La prise obligatoire apparut vers 1535, et le jeu (sur 8 × 8) a été résolu en 2007"], "more": [{"h": "Des points et des lignes à l’échiquier", "p": ["Le plateau d’alquerque compte 25 points en grille de 5 × 5, reliés par des lignes. Chaque camp place 12 pions, et la partie commence à partir du seul point vide, au centre. Les pions suivent les lignes et prennent en sautant par-dessus un pion adverse voisin.", "Quand les pions passèrent sur un échiquier, on n’utilisa plus que les cases d’une couleur. Un damier de 8 × 8 a 32 cases sombres ; en remplissant les trois premières rangées de chaque côté, on obtient 12 pions par camp — comme à l’alquerque."], "cap": ["Le plateau d’alquerque et sa position de départ : 5 × 5 points reliés par des lignes droites et diagonales, 12 pions par camp, seul le centre vide"]}, {"h": "Sauter pour prendre, aller à dame", "p": ["Les pions avancent d’une case en diagonale et prennent en sautant un pion adverse voisin si la case suivante est libre. Si une autre prise est alors possible, ils continuent de sauter. Aujourd’hui, si l’on peut prendre, on doit prendre.", "Le pion qui atteint la dernière rangée va à dame — on pose un second pion dessus — et peut alors reculer. Aux dames internationales sur 10 × 10, la dame parcourt toute une diagonale, ce qui change tout dans les finales."], "cap": ["Prise et promotion aux dames anglaises. Le pion rouge saute deux pions blancs d’affilée (×), puis atteint la dernière rangée et devient dame : deux pions empilés"]}, {"h": "Un jeu résolu, une famille qui s’étend", "p": ["Au Canada, Jonathan Schaeffer et son équipe créèrent le programme Chinook pour les dames anglaises. En 1992, il affronta Marion Tinsley, qui n’avait presque pas perdu en plus de 40 ans, et Tinsley l’emporta. L’équipe poursuivit ses calculs et prouva en 2007 qu’avec un jeu parfait des deux côtés, la partie est nulle.", "Pendant ce temps, la famille issue du même ancêtre vit partout : dames internationales sur 10 × 10, chachki russes, dama turque aux déplacements orthogonaux, dames canadiennes sur 12 × 12… avec des tournois dans chaque pays."], "cap": []}], "tl": [["Xe s.", "Le Livre des chansons nomme le qirq (alquerque)"], ["vers le XIIe s.", "Naissance du fierges, sans doute dans le sud de la France"], ["1283", "Le Livre des jeux d’Alphonse X décrit l’alquerque"], ["vers 1535", "La prise obligatoire apparaît en France"], ["1547", "Torquemada publie en Espagne le premier livre sur les dames"], ["XVIIIe s.", "Le damier de 10 × 10 se répand en France et aux Pays-Bas"], ["1992", "Tinsley bat le programme Chinook"], ["2007", "Preuve que les dames anglaises sont nulles avec un jeu parfait"]]}}, "pt": {"draughts": {"kf": ["Nasceu quando as peças do jogo árabe alquerque passaram para um tabuleiro de xadrez", "As peças andam na diagonal e capturam saltando; ao chegar à última fileira, viram dama", "A captura obrigatória surgiu por volta de 1535, e em 2007 o jogo (8 × 8) foi resolvido"], "more": [{"h": "Dos pontos e linhas ao tabuleiro de xadrez", "p": ["O tabuleiro de alquerque são 25 pontos numa grade de 5 × 5 ligados por linhas. Cada lado põe 12 peças, e o jogo começa pelo único ponto vazio, no centro. As peças andam pelas linhas e capturam saltando sobre uma inimiga vizinha.", "Quando as peças passaram para o tabuleiro de xadrez, passou-se a usar só as casas de uma cor. Um tabuleiro de 8 × 8 tem 32 casas escuras; preenchendo as três primeiras fileiras de cada lado, dá 12 peças para cada um — o mesmo que no alquerque."], "cap": ["O tabuleiro de alquerque e sua posição inicial: 5 × 5 pontos ligados por linhas retas e diagonais, 12 peças de cada lado, só o centro vazio"]}, {"h": "Saltar para capturar, virar dama", "p": ["As peças avançam uma casa na diagonal e capturam saltando sobre uma inimiga vizinha se a casa seguinte estiver livre. Se depois houver outra captura, continuam saltando. Nas damas de hoje, se é possível capturar, é obrigatório.", "A peça que chega à última fileira vira dama — põe-se outra peça por cima — e pode também andar para trás. No jogo internacional de 10 × 10, a dama percorre qualquer distância na diagonal, o que transforma os finais."], "cap": ["Captura e promoção. A peça vermelha salta duas brancas seguidas (×) e depois chega à última fileira e vira dama, com duas peças empilhadas"]}, {"h": "Um jogo resolvido e uma família que se espalha", "p": ["No Canadá, Jonathan Schaeffer e sua equipe criaram o programa Chinook. Em 1992 ele enfrentou Marion Tinsley, que em mais de 40 anos quase não perdera partidas, e Tinsley venceu. A equipe continuou calculando e em 2007 provou que, com jogo perfeito dos dois lados, o jogo (de 8 × 8) termina empatado.", "Enquanto isso, a família do mesmo ancestral segue viva no mundo todo: damas internacionais de 10 × 10, as shashki russas, a dama turca de movimentos ortogonais, as damas canadenses de 12 × 12… com torneios em cada país."], "cap": []}], "tl": [["séc. X", "O Livro das Canções cita o qirq (alquerque)"], ["c. séc. XII", "Nasce o fierges, provavelmente no sul da França"], ["1283", "O Livro dos Jogos de Afonso X descreve o alquerque"], ["c. 1535", "A captura obrigatória surge na França"], ["1547", "Torquemada publica na Espanha o primeiro livro sobre damas"], ["séc. XVIII", "O tabuleiro de 10 × 10 se espalha na França e nos Países Baixos"], ["1992", "Tinsley vence o programa Chinook"], ["2007", "Prova-se que o jogo (8 × 8) é empate com jogo perfeito"]]}}, "de": {"draughts": {"kf": ["Entstanden, als die Steine des arabischen Alquerque auf ein Schachbrett wanderten", "Die Steine ziehen schräg und schlagen durch Überspringen; in der letzten Reihe werden sie zur Dame", "Um 1535 kam der Schlagzwang hinzu, 2007 wurde das Spiel (8 × 8) gelöst"], "more": [{"h": "Von Punkten und Linien zum Schachbrett", "p": ["Ein Alquerque-Brett besteht aus 25 Punkten im 5 × 5-Raster, durch Linien verbunden. Jede Seite stellt 12 Steine auf, und das Spiel beginnt vom einzigen freien Punkt in der Mitte aus. Die Steine ziehen entlang der Linien und schlagen durch Überspringen eines benachbarten Gegners.", "Als die Steine aufs Schachbrett wanderten, nutzte man nur noch die Felder einer Farbe. Ein 8 × 8-Brett hat 32 dunkle Felder; füllt man auf jeder Seite die ersten drei Reihen, hat jeder 12 Steine – genau wie beim Alquerque."], "cap": ["Das Alquerque-Brett mit Anfangsstellung: 5 × 5 Punkte, verbunden durch gerade und schräge Linien, je 12 Steine, nur die Mitte frei"]}, {"h": "Springen, schlagen, Dame werden", "p": ["Die Steine ziehen ein Feld schräg vorwärts und schlagen, indem sie einen benachbarten Gegner überspringen, wenn das Feld dahinter frei ist. Ist danach ein weiterer Schlag möglich, springen sie weiter. Im heutigen Spiel gilt: Wer schlagen kann, muss schlagen.", "Ein Stein, der die letzte Reihe erreicht, wird zur Dame – ein zweiter Stein kommt obendrauf – und darf dann auch rückwärts ziehen. Im internationalen Spiel auf 10 × 10 Feldern zieht die Dame beliebig weit schräg, was das Endspiel völlig verändert."], "cap": ["Schlagen und Damewerden. Der rote Stein überspringt zwei weiße hintereinander (×), erreicht später die letzte Reihe und wird zur Dame – zwei Steine übereinander"]}, {"h": "Ein gelöstes Spiel und eine wachsende Familie", "p": ["In Kanada entwickelten Jonathan Schaeffer und sein Team das Programm Chinook. 1992 spielte es gegen Marion Tinsley, der in über 40 Jahren kaum eine Partie verloren hatte – und Tinsley gewann. Das Team rechnete weiter und bewies 2007, dass das Spiel (8 × 8) bei perfektem Spiel beider Seiten remis endet.", "Unterdessen lebt die Familie desselben Vorfahren überall weiter: internationale Dame auf 10 × 10, russische Schaschki, türkische Dama mit geraden Zügen, kanadische Dame auf 12 × 12 – mit Turnieren in jedem Land."], "cap": []}], "tl": [["10. Jh.", "Das Buch der Lieder nennt Qirq (Alquerque)"], ["um 12. Jh.", "Fierges entsteht, wohl in Südfrankreich"], ["1283", "Alfons’ X. Buch der Spiele beschreibt Alquerque"], ["um 1535", "In Frankreich kommt der Schlagzwang hinzu"], ["1547", "Torquemada veröffentlicht in Spanien das erste Buch über Dame"], ["18. Jh.", "Das 10 × 10-Brett verbreitet sich in Frankreich und den Niederlanden"], ["1992", "Tinsley besiegt das Programm Chinook"], ["2007", "Beweis: Das Spiel (8 × 8) ist bei perfektem Spiel remis"]]}}, "ru": {"draughts": {"kf": ["Появились, когда фишки арабской игры алькерк перенесли на шахматную доску", "Шашки ходят по диагонали и бьют, перепрыгивая; дойдя до последнего ряда, становятся дамками", "Около 1535 года добавилось обязательное взятие, а в 2007 году игра (8 × 8) была решена"], "more": [{"h": "От точек и линий к шахматной доске", "p": ["Доска алькерка — это 25 точек в сетке 5 × 5, соединённых линиями. Каждая сторона ставит 12 фишек, игра начинается с единственной пустой точки в центре. Фишки ходят по линиям и бьют, перепрыгивая через соседнюю фишку противника.", "Когда фишки перенесли на шахматную доску, стали использовать только клетки одного цвета. На доске 8 × 8 — 32 тёмных поля; если заполнить по три первых ряда с каждой стороны, у каждого выйдет по 12 шашек — как в алькерке."], "cap": ["Доска алькерка и начальная расстановка: 5 × 5 точек, соединённых прямыми и диагональными линиями, по 12 фишек, пуст только центр"]}, {"h": "Прыжок, взятие, дамка", "p": ["Шашки ходят на одно поле по диагонали вперёд и бьют, перепрыгивая через соседнюю шашку противника, если поле за ней свободно. Если затем можно бить снова, прыжки продолжаются. В нынешних правилах бить обязательно.", "Шашка, дошедшая до последнего ряда, становится дамкой — сверху кладут вторую — и может ходить и назад. В международных шашках на доске 10 × 10 дамка ходит на любое расстояние по диагонали, что совершенно меняет эндшпиль."], "cap": ["Взятие и превращение. Красная шашка бьёт две белые подряд (×), а потом доходит до последнего ряда и становится дамкой — две шашки друг на друге"]}, {"h": "Решённая игра и растущая семья", "p": ["В Канаде Джонатан Шеффер с коллегами создал программу «Чинук». В 1992 году она играла с Марионом Тинсли, который за 40 с лишним лет почти не проигрывал, и Тинсли победил. Команда продолжила расчёты и в 2007 году доказала, что при безошибочной игре обеих сторон партия (8 × 8) заканчивается вничью.", "А семья от того же предка живёт по всему миру: международные шашки 10 × 10, русские шашки, турецкая дама с ходами по вертикали и горизонтали, канадские шашки 12 × 12 — и в каждой стране проходят турниры."], "cap": []}], "tl": [["X в.", "В «Книге песен» упоминается кирк (алькерк)"], ["ок. XII в.", "Появляется фьерж, вероятно на юге Франции"], ["1283", "«Книга игр» Альфонсо X описывает алькерк"], ["ок. 1535", "Во Франции вводят обязательное взятие"], ["1547", "Торкемада издаёт в Испании первую книгу о шашках"], ["XVIII в.", "Доска 10 × 10 распространяется во Франции и Нидерландах"], ["1992", "Тинсли побеждает программу «Чинук»"], ["2007", "Доказано: при идеальной игре шашки 8 × 8 — ничья"]]}}, "tr": {"draughts": {"kf": ["Arap oyunu alkerkin taşları satranç tahtasına taşınınca doğdu", "Taşlar çapraz ilerler ve atlayarak alır; son sıraya varınca dama olur", "1535 dolaylarında zorunlu alma eklendi; 2007’de oyun (8 × 8) çözüldü"], "more": [{"h": "Nokta ve çizgilerden satranç tahtasına", "p": ["Alkerk tahtası, 5 × 5 ızgarada çizgilerle birleştirilmiş 25 noktadır. Her taraf 12 taş dizer ve oyun ortadaki tek boş noktadan başlar. Taşlar çizgiler boyunca ilerler ve yanındaki rakip taşın üzerinden atlayarak onu alır.", "Taşlar satranç tahtasına geçince yalnız bir renkteki kareler kullanılır oldu. 8 × 8 tahtada 32 koyu kare vardır; her iki yanda ilk üç sıra doldurulunca taraf başına 12 taş eder — alkerkle aynı sayı."], "cap": ["Alkerk tahtası ve başlangıç dizilişi: düz ve çapraz çizgilerle birleşen 5 × 5 nokta, her yanda 12 taş, yalnız orta boş"]}, {"h": "Atla, al, dama ol", "p": ["Taşlar çaprazına bir kare ilerler; yanındaki rakip taşın arkası boşsa onun üzerinden atlayarak alır. Ardından başka bir alma mümkünse atlamaya devam eder. Bugünkü kurala göre alabiliyorsan almak zorundasın.", "Son sıraya varan taşın üstüne ikinci bir taş konur ve dama olur; artık geri de gidebilir. 10 × 10 tahtadaki uluslararası oyunda dama çapraz boyunca istediği kadar uzağa gider ve bu, oyun sonunu tümüyle değiştirir."], "cap": ["Alma ve dama olma. Kırmızı taş iki beyaz taşı art arda atlayarak alır (×), sonra son sıraya varıp üst üste iki taştan oluşan dama olur"]}, {"h": "Çözülmüş bir oyun, büyüyen bir aile", "p": ["Kanada’da Jonathan Schaeffer ve ekibi Chinook adlı programı yaptı. Program 1992’de, 40 yılı aşkın sürede neredeyse hiç yenilmemiş usta Marion Tinsley ile oynadı ve Tinsley kazandı. Ekip hesaplamayı sürdürdü ve 2007’de, iki taraf da kusursuz oynarsa oyunun (8 × 8) berabere bittiğini kanıtladı.", "Bu arada aynı atadan gelen aile dünyanın her yerinde yaşıyor: 10 × 10 uluslararası dama, Rus şaşkisi, düz hareket eden Türk daması, 12 × 12 Kanada daması… ve her ülkede turnuvalar sürüyor."], "cap": []}], "tl": [["10. yy", "Şarkılar Kitabı’nda kırk (alkerk) adı geçer"], ["y. 12. yy", "Fierges muhtemelen güney Fransa’da doğar"], ["1283", "X. Alfonso’nun Oyunlar Kitabı alkerki anlatır"], ["y. 1535", "Fransa’da zorunlu alma eklenir"], ["1547", "Torquemada İspanya’da dama üzerine ilk kitabı yayımlar"], ["18. yy", "10 × 10 tahta Fransa’da ve Hollanda’da yayılır"], ["1992", "Tinsley, Chinook programını yener"], ["2007", "Oyunun (8 × 8) kusursuz oyunla berabere olduğu kanıtlanır"]]}}, "id": {"draughts": {"kf": ["Lahir ketika bidak permainan Arab alquerque dipindahkan ke papan catur", "Bidak bergerak diagonal dan menangkap dengan melompat; sampai di baris terakhir, ia menjadi raja", "Sekitar 1535 ditambahkan wajib menangkap, dan pada 2007 permainan (8 × 8) terpecahkan"], "more": [{"h": "Dari titik dan garis ke papan catur", "p": ["Papan alquerque terdiri atas 25 titik dalam kisi 5 × 5 yang dihubungkan garis. Tiap pihak menata 12 bidak, dan permainan dimulai dari satu-satunya titik kosong di tengah. Bidak bergerak menyusuri garis dan menangkap dengan melompati bidak lawan di sebelahnya.", "Ketika bidak dipindahkan ke papan catur, hanya petak satu warna yang dipakai. Papan 8 × 8 punya 32 petak gelap; bila tiga baris pertama di tiap sisi diisi, masing-masing mendapat 12 bidak — sama dengan alquerque."], "cap": ["Papan alquerque dan susunan awalnya: 5 × 5 titik dihubungkan garis lurus dan diagonal, 12 bidak per pihak, hanya bagian tengah kosong"]}, {"h": "Melompat, menangkap, menjadi raja", "p": ["Bidak maju satu petak secara diagonal dan menangkap dengan melompati bidak lawan di sebelahnya bila petak di baliknya kosong. Bila setelah itu ada tangkapan lain, ia terus melompat. Dalam aturan sekarang, jika bisa menangkap, wajib menangkap.", "Bidak yang mencapai baris terakhir menjadi raja — bidak kedua ditumpuk di atasnya — dan boleh bergerak mundur. Dalam permainan internasional 10 × 10, raja meluncur sejauh apa pun di diagonal, sehingga babak akhir berubah total."], "cap": ["Menangkap dan menjadi raja. Bidak merah melompati dua bidak putih berturut-turut (×), lalu kelak mencapai baris terakhir dan menjadi raja: dua bidak bertumpuk"]}, {"h": "Permainan yang terpecahkan, keluarga yang meluas", "p": ["Di Kanada, Jonathan Schaeffer dan timnya membuat program Chinook. Pada 1992 program itu melawan Marion Tinsley, yang lebih dari 40 tahun nyaris tak pernah kalah, dan Tinsley menang. Tim itu terus menghitung dan pada 2007 membuktikan bahwa bila kedua pihak bermain sempurna, permainan (8 × 8) berakhir remis.", "Sementara itu, keluarga dari leluhur yang sama hidup di seluruh dunia: dam internasional 10 × 10, shashki Rusia, dama Turki yang bergerak lurus, dam Kanada 12 × 12 — dan turnamen terus digelar di tiap negara."], "cap": []}], "tl": [["Abad ke-10", "Kitab Lagu menyebut qirq (alquerque)"], ["Sekitar abad ke-12", "Fierges lahir, mungkin di Prancis selatan"], ["1283", "Kitab Permainan Alfonso X menjelaskan alquerque"], ["Sekitar 1535", "Aturan wajib menangkap ditambahkan di Prancis"], ["1547", "Torquemada menerbitkan buku dam pertama di Spanyol"], ["Abad ke-18", "Papan 10 × 10 menyebar di Prancis dan Belanda"], ["1992", "Tinsley mengalahkan program Chinook"], ["2007", "Terbukti permainan (8 × 8) remis bila dimainkan sempurna"]]}}, "hi": {"draughts": {"kf": ["अरबी खेल अल्केर्के की गोटियाँ जब शतरंज के बोर्ड पर आईं, तब यह खेल जन्मा", "गोटियाँ तिरछी चलती हैं और कूदकर मारती हैं; आख़िरी पंक्ति तक पहुँचकर राजा बनती हैं", "लगभग 1535 में ‘मारना ज़रूरी’ का नियम जुड़ा, और 2007 में खेल (8 × 8) हल हो गया"], "more": [{"h": "बिंदु और रेखाओं से शतरंज के बोर्ड तक", "p": ["अल्केर्के का बोर्ड 5 × 5 जाल में रेखाओं से जुड़े 25 बिंदुओं का होता है। दोनों ओर 12-12 गोटियाँ रखी जाती हैं और खेल बीच के एकमात्र ख़ाली बिंदु से शुरू होता है। गोटियाँ रेखाओं पर चलती हैं और पास की विरोधी गोटी के ऊपर से कूदकर उसे मारती हैं।", "जब गोटियाँ शतरंज के बोर्ड पर आईं, तो सिर्फ़ एक रंग के खाने इस्तेमाल होने लगे। 8 × 8 बोर्ड पर 32 गहरे खाने होते हैं; दोनों ओर की पहली तीन पंक्तियाँ भरें तो हर पक्ष की 12 गोटियाँ बनती हैं — ठीक अल्केर्के जितनी।"], "cap": ["अल्केर्के का बोर्ड और शुरुआती जमावट: सीधी और तिरछी रेखाओं से जुड़े 5 × 5 बिंदु, हर ओर 12 गोटियाँ, सिर्फ़ बीच ख़ाली"]}, {"h": "कूदो, मारो, राजा बनो", "p": ["गोटियाँ तिरछे आगे एक खाना चलती हैं, और पास की विरोधी गोटी के पीछे का खाना ख़ाली हो तो उसके ऊपर से कूदकर उसे मारती हैं। उसके बाद फिर मार सकें तो कूदती रहती हैं। आज के नियम में मार सकते हो तो मारना ही पड़ता है।", "आख़िरी पंक्ति तक पहुँची गोटी पर दूसरी गोटी रख दी जाती है और वह राजा बन जाती है; अब वह पीछे भी चल सकती है। 10 × 10 बोर्ड वाले अंतरराष्ट्रीय खेल में राजा तिरछी रेखा पर कितनी भी दूर जा सकता है, जिससे अंत का खेल पूरी तरह बदल जाता है।"], "cap": ["मारना और राजा बनना। लाल गोटी लगातार दो सफ़ेद गोटियों के ऊपर से कूदकर उन्हें मारती है (×), फिर आख़िरी पंक्ति तक पहुँचकर दो गोटियों वाला राजा बनती है"]}, {"h": "हल हुआ खेल, फैलता परिवार", "p": ["कनाडा में जोनाथन शेफ़र और उनकी टीम ने चिनूक नाम का प्रोग्राम बनाया। 1992 में उसने मैरियन टिंसली से मुक़ाबला किया, जो 40 से ज़्यादा बरसों में मुश्किल से कोई बाज़ी हारे थे, और टिंसली जीते। टीम गणना करती रही और 2007 में साबित किया कि दोनों पक्ष बिना चूक खेलें तो खेल (8 × 8) बराबरी पर ख़त्म होता है।", "इस बीच उसी पूर्वज का परिवार दुनिया भर में ज़िंदा है: 10 × 10 का अंतरराष्ट्रीय ड्राफ़्ट्स, रूसी शाश्की, सीधी चाल वाला तुर्की दामा, 12 × 12 का कनाडाई चेकर्स — और हर देश में प्रतियोगिताएँ होती हैं।"], "cap": []}], "tl": [["10वीं सदी", "‘गीतों की किताब’ में क़िर्क़ (अल्केर्के) का नाम"], ["लगभग 12वीं सदी", "शायद दक्षिणी फ़्रांस में फ़ियर्ज का जन्म"], ["1283", "अल्फ़ोंसो दशम की ‘खेलों की किताब’ में अल्केर्के का वर्णन"], ["लगभग 1535", "फ़्रांस में ‘मारना ज़रूरी’ नियम जुड़ा"], ["1547", "स्पेन में तोरकेमादा ने ड्राफ़्ट्स पर पहली किताब छापी"], ["18वीं सदी", "फ़्रांस और नीदरलैंड में 10 × 10 बोर्ड फैला"], ["1992", "टिंसली ने चिनूक प्रोग्राम को हराया"], ["2007", "साबित हुआ कि बिना चूक खेलने पर खेल (8 × 8) बराबरी पर ख़त्म होता है"]]}}, "ar": {"draughts": {"kf": ["وُلدت حين نُقلت قطع اللعبة العربية «القِرْق» إلى رقعة الشطرنج", "تتحرك القطع قطريًا وتأسر بالقفز، وإذا بلغت الصف الأخير صارت «ملكًا»", "أُضيف الأسر الإجباري نحو 1535، وفي 2007 حُلّت اللعبة (8 × 8) حلًا تامًا"], "more": [{"h": "من النقاط والخطوط إلى رقعة الشطرنج", "p": ["لوح القرق 25 نقطة في شبكة 5 × 5 تصل بينها خطوط. يرصّ كل طرف 12 قطعة، وتبدأ اللعبة من النقطة الوحيدة الخالية في الوسط. تتحرك القطع على الخطوط وتأسر بالقفز فوق قطعة للخصم مجاورة لها.", "وحين نُقلت القطع إلى رقعة الشطرنج صار يُستعمل لون واحد من المربعات فقط. في الرقعة 8 × 8 اثنان وثلاثون مربعًا داكنًا، فإذا مُلئت الصفوف الثلاثة الأولى من كل جهة كان لكل طرف 12 قطعة، تمامًا كما في القرق."], "cap": ["لوح القرق ووضعه الابتدائي: 5 × 5 نقاط تصل بينها خطوط مستقيمة وقطرية، و12 قطعة لكل طرف، والوسط وحده خالٍ"]}, {"h": "اقفز وأسر، ثم كن ملكًا", "p": ["تتقدم القطع مربعًا واحدًا قطريًا إلى الأمام، وتأسر بالقفز فوق قطعة للخصم مجاورة إذا كان المربع خلفها خاليًا. وإن أمكن بعدها أسر آخر واصلت القفز. وفي قواعد اليوم: من استطاع الأسر وجب عليه.", "القطعة التي تبلغ الصف الأخير توضع فوقها قطعة ثانية فتصير ملكًا، ويجوز لها عندئذ التراجع. وفي اللعبة الدولية على رقعة 10 × 10 ينطلق الملك أي مسافة على القطر، فيتغير شكل نهاية الدور كليًا."], "cap": ["الأسر والتتويج. القطعة الحمراء تقفز فوق قطعتين بيضاوين متتاليتين فتأسرهما (×)، ثم تبلغ الصف الأخير فتصير ملكًا من قطعتين مكدستين"]}, {"h": "لعبة محلولة وعائلة تتسع", "p": ["في كندا صنع جوناثان شيفر وفريقه برنامج «تشينوك». وفي 1992 لاعب البرنامج ماريون تينسلي، الذي لم يكد يُهزم طوال أكثر من 40 عامًا، ففاز تينسلي. وواصل الفريق الحساب، وأثبت في 2007 أن اللعبة (8 × 8) تنتهي بالتعادل إذا لعب الطرفان لعبًا مثاليًا.", "وفي الأثناء تعيش العائلة المتحدرة من السلف نفسه في أنحاء العالم: الداما الدولية 10 × 10، والشاشكي الروسية، والداما التركية بحركاتها المستقيمة، والداما الكندية 12 × 12… وتُقام لها البطولات في كل بلد."], "cap": []}], "tl": [["القرن 10", "«كتاب الأغاني» يذكر القِرْق"], ["نحو القرن 12", "نشأة «الفييرج»، على الأرجح في جنوب فرنسا"], ["1283", "«كتاب الألعاب» لألفونسو العاشر يصف القرق"], ["نحو 1535", "إضافة الأسر الإجباري في فرنسا"], ["1547", "توركيمادا ينشر في إسبانيا أول كتاب عن الداما"], ["القرن 18", "انتشار رقعة 10 × 10 في فرنسا وهولندا"], ["1992", "تينسلي يهزم برنامج «تشينوك»"], ["2007", "إثبات أن اللعبة (8 × 8) تعادل باللعب المثالي"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (21): story 14 (reversi) made fuller */
(T => { const D = {"ja": {"reversi": {"kf": ["相手の石を自分の石ではさんで裏返し、最後に石の多いほうが勝つゲーム", "1880年代のロンドンで、2人のイギリス人が発明者の座を争った", "1970年代に日本で「オセロ」として大流行し、2023年には最善なら引き分けと示された"], "more": [{"h": "はさんで裏返す", "p": ["石は、相手の石を自分の石ではさめるマスにしか置けません。はさむ向きは縦・横・ななめの8方向で、一度に何方向でもはさめます。はさまれた石はすべて裏返って自分の色になります。", "置けるマスがなければパスし、2人とも置けなくなったら終わりです。四すみの石は二度とはさまれないので、すみを取るとぐっと有利になります。目先の枚数より、相手の打てる場所を減らすほうが大事だとされています。"], "cap": ["石を置いて裏返すしくみ。赤い輪のマスに黒を置くと、横・縦・ななめの3方向で白をはさみ、金の縁の7つの白がすべて黒に変わる"]}, {"h": "最初の4つの石", "p": ["初期のリバーシでは、はじめの4つの石を、2人が中央の4マスに順に置いていきました。そのため、同じ色が横に並ぶ形にも、交差する形にもなりえました。", "オセロは、はじめの4つを交差させて置く形に決めました。はじめから黒白どちらの石もはさみやすく、序盤から激しい攻め合いになります。今の世界大会も、この形から始まります。"], "cap": ["はじめの4つの石。左：初期のリバーシの並べ方の一例（同じ色が横に並ぶ）。右：オセロで決められた、交差させる並べ方"]}, {"h": "人間とコンピュータ", "p": ["オセロは日本から世界に広まり、1977年には東京で第1回の世界選手権が開かれました。ルールが簡単なぶん読みの深さで差がつき、強い選手は何十手も先を読みます。", "1997年、プログラム「ロジステロ」が世界チャンピオンの村上健と6局戦い、6戦全勝しました。2023年には、8×8のオセロはおたがいが最善を尽くせば引き分けになることが、計算によって示されています。"], "cap": []}], "tl": [["1880年代", "ロンドンでウォーターマンとモレットが発明を争う"], ["1893年", "ドイツのラーベンスブルガー社がリバーシを売り出す"], ["明治時代", "日本の本に「源平碁」として紹介される"], ["1973年", "日本で「オセロ」のセットが発売される"], ["1977年", "東京で第1回世界オセロ選手権"], ["1997年", "ロジステロが世界チャンピオン村上健に6戦全勝"], ["2023年", "8×8のオセロは最善なら引き分けと示される"]]}}, "en": {"reversi": {"kf": ["Trap your opponent’s discs between your own to turn them over; whoever has more discs at the end wins", "In 1880s London, two Englishmen fought over who had invented it", "It became a craze in Japan in the 1970s as Othello, and in 2023 it was shown to be a draw with perfect play"], "more": [{"h": "Bracket and flip", "p": ["You may only place a disc where it traps a line of your opponent’s discs between it and one of your own. Lines run in eight directions — across, up and down, and diagonally — and one move can trap several at once. Every trapped disc is turned over to your colour.", "If you have no legal move you pass, and the game ends when neither player can move. Corner discs can never be trapped, so taking a corner is a big advantage. Strong players care less about the number of discs now than about limiting where the opponent can play."], "cap": ["How discs flip. Black placed on the square ringed in red brackets white in three directions — across, down and diagonally — and all seven gold-rimmed discs turn black"]}, {"h": "The first four discs", "p": ["In early reversi, the two players took turns placing the first four discs on the four central squares, so the opening could be side by side or crosswise.", "Othello fixed the crosswise start. From the first move both colours are easy to trap, so the fight begins at once. World championships today start from this position."], "cap": ["The first four discs. Left: one way early reversi could begin, with the same colours side by side. Right: the crosswise start fixed by Othello"]}, {"h": "Humans and computers", "p": ["Othello spread from Japan to the world, and the first World Othello Championship was held in Tokyo in 1977. The rules are simple, so depth of reading makes the difference; strong players see dozens of moves ahead.", "In 1997 the program Logistello played world champion Takeshi Murakami six games and won all six. In 2023 computation showed that 8 × 8 Othello is a draw when both sides play perfectly."], "cap": []}], "tl": [["1880s", "Waterman and Mollett fight over the invention in London"], ["1893", "Ravensburger in Germany brings out Reversi"], ["Meiji era", "Japanese books introduce it as genpei-go"], ["1973", "Othello sets go on sale in Japan"], ["1977", "First World Othello Championship, in Tokyo"], ["1997", "Logistello beats world champion Takeshi Murakami 6–0"], ["2023", "8 × 8 Othello is shown to be a draw with perfect play"]]}}, "zh": {"reversi": {"kf": ["用自己的棋子夹住对方棋子并翻面，最后棋子多的一方获胜", "19世纪80年代的伦敦，两个英国人争夺发明者之名", "20世纪70年代以“奥赛罗”之名在日本风靡，2023年被证明在最佳下法下为和棋"], "more": [{"h": "夹住就翻面", "p": ["只能在能用自己的棋子夹住对方棋子的格子落子。夹的方向有横、竖、斜共8个，一步可以同时夹住好几个方向。被夹住的棋子全部翻成自己的颜色。", "没有可落的格子就弃权，双方都不能落子时游戏结束。四个角上的棋子永远不会被夹，所以占角非常有利。比起眼前的子数，减少对手能下的地方更重要。"], "cap": ["落子与翻面。在红圈格落下黑子，横、竖、斜三个方向都夹住了白子，金边的7枚白子全部变黑"]}, {"h": "最初的四枚棋子", "p": ["早期的黑白棋，由双方轮流把最初四枚棋子下在中央的四格里，所以既可能同色并排，也可能交叉。", "奥赛罗规定最初四枚交叉摆放。一开始黑白双方都容易被夹，开局就是激烈的攻防。今天的世界大赛也从这个局面开始。"], "cap": ["最初的四枚棋子。左：早期黑白棋的一种摆法（同色横向并排）。右：奥赛罗规定的交叉摆法"]}, {"h": "人与电脑", "p": ["奥赛罗从日本传向世界，1977年在东京举办了第一届世界锦标赛。规则简单，胜负就看计算的深度，高手能算到几十步之后。", "1997年，程序“Logistello”与世界冠军村上健下了6局，6局全胜。2023年，计算表明8×8的奥赛罗在双方都下出最佳着法时是和棋。"], "cap": []}], "tl": [["1880年代", "沃特曼与莫利特在伦敦争夺发明权"], ["1893年", "德国拉文斯堡公司推出黑白棋"], ["明治时代", "日本书籍以“源平棋”之名介绍"], ["1973年", "日本发售“奥赛罗”套装"], ["1977年", "东京举办第一届世界奥赛罗锦标赛"], ["1997年", "Logistello以6比0战胜世界冠军村上健"], ["2023年", "8×8奥赛罗被证明在最佳下法下为和棋"]]}}, "zh-TW": {"reversi": {"kf": ["用自己的棋子夾住對方棋子並翻面，最後棋子多的一方獲勝", "1880年代的倫敦，兩個英國人爭奪發明者之名", "1970年代以「奧賽羅」之名在日本風靡，2023年被證明在最佳下法下為和棋"], "more": [{"h": "夾住就翻面", "p": ["只能在能用自己的棋子夾住對方棋子的格子落子。夾的方向有橫、豎、斜共8個，一步可以同時夾住好幾個方向。被夾住的棋子全部翻成自己的顏色。", "沒有可落的格子就棄權，雙方都不能落子時遊戲結束。四個角上的棋子永遠不會被夾，所以佔角非常有利。比起眼前的子數，減少對手能下的地方更重要。"], "cap": ["落子與翻面。在紅圈格落下黑子，橫、豎、斜三個方向都夾住了白子，金邊的7枚白子全部變黑"]}, {"h": "最初的四枚棋子", "p": ["早期的黑白棋，由雙方輪流把最初四枚棋子下在中央的四格裡，所以既可能同色並排，也可能交叉。", "奧賽羅規定最初四枚交叉擺放。一開始黑白雙方都容易被夾，開局就是激烈的攻防。今天的世界大賽也從這個局面開始。"], "cap": ["最初的四枚棋子。左：早期黑白棋的一種擺法（同色橫向並排）。右：奧賽羅規定的交叉擺法"]}, {"h": "人與電腦", "p": ["奧賽羅從日本傳向世界，1977年在東京舉辦了第一屆世界錦標賽。規則簡單，勝負就看計算的深度，高手能算到幾十步之後。", "1997年，程式「Logistello」與世界冠軍村上健下了6局，6局全勝。2023年，計算表明8×8的奧賽羅在雙方都下出最佳著法時是和棋。"], "cap": []}], "tl": [["1880年代", "沃特曼與莫利特在倫敦爭奪發明權"], ["1893年", "德國拉文斯堡公司推出黑白棋"], ["明治時代", "日本書籍以「源平棋」之名介紹"], ["1973年", "日本發售「奧賽羅」套裝"], ["1977年", "東京舉辦第一屆世界奧賽羅錦標賽"], ["1997年", "Logistello以6比0戰勝世界冠軍村上健"], ["2023年", "8×8奧賽羅被證明在最佳下法下為和棋"]]}}, "ko": {"reversi": {"kf": ["상대 돌을 자기 돌로 끼워 뒤집고, 마지막에 돌이 많은 쪽이 이기는 게임", "1880년대 런던에서 두 영국인이 발명자 자리를 다퉜다", "1970년대 일본에서 ‘오델로’로 크게 유행했고, 2023년에는 최선이면 무승부임이 밝혀졌다"], "more": [{"h": "끼워서 뒤집는다", "p": ["돌은 상대 돌을 자기 돌로 끼울 수 있는 칸에만 놓을 수 있습니다. 끼우는 방향은 가로·세로·대각선의 8방향이고, 한 번에 여러 방향을 끼울 수 있습니다. 끼인 돌은 모두 뒤집혀 자기 색이 됩니다.", "놓을 칸이 없으면 패스하고, 둘 다 놓을 수 없게 되면 끝납니다. 네 귀퉁이의 돌은 다시는 끼이지 않으므로, 귀를 차지하면 크게 유리합니다. 당장의 돌 수보다 상대가 둘 수 있는 곳을 줄이는 것이 중요하다고 합니다."], "cap": ["돌을 놓아 뒤집는 원리. 빨간 고리 칸에 흑을 놓으면 가로·세로·대각선 세 방향에서 백을 끼우고, 금색 테의 백 7개가 모두 흑으로 바뀐다"]}, {"h": "처음 네 개의 돌", "p": ["초기 리버시에서는 처음 네 돌을 두 사람이 가운데 네 칸에 차례로 놓았습니다. 그래서 같은 색이 나란한 모양도, 엇갈린 모양도 될 수 있었습니다.", "오델로는 처음 네 돌을 엇갈리게 놓도록 정했습니다. 처음부터 흑백 어느 돌이든 끼우기 쉬워, 초반부터 치열한 공방이 벌어집니다. 지금의 세계 대회도 이 모양에서 시작합니다."], "cap": ["처음 네 돌. 왼쪽: 초기 리버시의 놓는 법의 한 예(같은 색이 가로로 나란히). 오른쪽: 오델로에서 정한 엇갈리게 놓는 법"]}, {"h": "사람과 컴퓨터", "p": ["오델로는 일본에서 세계로 퍼졌고, 1977년에는 도쿄에서 제1회 세계 선수권이 열렸습니다. 규칙이 간단한 만큼 수읽기의 깊이로 승부가 갈리며, 강한 선수는 수십 수 앞을 내다봅니다.", "1997년 프로그램 ‘로지스텔로’는 세계 챔피언 무라카미 다케시와 6판을 두어 모두 이겼습니다. 2023년에는 8×8 오델로가 양쪽이 최선을 다하면 무승부가 된다는 것이 계산으로 밝혀졌습니다."], "cap": []}], "tl": [["1880년대", "런던에서 워터먼과 몰릿이 발명을 다툼"], ["1893년", "독일 라벤스부르거 사가 리버시를 내놓음"], ["메이지 시대", "일본 책에 ‘겐페이고’로 소개됨"], ["1973년", "일본에서 ‘오델로’ 세트 발매"], ["1977년", "도쿄에서 제1회 세계 오델로 선수권"], ["1997년", "로지스텔로가 세계 챔피언 무라카미 다케시에게 6전 전승"], ["2023년", "8×8 오델로는 최선이면 무승부임이 밝혀짐"]]}}, "es": {"reversi": {"kf": ["Encierra las fichas rivales entre las tuyas para darles la vuelta; al final gana quien tenga más", "En el Londres de la década de 1880, dos ingleses se disputaron su invención", "En los años setenta arrasó en Japón como Othello, y en 2023 se demostró que es tablas con juego perfecto"], "more": [{"h": "Encerrar y voltear", "p": ["Solo se puede poner una ficha donde encierre una línea de fichas rivales entre ella y otra propia. Las líneas van en ocho direcciones —horizontal, vertical y diagonal— y una jugada puede encerrar varias a la vez. Todas las fichas encerradas se voltean a tu color.", "Si no tienes jugada, pasas, y la partida termina cuando ninguno puede mover. Las fichas de las esquinas nunca pueden encerrarse, así que tomar una esquina es una gran ventaja. Los buenos jugadores se fijan menos en cuántas fichas tienen ahora que en reducir dónde puede jugar el rival."], "cap": ["Cómo se voltean las fichas. Una negra colocada en la casilla del círculo rojo encierra blancas en tres direcciones —horizontal, vertical y diagonal— y las siete de borde dorado pasan a negras"]}, {"h": "Las cuatro primeras fichas", "p": ["En el reversi antiguo, los dos jugadores ponían por turnos las cuatro primeras fichas en las cuatro casillas centrales, así que la apertura podía quedar lado a lado o cruzada.", "El Othello fijó el inicio cruzado. Desde la primera jugada ambos colores son fáciles de encerrar y la lucha empieza enseguida. Los campeonatos mundiales actuales parten de esta posición."], "cap": ["Las cuatro primeras fichas. Izquierda: una forma en que podía empezar el reversi antiguo, con los mismos colores lado a lado. Derecha: el inicio cruzado que fijó el Othello"]}, {"h": "Humanos y computadoras", "p": ["El Othello pasó de Japón al mundo, y en 1977 se celebró en Tokio el primer Campeonato Mundial. Las reglas son sencillas, así que decide la profundidad del cálculo: los mejores ven decenas de jugadas por delante.", "En 1997 el programa Logistello jugó seis partidas contra el campeón del mundo Takeshi Murakami y las ganó todas. En 2023 se demostró mediante cálculo que el Othello de 8 × 8 termina en tablas si ambos juegan perfectamente."], "cap": []}], "tl": [["década de 1880", "Waterman y Mollett se disputan la invención en Londres"], ["1893", "Ravensburger lanza el Reversi en Alemania"], ["era Meiji", "Libros japoneses lo presentan como genpei-go"], ["1973", "Salen a la venta en Japón los juegos de Othello"], ["1977", "Primer Campeonato Mundial de Othello, en Tokio"], ["1997", "Logistello vence 6–0 al campeón Takeshi Murakami"], ["2023", "Se demuestra que el Othello de 8 × 8 es tablas con juego perfecto"]]}}, "fr": {"reversi": {"kf": ["Encadrer les pions adverses entre les siens pour les retourner ; à la fin, le plus grand nombre l’emporte", "Dans le Londres des années 1880, deux Anglais se disputèrent son invention", "Devenu un engouement au Japon dans les années 1970 sous le nom d’Othello, il s’est révélé nul en jeu parfait en 2023"], "more": [{"h": "Encadrer et retourner", "p": ["On ne peut poser un pion que là où il encadre une ligne de pions adverses entre lui et un pion à soi. Les lignes vont dans huit directions — horizontales, verticales et diagonales — et un coup peut en encadrer plusieurs à la fois. Tous les pions encadrés sont retournés à sa couleur.", "Sans coup possible, on passe ; la partie s’arrête quand aucun des deux ne peut jouer. Les pions des coins ne peuvent jamais être encadrés : prendre un coin est un gros avantage. Les forts joueurs comptent moins les pions du moment que les cases laissées à l’adversaire."], "cap": ["Le retournement. Un pion noir posé sur la case cerclée de rouge encadre des blancs dans trois directions — horizontale, verticale et diagonale — et les sept pions bordés d’or deviennent noirs"]}, {"h": "Les quatre premiers pions", "p": ["Dans le reversi ancien, les deux joueurs posaient tour à tour les quatre premiers pions sur les quatre cases centrales : le début pouvait donc être côte à côte ou croisé.", "L’Othello a fixé le départ croisé. Dès le premier coup, les deux couleurs sont faciles à encadrer et la lutte commence aussitôt. Les championnats du monde partent aujourd’hui de cette position."], "cap": ["Les quatre premiers pions. À gauche : un début possible du reversi ancien, mêmes couleurs côte à côte. À droite : le départ croisé fixé par l’Othello"]}, {"h": "Humains et ordinateurs", "p": ["L’Othello est passé du Japon au monde entier, et le premier championnat du monde s’est tenu à Tokyo en 1977. Les règles sont simples : c’est la profondeur du calcul qui fait la différence, et les meilleurs voient des dizaines de coups à l’avance.", "En 1997, le programme Logistello affronta le champion du monde Takeshi Murakami en six parties et les gagna toutes. En 2023, le calcul a montré que l’Othello 8 × 8 est nul si les deux camps jouent parfaitement."], "cap": []}], "tl": [["années 1880", "Waterman et Mollett se disputent l’invention à Londres"], ["1893", "Ravensburger lance le Reversi en Allemagne"], ["ère Meiji", "Des livres japonais le présentent sous le nom de genpei-go"], ["1973", "Les boîtes d’Othello sont mises en vente au Japon"], ["1977", "Premier championnat du monde d’Othello, à Tokyo"], ["1997", "Logistello bat le champion Takeshi Murakami 6–0"], ["2023", "L’Othello 8 × 8 est montré nul en jeu parfait"]]}}, "pt": {"reversi": {"kf": ["Prenda as peças do adversário entre as suas para virá-las; no fim, vence quem tiver mais", "Na Londres da década de 1880, dois ingleses disputaram sua invenção", "Virou febre no Japão nos anos 1970 como Othello e, em 2023, mostrou-se empate com jogo perfeito"], "more": [{"h": "Cercar e virar", "p": ["Só se pode pôr uma peça onde ela prenda uma linha de peças adversárias entre ela e outra sua. As linhas vão em oito direções — horizontal, vertical e diagonal — e um lance pode prender várias ao mesmo tempo. Todas as peças presas viram para a sua cor.", "Sem lance possível, passa-se a vez; o jogo termina quando nenhum dos dois pode jogar. As peças dos cantos nunca podem ser presas, então tomar um canto é uma grande vantagem. Os bons jogadores se importam menos com quantas peças têm agora do que em limitar onde o adversário pode jogar."], "cap": ["Como as peças viram. Uma preta posta na casa do círculo vermelho prende brancas em três direções — horizontal, vertical e diagonal — e as sete de borda dourada viram pretas"]}, {"h": "As quatro primeiras peças", "p": ["No reversi antigo, os dois jogadores punham por turnos as quatro primeiras peças nas quatro casas centrais, então a abertura podia ficar lado a lado ou cruzada.", "O Othello fixou o início cruzado. Desde o primeiro lance as duas cores são fáceis de prender, e a luta começa logo. Os campeonatos mundiais de hoje partem dessa posição."], "cap": ["As quatro primeiras peças. Esquerda: um começo possível do reversi antigo, com as mesmas cores lado a lado. Direita: o início cruzado fixado pelo Othello"]}, {"h": "Humanos e computadores", "p": ["O Othello foi do Japão para o mundo, e o primeiro Campeonato Mundial foi em Tóquio, em 1977. As regras são simples, então decide a profundidade do cálculo: os melhores enxergam dezenas de lances à frente.", "Em 1997 o programa Logistello jogou seis partidas contra o campeão mundial Takeshi Murakami e venceu todas. Em 2023, cálculos mostraram que o Othello 8 × 8 termina empatado se os dois jogarem perfeitamente."], "cap": []}], "tl": [["década de 1880", "Waterman e Mollett disputam a invenção em Londres"], ["1893", "A Ravensburger lança o Reversi na Alemanha"], ["era Meiji", "Livros japoneses o apresentam como genpei-go"], ["1973", "Os jogos de Othello chegam às lojas no Japão"], ["1977", "Primeiro Campeonato Mundial de Othello, em Tóquio"], ["1997", "Logistello vence o campeão Takeshi Murakami por 6–0"], ["2023", "Mostra-se que o Othello 8 × 8 é empate com jogo perfeito"]]}}, "de": {"reversi": {"kf": ["Gegnerische Steine zwischen eigenen einschließen und umdrehen; am Ende gewinnt, wer mehr hat", "Im London der 1880er stritten zwei Engländer darum, wer es erfunden hatte", "In den 1970ern wurde es in Japan als Othello zum Renner; 2023 zeigte sich: bei perfektem Spiel remis"], "more": [{"h": "Einschließen und umdrehen", "p": ["Man darf einen Stein nur dort setzen, wo er eine Reihe gegnerischer Steine zwischen sich und einem eigenen einschließt. Die Reihen laufen in acht Richtungen – waagerecht, senkrecht und schräg –, und ein Zug kann mehrere zugleich einschließen. Alle eingeschlossenen Steine werden auf die eigene Farbe gedreht.", "Wer nicht ziehen kann, setzt aus; das Spiel endet, wenn keiner mehr ziehen kann. Ecksteine können nie eingeschlossen werden, deshalb ist eine Ecke ein großer Vorteil. Starke Spieler achten weniger auf die momentane Steinzahl als darauf, die Zugmöglichkeiten des Gegners zu verringern."], "cap": ["So wird umgedreht. Ein schwarzer Stein auf dem rot umringten Feld schließt Weiß in drei Richtungen ein – waagerecht, senkrecht und schräg –, und alle sieben golden umrandeten Steine werden schwarz"]}, {"h": "Die ersten vier Steine", "p": ["Beim frühen Reversi setzten die beiden Spieler die ersten vier Steine abwechselnd auf die vier Mittelfelder, sodass die Eröffnung nebeneinander oder gekreuzt ausfallen konnte.", "Othello legte den gekreuzten Start fest. Von Anfang an lassen sich beide Farben leicht einschließen, und der Kampf beginnt sofort. Weltmeisterschaften beginnen heute aus dieser Stellung."], "cap": ["Die ersten vier Steine. Links: ein möglicher Beginn des frühen Reversi, gleiche Farben nebeneinander. Rechts: der von Othello festgelegte gekreuzte Start"]}, {"h": "Mensch und Computer", "p": ["Othello verbreitete sich von Japan aus in die Welt; die erste Othello-Weltmeisterschaft fand 1977 in Tokio statt. Die Regeln sind einfach, also entscheidet die Rechentiefe: Spitzenspieler sehen Dutzende Züge voraus.", "1997 spielte das Programm Logistello sechs Partien gegen Weltmeister Takeshi Murakami und gewann alle. 2023 zeigten Berechnungen, dass 8 × 8-Othello bei perfektem Spiel beider Seiten remis endet."], "cap": []}], "tl": [["1880er", "Waterman und Mollett streiten in London um die Erfindung"], ["1893", "Ravensburger bringt Reversi heraus"], ["Meiji-Zeit", "Japanische Bücher stellen es als Genpei-go vor"], ["1973", "In Japan kommen Othello-Spiele in den Handel"], ["1977", "Erste Othello-Weltmeisterschaft in Tokio"], ["1997", "Logistello schlägt Weltmeister Takeshi Murakami 6:0"], ["2023", "8 × 8-Othello erweist sich bei perfektem Spiel als remis"]]}}, "ru": {"reversi": {"kf": ["Зажимай фишки соперника между своими и переворачивай; в конце побеждает тот, у кого их больше", "В Лондоне 1880-х двое англичан спорили, кто изобрёл игру", "В 1970-х она стала повальным увлечением в Японии под именем «Отелло», а в 2023 году оказалось: при идеальной игре — ничья"], "more": [{"h": "Зажать и перевернуть", "p": ["Фишку можно ставить только туда, где она зажмёт ряд фишек соперника между собой и своей фишкой. Ряды идут в восьми направлениях — по горизонтали, вертикали и диагоналям, — и один ход может зажать сразу несколько. Все зажатые фишки переворачиваются в твой цвет.", "Если хода нет — пропускаешь; игра кончается, когда ходить не может никто. Угловые фишки никогда не зажать, поэтому занять угол — большое преимущество. Сильные игроки меньше думают о числе фишек сейчас и больше — о том, чтобы урезать ходы соперника."], "cap": ["Как переворачивают фишки. Чёрная, поставленная на клетку в красном кольце, зажимает белые в трёх направлениях — по горизонтали, вертикали и диагонали, — и все семь фишек с золотой каймой становятся чёрными"]}, {"h": "Первые четыре фишки", "p": ["В раннем реверси игроки по очереди ставили первые четыре фишки на четыре центральные клетки, поэтому начало могло быть и «рядом», и крест-накрест.", "«Отелло» закрепило начало крест-накрест. С первого хода обе стороны легко зажать, и борьба начинается сразу. Чемпионаты мира сегодня начинаются с этой позиции."], "cap": ["Первые четыре фишки. Слева: одно из возможных начал старого реверси — одинаковые цвета рядом. Справа: начало крест-накрест, закреплённое в «Отелло»"]}, {"h": "Люди и компьютеры", "p": ["«Отелло» разошлось из Японии по миру, и в 1977 году в Токио прошёл первый чемпионат мира. Правила просты, так что всё решает глубина расчёта: сильнейшие видят на десятки ходов вперёд.", "В 1997 году программа Logistello сыграла с чемпионом мира Такэси Мураками шесть партий и выиграла все. В 2023 году расчёты показали, что «Отелло» 8 × 8 при идеальной игре обеих сторон заканчивается вничью."], "cap": []}], "tl": [["1880-е", "Уотерман и Моллетт спорят в Лондоне об изобретении"], ["1893", "Ravensburger в Германии выпускает «Реверси»"], ["эпоха Мэйдзи", "Японские книги описывают игру как гэмпэй-го"], ["1973", "В Японии поступают в продажу наборы «Отелло»"], ["1977", "Первый чемпионат мира по «Отелло» в Токио"], ["1997", "Logistello обыгрывает чемпиона мира Такэси Мураками 6:0"], ["2023", "Показано: «Отелло» 8 × 8 при идеальной игре — ничья"]]}}, "tr": {"reversi": {"kf": ["Rakibin taşlarını kendi taşlarınla kıstırıp çevirirsin; sonunda taşı çok olan kazanır", "1880’lerin Londra’sında iki İngiliz, mucitlik için çekişti", "1970’lerde Japonya’da Othello adıyla çılgınlığa dönüştü; 2023’te kusursuz oyunda beraberlik olduğu gösterildi"], "more": [{"h": "Kıstır ve çevir", "p": ["Taş yalnızca, rakibin bir sıra taşını kendisiyle kendi taşlarından biri arasında kıstıracağı yere konabilir. Sıralar sekiz yönde uzanır — yatay, dikey ve çapraz — ve tek hamle birkaçını birden kıstırabilir. Kıstırılan bütün taşlar senin rengine çevrilir.", "Hamlen yoksa pas geçersin; iki oyuncu da oynayamayınca oyun biter. Köşe taşları asla kıstırılamaz, bu yüzden köşe almak büyük üstünlüktür. Güçlü oyuncular o anki taş sayısından çok, rakibin oynayabileceği yerleri azaltmaya bakar."], "cap": ["Taşların çevrilişi. Kırmızı halkalı kareye konan siyah taş, beyazları yatay, dikey ve çapraz üç yönde kıstırır; altın kenarlı yedi taşın hepsi siyaha döner"]}, {"h": "İlk dört taş", "p": ["Eski reversi’de iki oyuncu ilk dört taşı sırayla ortadaki dört kareye koyardı; bu yüzden açılış yan yana da, çapraz da olabilirdi.", "Othello çapraz başlangıcı sabitledi. İlk hamleden itibaren iki renk de kolayca kıstırılabildiği için mücadele hemen başlar. Bugünkü dünya şampiyonaları bu konumdan başlar."], "cap": ["İlk dört taş. Solda: eski reversinin olası bir başlangıcı (aynı renkler yan yana). Sağda: Othello’nun sabitlediği çapraz başlangıç"]}, {"h": "İnsanlar ve bilgisayarlar", "p": ["Othello Japonya’dan dünyaya yayıldı; ilk Dünya Othello Şampiyonası 1977’de Tokyo’da yapıldı. Kurallar basit olduğu için farkı hesap derinliği yaratır; güçlü oyuncular onlarca hamle ilerisini görür.", "1997’de Logistello programı dünya şampiyonu Takeshi Murakami ile altı oyun oynadı ve hepsini kazandı. 2023’te hesaplar, 8 × 8 Othello’nun iki taraf da kusursuz oynarsa berabere bittiğini gösterdi."], "cap": []}], "tl": [["1880’ler", "Waterman ve Mollett Londra’da mucitlik için çekişir"], ["1893", "Ravensburger Almanya’da Reversi’yi piyasaya sürer"], ["Meiji dönemi", "Japon kitapları oyunu genpei-go adıyla tanıtır"], ["1973", "Japonya’da Othello takımları satışa çıkar"], ["1977", "İlk Dünya Othello Şampiyonası Tokyo’da"], ["1997", "Logistello, dünya şampiyonu Takeshi Murakami’yi 6–0 yener"], ["2023", "8 × 8 Othello’nun kusursuz oyunda berabere olduğu gösterilir"]]}}, "id": {"reversi": {"kf": ["Jepit bidak lawan di antara bidakmu untuk membaliknya; di akhir, yang bidaknya lebih banyak menang", "Di London tahun 1880-an, dua orang Inggris memperebutkan gelar penemunya", "Pada 1970-an meledak di Jepang dengan nama Othello, dan pada 2023 terbukti remis bila dimainkan sempurna"], "more": [{"h": "Jepit lalu balik", "p": ["Bidak hanya boleh ditaruh di tempat yang menjepit sederet bidak lawan di antara bidak itu dan bidakmu yang lain. Deretan bisa ke delapan arah — mendatar, tegak, dan diagonal — dan satu langkah bisa menjepit beberapa arah sekaligus. Semua bidak yang terjepit dibalik menjadi warnamu.", "Bila tak ada langkah, kamu lewat; permainan selesai bila keduanya tak bisa melangkah. Bidak di sudut tak pernah bisa dijepit, jadi merebut sudut sangat menguntungkan. Pemain kuat lebih memikirkan mengurangi tempat lawan bisa melangkah daripada jumlah bidak saat itu."], "cap": ["Cara bidak dibalik. Bidak hitam yang ditaruh di petak berlingkaran merah menjepit putih ke tiga arah — mendatar, tegak, dan diagonal — dan ketujuh bidak bertepi emas berubah hitam"]}, {"h": "Empat bidak pertama", "p": ["Pada reversi awal, kedua pemain bergantian menaruh empat bidak pertama di empat petak tengah, sehingga pembukaannya bisa berdampingan atau menyilang.", "Othello menetapkan awal menyilang. Sejak langkah pertama kedua warna mudah dijepit, sehingga pertarungan langsung dimulai. Kejuaraan dunia masa kini berangkat dari posisi ini."], "cap": ["Empat bidak pertama. Kiri: salah satu awal reversi lama (warna sama berdampingan). Kanan: awal menyilang yang ditetapkan Othello"]}, {"h": "Manusia dan komputer", "p": ["Othello menyebar dari Jepang ke seluruh dunia, dan Kejuaraan Dunia Othello pertama digelar di Tokyo pada 1977. Aturannya sederhana, jadi kedalaman perhitungan yang menentukan; pemain terbaik melihat puluhan langkah ke depan.", "Pada 1997 program Logistello melawan juara dunia Takeshi Murakami dalam enam partai dan memenangkan semuanya. Pada 2023 perhitungan menunjukkan bahwa Othello 8 × 8 berakhir remis bila kedua pihak bermain sempurna."], "cap": []}], "tl": [["1880-an", "Waterman dan Mollett memperebutkan penemuan di London"], ["1893", "Ravensburger di Jerman meluncurkan Reversi"], ["Zaman Meiji", "Buku Jepang memperkenalkannya sebagai genpei-go"], ["1973", "Set Othello mulai dijual di Jepang"], ["1977", "Kejuaraan Dunia Othello pertama di Tokyo"], ["1997", "Logistello mengalahkan juara dunia Takeshi Murakami 6–0"], ["2023", "Othello 8 × 8 terbukti remis bila dimainkan sempurna"]]}}, "hi": {"reversi": {"kf": ["विरोधी की गोटियों को अपनी गोटियों के बीच घेरकर पलटो; अंत में जिसकी गोटियाँ ज़्यादा, वह जीते", "1880 के दशक के लंदन में दो अंग्रेज़ों में आविष्कारक होने पर झगड़ा हुआ", "1970 के दशक में जापान में ‘ओथेलो’ नाम से छा गया, और 2023 में दिखाया गया कि बिना चूक खेलें तो बराबरी"], "more": [{"h": "घेरो और पलटो", "p": ["गोटी सिर्फ़ वहीं रखी जा सकती है जहाँ वह विरोधी की गोटियों की एक पंक्ति को अपने और अपनी किसी दूसरी गोटी के बीच घेर ले। पंक्तियाँ आठ दिशाओं में जाती हैं — आड़ी, खड़ी और तिरछी — और एक चाल कई दिशाएँ एक साथ घेर सकती है। घिरी हुई सारी गोटियाँ आपके रंग में पलट जाती हैं।", "कोई चाल न हो तो बारी छोड़ते हैं; जब दोनों में से कोई न चल सके, खेल ख़त्म। कोनों की गोटियाँ कभी घेरी नहीं जा सकतीं, इसलिए कोना लेना बड़ा फ़ायदा है। मज़बूत खिलाड़ी अभी की गिनती से ज़्यादा इस पर ध्यान देते हैं कि विरोधी के खेलने की जगहें कम हों।"], "cap": ["गोटियाँ कैसे पलटती हैं। लाल घेरे वाले खाने पर रखी काली गोटी तीन दिशाओं — आड़ी, खड़ी और तिरछी — में सफ़ेद गोटियों को घेरती है, और सुनहरे किनारे वाली सातों गोटियाँ काली हो जाती हैं"]}, {"h": "पहली चार गोटियाँ", "p": ["शुरुआती रिवर्सी में दोनों खिलाड़ी बारी-बारी से पहली चार गोटियाँ बीच के चार खानों में रखते थे, इसलिए शुरुआत अगल-बगल भी हो सकती थी और आड़ी-तिरछी भी।", "ओथेलो ने आड़ी-तिरछी शुरुआत तय कर दी। पहली चाल से ही दोनों रंग आसानी से घेरे जा सकते हैं, सो मुक़ाबला तुरंत शुरू हो जाता है। आज की विश्व प्रतियोगिताएँ इसी स्थिति से शुरू होती हैं।"], "cap": ["पहली चार गोटियाँ। बाएँ: पुराने रिवर्सी की एक संभव शुरुआत (एक ही रंग अगल-बगल)। दाएँ: ओथेलो की तय की हुई आड़ी-तिरछी शुरुआत"]}, {"h": "इंसान और कंप्यूटर", "p": ["ओथेलो जापान से दुनिया भर में फैला, और 1977 में टोक्यो में पहली विश्व ओथेलो चैंपियनशिप हुई। नियम सरल हैं, इसलिए फ़र्क़ गणना की गहराई से पड़ता है; शीर्ष खिलाड़ी दर्जनों चालें आगे देखते हैं।", "1997 में लॉजिस्टेलो प्रोग्राम ने विश्व चैंपियन ताकेशी मुराकामी से छह बाज़ियाँ खेलीं और सभी जीतीं। 2023 में गणनाओं ने दिखाया कि 8 × 8 ओथेलो दोनों पक्षों के बिना चूक खेलने पर बराबरी पर ख़त्म होता है।"], "cap": []}], "tl": [["1880 का दशक", "लंदन में वॉटरमैन और मॉलेट आविष्कार पर झगड़े"], ["1893", "जर्मनी में रेवेन्सबर्गर ने रिवर्सी निकाला"], ["मेइजी काल", "जापानी किताबों में ‘गेनपेई-गो’ नाम से परिचय"], ["1973", "जापान में ओथेलो के सेट बिकने लगे"], ["1977", "टोक्यो में पहली विश्व ओथेलो चैंपियनशिप"], ["1997", "लॉजिस्टेलो ने विश्व चैंपियन ताकेशी मुराकामी को 6–0 से हराया"], ["2023", "दिखाया गया कि 8 × 8 ओथेलो बिना चूक खेलने पर बराबरी है"]]}}, "ar": {"reversi": {"kf": ["احصر أحجار خصمك بين أحجارك لتقلبها، ومن كانت أحجاره أكثر في النهاية فاز", "في لندن ثمانينيات القرن التاسع عشر تنازع إنجليزيان على اختراعها", "صارت هوسًا في اليابان في السبعينيات باسم «أوثيلو»، وفي 2023 تبيّن أنها تعادل باللعب المثالي"], "more": [{"h": "احصر واقلب", "p": ["لا يجوز وضع حجر إلا حيث يحصر صفًّا من أحجار الخصم بينه وبين حجر لك. تمتد الصفوف في ثمانية اتجاهات — أفقية وعمودية وقطرية — وقد تحصر النقلة الواحدة عدة صفوف معًا. وكل حجر محصور يُقلب إلى لونك.", "إن لم تكن لك نقلة تُمرّر الدور، وتنتهي اللعبة حين لا يستطيع أي منكما اللعب. أحجار الزوايا لا تُحصر أبدًا، لذا فأخذ زاوية ميزة كبيرة. ويهتم اللاعبون الأقوياء بتقليل الأماكن المتاحة لخصمهم أكثر من عدد أحجارهم في اللحظة."], "cap": ["طريقة القلب. حجر أسود يوضع في المربع ذي الحلقة الحمراء يحصر البيض في ثلاثة اتجاهات — أفقيًا وعموديًا وقطريًا — فتنقلب الأحجار السبعة ذات الإطار الذهبي سوداء"]}, {"h": "الأحجار الأربعة الأولى", "p": ["في الريفرسي القديمة كان اللاعبان يضعان بالتناوب الأحجار الأربعة الأولى في المربعات الأربعة الوسطى، فقد تأتي البداية متجاورة أو متقاطعة.", "وثبّتت أوثيلو البداية المتقاطعة. فمنذ النقلة الأولى يسهل حصر اللونين، فيبدأ الصراع فورًا. وتنطلق بطولات العالم اليوم من هذا الوضع."], "cap": ["الأحجار الأربعة الأولى. يسارًا: بداية ممكنة للريفرسي القديمة (اللونان متجاوران). يمينًا: البداية المتقاطعة التي ثبّتتها أوثيلو"]}, {"h": "البشر والحواسيب", "p": ["انتشرت أوثيلو من اليابان إلى العالم، وأُقيمت أول بطولة عالمية لها في طوكيو عام 1977. القواعد بسيطة، فيصنع الفارقَ عمقُ الحساب، ويرى كبار اللاعبين عشرات النقلات مقدمًا.", "في 1997 لعب برنامج «لوجيستيلو» ست مباريات مع بطل العالم تاكيشي موراكامي وفاز بها كلها. وفي 2023 أظهرت الحسابات أن أوثيلو 8 × 8 تنتهي بالتعادل إذا لعب الطرفان لعبًا مثاليًا."], "cap": []}], "tl": [["ثمانينيات القرن 19", "ووترمان وموليت يتنازعان الاختراع في لندن"], ["1893", "رافنسبورغر في ألمانيا تطرح «ريفرسي»"], ["عصر ميجي", "كتب يابانية تقدمها باسم «غينبي-غو»"], ["1973", "طرح مجموعات أوثيلو في اليابان"], ["1977", "أول بطولة عالم لأوثيلو في طوكيو"], ["1997", "لوجيستيلو يهزم بطل العالم تاكيشي موراكامي 6–0"], ["2023", "إظهار أن أوثيلو 8 × 8 تعادل باللعب المثالي"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (22): story 15 (mancala) made fuller */
(T => { const D = {"ja": {"mancala": {"kf": ["穴の石を取り出し、となりの穴から1つずつ配って進める「種まき」のゲームの仲間", "年代のはっきりした最古の盤は、6〜7世紀ごろの古代アクスム王国のもの", "2列・4列、店（ストア）のあるものなど、地域ごとに形もルールもさまざま"], "more": [{"h": "種をまく", "p": ["マンカラでは、自分の側の穴をひとつ選んで石を全部取り出し、となりの穴から1つずつ配っていきます。畑に種をまくようなこの動きを「種まき」と呼びます。", "西アフリカのオワレでは、48個の石を12の穴に4つずつ入れて始めます。最後の石を入れた相手の穴が2つか3つになったら、その石を取れます。何個ずつ配るとどこで止まるか、先を数えて読む力がものをいうゲームです。オワレは大西洋をこえ、カリブ海の島々にも伝わりました。"], "cap": ["オワレの種まき。金の輪の穴の3つの石を反時計回りに1つずつ配り、最後の1つで相手の穴がちょうど3つになったので、その3つを取る（赤い輪）"]}, {"h": "2列と4列", "p": ["マンカラの盤には、大きく分けて2列のものと4列のものがあります。西アフリカやアジアには2列の盤が多く、東アフリカから南部アフリカには4列の盤が広がっています。タンザニアのバオは4列×8穴で、名前はスワヒリ語で「盤」という意味です。", "東南アジアのチョンカやスンカのように、盤の両はしに取った石をためる大きな穴「店」があるものもあります。20世紀のアメリカで生まれた「カラハ」も店のある2列の形で、2000年には、6穴に4つずつで始めるカラハは先手が必ず勝てることが計算で示されました。"], "cap": ["マンカラの盤の形の例。2列×6穴（オワレなど）、2列×7穴に両はしの店（東南アジアのチョンカなど）、4列×8穴（東アフリカのバオなど）"]}, {"h": "書きとめた人々", "p": ["ヨーロッパの学者がマンカラを詳しく書いたのは、イギリスのトマス・ハイドが最初とされます。1694年の『東洋の遊戯について』で、アラビア語の名前とともに遊び方を紹介しました。", "1836年には、エドワード・W・レーンがカイロの人々の暮らしを描いた本の中で、カフェで遊ばれる「マンカラ」を書きとめています。今では研究者が各地の遊び方を集め、記録されたルールは数百にのぼります。"], "cap": []}], "tl": [["6〜7世紀", "古代アクスム王国の遺跡に、年代のはっきりした最古の盤"], ["1694年", "トマス・ハイドが『東洋の遊戯について』でマンカラを紹介"], ["18〜19世紀", "オワレなどが大西洋をこえ、カリブ海の島々に伝わる"], ["1836年", "E・W・レーンがカイロのマンカラを書きとめる"], ["20世紀なかば", "アメリカで店のある2列のマンカラ「カラハ」が売り出される"], ["2000年", "6穴4石のカラハは先手必勝と計算で示される"]]}}, "en": {"mancala": {"kf": ["A family of “sowing” games: lift the seeds from a pit and drop them one by one into the pits that follow", "The oldest securely dated boards come from the ancient kingdom of Aksum, around the 6th–7th century", "Two rows or four, with or without stores — the board and rules vary from region to region"], "more": [{"h": "Sowing", "p": ["In mancala you choose a pit on your side, lift out all its seeds, and drop them one at a time into the pits that follow. This movement, like scattering seed in a field, is called sowing.", "Oware, from West Africa, begins with 48 seeds, four in each of 12 pits. If your last seed makes two or three in an opponent’s pit, you capture them. Knowing where a sowing will end — counting ahead — is everything. Oware crossed the Atlantic and is also played in the Caribbean."], "cap": ["Sowing in oware. The three seeds of the gold-ringed pit go one by one anticlockwise; the last makes exactly 3 in an opponent’s pit, so those 3 are captured (red ring)"]}, {"h": "Two rows and four", "p": ["Mancala boards fall broadly into two-row and four-row types. Two-row boards are common in West Africa and Asia; four-row boards spread from East Africa to southern Africa. Tanzania’s bao has 4 rows of 8 pits; its name is simply Swahili for “board”.", "Some, like congkak and sungka in Southeast Asia, have a large pit at each end — a store — for captured seeds. Kalah, born in 20th-century America, is a two-row game with stores, and in 2000 computation showed that Kalah with six pits and four seeds each is a win for the first player."], "cap": ["Examples of mancala board shapes: 2 rows of 6 (oware and others), 2 rows of 7 with a store at each end (congkak in Southeast Asia and others), 4 rows of 8 (bao in East Africa and others)"]}, {"h": "Those who wrote it down", "p": ["The first European scholar to describe mancala in detail is usually said to be Thomas Hyde of England. In De Ludis Orientalibus (1694) he gave its Arabic name and how it was played.", "In 1836 Edward W. Lane, describing everyday life in Cairo, recorded “mankalah” as it was played in coffee houses. Today researchers have gathered games from all over, and the recorded rule sets number in the hundreds."], "cap": []}], "tl": [["6th–7th c.", "The oldest securely dated boards, from sites of ancient Aksum"], ["1694", "Thomas Hyde describes mancala in De Ludis Orientalibus"], ["18th–19th c.", "Oware and others cross the Atlantic to the Caribbean"], ["1836", "E. W. Lane records mankalah in Cairo"], ["mid-20th c.", "Kalah, a two-row game with stores, goes on sale in the US"], ["2000", "Kalah with six pits and four seeds is shown to be a first-player win"]]}}, "zh": {"mancala": {"kf": ["从一个坑里取出全部棋子，从下一个坑起一颗一颗分下去的“播种”类游戏", "年代确定的最古老棋盘，来自约6–7世纪的古代阿克苏姆王国", "两排、四排、带“仓”的……各地棋盘与规则千差万别"], "more": [{"h": "播种", "p": ["播棋要从自己这边选一个坑，把里面的棋子全部取出，从下一个坑起一颗一颗放下去。这个像在田里撒种的动作叫“播种”。", "西非的奥瓦雷开局有48颗棋子，12个坑各放4颗。最后一颗落入的对方坑若变成2颗或3颗，就可以把它们取走。分几颗、停在哪里，要靠往前数、往前算。奥瓦雷还越过大西洋，传到了加勒比海诸岛。"], "cap": ["奥瓦雷的播种。把金圈坑里的3颗逆时针一颗颗分出去，最后一颗使对方的坑正好变成3颗，于是把这3颗取走（红圈）"]}, {"h": "两排与四排", "p": ["播棋的棋盘大致分为两排和四排两类。西非和亚洲多是两排，四排的棋盘则从东非一直分布到非洲南部。坦桑尼亚的巴奥是4排×8坑，名字在斯瓦希里语里就是“棋盘”的意思。", "像东南亚的晨卡、松卡那样，有的棋盘两端有存放所取棋子的大坑——“仓”。20世纪诞生于美国的“卡拉哈”也是带仓的两排形式；2000年，计算表明每坑4颗、6坑的卡拉哈先手必胜。"], "cap": ["播棋棋盘的几种形状：2排×6坑（奥瓦雷等），2排×7坑加两端的仓（东南亚的晨卡等），4排×8坑（东非的巴奥等）"]}, {"h": "把它记下来的人", "p": ["一般认为，最早详细记述播棋的欧洲学者是英国的托马斯·海德。他在1694年的《东方游戏考》中介绍了它的阿拉伯语名字和玩法。", "1836年，爱德华·W·莱恩在描写开罗人生活的书中，记下了咖啡馆里玩的“曼卡拉”。如今研究者收集了各地的玩法，记录下来的规则多达数百种。"], "cap": []}], "tl": [["6–7世纪", "古代阿克苏姆王国遗址出土年代确定的最古老棋盘"], ["1694年", "托马斯·海德在《东方游戏考》中介绍播棋"], ["18–19世纪", "奥瓦雷等越过大西洋传到加勒比海诸岛"], ["1836年", "E·W·莱恩记下开罗的曼卡拉"], ["20世纪中叶", "带仓的两排播棋“卡拉哈”在美国发售"], ["2000年", "计算表明6坑4子的卡拉哈先手必胜"]]}}, "zh-TW": {"mancala": {"kf": ["從一個坑裡取出全部棋子，從下一個坑起一顆一顆分下去的「播種」類遊戲", "年代確定的最古老棋盤，來自約6–7世紀的古代阿克蘇姆王國", "兩排、四排、帶「倉」的……各地棋盤與規則千差萬別"], "more": [{"h": "播種", "p": ["播棋要從自己這邊選一個坑，把裡面的棋子全部取出，從下一個坑起一顆一顆放下去。這個像在田裡撒種的動作叫「播種」。", "西非的奧瓦雷開局有48顆棋子，12個坑各放4顆。最後一顆落入的對方坑若變成2顆或3顆，就可以把它們取走。分幾顆、停在哪裡，要靠往前數、往前算。奧瓦雷還越過大西洋，傳到了加勒比海諸島。"], "cap": ["奧瓦雷的播種。把金圈坑裡的3顆逆時針一顆顆分出去，最後一顆使對方的坑正好變成3顆，於是把這3顆取走（紅圈）"]}, {"h": "兩排與四排", "p": ["播棋的棋盤大致分為兩排和四排兩類。西非和亞洲多是兩排，四排的棋盤則從東非一直分布到非洲南部。坦尚尼亞的巴奧是4排×8坑，名字在史瓦希里語裡就是「棋盤」的意思。", "像東南亞的晨卡、松卡那樣，有的棋盤兩端有存放所取棋子的大坑——「倉」。20世紀誕生於美國的「卡拉哈」也是帶倉的兩排形式；2000年，計算表明每坑4顆、6坑的卡拉哈先手必勝。"], "cap": ["播棋棋盤的幾種形狀：2排×6坑（奧瓦雷等），2排×7坑加兩端的倉（東南亞的晨卡等），4排×8坑（東非的巴奧等）"]}, {"h": "把它記下來的人", "p": ["一般認為，最早詳細記述播棋的歐洲學者是英國的托馬斯·海德。他在1694年的《東方遊戲考》中介紹了它的阿拉伯語名字和玩法。", "1836年，愛德華·W·萊恩在描寫開羅人生活的書中，記下了咖啡館裡玩的「曼卡拉」。如今研究者收集了各地的玩法，記錄下來的規則多達數百種。"], "cap": []}], "tl": [["6–7世紀", "古代阿克蘇姆王國遺址出土年代確定的最古老棋盤"], ["1694年", "托馬斯·海德在《東方遊戲考》中介紹播棋"], ["18–19世紀", "奧瓦雷等越過大西洋傳到加勒比海諸島"], ["1836年", "E·W·萊恩記下開羅的曼卡拉"], ["20世紀中葉", "帶倉的兩排播棋「卡拉哈」在美國發售"], ["2000年", "計算表明6坑4子的卡拉哈先手必勝"]]}}, "ko": {"mancala": {"kf": ["구멍의 돌을 모두 꺼내 다음 구멍부터 하나씩 나눠 넣으며 나아가는 ‘씨뿌리기’ 게임의 무리", "연대가 확실한 가장 오래된 판은 6~7세기 무렵 고대 악숨 왕국의 것", "두 줄, 네 줄, 창고가 있는 것 등 지역마다 판도 규칙도 다양하다"], "more": [{"h": "씨뿌리기", "p": ["만칼라에서는 자기 쪽 구멍 하나를 골라 돌을 모두 꺼내고, 다음 구멍부터 하나씩 넣어 갑니다. 밭에 씨를 뿌리는 듯한 이 동작을 ‘씨뿌리기’라고 부릅니다.", "서아프리카의 오와레는 48개의 돌을 12개 구멍에 4개씩 넣고 시작합니다. 마지막 돌이 들어간 상대 구멍이 2개나 3개가 되면 그 돌을 가져옵니다. 몇 개를 넣으면 어디서 멈추는지 미리 세어 읽는 힘이 중요한 게임입니다. 오와레는 대서양을 건너 카리브해 섬들에도 전해졌습니다."], "cap": ["오와레의 씨뿌리기. 금색 고리 구멍의 돌 3개를 시계 반대 방향으로 하나씩 넣고, 마지막 하나로 상대 구멍이 딱 3개가 되어 그 3개를 가져간다(빨간 고리)"]}, {"h": "두 줄과 네 줄", "p": ["만칼라 판은 크게 두 줄짜리와 네 줄짜리로 나뉩니다. 서아프리카와 아시아에는 두 줄 판이 많고, 네 줄 판은 동아프리카에서 남부 아프리카까지 퍼져 있습니다. 탄자니아의 바오는 4줄×8구멍이며, 이름은 스와힐리어로 ‘판’이라는 뜻입니다.", "동남아시아의 총칵이나 숭카처럼 판 양 끝에 잡은 돌을 모으는 큰 구멍 ‘창고’가 있는 것도 있습니다. 20세기 미국에서 태어난 ‘칼라’도 창고가 있는 두 줄 형태로, 2000년에는 6구멍에 4개씩으로 시작하는 칼라는 선수가 반드시 이긴다는 것이 계산으로 밝혀졌습니다."], "cap": ["만칼라 판 모양의 예. 2줄×6구멍(오와레 등), 2줄×7구멍에 양 끝의 창고(동남아시아의 총칵 등), 4줄×8구멍(동아프리카의 바오 등)"]}, {"h": "기록한 사람들", "p": ["만칼라를 자세히 쓴 첫 유럽 학자는 영국의 토머스 하이드로 알려져 있습니다. 1694년의 『동양의 놀이에 대하여』에서 아랍어 이름과 함께 놀이법을 소개했습니다.", "1836년에는 에드워드 W. 레인이 카이로 사람들의 생활을 그린 책에서 카페에서 즐기는 ‘만칼라’를 기록했습니다. 지금은 연구자들이 곳곳의 놀이법을 모아, 기록된 규칙이 수백 가지에 이릅니다."], "cap": []}], "tl": [["6~7세기", "고대 악숨 왕국 유적에서 연대가 확실한 가장 오래된 판"], ["1694년", "토머스 하이드가 『동양의 놀이에 대하여』에서 만칼라 소개"], ["18~19세기", "오와레 등이 대서양을 건너 카리브해 섬들로"], ["1836년", "E. W. 레인이 카이로의 만칼라를 기록"], ["20세기 중반", "미국에서 창고가 있는 두 줄 만칼라 ‘칼라’ 발매"], ["2000년", "6구멍 4개의 칼라는 선수 필승으로 계산됨"]]}}, "es": {"mancala": {"kf": ["Una familia de juegos de «siembra»: se sacan las semillas de un hoyo y se dejan una a una en los siguientes", "Los tableros más antiguos bien fechados proceden del antiguo reino de Aksum, hacia los siglos VI–VII", "Dos filas o cuatro, con o sin almacenes: el tablero y las reglas cambian de una región a otra"], "more": [{"h": "Sembrar", "p": ["En el mancala se elige un hoyo del propio lado, se sacan todas sus semillas y se dejan una a una en los hoyos siguientes. Este movimiento, como esparcir semillas en un campo, se llama sembrar.", "El oware, de África occidental, empieza con 48 semillas, cuatro en cada uno de 12 hoyos. Si la última semilla deja dos o tres en un hoyo rival, se capturan. Saber dónde terminará una siembra —contar por adelantado— lo es todo. El oware cruzó el Atlántico y también se juega en el Caribe."], "cap": ["La siembra en el oware. Las tres semillas del hoyo del anillo dorado se reparten una a una en sentido antihorario; la última deja exactamente 3 en un hoyo rival, que se capturan (anillo rojo)"]}, {"h": "Dos filas y cuatro", "p": ["Los tableros de mancala se dividen en general en dos tipos: de dos y de cuatro filas. Los de dos filas abundan en África occidental y Asia; los de cuatro se extienden de África oriental al sur del continente. El bao de Tanzania tiene 4 filas de 8 hoyos, y su nombre significa simplemente «tablero» en suajili.", "Algunos, como el congkak y el sungka del Sudeste Asiático, tienen en cada extremo un hoyo grande —un almacén— para las semillas capturadas. El kalah, nacido en Estados Unidos en el siglo XX, es un juego de dos filas con almacenes, y en 2000 se calculó que el kalah con seis hoyos y cuatro semillas en cada uno lo gana siempre el primer jugador."], "cap": ["Ejemplos de tableros de mancala: 2 filas de 6 (oware y otros), 2 filas de 7 con un almacén en cada extremo (congkak del Sudeste Asiático y otros), 4 filas de 8 (bao de África oriental y otros)"]}, {"h": "Quienes lo pusieron por escrito", "p": ["Se suele decir que el primer erudito europeo que describió el mancala con detalle fue el inglés Thomas Hyde. En De Ludis Orientalibus (1694) dio su nombre árabe y explicó cómo se jugaba.", "En 1836, Edward W. Lane, al describir la vida cotidiana de El Cairo, anotó el «mankalah» que se jugaba en los cafés. Hoy los investigadores han reunido juegos de todas partes, y las reglas registradas se cuentan por cientos."], "cap": []}], "tl": [["ss. VI–VII", "Los tableros más antiguos bien fechados, en yacimientos de Aksum"], ["1694", "Thomas Hyde describe el mancala en De Ludis Orientalibus"], ["ss. XVIII–XIX", "El oware y otros cruzan el Atlántico hasta el Caribe"], ["1836", "E. W. Lane anota el mankalah de El Cairo"], ["mediados del s. XX", "Sale a la venta en EE. UU. el kalah, de dos filas con almacenes"], ["2000", "Se calcula que el kalah de seis hoyos y cuatro semillas lo gana el primer jugador"]]}}, "fr": {"mancala": {"kf": ["Une famille de jeux de « semailles » : on prend les graines d’un trou et on les dépose une à une dans les suivants", "Les plus anciens tabliers bien datés viennent de l’ancien royaume d’Aksoum, vers les VIe–VIIe siècles", "Deux rangées ou quatre, avec ou sans greniers : tablier et règles changent d’une région à l’autre"], "more": [{"h": "Semer", "p": ["Au mancala, on choisit un trou de son côté, on en sort toutes les graines et on les dépose une à une dans les trous suivants. Ce geste, comme semer dans un champ, s’appelle les semailles.", "L’awalé (oware), d’Afrique de l’Ouest, commence avec 48 graines, quatre dans chacun des 12 trous. Si la dernière graine laisse deux ou trois graines dans un trou adverse, on les prend. Savoir où finira une semaille — compter d’avance — est essentiel. L’awalé a traversé l’Atlantique et se joue aussi aux Antilles."], "cap": ["Les semailles à l’awalé (oware). Les trois graines du trou cerclé d’or partent une à une dans le sens inverse des aiguilles d’une montre ; la dernière laisse exactement 3 graines dans un trou adverse, qui sont prises (cercle rouge)"]}, {"h": "Deux rangées et quatre", "p": ["Les tabliers de mancala se rangent en gros en deux familles : à deux et à quatre rangées. Les premiers dominent en Afrique de l’Ouest et en Asie ; les seconds s’étendent de l’Afrique de l’Est au sud du continent. Le bao de Tanzanie compte 4 rangées de 8 trous ; son nom veut simplement dire « tablier » en swahili.", "Certains, comme le congkak et le sungka d’Asie du Sud-Est, ont à chaque bout un grand trou — un grenier — pour les graines prises. Le kalah, né aux États-Unis au XXe siècle, est un jeu à deux rangées avec greniers ; en 2000, le calcul a montré que le kalah à six trous et quatre graines est gagné par le premier joueur."], "cap": ["Exemples de tabliers de mancala : 2 rangées de 6 (awalé et autres), 2 rangées de 7 avec un grenier à chaque bout (congkak d’Asie du Sud-Est et autres), 4 rangées de 8 (bao d’Afrique de l’Est et autres)"]}, {"h": "Ceux qui l’ont décrit", "p": ["On considère souvent l’Anglais Thomas Hyde comme le premier savant européen à décrire le mancala en détail. Dans De Ludis Orientalibus (1694), il en donna le nom arabe et la manière de jouer.", "En 1836, Edward W. Lane, décrivant la vie quotidienne au Caire, nota le « mankalah » joué dans les cafés. Aujourd’hui, les chercheurs ont recueilli des jeux du monde entier, et les règles relevées se comptent par centaines."], "cap": []}], "tl": [["VIe–VIIe s.", "Les plus anciens tabliers bien datés, sur des sites d’Aksoum"], ["1694", "Thomas Hyde décrit le mancala dans De Ludis Orientalibus"], ["XVIIIe–XIXe s.", "L’awalé et d’autres traversent l’Atlantique jusqu’aux Antilles"], ["1836", "E. W. Lane note le mankalah du Caire"], ["milieu du XXe s.", "Le kalah, à deux rangées et greniers, est commercialisé aux États-Unis"], ["2000", "Calcul : le kalah à six trous et quatre graines est gagné par le premier joueur"]]}}, "pt": {"mancala": {"kf": ["Uma família de jogos de «semeadura»: tiram-se as sementes de uma cova e deixam-se uma a uma nas seguintes", "Os tabuleiros mais antigos bem datados vêm do antigo reino de Axum, por volta dos séculos VI–VII", "Duas fileiras ou quatro, com ou sem depósitos: tabuleiro e regras mudam de região para região"], "more": [{"h": "Semear", "p": ["No mancala escolhe-se uma cova do próprio lado, tiram-se todas as sementes e deixa-se uma a uma nas covas seguintes. Esse gesto, como lançar sementes no campo, chama-se semeadura.", "O oware, da África Ocidental, começa com 48 sementes, quatro em cada uma de 12 covas. Se a última semente deixar duas ou três numa cova adversária, elas são capturadas. Saber onde a semeadura vai parar — contar antes — é tudo. O oware cruzou o Atlântico e também é jogado no Caribe."], "cap": ["A semeadura no oware. As três sementes da cova do anel dourado vão uma a uma no sentido anti-horário; a última deixa exatamente 3 numa cova adversária, que são capturadas (anel vermelho)"]}, {"h": "Duas fileiras e quatro", "p": ["Os tabuleiros de mancala dividem-se em geral em dois tipos: de duas e de quatro fileiras. Os de duas predominam na África Ocidental e na Ásia; os de quatro vão da África Oriental ao sul do continente. O bao da Tanzânia tem 4 fileiras de 8 covas, e o nome significa simplesmente «tabuleiro» em suaíli.", "Alguns, como o congkak e o sungka do Sudeste Asiático, têm em cada ponta uma cova grande — um depósito — para as sementes capturadas. O kalah, nascido nos EUA no século XX, é um jogo de duas fileiras com depósitos, e em 2000 calculou-se que o kalah de seis covas com quatro sementes é sempre vencido pelo primeiro jogador."], "cap": ["Exemplos de tabuleiros de mancala: 2 fileiras de 6 (oware e outros), 2 fileiras de 7 com um depósito em cada ponta (congkak do Sudeste Asiático e outros), 4 fileiras de 8 (bao da África Oriental e outros)"]}, {"h": "Quem o registrou", "p": ["Costuma-se dizer que o primeiro estudioso europeu a descrever o mancala em detalhe foi o inglês Thomas Hyde. Em De Ludis Orientalibus (1694), deu seu nome árabe e explicou como se jogava.", "Em 1836, Edward W. Lane, ao descrever o cotidiano do Cairo, registrou o «mankalah» jogado nos cafés. Hoje os pesquisadores reuniram jogos de toda parte, e as regras registradas somam centenas."], "cap": []}], "tl": [["sécs. VI–VII", "Os tabuleiros mais antigos bem datados, em sítios de Axum"], ["1694", "Thomas Hyde descreve o mancala em De Ludis Orientalibus"], ["sécs. XVIII–XIX", "O oware e outros cruzam o Atlântico até o Caribe"], ["1836", "E. W. Lane registra o mankalah do Cairo"], ["meados do séc. XX", "O kalah, de duas fileiras com depósitos, é vendido nos EUA"], ["2000", "Calcula-se que o kalah de seis covas e quatro sementes é vitória do primeiro jogador"]]}}, "de": {"mancala": {"kf": ["Eine Familie von „Säspielen“: Man nimmt die Samen aus einer Mulde und legt sie einzeln in die folgenden", "Die ältesten sicher datierten Bretter stammen aus dem alten Reich Aksum, etwa aus dem 6.–7. Jahrhundert", "Zwei Reihen oder vier, mit oder ohne Speicher – Brett und Regeln wechseln von Region zu Region"], "more": [{"h": "Säen", "p": ["Beim Mancala wählt man eine Mulde auf der eigenen Seite, nimmt alle Samen heraus und legt sie einzeln in die folgenden Mulden. Diese Bewegung, wie das Ausstreuen von Saat auf einem Feld, heißt Säen.", "Oware aus Westafrika beginnt mit 48 Samen, je vier in 12 Mulden. Macht der letzte Same zwei oder drei in einer gegnerischen Mulde, schlägt man sie. Zu wissen, wo eine Saat endet – vorauszuzählen –, ist alles. Oware überquerte den Atlantik und wird auch in der Karibik gespielt."], "cap": ["Säen beim Oware. Die drei Samen der gold umringten Mulde wandern einzeln gegen den Uhrzeigersinn; der letzte macht genau 3 in einer gegnerischen Mulde, die geschlagen werden (roter Ring)"]}, {"h": "Zwei Reihen und vier", "p": ["Mancala-Bretter teilen sich grob in zwei- und vierreihige. Zweireihige sind in Westafrika und Asien verbreitet, vierreihige reichen von Ostafrika bis ins südliche Afrika. Das tansanische Bao hat 4 Reihen zu 8 Mulden; sein Name heißt auf Swahili einfach „Brett“.", "Manche, wie Congkak und Sungka in Südostasien, haben an jedem Ende eine große Mulde – einen Speicher – für geschlagene Samen. Kalah, im 20. Jahrhundert in den USA entstanden, ist ein zweireihiges Spiel mit Speichern; 2000 zeigte eine Berechnung, dass Kalah mit sechs Mulden und je vier Samen vom Anziehenden gewonnen wird."], "cap": ["Beispiele für Mancala-Bretter: 2 Reihen zu 6 (Oware u. a.), 2 Reihen zu 7 mit je einem Speicher an den Enden (Congkak in Südostasien u. a.), 4 Reihen zu 8 (Bao in Ostafrika u. a.)"]}, {"h": "Die es aufschrieben", "p": ["Als erster europäischer Gelehrter, der Mancala genau beschrieb, gilt meist der Engländer Thomas Hyde. In De Ludis Orientalibus (1694) nannte er den arabischen Namen und die Spielweise.", "1836 hielt Edward W. Lane in seiner Schilderung des Alltags in Kairo das „Mankalah“ fest, das in Kaffeehäusern gespielt wurde. Heute haben Forscher Spiele aus aller Welt gesammelt; die aufgezeichneten Regelvarianten gehen in die Hunderte."], "cap": []}], "tl": [["6.–7. Jh.", "Die ältesten sicher datierten Bretter, aus Fundstätten von Aksum"], ["1694", "Thomas Hyde beschreibt Mancala in De Ludis Orientalibus"], ["18.–19. Jh.", "Oware und andere gelangen über den Atlantik in die Karibik"], ["1836", "E. W. Lane hält das Mankalah von Kairo fest"], ["Mitte 20. Jh.", "Kalah, zweireihig mit Speichern, kommt in den USA in den Handel"], ["2000", "Berechnung: Kalah mit sechs Mulden und vier Samen gewinnt der Anziehende"]]}}, "ru": {"mancala": {"kf": ["Семейство «посевных» игр: камни вынимают из лунки и раскладывают по одному в следующие", "Древнейшие точно датированные доски — из древнего Аксумского царства, примерно VI–VII веков", "Два ряда или четыре, с «амбарами» или без — доски и правила разнятся от края к краю"], "more": [{"h": "Посев", "p": ["В манкале выбирают лунку на своей стороне, вынимают все камни и кладут по одному в следующие лунки. Это движение, похожее на разбрасывание семян по полю, называют посевом.", "Оваре из Западной Африки начинают с 48 камнями, по четыре в каждой из 12 лунок. Если последний камень делает в лунке соперника два или три камня, их забирают. Всё решает умение заранее сосчитать, где закончится посев. Оваре пересекла Атлантику, в неё играют и на островах Карибского моря."], "cap": ["Посев в оваре. Три камня из лунки в золотом кольце раскладывают по одному против часовой стрелки; последний делает ровно 3 в лунке соперника — их забирают (красное кольцо)"]}, {"h": "Два ряда и четыре", "p": ["Доски манкалы в целом делятся на двух- и четырёхрядные. Двухрядные распространены в Западной Африке и Азии, четырёхрядные — от Восточной Африки до юга континента. Танзанийская бао — 4 ряда по 8 лунок; её название на суахили значит просто «доска».", "У некоторых, как у чонгкака и сунгки в Юго-Восточной Азии, на концах есть большие лунки — «амбары» для взятых камней. Калах, появившийся в США в XX веке, — двухрядная игра с амбарами; в 2000 году расчёт показал, что в калахе с шестью лунками по четыре камня первый игрок выигрывает."], "cap": ["Примеры досок манкалы: 2 ряда по 6 (оваре и др.), 2 ряда по 7 с «амбаром» на каждом конце (чонгкак в Юго-Восточной Азии и др.), 4 ряда по 8 (бао в Восточной Африке и др.)"]}, {"h": "Те, кто записал", "p": ["Первым европейским учёным, подробно описавшим манкалу, обычно называют англичанина Томаса Хайда. В труде «О восточных играх» (1694) он привёл её арабское название и правила.", "В 1836 году Эдвард У. Лейн, описывая повседневную жизнь Каира, записал «манкалу», в которую играли в кофейнях. Сегодня исследователи собрали игры со всего света, и записанных правил — сотни."], "cap": []}], "tl": [["VI–VII вв.", "Древнейшие точно датированные доски — из памятников Аксума"], ["1694", "Томас Хайд описывает манкалу в «О восточных играх»"], ["XVIII–XIX вв.", "Оваре и другие пересекают Атлантику и попадают в Карибский регион"], ["1836", "Э. У. Лейн записывает каирскую манкалу"], ["сер. XX в.", "В США выходит калах — двухрядная игра с амбарами"], ["2000", "Расчёт: калах с шестью лунками по четыре камня выигрывает первый игрок"]]}}, "tr": {"mancala": {"kf": ["Bir kuyudaki taşları alıp sonraki kuyulara birer birer bırakarak oynanan “ekme” oyunları ailesi", "Tarihi kesin olan en eski tahtalar, 6.–7. yüzyıl dolaylarındaki eski Aksum Krallığı’ndan", "İki sıra ya da dört, hazineli ya da hazinesiz: tahta ve kurallar bölgeden bölgeye değişir"], "more": [{"h": "Ekmek", "p": ["Mangalada kendi tarafından bir kuyu seçip içindeki bütün taşları alır, sonraki kuyulara birer birer bırakırsın. Tarlaya tohum serpmeye benzeyen bu harekete ekme denir.", "Batı Afrika’nın oware’si 48 taşla, 12 kuyunun her birine dörder taşla başlar. Son taş rakip kuyuyu iki ya da üç yaparsa o taşları alırsın. Ekmenin nerede biteceğini önceden saymak her şeydir. Oware Atlantik’i aşıp Karayipler’e de ulaştı."], "cap": ["Oware’de ekme. Altın halkalı kuyudaki üç taş saat yönünün tersine birer birer dağıtılır; sonuncusu rakip kuyuyu tam 3 yapınca o 3 taş alınır (kırmızı halka)"]}, {"h": "İki sıra ve dört sıra", "p": ["Mangala tahtaları kabaca iki ve dört sıralı olarak ikiye ayrılır. İki sıralılar Batı Afrika’da ve Asya’da yaygındır; dört sıralılar Doğu Afrika’dan kıtanın güneyine kadar uzanır. Tanzanya’nın bao’su 4 sıra × 8 kuyudur; adı Svahilicede düpedüz “tahta” demektir.", "Güneydoğu Asya’daki congkak ve sungka gibi bazılarında, iki uçta alınan taşların toplandığı büyük bir kuyu — hazine — bulunur. 20. yüzyılda ABD’de doğan Kalah da hazineli iki sıralı bir oyundur; 2000’de yapılan hesap, altı kuyulu ve dörder taşlı Kalah’ı ilk oyuncunun hep kazandığını gösterdi."], "cap": ["Mangala tahtası örnekleri: 2 sıra × 6 (oware vb.), 2 sıra × 7 ve iki uçta birer hazine (Güneydoğu Asya’nın congkak’ı vb.), 4 sıra × 8 (Doğu Afrika’nın bao’su vb.)"]}, {"h": "Onu yazıya geçirenler", "p": ["Mangalayı ayrıntılı anlatan ilk Avrupalı bilginin genellikle İngiliz Thomas Hyde olduğu söylenir. De Ludis Orientalibus’ta (1694) oyunun Arapça adını ve oynanışını verdi.", "1836’da Edward W. Lane, Kahire’nin gündelik yaşamını anlattığı kitabında kahvelerde oynanan “mankala”yı kaydetti. Bugün araştırmacılar dünyanın dört bir yanından oyunlar topladı; kaydedilen kural takımları yüzlercedir."], "cap": []}], "tl": [["6.–7. yy", "Aksum’daki yerleşimlerden, tarihi kesin en eski tahtalar"], ["1694", "Thomas Hyde, De Ludis Orientalibus’ta mangalayı anlatır"], ["18.–19. yy", "Oware ve benzerleri Atlantik’i aşıp Karayipler’e ulaşır"], ["1836", "E. W. Lane Kahire’deki mankalayı kaydeder"], ["20. yy ortası", "Hazineli iki sıralı Kalah ABD’de satışa çıkar"], ["2000", "Altı kuyulu dört taşlı Kalah’ı ilk oyuncunun kazandığı hesaplanır"]]}}, "id": {"mancala": {"kf": ["Keluarga permainan “menabur”: biji diambil dari satu lubang lalu dijatuhkan satu per satu ke lubang berikutnya", "Papan tertua yang pasti tarikhnya berasal dari Kerajaan Aksum kuno, sekitar abad ke-6–7", "Dua baris atau empat, dengan atau tanpa lumbung — papan dan aturannya berbeda di tiap wilayah"], "more": [{"h": "Menabur", "p": ["Dalam mancala, kamu memilih satu lubang di sisimu, mengambil semua bijinya, lalu menjatuhkannya satu per satu ke lubang-lubang berikutnya. Gerakan seperti menabur benih di ladang ini disebut menabur.", "Oware dari Afrika Barat dimulai dengan 48 biji, empat di tiap 12 lubang. Bila biji terakhir membuat lubang lawan berisi dua atau tiga, biji itu kamu ambil. Mengetahui di mana taburan akan berhenti — menghitung lebih dulu — adalah kuncinya. Oware menyeberangi Atlantik dan juga dimainkan di Karibia."], "cap": ["Menabur dalam oware. Tiga biji dari lubang bercincin emas dijatuhkan satu per satu berlawanan arah jarum jam; biji terakhir membuat lubang lawan berisi tepat 3, maka ketiganya diambil (cincin merah)"]}, {"h": "Dua baris dan empat", "p": ["Papan mancala secara garis besar terbagi dua: dua baris dan empat baris. Papan dua baris banyak di Afrika Barat dan Asia; papan empat baris tersebar dari Afrika Timur hingga Afrika bagian selatan. Bao dari Tanzania berukuran 4 baris × 8 lubang; namanya dalam bahasa Swahili berarti “papan”.", "Sebagian, seperti congklak dan sungka di Asia Tenggara, punya lubang besar di tiap ujung — lumbung — untuk biji tangkapan. Kalah, yang lahir di Amerika abad ke-20, adalah permainan dua baris dengan lumbung; pada 2000 perhitungan menunjukkan Kalah dengan enam lubang berisi empat biji selalu dimenangkan pemain pertama."], "cap": ["Contoh bentuk papan mancala: 2 baris × 6 (oware dll.), 2 baris × 7 dengan lumbung di kedua ujung (congklak di Asia Tenggara dll.), 4 baris × 8 (bao di Afrika Timur dll.)"]}, {"h": "Mereka yang mencatatnya", "p": ["Sarjana Eropa pertama yang menggambarkan mancala secara rinci biasanya disebut Thomas Hyde dari Inggris. Dalam De Ludis Orientalibus (1694) ia mencatat nama Arabnya dan cara bermainnya.", "Pada 1836, Edward W. Lane, saat menggambarkan kehidupan sehari-hari di Kairo, mencatat “mankalah” yang dimainkan di kedai kopi. Kini para peneliti telah mengumpulkan permainan dari mana-mana, dan aturan yang tercatat mencapai ratusan."], "cap": []}], "tl": [["Abad ke-6–7", "Papan tertua yang pasti tarikhnya, dari situs Aksum"], ["1694", "Thomas Hyde menggambarkan mancala dalam De Ludis Orientalibus"], ["Abad ke-18–19", "Oware dan lainnya menyeberangi Atlantik ke Karibia"], ["1836", "E. W. Lane mencatat mankalah di Kairo"], ["Pertengahan abad ke-20", "Kalah, dua baris dengan lumbung, dijual di AS"], ["2000", "Dihitung bahwa Kalah enam lubang empat biji dimenangkan pemain pertama"]]}}, "hi": {"mancala": {"kf": ["“बुवाई” वाले खेलों का परिवार: एक गड्ढे के सारे बीज उठाकर अगले गड्ढों में एक-एक डालते जाते हैं", "पक्की तारीख़ वाले सबसे पुराने बोर्ड प्राचीन अक्सुम राज्य के हैं, लगभग 6वीं–7वीं सदी के", "दो पंक्तियाँ या चार, भंडार के साथ या बिना — इलाक़े-इलाक़े में बोर्ड और नियम बदलते हैं"], "more": [{"h": "बुवाई", "p": ["मनकाला में अपनी ओर का एक गड्ढा चुनकर उसके सारे बीज निकालते हैं और अगले गड्ढों में एक-एक डालते जाते हैं। खेत में बीज छिड़कने जैसी इस चाल को बुवाई कहते हैं।", "पश्चिम अफ़्रीका का ओवारे 48 बीजों से शुरू होता है — 12 गड्ढों में चार-चार। आख़िरी बीज से विरोधी के गड्ढे में दो या तीन हो जाएँ, तो वे आपके। बुवाई कहाँ ख़त्म होगी, यह पहले से गिन लेना ही सब कुछ है। ओवारे अटलांटिक पार कर कैरिबियाई द्वीपों तक पहुँचा।"], "cap": ["ओवारे में बुवाई। सुनहरे घेरे वाले गड्ढे के तीन बीज घड़ी की उल्टी दिशा में एक-एक कर डाले जाते हैं; आख़िरी बीज विरोधी के गड्ढे में ठीक 3 कर देता है, तो वे 3 ले लिए जाते हैं (लाल घेरा)"]}, {"h": "दो पंक्तियाँ और चार", "p": ["मनकाला के बोर्ड मोटे तौर पर दो पंक्ति और चार पंक्ति वाले होते हैं। दो पंक्ति वाले पश्चिम अफ़्रीका और एशिया में आम हैं; चार पंक्ति वाले पूर्वी अफ़्रीका से दक्षिणी अफ़्रीका तक फैले हैं। तंज़ानिया का बाओ 4 पंक्ति × 8 गड्ढों का है; स्वाहिली में इसके नाम का मतलब ही “बोर्ड” है।", "दक्षिण-पूर्व एशिया के चोंगकाक और सुंगका जैसे कुछ बोर्डों के दोनों सिरों पर पकड़े गए बीजों के लिए बड़ा गड्ढा — भंडार — होता है। 20वीं सदी में अमेरिका में जन्मा कलाह भी भंडार वाला दो पंक्ति का खेल है; 2000 में गणना से पता चला कि छह गड्ढों और चार-चार बीजों वाला कलाह हमेशा पहला खिलाड़ी जीतता है।"], "cap": ["मनकाला बोर्डों के उदाहरण: 2 पंक्ति × 6 (ओवारे आदि), दोनों सिरों पर भंडार वाला 2 पंक्ति × 7 (दक्षिण-पूर्व एशिया का चोंगकाक आदि), 4 पंक्ति × 8 (पूर्वी अफ़्रीका का बाओ आदि)"]}, {"h": "इसे दर्ज करने वाले", "p": ["मनकाला का विस्तार से वर्णन करने वाले पहले यूरोपीय विद्वान आम तौर पर इंग्लैंड के थॉमस हाइड माने जाते हैं। ‘दे लूदिस ओरिएंतालिबुस’ (1694) में उन्होंने इसका अरबी नाम और खेलने का तरीक़ा दिया।", "1836 में एडवर्ड डब्ल्यू. लेन ने क़ाहिरा के रोज़मर्रा जीवन के वर्णन में क़हवाख़ानों में खेले जाने वाले “मनकाला” को दर्ज किया। आज शोधकर्ताओं ने दुनिया भर से खेल जुटाए हैं, और दर्ज नियमों की गिनती सैकड़ों में है।"], "cap": []}], "tl": [["6वीं–7वीं सदी", "अक्सुम के स्थलों से पक्की तारीख़ वाले सबसे पुराने बोर्ड"], ["1694", "थॉमस हाइड ने ‘दे लूदिस ओरिएंतालिबुस’ में मनकाला का वर्णन किया"], ["18वीं–19वीं सदी", "ओवारे आदि अटलांटिक पार कर कैरिबियन पहुँचे"], ["1836", "ई. डब्ल्यू. लेन ने क़ाहिरा का मनकाला दर्ज किया"], ["20वीं सदी का मध्य", "भंडार वाला दो पंक्ति का कलाह अमेरिका में बिकने लगा"], ["2000", "गणना: छह गड्ढे, चार बीज वाले कलाह में पहला खिलाड़ी जीतता है"]]}}, "ar": {"mancala": {"kf": ["عائلة من ألعاب «البذر»: تُرفع البذور من حفرة وتُلقى واحدة واحدة في الحفر التالية", "أقدم الألواح المؤرخة بثقة من مملكة أكسوم القديمة، نحو القرنين السادس والسابع", "صفّان أو أربعة، بمخازن أو بدونها: يتغير اللوح والقواعد من منطقة إلى أخرى"], "more": [{"h": "البذر", "p": ["في المنقلة تختار حفرة في جهتك، وترفع كل بذورها، ثم تلقيها واحدة واحدة في الحفر التالية. وتُسمّى هذه الحركة، الشبيهة بنثر البذور في الحقل، بذرًا.", "تبدأ الأواري من غرب أفريقيا بـ48 بذرة، أربعًا في كل حفرة من الحفر الاثنتي عشرة. فإذا جعلت البذرة الأخيرة حفرة للخصم اثنتين أو ثلاثًا أخذتَها. ومعرفة أين ينتهي البذر — أي العدّ مسبقًا — هي كل شيء. وقد عبرت الأواري الأطلسي وتُلعب أيضًا في جزر الكاريبي."], "cap": ["البذر في الأواري. تُوزَّع البذور الثلاث من الحفرة ذات الحلقة الذهبية واحدة واحدة عكس عقارب الساعة، فتجعل الأخيرة حفرة الخصم ثلاثًا تمامًا فتُؤخذ الثلاث (الحلقة الحمراء)"]}, {"h": "صفّان وأربعة", "p": ["تنقسم ألواح المنقلة عمومًا إلى ذات صفين وذات أربعة صفوف. تكثر ذات الصفين في غرب أفريقيا وآسيا، وتمتد ذات الأربعة من شرق أفريقيا إلى جنوبها. والباو التنزانية أربعة صفوف من 8 حفر، واسمها بالسواحلية يعني ببساطة «اللوح».", "وفي بعضها، مثل الكونغكاك والسونغكا في جنوب شرق آسيا، حفرة كبيرة في كل طرف — مخزن — للبذور المأخوذة. و«كالاه» التي وُلدت في أمريكا في القرن العشرين لعبة بصفين ومخزنين، وقد أظهر الحساب عام 2000 أن كالاه بست حفر وأربع بذور في كل منها يفوز بها اللاعب الأول دائمًا."], "cap": ["أمثلة لألواح المنقلة: صفّان من 6 (الأواري وغيرها)، صفّان من 7 مع مخزن في كل طرف (الكونغكاك في جنوب شرق آسيا وغيرها)، أربعة صفوف من 8 (الباو في شرق أفريقيا وغيرها)"]}, {"h": "من دوّنوها", "p": ["يُقال عادة إن أول عالم أوروبي وصف المنقلة بالتفصيل هو الإنجليزي توماس هايد، الذي ذكر في كتابه «عن الألعاب الشرقية» (1694) اسمها العربي وطريقة لعبها.", "وفي 1836 دوّن إدوارد و. لين، وهو يصف الحياة اليومية في القاهرة، «المنقلة» التي كانت تُلعب في المقاهي. واليوم جمع الباحثون ألعابًا من كل مكان، وتبلغ القواعد المدوّنة المئات."], "cap": []}], "tl": [["القرنان 6–7", "أقدم الألواح المؤرخة بثقة، من مواقع أكسوم"], ["1694", "توماس هايد يصف المنقلة في «عن الألعاب الشرقية»"], ["القرنان 18–19", "الأواري وغيرها تعبر الأطلسي إلى الكاريبي"], ["1836", "إ. و. لين يدوّن منقلة القاهرة"], ["منتصف القرن 20", "طرح «كالاه» ذات الصفين والمخزنين في الولايات المتحدة"], ["2000", "حساب يُظهر أن كالاه بست حفر وأربع بذور فوز للاعب الأول"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
/* 2026-11-24 (23): story 16 (morris) made fuller */
(T => { const D = {"ja": {"morris": {"kf": ["三重の四角の24の点に9つずつ駒を置き、3つ並べて相手の駒を取るゲーム", "ローマ時代から、船の甲板や大聖堂のベンチなど人の集まる場所に盤が刻まれてきた", "1996年、コンピュータで全局面が調べられ、最善なら引き分けと証明された"], "more": [{"h": "置く、動かす、跳ぶ", "p": ["ゲームは3つの段階で進みます。まず、2人が交互に9つの駒を空いた点に置いていきます。全部置き終わったら、線にそってとなりの空いた点へ1つずつ駒を動かします。", "線の上で3つの駒を一列に並べると「ミル」ができ、相手の駒を1つ盤から取れます。駒が3つに減ると、どの空いた点へも「跳んで」動けるというルールもよく使われます。駒が2つになるか、動けなくなったほうの負けです。"], "cap": ["ナイン・メンズ・モリスの盤。白がいちばん外の辺に3つ並べて「ミル」を作った（金）ので、黒の駒を1つ取れる（赤い×）"]}, {"h": "3人から12人まで", "p": ["モリスの仲間は、駒の数で呼ばれます。3つずつで遊ぶスリー・メンズ・モリスは、三目並べに近い小さな盤です。6つずつのシックス・メンズ・モリスは、四角が二重の盤を使います。", "12ずつのトゥエルブ・メンズ・モリスは、ナイン・メンズの盤にななめの線を足したものです。南アフリカでは「モラバラバ」の名で、牛飼いの少年たちが地面に描いて遊んできたといわれ、今は大会も開かれています。"], "cap": ["盤の大きさくらべ。数は1人の駒の数で、スリー・メンズ（3）、シックス・メンズ（6）、ナイン・メンズ（9）、トゥエルブ・メンズ（12）の盤"]}, {"h": "チェスの名人とコンピュータ", "p": ["チェスの世界チャンピオンだったエマヌエル・ラスカーも、このゲームに夢中になったひとりです。1931年の著書『諸民族のボードゲーム』で、駒を10ずつにして、置いている途中でも動かせる遊び方を考えました。", "1996年、スイスのラルフ・ガッサーは、終盤の局面をすべて計算した表と、序盤からの探索を組み合わせて、ナイン・メンズ・モリスは双方が最善を尽くせば引き分けになることを示しました。盤の点はわずか24でも、局面の数は数十億にのぼります。"], "cap": []}], "tl": [["ローマ時代", "帝国の各地の石に盤が刻まれる（確かな古い例）"], ["900年ごろ", "ノルウェーのゴクスタ船の甲板に盤が刻まれる"], ["1283年", "アルフォンソ10世の『遊戯の書』にモリスが描かれる"], ["中世", "イギリスの大聖堂の回廊のベンチに盤が刻まれる"], ["1590年代", "シェイクスピア『夏の夜の夢』に、泥で埋まった盤が出てくる"], ["1931年", "ラスカーが『諸民族のボードゲーム』で新しい遊び方を提案"], ["1996年", "ガッサーが「最善なら引き分け」を証明"]]}}, "en": {"morris": {"kf": ["Nine pieces each on the 24 points of three nested squares; make three in a row to take an enemy piece", "Since Roman times its board has been cut wherever people gathered — ship decks, cathedral benches", "In 1996 every position was examined by computer: with perfect play it is a draw"], "more": [{"h": "Place, move, fly", "p": ["The game runs in three phases. First the players take turns placing their nine pieces on empty points. When all are placed, they move one piece at a time along a line to a neighbouring empty point.", "Three of your pieces in a row along a line make a “mill”, and you take one of your opponent’s pieces from the board. A common rule lets a player reduced to three pieces “fly” to any empty point. You lose when you are down to two pieces or cannot move."], "cap": ["A nine men’s morris board. White has made a mill of three along the outer edge (gold) and may take one black piece (red cross)"]}, {"h": "From three men to twelve", "p": ["The family is named by its number of pieces. Three men’s morris, with three pieces each, is a small board close to noughts and crosses. Six men’s morris uses a board of two nested squares.", "Twelve men’s morris adds diagonal lines to the nine men’s board. In South Africa it is called morabaraba; herd boys are said to have scratched it on the ground, and today it has its own tournaments."], "cap": ["Boards compared. The number is how many pieces each player has: three, six, nine and twelve men’s morris"]}, {"h": "A chess champion and a computer", "p": ["The world chess champion Emanuel Lasker was among those taken with the game. In his book Brettspiele der Völker (1931) he proposed a version with ten pieces each, in which pieces may move even before all are placed.", "In 1996 Ralph Gasser in Switzerland combined complete tables of endgame positions with a search from the opening to show that nine men’s morris is a draw when both sides play perfectly. The board has only 24 points, yet the positions run into billions."], "cap": []}], "tl": [["Roman era", "Boards are cut in stone across the empire (the first secure examples)"], ["c. 900", "A board is cut on a deck plank of the Gokstad ship in Norway"], ["1283", "Alfonso X’s Book of Games illustrates morris"], ["Middle Ages", "Boards are cut on cloister benches of English cathedrals"], ["1590s", "Shakespeare’s A Midsummer Night’s Dream mentions a board filled with mud"], ["1931", "Lasker proposes a new version in Brettspiele der Völker"], ["1996", "Gasser proves a draw with perfect play"]]}}, "zh": {"morris": {"kf": ["在三个套在一起的方框共24个点上各放9枚子，连成三子就吃掉对方一子", "从罗马时代起，船的甲板、大教堂的石凳等人群聚集之处都刻着棋盘", "1996年电脑查遍所有局面，证明最佳下法下为和棋"], "more": [{"h": "落子、走子、飞子", "p": ["游戏分三个阶段。先由双方轮流把9枚子放到空点上；全部放完后，每次沿线把一枚子走到相邻的空点。", "沿线把三枚子连成一行就“成磨”，可以从盘上拿掉对方一枚子。常见的规则是：子减到3枚时，可以“飞”到任何空点。子剩2枚或无路可走的一方输。"], "cap": ["九子棋棋盘。白方在最外框的一边连成三子“成磨”（金色），可以吃掉一枚黑子（红叉）"]}, {"h": "从三子到十二子", "p": ["这一族游戏以子数命名。每人3枚的三子棋棋盘很小，接近井字棋；每人6枚的六子棋用两层方框的棋盘。", "每人12枚的十二子棋，是在九子棋棋盘上加了斜线。在南非叫“莫拉巴拉巴”，据说放牛的少年在地上画着玩，如今也有比赛。"], "cap": ["棋盘比较。数字是每人的子数：三子棋、六子棋、九子棋、十二子棋的棋盘"]}, {"h": "国际象棋名人与电脑", "p": ["国际象棋世界冠军埃马努埃尔·拉斯克也迷上了这种游戏。他在1931年的《各民族的棋类游戏》中，提出每人10枚、在落子阶段也能走子的新玩法。", "1996年，瑞士的拉尔夫·加瑟把算尽所有残局的表格与从开局起的搜索结合起来，证明双方都下最佳着法时九子棋是和棋。棋盘只有24个点，局面数却多达数十亿。"], "cap": []}], "tl": [["罗马时代", "帝国各地的石头上刻着棋盘（可靠的古例）"], ["900年前后", "挪威戈克斯塔德船的甲板上刻着棋盘"], ["1283年", "阿方索十世的《游戏之书》画有九子棋"], ["中世纪", "英国大教堂回廊的石凳上刻着棋盘"], ["1590年代", "莎士比亚《仲夏夜之梦》写到被泥填满的棋盘"], ["1931年", "拉斯克在《各民族的棋类游戏》中提出新玩法"], ["1996年", "加瑟证明最佳下法下为和棋"]]}}, "zh-TW": {"morris": {"kf": ["在三個套在一起的方框共24個點上各放9枚子，連成三子就吃掉對方一子", "從羅馬時代起，船的甲板、大教堂的石凳等人群聚集之處都刻著棋盤", "1996年電腦查遍所有局面，證明最佳下法下為和棋"], "more": [{"h": "落子、走子、飛子", "p": ["遊戲分三個階段。先由雙方輪流把9枚子放到空點上；全部放完後，每次沿線把一枚子走到相鄰的空點。", "沿線把三枚子連成一行就「成磨」，可以從盤上拿掉對方一枚子。常見的規則是：子減到3枚時，可以「飛」到任何空點。子剩2枚或無路可走的一方輸。"], "cap": ["九子棋棋盤。白方在最外框的一邊連成三子「成磨」（金色），可以吃掉一枚黑子（紅叉）"]}, {"h": "從三子到十二子", "p": ["這一族遊戲以子數命名。每人3枚的三子棋棋盤很小，接近井字遊戲；每人6枚的六子棋用兩層方框的棋盤。", "每人12枚的十二子棋，是在九子棋棋盤上加了斜線。在南非叫「莫拉巴拉巴」，據說放牛的少年在地上畫著玩，如今也有比賽。"], "cap": ["棋盤比較。數字是每人的子數：三子棋、六子棋、九子棋、十二子棋的棋盤"]}, {"h": "西洋棋名人與電腦", "p": ["西洋棋世界冠軍埃馬努埃爾·拉斯克也迷上了這種遊戲。他在1931年的《各民族的棋類遊戲》中，提出每人10枚、在落子階段也能走子的新玩法。", "1996年，瑞士的拉爾夫·加瑟把算盡所有殘局的表格與從開局起的搜索結合起來，證明雙方都下最佳著法時九子棋是和棋。棋盤只有24個點，局面數卻多達數十億。"], "cap": []}], "tl": [["羅馬時代", "帝國各地的石頭上刻著棋盤（可靠的古例）"], ["900年前後", "挪威科克斯塔德船的甲板上刻著棋盤"], ["1283年", "阿方索十世的《遊戲之書》畫有九子棋"], ["中世紀", "英國大教堂迴廊的石凳上刻著棋盤"], ["1590年代", "莎士比亞《仲夏夜之夢》寫到被泥填滿的棋盤"], ["1931年", "拉斯克在《各民族的棋類遊戲》中提出新玩法"], ["1996年", "加瑟證明最佳下法下為和棋"]]}}, "ko": {"morris": {"kf": ["세 겹 사각형의 24개 점에 9개씩 말을 놓고, 셋을 나란히 세워 상대 말을 잡는 게임", "로마 시대부터 배의 갑판, 대성당의 돌 벤치 등 사람이 모이는 곳마다 판이 새겨졌다", "1996년 컴퓨터로 모든 국면을 조사해, 최선이면 무승부임이 증명되었다"], "more": [{"h": "놓고, 움직이고, 뛴다", "p": ["게임은 세 단계로 진행됩니다. 먼저 두 사람이 번갈아 9개의 말을 빈 점에 놓습니다. 모두 놓으면, 선을 따라 옆의 빈 점으로 말을 하나씩 움직입니다.", "선 위에 말 셋을 한 줄로 세우면 ‘밀’이 되어 상대 말 하나를 판에서 들어냅니다. 말이 셋으로 줄면 어느 빈 점으로든 ‘뛸’ 수 있다는 규칙도 흔히 씁니다. 말이 둘이 되거나 움직일 수 없게 된 쪽이 집니다."], "cap": ["나인 멘스 모리스 판. 백이 가장 바깥 변에 셋을 세워 ‘밀’을 만들었으므로(금색) 흑 말 하나를 잡을 수 있다(빨간 ×)"]}, {"h": "셋에서 열둘까지", "p": ["모리스 가족은 말의 수로 불립니다. 셋씩 하는 스리 멘스 모리스는 틱택토에 가까운 작은 판입니다. 여섯씩 하는 식스 멘스 모리스는 사각형이 두 겹인 판을 씁니다.", "열둘씩 하는 트웰브 멘스 모리스는 나인 멘스 판에 대각선을 더한 것입니다. 남아프리카에서는 ‘모라바라바’라 불리며, 소 치는 소년들이 땅에 그려 놀았다고 하고, 지금은 대회도 열립니다."], "cap": ["판 크기 비교. 숫자는 한 사람의 말 수로, 스리·식스·나인·트웰브 멘스 모리스의 판"]}, {"h": "체스 챔피언과 컴퓨터", "p": ["체스 세계 챔피언 에마누엘 라스커도 이 게임에 빠진 사람이었습니다. 1931년의 책 『여러 민족의 보드게임』에서 말을 열 개씩으로 하고, 놓는 도중에도 움직일 수 있는 방식을 제안했습니다.", "1996년 스위스의 랄프 가서는 모든 종반 국면을 계산한 표와 초반부터의 탐색을 합쳐, 양쪽이 최선을 다하면 나인 멘스 모리스는 무승부임을 보였습니다. 판의 점은 24개뿐이지만 국면 수는 수십억에 이릅니다."], "cap": []}], "tl": [["로마 시대", "제국 곳곳의 돌에 판이 새겨짐(확실한 옛 예)"], ["900년 무렵", "노르웨이 고크스타 배의 갑판에 판이 새겨짐"], ["1283년", "알폰소 10세의 『놀이의 책』에 모리스가 그려짐"], ["중세", "영국 대성당 회랑의 벤치에 판이 새겨짐"], ["1590년대", "셰익스피어 『한여름 밤의 꿈』에 진흙으로 메워진 판이 나옴"], ["1931년", "라스커가 『여러 민족의 보드게임』에서 새 방식 제안"], ["1996년", "가서가 ‘최선이면 무승부’를 증명"]]}}, "es": {"morris": {"kf": ["Nueve fichas por jugador en los 24 puntos de tres cuadrados anidados; tres en línea capturan una ficha rival", "Desde época romana, su tablero se grabó allí donde la gente se reunía: cubiertas de barcos, bancos de catedrales", "En 1996 se examinaron por ordenador todas las posiciones: con juego perfecto, tablas"], "more": [{"h": "Colocar, mover, volar", "p": ["La partida tiene tres fases. Primero los jugadores colocan por turnos sus nueve fichas en puntos vacíos. Cuando todas están puestas, mueven una ficha cada vez por una línea hasta un punto vecino vacío.", "Tres fichas propias en línea forman un «molino» y permiten retirar una ficha rival del tablero. Una regla habitual permite al jugador que queda con tres fichas «volar» a cualquier punto vacío. Pierde quien se queda con dos fichas o no puede mover."], "cap": ["Un tablero de molino. Las blancas han formado un molino en el lado exterior (dorado) y pueden quitar una ficha negra (cruz roja)"]}, {"h": "De tres fichas a doce", "p": ["La familia se nombra por su número de fichas. El molino de tres, con tres fichas cada uno, es un tablero pequeño cercano al tres en raya. El de seis usa un tablero de dos cuadrados anidados.", "El de doce añade líneas diagonales al tablero del de nueve. En Sudáfrica se llama morabaraba; se dice que los pastorcillos lo trazaban en el suelo, y hoy tiene sus propios torneos."], "cap": ["Tableros comparados. El número indica las fichas de cada jugador: molino de tres, de seis, de nueve y de doce"]}, {"h": "Un campeón de ajedrez y una computadora", "p": ["El campeón mundial de ajedrez Emanuel Lasker fue uno de los que se apasionaron por el juego. En su libro Brettspiele der Völker (1931) propuso una versión con diez fichas por jugador, en la que se puede mover antes de haber colocado todas.", "En 1996, Ralph Gasser, en Suiza, combinó tablas completas de finales con una búsqueda desde la apertura y demostró que el molino de nueve es tablas si ambos juegan perfectamente. El tablero tiene solo 24 puntos, pero las posiciones se cuentan por miles de millones."], "cap": []}], "tl": [["época romana", "Se graban tableros en piedra por todo el imperio (los primeros ejemplos seguros)"], ["h. 900", "Se graba un tablero en una tabla de la cubierta del barco de Gokstad (Noruega)"], ["1283", "El Libro de los juegos de Alfonso X ilustra el molino"], ["Edad Media", "Se graban tableros en bancos de claustros de catedrales inglesas"], ["década de 1590", "El sueño de una noche de verano, de Shakespeare, menciona un tablero lleno de barro"], ["1931", "Lasker propone una nueva versión en Brettspiele der Völker"], ["1996", "Gasser demuestra que con juego perfecto es tablas"]]}}, "pt": {"morris": {"kf": ["Nove peças por jogador nos 24 pontos de três quadrados encaixados; três em linha capturam uma peça adversária", "Desde a época romana seu tabuleiro foi gravado onde as pessoas se reuniam: conveses de navios, bancos de catedrais", "Em 1996 todas as posições foram examinadas por computador: com jogo perfeito, empate"], "more": [{"h": "Colocar, mover, voar", "p": ["O jogo tem três fases. Primeiro os jogadores colocam por turnos suas nove peças em pontos vazios. Quando todas estão colocadas, movem uma peça por vez ao longo de uma linha até um ponto vizinho vazio.", "Três peças suas em linha formam um «moinho», e você retira uma peça do adversário. Uma regra comum deixa quem ficou com três peças «voar» para qualquer ponto vazio. Perde quem fica com duas peças ou não pode mover."], "cap": ["Um tabuleiro de trilha. As brancas formaram um moinho no lado externo (dourado) e podem retirar uma peça preta (cruz vermelha)"]}, {"h": "De três peças a doze", "p": ["A família é nomeada pelo número de peças. A trilha de três, com três peças cada, é um tabuleiro pequeno, próximo do jogo da velha. A de seis usa um tabuleiro de dois quadrados encaixados.", "A de doze acrescenta linhas diagonais ao tabuleiro da de nove. Na África do Sul chama-se morabaraba; diz-se que meninos pastores o riscavam no chão, e hoje tem seus próprios torneios."], "cap": ["Tabuleiros comparados. O número é quantas peças cada jogador tem: trilha de três, de seis, de nove e de doze"]}, {"h": "Um campeão de xadrez e um computador", "p": ["O campeão mundial de xadrez Emanuel Lasker foi um dos que se apaixonaram pelo jogo. No livro Brettspiele der Völker (1931) propôs uma versão com dez peças para cada um, em que se pode mover antes de colocar todas.", "Em 1996, Ralph Gasser, na Suíça, combinou tabelas completas de finais com uma busca a partir da abertura e mostrou que a trilha de nove é empate se os dois jogarem perfeitamente. O tabuleiro tem só 24 pontos, mas as posições chegam a bilhões."], "cap": []}], "tl": [["época romana", "Tabuleiros gravados em pedra por todo o império (os primeiros exemplos seguros)"], ["c. 900", "Um tabuleiro é gravado numa tábua do convés do navio de Gokstad (Noruega)"], ["1283", "O Livro dos Jogos de Afonso X ilustra a trilha"], ["Idade Média", "Tabuleiros gravados em bancos de claustros de catedrais inglesas"], ["década de 1590", "Sonho de uma Noite de Verão, de Shakespeare, cita um tabuleiro cheio de lama"], ["1931", "Lasker propõe uma nova versão em Brettspiele der Völker"], ["1996", "Gasser prova que com jogo perfeito é empate"]]}}, "fr": {"morris": {"kf": ["Neuf pions chacun sur les 24 points de trois carrés emboîtés ; trois alignés prennent un pion adverse", "Depuis l’époque romaine, son tablier a été gravé partout où l’on se réunissait : ponts de navires, bancs de cathédrales", "En 1996, toutes les positions ont été examinées par ordinateur : en jeu parfait, c’est nul"], "more": [{"h": "Poser, déplacer, voler", "p": ["La partie se joue en trois phases. D’abord, les joueurs posent tour à tour leurs neuf pions sur des points libres. Une fois tous posés, ils déplacent un pion à la fois le long d’une ligne vers un point voisin libre.", "Trois pions alignés sur une ligne forment un « moulin » et permettent de retirer un pion adverse. Une règle courante permet au joueur réduit à trois pions de « voler » vers n’importe quel point libre. On perd quand il ne reste que deux pions ou qu’on ne peut plus bouger."], "cap": ["Un tablier de jeu du moulin. Les Blancs ont formé un moulin sur le côté extérieur (or) et peuvent prendre un pion noir (croix rouge)"]}, {"h": "De trois pions à douze", "p": ["La famille se nomme d’après le nombre de pions. Le moulin à trois, avec trois pions chacun, est un petit tablier proche du morpion. Le moulin à six utilise deux carrés emboîtés.", "Le moulin à douze ajoute des diagonales au tablier du moulin à neuf. En Afrique du Sud, on l’appelle morabaraba ; les jeunes bouviers, dit-on, le traçaient sur le sol, et il a aujourd’hui ses tournois."], "cap": ["Tabliers comparés. Le nombre indique les pions de chaque joueur : moulin à trois, à six, à neuf et à douze"]}, {"h": "Un champion d’échecs et un ordinateur", "p": ["Le champion du monde d’échecs Emanuel Lasker se passionna lui aussi pour ce jeu. Dans Brettspiele der Völker (1931), il proposa une version à dix pions chacun, où l’on peut déplacer avant d’avoir tout posé.", "En 1996, le Suisse Ralph Gasser combina des tables complètes de finales et une recherche depuis l’ouverture pour montrer que le jeu du moulin est nul si les deux camps jouent parfaitement. Le tablier n’a que 24 points, mais les positions se comptent par milliards."], "cap": []}], "tl": [["époque romaine", "Des tabliers gravés dans la pierre à travers l’empire (premiers exemples sûrs)"], ["vers 900", "Un tablier est gravé sur une planche du pont du navire de Gokstad (Norvège)"], ["1283", "Le Livre des jeux d’Alphonse X illustre le moulin"], ["Moyen Âge", "Des tabliers gravés sur les bancs des cloîtres de cathédrales anglaises"], ["années 1590", "Le Songe d’une nuit d’été de Shakespeare évoque un tablier rempli de boue"], ["1931", "Lasker propose une nouvelle version dans Brettspiele der Völker"], ["1996", "Gasser prouve qu’en jeu parfait, c’est nul"]]}}, "de": {"morris": {"kf": ["Je neun Steine auf den 24 Punkten dreier ineinanderliegender Quadrate; drei in einer Reihe schlagen einen gegnerischen Stein", "Seit der Römerzeit wurde das Brett überall eingeritzt, wo Menschen zusammenkamen – auf Schiffsdecks, Domsitzbänken", "1996 wurden alle Stellungen per Computer untersucht: Bei perfektem Spiel endet Mühle remis"], "more": [{"h": "Setzen, ziehen, springen", "p": ["Das Spiel hat drei Phasen. Zuerst setzen die Spieler abwechselnd ihre neun Steine auf freie Punkte. Sind alle gesetzt, zieht man je einen Stein entlang einer Linie auf einen benachbarten freien Punkt.", "Drei eigene Steine in einer Reihe bilden eine „Mühle“, und man nimmt dem Gegner einen Stein vom Brett. Nach einer verbreiteten Regel darf, wer nur noch drei Steine hat, auf jeden freien Punkt „springen“. Verloren hat, wer nur noch zwei Steine hat oder nicht mehr ziehen kann."], "cap": ["Ein Mühlebrett. Weiß hat an der äußeren Kante eine Mühle geschlossen (gold) und darf einen schwarzen Stein nehmen (rotes Kreuz)"]}, {"h": "Von drei Steinen bis zwölf", "p": ["Die Familie wird nach der Zahl der Steine benannt. Die Dreiermühle mit drei Steinen je Spieler ist ein kleines Brett, nahe am Tic-Tac-Toe. Die Sechsermühle nutzt ein Brett aus zwei ineinanderliegenden Quadraten.", "Die Zwölfermühle ergänzt das Brett der Neunermühle um Diagonalen. In Südafrika heißt sie Morabaraba; Hirtenjungen sollen sie in den Boden geritzt haben, und heute gibt es eigene Turniere."], "cap": ["Bretter im Vergleich. Die Zahl nennt die Steine je Spieler: Dreier-, Sechser-, Neuner- und Zwölfermühle"]}, {"h": "Ein Schachweltmeister und ein Computer", "p": ["Auch Schachweltmeister Emanuel Lasker war von dem Spiel begeistert. In seinem Buch Brettspiele der Völker (1931) schlug er eine Fassung mit je zehn Steinen vor, bei der man schon ziehen darf, bevor alle Steine gesetzt sind.", "1996 verband der Schweizer Ralph Gasser vollständige Endspieltabellen mit einer Suche von der Eröffnung aus und zeigte: Bei perfektem Spiel beider Seiten endet Mühle remis. Das Brett hat nur 24 Punkte, doch die Stellungen gehen in die Milliarden."], "cap": []}], "tl": [["Römerzeit", "Bretter werden überall im Reich in Stein geritzt (erste sichere Beispiele)"], ["um 900", "Ein Brett wird in eine Deckplanke des Gokstad-Schiffs (Norwegen) geritzt"], ["1283", "Das Buch der Spiele Alfons’ X. bildet Mühle ab"], ["Mittelalter", "Bretter auf Kreuzgangbänken englischer Kathedralen"], ["1590er", "Shakespeares Ein Sommernachtstraum erwähnt ein mit Schlamm gefülltes Brett"], ["1931", "Lasker schlägt in Brettspiele der Völker eine neue Fassung vor"], ["1996", "Gasser beweist: bei perfektem Spiel remis"]]}}, "ru": {"morris": {"kf": ["По девять фишек на 24 точках трёх вложенных квадратов; три в ряд снимают фишку соперника", "С римских времён доску вырезали везде, где собирались люди: на палубах кораблей, на скамьях соборов", "В 1996 году компьютер перебрал все позиции: при идеальной игре — ничья"], "more": [{"h": "Ставить, ходить, летать", "p": ["Партия идёт в три этапа. Сначала игроки по очереди ставят свои девять фишек на свободные точки. Когда все поставлены, фишки по одной передвигают по линии на соседнюю свободную точку.", "Три свои фишки в ряд на линии образуют «мельницу», и можно снять с доски фишку соперника. По распространённому правилу игрок, у которого осталось три фишки, может «летать» на любую свободную точку. Проигрывает тот, у кого осталось две фишки или нет хода."], "cap": ["Доска мельницы. Белые выстроили мельницу на внешней стороне (золото) и могут снять чёрную фишку (красный крест)"]}, {"h": "От трёх фишек до двенадцати", "p": ["Семейство называют по числу фишек. Мельница на три фишки — маленькая доска, близкая к крестикам-ноликам. Для шести фишек используют доску из двух вложенных квадратов.", "Мельница на двенадцать фишек добавляет к доске диагонали. В Южной Африке её зовут морабараба; говорят, мальчишки-пастухи чертили её на земле, а сегодня по ней проводят турниры."], "cap": ["Доски в сравнении. Число — фишки каждого игрока: мельница на три, шесть, девять и двенадцать фишек"]}, {"h": "Чемпион по шахматам и компьютер", "p": ["Увлекался мельницей и чемпион мира по шахматам Эмануил Ласкер. В книге «Настольные игры народов» (1931) он предложил вариант с десятью фишками у каждого, где ходить можно, ещё не выставив все фишки.", "В 1996 году швейцарец Ральф Гассер соединил полные таблицы эндшпилей с перебором от начала партии и показал: при идеальной игре обеих сторон мельница заканчивается вничью. На доске всего 24 точки, но позиций — миллиарды."], "cap": []}], "tl": [["римская эпоха", "Доски вырезают в камне по всей империи (первые надёжные примеры)"], ["ок. 900", "Доску вырезают на палубной доске корабля из Гокстада (Норвегия)"], ["1283", "«Книга игр» Альфонсо X изображает мельницу"], ["Средние века", "Доски на скамьях галерей английских соборов"], ["1590-е", "В «Сне в летнюю ночь» Шекспира — доска, залитая грязью"], ["1931", "Ласкер предлагает новый вариант в «Настольных играх народов»"], ["1996", "Гассер доказывает ничью при идеальной игре"]]}}, "tr": {"morris": {"kf": ["İç içe üç karenin 24 noktasına dokuzar taş; üçü bir sıraya gelince rakipten bir taş alınır", "Roma döneminden beri tahtası insanların toplandığı her yere oyuldu: gemi güvertelerine, katedral sıralarına", "1996’da tüm konumlar bilgisayarla incelendi: kusursuz oyunda beraberlik"], "more": [{"h": "Koy, sür, uç", "p": ["Oyun üç aşamada ilerler. Önce oyuncular sırayla dokuz taşını boş noktalara koyar. Hepsi konunca, bir çizgi boyunca komşu boş noktaya her seferinde bir taş sürülür.", "Bir çizgi üzerinde üç taşını sıraya dizersen “değirmen” olur ve rakibin bir taşını tahtadan alırsın. Yaygın bir kurala göre üç taşı kalan oyuncu herhangi bir boş noktaya “uçabilir”. İki taşı kalan ya da hamle yapamayan kaybeder."], "cap": ["Bir dokuz taş tahtası. Beyaz dış kenarda değirmen kurdu (altın) ve bir siyah taş alabilir (kırmızı çarpı)"]}, {"h": "Üç taştan on ikiye", "p": ["Aile, taş sayısına göre adlandırılır. Üçer taşlı oyun, XOX’a yakın küçük bir tahtadır. Altışar taşlı oyun iç içe iki kareli bir tahta kullanır.", "On ikişer taşlı oyun, dokuz taş tahtasına çapraz çizgiler ekler. Güney Afrika’da morabaraba denir; sığır güden çocukların onu toprağa çizdiği anlatılır, bugün turnuvaları bile vardır."], "cap": ["Tahtaların karşılaştırması. Sayı her oyuncunun taşıdır: üç, altı, dokuz ve on iki taş"]}, {"h": "Bir satranç şampiyonu ve bir bilgisayar", "p": ["Dünya satranç şampiyonu Emanuel Lasker de bu oyuna tutulanlardandı. Brettspiele der Völker (1931) kitabında, oyuncu başına on taşlı ve bütün taşlar konmadan da sürülebilen bir sürüm önerdi.", "1996’da İsviçreli Ralph Gasser, oyun sonlarının tam tablolarını açılıştan başlayan bir aramayla birleştirerek, iki taraf da kusursuz oynarsa dokuz taşın berabere bittiğini gösterdi. Tahtada yalnızca 24 nokta vardır ama konumların sayısı milyarları bulur."], "cap": []}], "tl": [["Roma dönemi", "İmparatorluk boyunca taşlara tahtalar oyulur (ilk kesin örnekler)"], ["y. 900", "Norveç’teki Gokstad gemisinin güverte tahtasına bir tahta oyulur"], ["1283", "X. Alfonso’nun Oyunlar Kitabı dokuz taşı resmeder"], ["Orta Çağ", "İngiliz katedrallerinin revak sıralarına tahtalar oyulur"], ["1590’lar", "Shakespeare’in Bir Yaz Gecesi Rüyası çamurla dolmuş bir tahtadan söz eder"], ["1931", "Lasker, Brettspiele der Völker’de yeni bir sürüm önerir"], ["1996", "Gasser kusursuz oyunda beraberliği kanıtlar"]]}}, "id": {"morris": {"kf": ["Sembilan bidak tiap pemain di 24 titik tiga persegi bersarang; tiga sebaris mengambil satu bidak lawan", "Sejak zaman Romawi papannya dipahat di mana pun orang berkumpul: geladak kapal, bangku katedral", "Pada 1996 semua posisi diperiksa komputer: bila dimainkan sempurna, hasilnya remis"], "more": [{"h": "Taruh, gerakkan, terbang", "p": ["Permainan berjalan dalam tiga tahap. Mula-mula pemain bergantian menaruh sembilan bidaknya di titik kosong. Setelah semua tertaruh, satu bidak digerakkan tiap giliran menyusuri garis ke titik tetangga yang kosong.", "Tiga bidakmu sebaris di satu garis membentuk “gilingan”, dan kamu mengambil satu bidak lawan dari papan. Aturan yang lazim membolehkan pemain yang tinggal punya tiga bidak untuk “terbang” ke titik kosong mana pun. Yang kalah adalah yang tinggal punya dua bidak atau tak bisa bergerak."], "cap": ["Papan nine men’s morris. Putih membentuk gilingan di sisi terluar (emas) dan boleh mengambil satu bidak hitam (silang merah)"]}, {"h": "Dari tiga bidak hingga dua belas", "p": ["Keluarga ini dinamai menurut jumlah bidaknya. Morris tiga bidak adalah papan kecil yang mirip tic-tac-toe. Morris enam bidak memakai papan dua persegi bersarang.", "Morris dua belas bidak menambahkan garis diagonal pada papan morris sembilan. Di Afrika Selatan namanya morabaraba; konon anak-anak penggembala menggambarnya di tanah, dan kini ia punya turnamen sendiri."], "cap": ["Perbandingan papan. Angka menunjukkan jumlah bidak tiap pemain: morris tiga, enam, sembilan, dan dua belas"]}, {"h": "Juara catur dan komputer", "p": ["Juara dunia catur Emanuel Lasker termasuk yang tergila-gila pada permainan ini. Dalam bukunya Brettspiele der Völker (1931) ia mengusulkan versi dengan sepuluh bidak tiap pemain, yang bidaknya boleh digerakkan sebelum semua ditaruh.", "Pada 1996 Ralph Gasser dari Swiss menggabungkan tabel lengkap posisi akhir dengan penelusuran dari pembukaan, dan menunjukkan bahwa nine men’s morris berakhir remis bila kedua pihak bermain sempurna. Papannya hanya 24 titik, tetapi jumlah posisinya mencapai miliaran."], "cap": []}], "tl": [["Zaman Romawi", "Papan dipahat di batu di seluruh kekaisaran (contoh pasti pertama)"], ["Sekitar 900", "Papan dipahat di papan geladak kapal Gokstad (Norwegia)"], ["1283", "Kitab Permainan Alfonso X menggambarkan morris"], ["Abad Pertengahan", "Papan dipahat di bangku serambi katedral Inggris"], ["1590-an", "A Midsummer Night’s Dream karya Shakespeare menyebut papan yang penuh lumpur"], ["1931", "Lasker mengusulkan versi baru dalam Brettspiele der Völker"], ["1996", "Gasser membuktikan remis bila dimainkan sempurna"]]}}, "hi": {"morris": {"kf": ["तीन एक-दूसरे में बने वर्गों के 24 बिंदुओं पर नौ-नौ गोटियाँ; तीन एक पंक्ति में आएँ तो विरोधी की एक गोटी हटती है", "रोमन काल से इसका बोर्ड वहाँ खोदा गया जहाँ लोग जुटते थे — जहाज़ों के डेक, गिरजाघरों की बेंचें", "1996 में कंप्यूटर ने सारी स्थितियाँ जाँचीं: बिना चूक खेलें तो बराबरी"], "more": [{"h": "रखो, चलो, उड़ो", "p": ["खेल तीन चरणों में चलता है। पहले दोनों बारी-बारी से अपनी नौ गोटियाँ ख़ाली बिंदुओं पर रखते हैं। सब रख लेने के बाद, हर बार एक गोटी रेखा के साथ पास के ख़ाली बिंदु पर चलाई जाती है।", "रेखा पर अपनी तीन गोटियाँ एक पंक्ति में आएँ तो ‘मिल’ बनती है और विरोधी की एक गोटी बोर्ड से हटा सकते हैं। एक आम नियम में, जिसके पास तीन गोटियाँ बचें, वह किसी भी ख़ाली बिंदु पर ‘उड़’ सकता है। जिसके पास दो गोटियाँ बचें या जो चल न सके, वह हारता है।"], "cap": ["नाइन मेन्स मॉरिस का बोर्ड। सफ़ेद ने बाहरी किनारे पर तीन गोटियों की ‘मिल’ बनाई (सुनहरा), इसलिए वह एक काली गोटी हटा सकता है (लाल क्रॉस)"]}, {"h": "तीन से बारह गोटियों तक", "p": ["यह परिवार गोटियों की संख्या से जाना जाता है। तीन-तीन गोटियों वाला थ्री मेन्स मॉरिस छोटा बोर्ड है, ज़ीरो-काटा जैसा। छह-छह वाला सिक्स मेन्स मॉरिस दो एक-दूसरे में बने वर्गों का बोर्ड इस्तेमाल करता है।", "बारह-बारह वाला ट्वेल्व मेन्स मॉरिस, नाइन मेन्स के बोर्ड में तिरछी रेखाएँ जोड़ता है। दक्षिण अफ़्रीका में इसे मोराबाराबा कहते हैं; कहा जाता है कि मवेशी चराने वाले लड़के इसे ज़मीन पर बनाते थे, और आज इसकी प्रतियोगिताएँ भी होती हैं।"], "cap": ["बोर्डों की तुलना। संख्या हर खिलाड़ी की गोटियाँ है: थ्री, सिक्स, नाइन और ट्वेल्व मेन्स मॉरिस"]}, {"h": "शतरंज विजेता और कंप्यूटर", "p": ["विश्व शतरंज विजेता इमैनुअल लास्कर भी इस खेल के दीवाने थे। अपनी किताब ‘ब्रेटश्पीले डेर फ़ोल्कर’ (1931) में उन्होंने दस-दस गोटियों वाला रूप सुझाया, जिसमें सारी गोटियाँ रखने से पहले भी चल सकते हैं।", "1996 में स्विट्ज़रलैंड के राल्फ़ गैसर ने अंत की सारी स्थितियों की पूरी तालिकाओं को शुरुआत से की गई खोज के साथ जोड़कर दिखाया कि दोनों पक्ष बिना चूक खेलें तो नाइन मेन्स मॉरिस बराबरी पर ख़त्म होता है। बोर्ड पर सिर्फ़ 24 बिंदु हैं, पर स्थितियाँ अरबों में हैं।"], "cap": []}], "tl": [["रोमन काल", "साम्राज्य भर में पत्थरों पर बोर्ड खोदे गए (पहले पक्के उदाहरण)"], ["लगभग 900", "नॉर्वे के गोकस्ताद जहाज़ के डेक के तख़्ते पर बोर्ड खोदा गया"], ["1283", "अल्फ़ोंसो दशम की ‘खेलों की किताब’ में मॉरिस का चित्र"], ["मध्यकाल", "इंग्लैंड के गिरजाघरों के गलियारों की बेंचों पर बोर्ड"], ["1590 का दशक", "शेक्सपियर के ‘ए मिडसमर नाइट्स ड्रीम’ में कीचड़ भरे बोर्ड का ज़िक्र"], ["1931", "लास्कर ने ‘ब्रेटश्पीले डेर फ़ोल्कर’ में नया रूप सुझाया"], ["1996", "गैसर ने सिद्ध किया कि बिना चूक खेलने पर बराबरी"]]}}, "ar": {"morris": {"kf": ["تسع قطع لكل لاعب على 24 نقطة في ثلاثة مربعات متداخلة؛ وثلاث في صف واحد تُسقط قطعة للخصم", "منذ العصر الروماني نُقش لوحها حيث اجتمع الناس: على أسطح السفن ومقاعد الكاتدرائيات", "في 1996 فُحصت كل الأوضاع بالحاسوب: باللعب المثالي تنتهي بالتعادل"], "more": [{"h": "ضَع، حرِّك، طِر", "p": ["تمر اللعبة بثلاث مراحل. أولًا يضع اللاعبان بالتناوب قطعهما التسع على النقاط الخالية. وبعد وضعها كلها تُحرَّك قطعة واحدة كل مرة على خط إلى نقطة مجاورة خالية.", "ثلاث من قطعك في صف واحد على خط تكوّن «طاحونة»، فترفع قطعة للخصم عن اللوح. وفي قاعدة شائعة يجوز لمن بقيت له ثلاث قطع أن «يطير» إلى أي نقطة خالية. ويخسر من بقيت له قطعتان أو عجز عن الحركة."], "cap": ["لوح الطاحونة. كوّن الأبيض طاحونة على الضلع الخارجي (بالذهبي)، فيحق له أخذ قطعة سوداء (الإشارة الحمراء)"]}, {"h": "من ثلاث قطع إلى اثنتي عشرة", "p": ["تُسمّى هذه العائلة بعدد قطعها. طاحونة الثلاث، بثلاث قطع لكل لاعب، لوح صغير قريب من «إكس-أو». وطاحونة الست تستعمل لوحًا من مربعين متداخلين.", "أما طاحونة الاثنتي عشرة فتضيف خطوطًا قطرية إلى لوح طاحونة التسع. وفي جنوب أفريقيا تُسمّى «مورابارابا»، ويُقال إن صبية الرعاة كانوا يرسمونها على الأرض، ولها اليوم بطولات."], "cap": ["مقارنة الألواح. العدد هو قطع كل لاعب: طاحونة الثلاث والست والتسع والاثنتي عشرة"]}, {"h": "بطل شطرنج وحاسوب", "p": ["وكان بطل العالم في الشطرنج إيمانويل لاسكر ممن شُغفوا بهذه اللعبة. ففي كتابه «ألعاب الألواح عند الشعوب» (1931) اقترح نسخة بعشر قطع لكل لاعب، يجوز فيها التحريك قبل وضع كل القطع.", "وفي 1996 جمع السويسري رالف غاسر جداول كاملة لأوضاع النهاية مع بحث يبدأ من الافتتاح، فأثبت أن الطاحونة تنتهي بالتعادل إذا لعب الطرفان لعبًا مثاليًا. للوح 24 نقطة فقط، لكن عدد الأوضاع يبلغ المليارات."], "cap": []}], "tl": [["العصر الروماني", "نقش ألواح على الحجر في أنحاء الإمبراطورية (أول الأمثلة المؤكدة)"], ["نحو 900", "نقش لوح على خشبة من سطح سفينة غوكستاد (النرويج)"], ["1283", "«كتاب الألعاب» لألفونسو العاشر يصوّر الطاحونة"], ["العصور الوسطى", "ألواح منقوشة على مقاعد أروقة الكاتدرائيات الإنجليزية"], ["تسعينيات القرن 16", "«حلم ليلة صيف» لشكسبير يذكر لوحًا امتلأ بالطين"], ["1931", "لاسكر يقترح نسخة جديدة في «ألعاب الألواح عند الشعوب»"], ["1996", "غاسر يثبت التعادل باللعب المثالي"]]}}};
  Object.keys(D).forEach(l => { const t = T[l]; if (!t) return; Object.keys(D[l]).forEach(id => { if (t[id]) Object.assign(t[id], D[l][id]); }); }); })(window.MUSEUM_READ_T);
